_G.Spooky = _G.Spooky or {}
local Spooky = _G.Spooky

Spooky.Diagnostics = {errors={}, statuses={}, lastNotice={}}
function Spooky.ReportIssue(feature, err)
    local d=Spooky.Diagnostics
    local text=tostring(err)
    local item=d.errors[feature]
    d.errors[feature]={message=text,count=(item and item.count or 0)+1,time=os.clock()}
    if not d.lastNotice[feature] or os.clock()-d.lastNotice[feature]>15 then
        d.lastNotice[feature]=os.clock()
        warn("[Zen Hub / " .. feature .. "] " .. text)
        if _G.Spooky_Log then pcall(_G.Spooky_Log,feature .. ": " .. text) end
        if not d.lastToast or os.clock()-d.lastToast>20 then
            d.lastToast=os.clock()
            pcall(function()
                game:GetService("StarterGui"):SetCore("SendNotification",{
                    Title="Zen Hub · " .. feature,
                    Text="Error detectado. Revisa la consola de errores.",Duration=5,
                })
            end)
        end
    end
end
Spooky.Globals   = Spooky.Globals or {}
Spooky.State     = Spooky.State or {}
Spooky.Config    = Spooky.Config or {}
Spooky.VFX       = Spooky.VFX or {}
Spooky.UI        = Spooky.UI or {}
Spooky.Cache     = Spooky.Cache or {}
Spooky.Closures  = Spooky.Closures or {}
_G.PlayerBlacklist = _G.PlayerBlacklist or {}
Spooky.Blacklist = _G.PlayerBlacklist
function Spooky.ExportPlayerBlacklist()
    local result = {}
    for key, value in pairs(_G.PlayerBlacklist or {}) do
        if value == true and (type(key) == "string" or type(key) == "number") then result[tostring(key)] = true end
    end
    return result
end
function Spooky.RestorePlayerBlacklist(data)
    if type(data) ~= "table" then return end
    local result = {}
    for key, value in pairs(data) do
        if value == true and (type(key) == "string" or type(key) == "number") then
            result[tostring(key)] = true
            if tonumber(key) then result[tonumber(key)] = true end
        end
    end
    _G.PlayerBlacklist, Spooky.Blacklist = result, result
    if Spooky.RefreshPlayerList then task.defer(Spooky.RefreshPlayerList) end
end

local Players           = game:GetService("Players")
local TweenService      = game:GetService("TweenService")
local UserInputService  = game:GetService("UserInputService")
local RunService        = game:GetService("RunService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local HttpService       = game:GetService("HttpService")
local Lighting          = game:GetService("Lighting")
local TeleportService   = game:GetService("TeleportService")
local LocalPlayer = Players.LocalPlayer or Players.PlayerAdded:Wait()
local PlayerGui   = LocalPlayer:WaitForChild("PlayerGui")
local rawMouse    = LocalPlayer:GetMouse()
if type(getgenv) ~= "function" then
    getgenv = function() return _G end
end
pcall(function()
    LocalPlayer.Idled:Connect(function()
        local vu = game:GetService("VirtualUser")
        if vu then
            vu:ClickButton2(Vector2.zero)
        end
    end)
end)

task.spawn(function()
    pcall(function()
        if not game:IsLoaded() then
            pcall(function() game.Loaded:Wait() end)
        end
        local chosenTeam = nil
        if isfile and isfile("Sovereign_AutoTeam.txt") and readfile then
            local raw = readfile("Sovereign_AutoTeam.txt")
            if raw then
                local t = string.match(raw, "%a+")
                if t == "Marines" or t == "Pirates" then
                    chosenTeam = t
                end
            end
        end
        if chosenTeam then
            local rem = ReplicatedStorage:WaitForChild("Remotes", 10) or ReplicatedStorage:FindFirstChild("Remotes")
            local comm = rem and (rem:WaitForChild("CommF_", 10) or rem:FindFirstChild("CommF_"))
            if comm then
                comm:InvokeServer("SetTeam", chosenTeam)
            elseif ReplicatedStorage:FindFirstChild("Remotes") and ReplicatedStorage.Remotes:FindFirstChild("CommF_") then
                ReplicatedStorage.Remotes.CommF_:InvokeServer("SetTeam", chosenTeam)
            end
        end
    end)
end)
local function getSafeParent()
    if gethui then
        local ok, h = pcall(gethui)
        if ok and h then return h end
    end
    if syn and syn.protect_gui then
        pcall(syn.protect_gui, PlayerGui)
        return PlayerGui
    end
    return PlayerGui
end
local TargetParent = getSafeParent()
local function safeParent(gui)
    if not gui then return end
    local ok = pcall(function() gui.Parent = TargetParent end)
    if (not ok or not gui.Parent) and LocalPlayer then
        pcall(function()
            gui.Parent = LocalPlayer:FindFirstChild("PlayerGui") or LocalPlayer:WaitForChild("PlayerGui", 3)
        end)
    end
end
if _G.Spooky_Cleanup then
    pcall(_G.Spooky_Cleanup)
end
local SCRIPT_SESSION = tick()
_G.Spooky_Session = SCRIPT_SESSION
local function isCurrentSession()
    return _G.Spooky_Session == SCRIPT_SESSION
end
local ActiveScriptConnections = {}
local function registerConnection(conn)
    if conn then
        table.insert(ActiveScriptConnections, conn)
    end
    return conn
end
local function cleanOldGuis(parent)
    if not parent then return end
    local guiNames = {
        "Sovereign_GUI",
        "Sovereign_LoadingGui",
        "Sovereign_LoginGui",
        "Sovereign_MobileToggle",
        "SovereignCamLockWidget",
        "SovereignTrackerWidget",
        "SanguineNoLagBoostWidget",
        "SanguineLagBoostWidget",
        "SuperJumpWidget",
        "SovereignSuperJumpWidget",
        "Sovereign_Macro_Floating_Combo",
        "SovereignMacroEditorWindow",
        "SovereignIslandTeleport",
        "SovereignIslandTeleportGui",
        "IslandTeleportGui",
        "SovereignShipCustomGui",
        "SovereignShipModWindow",
        "ShipCustomGui",
        "SovereignKeybindsGui",
        "Sovereign_Notification_Gui",
        "SovereignCombatHUDWidget",
        "Sovereign_Float_FloatHUD_Aimbot",
        "Sovereign_Float_FloatHUD_BusoKen",
        "Sovereign_Float_FloatHUD_V4",
        "Sovereign_Float_FloatHUD_Soru",
        "Sovereign_Float_FloatHUD_MagnetHealth"
    }
    for _, name in ipairs(guiNames) do
        local g = parent:FindFirstChild(name)
        if g then pcall(function() g:Destroy() end) end
    end
    for _, ch in ipairs(parent:GetChildren()) do
        if ch:IsA("ScreenGui") and string.find(ch.Name, "Sovereign_Float_") then
            pcall(function() ch:Destroy() end)
        end
    end
end
cleanOldGuis(TargetParent)
if PlayerGui and PlayerGui ~= TargetParent then cleanOldGuis(PlayerGui) end

