    TweenService:Create(panel, TweenInfo.new(0.42, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
        GroupTransparency = 0,
        Position = UDim2.new(0.5, 0, 0.5, 0)
    }):Play()
    TweenService:Create(scale, TweenInfo.new(0.42, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
        Scale = 1
    }):Play()

    local pulsing = true
    task.spawn(function()
        while pulsing and panel.Parent do
            TweenService:Create(aura, TweenInfo.new(1.0, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {
                Size = UDim2.new(0, 76, 0, 76),
                Position = UDim2.new(0, 22, 0, 18),
                ImageTransparency = 0.25
            }):Play()
            task.wait(1.0)
            if not pulsing or not panel.Parent then break end
            TweenService:Create(aura, TweenInfo.new(1.0, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {
                Size = UDim2.new(0, 64, 0, 64),
                Position = UDim2.new(0, 28, 0, 24),
                ImageTransparency = 0.65
            }):Play()
            task.wait(1.0)
        end
    end)

    local currentPct = 15
    local targetPct = 15
    local function setProgress(pct, duration, statusText, phaseText)
        targetPct = math.clamp(pct, 0, 100)
        if statusText then status.Text = statusText end
        if phaseText then footer.Text = phaseText end
        TweenService:Create(fill, TweenInfo.new(duration or 0.35, Enum.EasingStyle.Cubic, Enum.EasingDirection.Out), {
            Size = UDim2.fromScale(targetPct / 100, 1)
        }):Play()

        local startP = currentPct
        local startTime = os.clock()
        local animDur = duration or 0.35
        task.spawn(function()
            while os.clock() - startTime < animDur do
                local alpha = (os.clock() - startTime) / animDur
                local val = math.floor(startP + (targetPct - startP) * alpha)
                pctLbl.Text = tostring(val) .. "%"
                task.wait(0.03)
            end
            currentPct = targetPct
            pctLbl.Text = tostring(targetPct) .. "%"
        end)
    end

    local finished = false
    local function finish()
        if finished then return end
        finished = true
        pulsing = false
        setProgress(100, 0.22, es and "Tu espacio esta listo!" or "Your workspace is ready!", "Zen Hub / READY")
        pctLbl.TextColor3 = Color3.fromRGB(120, 255, 180)
        TweenService:Create(spark, TweenInfo.new(0.2), { BackgroundColor3 = Color3.fromRGB(120, 255, 180) }):Play()

        task.delay(0.26, function()
            if not isCurrentSession() then
                pcall(function() blur:Destroy() end)
                gui:Destroy()
                return
            end
            TweenService:Create(blur, TweenInfo.new(0.28, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Size = 0 }):Play()
            TweenService:Create(shade, TweenInfo.new(0.28, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { BackgroundTransparency = 1 }):Play()
            TweenService:Create(panel, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.In), {
                GroupTransparency = 1,
                Position = UDim2.new(0.5, 0, 0.5, -20)
            }):Play()
            TweenService:Create(scale, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.In), {
                Scale = 0.85
            }):Play()

            task.delay(0.32, function()
                _G.SpookyStartupLoaderFinished = true
                local reveal = _G.SpookyOnStartupLoaderFinished
                _G.SpookyOnStartupLoaderFinished = nil
                if reveal then pcall(reveal) end
                pcall(function() blur:Destroy() end)
                pcall(function() gui:Destroy() end)
            end)
        end)
    end

    _G.SpookyStartupStage = function(stage)
        if finished or not isCurrentSession() then return end
        local stages = {
            controls = { 55, "FASE 02 / CONTROLES", es and "Organizando controles y atajos..." or "Organizing controls & keybinds..." },
            combat   = { 88, "FASE 03 / SISTEMAS",  es and "Calibrando funciones de combate..." or "Calibrating combat systems..." },
        }
        local data = stages[stage]
        if data then
            setProgress(data[1], 0.32, data[3], data[2])
        end
    end

    local began = os.clock()
    _G.SpookyFinishStartup = function()
        task.delay(math.max(0, 0.65 - (os.clock() - began)), finish)
    end

    skip.Activated:Connect(finish)

    task.delay(10, function()
        if not finished and isCurrentSession() then
            finish()
        end
    end)
end

