local function performFullScriptShutdown()
    print("[Zen Hub] Full Shutdown: Deactivating ALL features and cleaning up...")

    local fCallbacks = _G.FeatureCallbacks
    local fStates = _G.FeatureStates
    if fCallbacks and fStates then
        for featName, cb in pairs(fCallbacks) do
            if fStates[featName] == true then
                pcall(function() cb(false) end)
            end
        end
    end
    local fStates = _G.FeatureStates
    if fStates then
        for featName, _ in pairs(fStates) do
            fStates[featName] = false
        end
    end

    if _G.SpookyStopMacro then pcall(_G.SpookyStopMacro) end
    if _G.SpookyRestoreGunAim then pcall(_G.SpookyRestoreGunAim); _G.SpookyRestoreGunAim = nil end
    if _G.SpookyRestoreMouseAim then pcall(_G.SpookyRestoreMouseAim) end
    if Spooky.CleanupCombatVisuals then pcall(Spooky.CleanupCombatVisuals) end
    pcall(function() RunService:UnbindFromRenderStep("SovereignCamLockExecution") end)

    _G.Spooky_Session = nil
    _G.Spooky_Loaded = false

    getgenv().SpookyAutoBountyRunning = false
    getgenv().AutoBountyActive = false
    _G.AutoFarmOvercharged = false
    _G.GunAuraActive = false
    _G.MagnetM1Active = false
    _G.G_DragonGunM1 = false
    _G.lockedAim1Char = nil
    _G.aimbot1TargetPos = nil
    _G.lockedAim2Char = nil
    _G.G_SilentAimTargetPos = nil
    _G.centuTargetChar = nil
    _G.centuAimPosition = nil
    local fnAutoBounty = _G.stopSpookyAutoBountyExact or (type(stopSpookyAutoBountyExact) == "function" and stopSpookyAutoBountyExact)
    if fnAutoBounty then pcall(fnAutoBounty) end
    local fnIslandTween = _G.stopIslandTween or (type(stopIslandTween) == "function" and stopIslandTween)
    if fnIslandTween then pcall(fnIslandTween) end

    local fnCleanESPs = _G.Spooky_CleanAllESPs or _G.cleanAllESPs or (type(cleanAllESPs) == "function" and cleanAllESPs)
    if fnCleanESPs then pcall(fnCleanESPs) end
    local fnCleanVFX = getgenv().SpookyColorVFX_Cleanup or _G.SpookyColorVFX_Cleanup or _G.cleanupVFX or (type(cleanupVFX) == "function" and cleanupVFX)
    if fnCleanVFX then pcall(fnCleanVFX) end
    local fnFruitScales = _G.Spooky_RestoreFruitScales or _G.restoreAllFruitScales or (type(restoreAllFruitScales) == "function" and restoreAllFruitScales)
    if fnFruitScales then pcall(fnFruitScales) end
    local fnHud = _G.Spooky_CleanupHudOverlays or _G.cleanupHudOverlays or (type(cleanupHudOverlays) == "function" and cleanupHudOverlays)
    if fnHud then pcall(fnHud) end

    pcall(function()
        local char = LocalPlayer.Character
        if char then
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum then
                hum.PlatformStand = false
                hum.Sit = false
            end
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if hrp then
                for _, ch in ipairs(hrp:GetChildren()) do
                    if ch:IsA("BodyVelocity") or ch:IsA("BodyGyro") then
                        pcall(function() ch:Destroy() end)
                    end
                end
            end
            for _, p in ipairs(char:GetDescendants()) do
                if p:IsA("BasePart") then p.CanTouch = true end
            end
        end
    end)

    pcall(function()
        local cam = workspace.CurrentCamera
        if cam then
            local char = LocalPlayer.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if hum then cam.CameraSubject = hum end
            cam.CameraType = Enum.CameraType.Custom
            cam.FieldOfView = 70
            LocalPlayer.CameraMaxZoomDistance = 128
            LocalPlayer.CameraMinZoomDistance = 0.5
        end
    end)

    for _, conn in ipairs(ActiveScriptConnections) do
        if conn and conn.Disconnect then
            pcall(function() conn:Disconnect() end)
        end
    end
    table.clear(ActiveScriptConnections)

    pcall(function()
        for _, obj in ipairs(workspace:GetChildren()) do
            if obj.Name == "SovereignWaterPlatform" or obj.Name == "WaterPlatform" or obj.Name == "SovereignTracerAnchor" then
                pcall(function() obj:Destroy() end)
            end
        end
        local waterPlane = workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("WaterBase-Plane")
        if waterPlane then
            waterPlane.CanCollide = false
            waterPlane.Size = Vector3.new(1000, 80, 1000)
        end
        for _, obj in ipairs(Lighting:GetChildren()) do
            if obj.Name:find("Sovereign") or obj.Name:find("Shaders") then
                pcall(function() obj:Destroy() end)
            end
        end
    end)

    cleanOldGuis(TargetParent)
    if PlayerGui and PlayerGui ~= TargetParent then cleanOldGuis(PlayerGui) end
    pcall(function()
        local pGui = LocalPlayer:FindFirstChild("PlayerGui") or game:GetService("CoreGui")
        local guiList = {
            "Sovereign_GUI", "Sovereign_LoginGui", "Sovereign_MobileToggle", "SovereignCamLockWidget", "SovereignTrackerWidget",
            "SuperJumpWidget", "SovereignSuperJumpWidget", "Sovereign_HUDOverlay",
            "Sovereign_Macro_Floating_Combo", "Sovereign_ImportModal", "SovereignIslandTeleport",
            "SovereignIslandTeleportGui", "IslandTeleportGui", "SovereignShipCustomGui", "SovereignShipModWindow"
        }
        for _, gName in ipairs(guiList) do
            local found = pGui:FindFirstChild(gName, true)
            if found then pcall(function() found:Destroy() end) end
        end
    end)

    pcall(function()
        if Spooky.UI.screen and Spooky.UI.screen.Parent then
            Spooky.UI.screen:Destroy()
        end
    end)
    pcall(function() if _G.ZenDestroyBountyUI then _G.ZenDestroyBountyUI() end end)
    print("[Zen Hub] All features successfully deactivated and script closed.")
end
_G.Spooky_Cleanup = performFullScriptShutdown
_G.Spooky_Loaded = true

task.spawn(function()
    local savedTeam = "Pirates"
    pcall(function()
        if isfile and isfile("Sovereign_AutoTeam.txt") and readfile then
            local raw = readfile("Sovereign_AutoTeam.txt")
            if raw then
                local t = string.match(raw, "%a+")
                if t == "Marines" or t == "Pirates" or t == "None" then
                    savedTeam = t
                end
            end
        else
            if writefile then writefile("Sovereign_AutoTeam.txt", "Pirates") end
        end
    end)
    if savedTeam ~= "None" then
        repeat task.wait(0.2) until game:IsLoaded() and game.Players.LocalPlayer
        local lp = game.Players.LocalPlayer
        local rem = game:GetService("ReplicatedStorage"):WaitForChild("Remotes", 10)
        local commF = rem and rem:WaitForChild("CommF_", 10)
        local tries = 0
        while (not lp.Team or lp.Team.Name ~= savedTeam) and tries < 10 do
            if commF then
                pcall(function() commF:InvokeServer("SetTeam", savedTeam) end)
            end
            task.wait(1.0)
            tries = tries + 1
        end
    end
end)

