function Spooky.TakeAttackBudget(channel, delay)
    local now = os.clock()
    if now < (Spooky.AttackBudget[channel] or 0) then return false end
    Spooky.AttackBudget[channel] = now + math.clamp(tonumber(delay) or 0.15, 0.12, 1)
    return true
end
