    local function resolveCanonicalTabId(name)
        if not name then return "Home" end
        local s = tostring(name)
        local norm = string.lower(string.gsub(s, "[%s_]+", ""))

        if norm == "home" or norm == "inicio" or norm == "dashboard" then
            return "Home"
        elseif norm == "combat" or norm == "combate" or norm == "pvp" then
            return "Combat"
        elseif norm == "sovereignbounty" or norm == "autobounty" or norm == "bounty" or norm == "sovereignbounty" or norm == "autobounty" then
            return "SovereignBounty"
        elseif norm == "kitsunebounty" or norm == "kitautobounty" or norm == "kitbounty" or norm == "kitsune" then
            return "SovereignBounty"
        elseif norm == "controlpeople" or norm == "playerlist" or norm == "players" or norm == "other" or norm == "jugadores" or norm == "player" then
            return "ControlPeople"
        elseif norm == "cheats" or norm == "glitches" or norm == "trucos" then
            return "Cheats"
        elseif norm == "fflags" or norm == "ffflags" or norm == "fastflags" or norm == "flags" then
            return "FFlags"
        elseif norm == "macro" or norm == "macros" then
            return "Macro"
        elseif norm == "keybinds" or norm == "keybind" or norm == "atajos" or norm == "teclas" then
            return "Keybinds"
        elseif norm == "color" or norm == "colors" or norm == "colores" then
            return "Color"
        elseif norm == "visual" or norm == "visuals" or norm == "esp" or norm == "visuales" then
            return "Visual"
        elseif norm == "hud" then
            return "HUD"
        elseif norm == "dungeons" or norm == "dougeons" or norm == "dungeon" or norm == "mazmorras" then
            return "Dungeons"
        elseif norm == "tpislands" or norm == "tpmap" or norm == "map" or norm == "islands" or norm == "teleport" or norm == "mapatp" then
            return "TPIslands"
        elseif norm == "ui" or norm == "interface" or norm == "interfaz" or norm == "gui" then
            return "UI"
        elseif norm == "misc" or norm == "varios" or norm == "miscellaneous" then
            return "Misc"
        elseif norm == "configs" or norm == "config" or norm == "profiles" or norm == "ajustes" or norm == "configuraciones" then
            return "Configs"
        elseif norm == "report" or norm == "reportar" or norm == "bugreport" or norm == "feedback" then
            return "Report"
        elseif norm == "functions" or norm == "funciones" or norm == "func" or norm == "function" then
            return "Functions"
        end

        return "Home"
    end
    _G.ResolveCanonicalTabId = resolveCanonicalTabId

    local currentActiveTab = "Home"
    _G.CurrentActiveTab = currentActiveTab
    local function updateSidebarVisual(selectedId)
        local canonSel = resolveCanonicalTabId(selectedId or currentActiveTab or "Home")
        local curAccent = _G.CurrentAccentColor or Color3.fromRGB(255, 45, 55)
        local curBright = _G.CurrentAccentColorBright or Color3.fromRGB(175, 145, 255)
        for id, btnData in pairs(NavButtons) do
            local isSel = (id == canonSel)
            local btn = btnData.btn or btnData
            local st = btnData.st or (btn and btn:FindFirstChildOfClass("UIStroke"))
            local ind = btnData.ind
            local lbl = btnData.lbl

            if btn then
                TweenService:Create(btn, TweenInfo.new(0.15), {
                    BackgroundColor3 = isSel and Color3.fromRGB(24, 22, 38) or Color3.fromRGB(12, 12, 17)
                }):Play()
            end
            if st then
                TweenService:Create(st, TweenInfo.new(0.15), {
                    Color = isSel and curAccent or Color3.fromRGB(30, 28, 40),
                    Thickness = isSel and 1.2 or 1
                }):Play()
            end
            if ind then
                TweenService:Create(ind, TweenInfo.new(0.15), {
                    Size = isSel and UDim2.new(0, 3, 0, 14) or UDim2.new(0, 0, 0, 14),
                    BackgroundColor3 = curBright,
                    BackgroundTransparency = isSel and 0 or 1
                }):Play()
            end
            if lbl then
                TweenService:Create(lbl, TweenInfo.new(0.15), {
                    TextColor3 = isSel and curBright or Color3.fromRGB(150, 150, 170)
                }):Play()
            end
        end
    end
    _G.UpdateSidebarVisual = updateSidebarVisual

    showTab = function(tabName)
        local canonId = resolveCanonicalTabId(tabName)
        currentActiveTab = canonId
        _G.CurrentActiveTab = canonId
        local isHome = (canonId == "Home")
        if titleBanner then titleBanner.Visible = isHome end
        if profileContainer then profileContainer.Visible = isHome end
        if playerProfile then playerProfile.Visible = isHome end
        if welcomeLbl then welcomeLbl.Visible = isHome end
        if HomeStatsContainer then HomeStatsContainer.Visible = isHome end
        creditsLbl.Visible = isHome
        creditsPersonLbl.Visible = isHome
        if creditsBadge then creditsBadge.Visible = isHome end
        if topImg then topImg.Visible = false end
        if midImg then midImg.Visible = false end
        if botImg then botImg.Visible = false end

        if _G.SpookyThemedElements and _G.SpookyThemedElements.centerPagesBg then
            _G.SpookyThemedElements.centerPagesBg.Visible = true
        end

        for _, page in pairs(PagesFolder:GetChildren()) do
            if page:IsA("GuiObject") then
                local isTarget = false
                if not isHome then
                    if canonId == "Combat" and page.Name == "Combat_Page" then
                        isTarget = true
                    elseif canonId == "SovereignBounty" and page.Name == "AutoBounty_Page" then
                        isTarget = true
                    elseif canonId == "KitsuneBounty" and page.Name == "KitsuneBounty_Page" then
                        isTarget = true
                    elseif canonId == "ControlPeople" and page.Name == "ControlPeople_Page" then
                        isTarget = true
                        if _G.SpookyRefreshPlayerList then
                            task.defer(function() pcall(_G.SpookyRefreshPlayerList) end)
                        end
                    elseif canonId == "Cheats" and (page.Name == "Glitches_Page" or page.Name == "Cheats_Page") then
                        isTarget = true
                    elseif canonId == "FFlags" and page.Name == "FFlags_Page" then
                        isTarget = true
                    elseif canonId == "Macro" and page.Name == "Macro_Page" then
                        isTarget = true
                    elseif canonId == "Keybinds" and page.Name == "Keybinds_Page" then
                        isTarget = true
                    elseif canonId == "Color" and (page.Name == "SacredVFX_Page" or page.Name == "Color_Page") then
                        isTarget = true
                    elseif canonId == "Visual" and (page.Name == "Visual_Page" or page.Name == "Visuals_Page") then
                        isTarget = true
                    elseif canonId == "HUD" and page.Name == "HUD_Page" then
                        isTarget = true
                    elseif canonId == "Dungeons" and page.Name == "Dungeons_Page" then
                        isTarget = true
                    elseif canonId == "TPIslands" and page.Name == "TPIslands_Page" then
                        isTarget = true
                    elseif canonId == "UI" and page.Name == "UI_Page" then
                        isTarget = true
                    elseif canonId == "Misc" and page.Name == "Misc_Page" then
                        isTarget = true
                    elseif canonId == "Configs" and page.Name == "Configs_Page" then
                        isTarget = true
                    elseif canonId == "Report" and page.Name == "Report_Page" then
                        isTarget = true
                    elseif canonId == "Functions" and page.Name == "Functions_Page" then
                        isTarget = true
                    end
                end
                page.Visible = isTarget
            end
        end
        PagesFolder.Visible = true
        updateSidebarVisual(canonId)
        if canonId == "SovereignBounty" and _G.ZenOpenBountyUI then task.defer(function() pcall(_G.ZenOpenBountyUI) end) end
        addLog("[TAB] " .. tostring(canonId))
    end
    globalShowTab = showTab
    _G.SpookyShowTab = showTab

    for idx, tdef in ipairs(tabDefinitions) do
        local isDefault = (tdef.id == "Home")
        local btn = Instance.new("TextButton", SidebarScroll)
        btn.Name = string.lower(tdef.label) .. " button"
        btn.Size = UDim2.new(1, -6, 0, 27)
        btn.BackgroundColor3 = isDefault and Color3.fromRGB(24, 22, 38) or Color3.fromRGB(12, 12, 17)
        btn.Font = Enum.Font.GothamBold
        btn.Text = ""
        btn.AutoButtonColor = false
        btn.LayoutOrder = idx
        btn.ZIndex = 9

        Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 7)
        local st = Instance.new("UIStroke", btn)
        st.Color = isDefault and Color3.fromRGB(120, 95, 195) or Color3.fromRGB(30, 28, 40)
        st.Thickness = isDefault and 1.2 or 1

        local ind = Instance.new("Frame", btn)
        ind.Name = "ActiveIndicator"
        ind.Size = isDefault and UDim2.new(0, 3, 0, 14) or UDim2.new(0, 0, 0, 14)
        ind.Position = UDim2.new(0, 3, 0.5, -7)
        ind.BackgroundColor3 = Color3.fromRGB(160, 130, 255)
        ind.BackgroundTransparency = isDefault and 0 or 1
        ind.BorderSizePixel = 0
        Instance.new("UICorner", ind).CornerRadius = UDim.new(1, 0)

        local lbl = Instance.new("TextLabel", btn)
        lbl.Name = "TabLabel"
        lbl.Active = false
        lbl.Size = (tdef.isSoon and UDim2.new(1, -36, 1, 0) or UDim2.new(1, -14, 1, 0))
        lbl.Position = UDim2.new(0, 10, 0, 0)
        lbl.BackgroundTransparency = 1
        lbl.Font = Enum.Font.GothamBold
        lbl.Text = tdef.label
        lbl.TextSize = (tdef.isSoon and 8.5 or 10.5)
        lbl.TextColor3 = isDefault and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(150, 150, 170)
        lbl.TextXAlignment = Enum.TextXAlignment.Left
        lbl.ZIndex = 10

        btn.MouseEnter:Connect(function()
            if btn.BackgroundColor3 ~= Color3.fromRGB(24, 22, 38) then
                TweenService:Create(btn, TweenInfo.new(0.12), { BackgroundColor3 = Color3.fromRGB(18, 18, 26) }):Play()
