    local userMovedTogglePos = nil
    local toggleDragging, toggleDragStart, toggleStartPos, toggleMoved = false, nil, nil, false
    MobileToggle.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            toggleDragging = true
            toggleMoved = false
            toggleDragStart = input.Position
            toggleStartPos = MobileToggle.Position
        end
    end)
    UserInputService.InputChanged:Connect(function(input)
        if toggleDragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
            local delta = input.Position - toggleDragStart
            if delta.Magnitude > 8 then toggleMoved = true end
            if toggleStartPos then
                local newPos = UDim2.new(
                    toggleStartPos.X.Scale, toggleStartPos.X.Offset + delta.X,
                    toggleStartPos.Y.Scale, toggleStartPos.Y.Offset + delta.Y
                )
                MobileToggle.Position = newPos
                userMovedTogglePos = newPos
            end
        end
    end)
    UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            toggleDragging = false
            if toggleMoved then task.delay(0.15, function() toggleMoved = false end) end
        end
    end)

    local isAnimatingUI = false
    local currentUIAnimation = "Pop"
    local uiAnimDuration = 0.28
    _G.SpookySetUIAnimation = function(name, dur)
        local allowed = {Pop=true, Bounce=true, SlideUp=true, SlideDown=true, ZoomSmooth=true, Fade=true}
        if allowed[name] then currentUIAnimation = name end
        local duration = tonumber(dur)
        if duration and duration == duration then uiAnimDuration = math.clamp(duration, 0.1, 0.6) end
        if _G.SpookyUpdateAnimButtonsVisual then
            _G.SpookyUpdateAnimButtonsVisual(currentUIAnimation)
        end
    end
    _G.SpookyGetUIAnimation = function()
        return currentUIAnimation, uiAnimDuration
    end

    local function showMobileBtn()
        MobileToggle.Position = userMovedTogglePos or UDim2.new(0, 20, 0, 80)
        MobileToggle.Size = UDim2.new(0, 52, 0, 52)
        MobileToggle.Visible = true
        isAnimatingUI = false
    end

    local uiAnimationToken = 0
    local uiMotionTweens = {}
    local uiRequestedVisible = nil
    local lastUIToggleInput = nil
    local fadeConnection, fadeValue = nil, nil
    local fadeOriginals = {}
    local function resetUIFade()
        if fadeConnection then fadeConnection:Disconnect(); fadeConnection = nil end
        if fadeValue then fadeValue:Destroy(); fadeValue = nil end
        for obj, properties in pairs(fadeOriginals) do
            if obj.Parent then
                for property, value in pairs(properties) do obj[property] = value end
            end
        end
        table.clear(fadeOriginals)
    end
    local function collectUIFade(obj)
        if obj:IsA("GuiObject") and not obj.Visible then return end
        local properties = {}
        if obj:IsA("GuiObject") then properties.BackgroundTransparency = obj.BackgroundTransparency end
        if obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then
            properties.TextTransparency = obj.TextTransparency
            properties.TextStrokeTransparency = obj.TextStrokeTransparency
        elseif obj:IsA("ImageLabel") or obj:IsA("ImageButton") then
            properties.ImageTransparency = obj.ImageTransparency
        elseif obj:IsA("UIStroke") then
            properties.Transparency = obj.Transparency
        end
        if next(properties) then fadeOriginals[obj] = properties end
        for _, child in ipairs(obj:GetChildren()) do collectUIFade(child) end
    end
    local function setUIVisibility(visible)
        if not isCurrentSession() or (visible and not isKeyValidLocal) then return end
        visible = visible == true
        uiRequestedVisible = visible
        uiAnimationToken += 1
        local token = uiAnimationToken
        for _, tween in ipairs(uiMotionTweens) do tween:Cancel() end
        table.clear(uiMotionTweens)
        resetUIFade()
        isAnimatingUI = true
        local scale = tonumber(userCustomScale or currentBaseScale or _G.InitialUIScaleVal) or 0.85
        local base = lastUIPos or UDim2.new(0.5, 0, 0.5, 0)
        local duration = math.clamp(tonumber(uiAnimDuration) or 0.28, 0.1, 0.6)
        if not visible then duration *= 0.75 end
        if _G.SpookyFloatTween then pcall(function() _G.SpookyFloatTween:Pause() end) end
        MAINUIframe.AnchorPoint = Vector2.new(0.5, 0.5)
        MobileToggle.Visible = true
        local mode = currentUIAnimation
        local offset = mode == "SlideDown" and -80 or (mode == "SlideUp" and 80 or 0)
        local startPosition = base + UDim2.fromOffset(0, offset)
        local factor = mode == "ZoomSmooth" and 0.72 or (mode == "Pop" and 0.88 or (mode == "Bounce" and 0.80 or 1))
        local compact = scale * factor
        local wasVisible = MAINUIframe.Visible
        MAINUIframe.Visible = true
        if visible and not wasVisible then
            MAINUIframe.Position = startPosition
            UIScale.Scale = compact
        end
        local style = visible and (mode == "Pop" and Enum.EasingStyle.Back or (mode == "Bounce" and Enum.EasingStyle.Bounce or Enum.EasingStyle.Quint)) or Enum.EasingStyle.Quad
        local info = TweenInfo.new(duration, style, visible and Enum.EasingDirection.Out or Enum.EasingDirection.In)
        local motion = TweenService:Create(MAINUIframe, info, {Position = visible and base or startPosition})
        local zoom = TweenService:Create(UIScale, info, {Scale = visible and scale or compact})
        table.insert(uiMotionTweens, motion); table.insert(uiMotionTweens, zoom)
        motion:Play(); zoom:Play()
        if mode == "Fade" then
            collectUIFade(MAINUIframe)
            fadeValue = Instance.new("NumberValue")
            fadeValue.Value = visible and 1 or 0
            local function applyFade(value)
                for obj, properties in pairs(fadeOriginals) do
                    if obj.Parent then
                        for property, original in pairs(properties) do obj[property] = original + (1 - original) * value end
                    end
                end
            end
            applyFade(fadeValue.Value)
            fadeConnection = fadeValue.Changed:Connect(applyFade)
            local fadeTween = TweenService:Create(fadeValue, info, {Value = visible and 0 or 1})
            table.insert(uiMotionTweens, fadeTween)
            fadeTween:Play()
        end
        task.delay(duration, function()
            if token ~= uiAnimationToken or not isCurrentSession() or not MAINUIframe.Parent then return end
            MAINUIframe.Visible = visible
            resetUIFade()
            MAINUIframe.Position = base
            UIScale.Scale = scale
            isAnimatingUI = false
            if visible and _G.SpookyFloatTween then pcall(function() _G.SpookyFloatTween:Play() end) end
            if not visible then showMobileBtn() end
        end)
    end
    _G.SpookyToggleUI = function(input)
        if not isCurrentSession() or not isKeyValidLocal then return end
        if input and input == lastUIToggleInput then return end
        lastUIToggleInput = input
        local visible = MAINUIframe.Visible
        if isAnimatingUI and uiRequestedVisible ~= nil then visible = uiRequestedVisible end
        setUIVisibility(not visible)
    end

    _G.SpookySetUIVisibility = setUIVisibility

    _G.SpookyPreviewAnimation = function()
        if isAnimatingUI then return end
        if not MAINUIframe.Visible then
            setUIVisibility(true)
        else
            setUIVisibility(false)
            local previewToken = uiAnimationToken
            task.delay(math.clamp(tonumber(uiAnimDuration) or 0.28, 0.1, 0.6) + 0.15, function()
                if previewToken ~= uiAnimationToken or not isCurrentSession() then return end
                setUIVisibility(true)
            end)
        end
    end

    local function onCloseScript()
        if isAnimatingUI then return end
        isAnimatingUI = true
        local tw = TweenService:Create(UIScale, TweenInfo.new(0.2, Enum.EasingStyle.Back, Enum.EasingDirection.In), { Scale = 0.02 })
        tw:Play()
        task.delay(0.22, function()
            performFullScriptShutdown()
        end)
    end
    CloseBtn.Activated:Connect(onCloseScript)

    local function handleToggleOpen()
        if toggleMoved or not isKeyValidLocal or not isCurrentSession() then return end
        _G.SpookyToggleUI()
    end
    MinimizeBtn.Activated:Connect(function() setUIVisibility(false) end)
    MobileToggle.Activated:Connect(handleToggleOpen)
    registerConnection(UserInputService.InputBegan:Connect(function(input, gpe)
        if gpe or not isKeyValidLocal or not isCurrentSession() or UserInputService:GetFocusedTextBox() then return end
        if input.KeyCode == Enum.KeyCode.RightControl or input.KeyCode == Enum.KeyCode.Insert then
            _G.SpookyToggleUI(input)
        end
    end))

    local ThemeAccents = {
        ["White"] = {
            accent = Color3.fromRGB(255, 255, 255),
            bright = Color3.fromRGB(235, 235, 245)
        },
        ["Purple"] = {
            accent = Color3.fromRGB(160, 130, 255),
            bright = Color3.fromRGB(195, 170, 255)
        },
        ["Red"] = {
