            bright = Color3.fromRGB(255, 115, 125)
        },
        ["Cyan"] = {
            accent = Color3.fromRGB(0, 215, 255),
            bright = Color3.fromRGB(90, 235, 255)
        },
        ["Green"] = {
            accent = Color3.fromRGB(50, 225, 120),
            bright = Color3.fromRGB(110, 255, 170)
        },
        ["Blue"] = {
            accent = Color3.fromRGB(65, 145, 255),
            bright = Color3.fromRGB(120, 180, 255)
        },
        ["Yellow"] = {
            accent = Color3.fromRGB(255, 215, 50),
            bright = Color3.fromRGB(255, 235, 110)
        },
        ["Orange"] = {
            accent = Color3.fromRGB(255, 135, 30),
            bright = Color3.fromRGB(255, 175, 75)
        },
        ["Pink"] = {
            accent = Color3.fromRGB(255, 105, 180),
            bright = Color3.fromRGB(255, 155, 210)
        },
        ["Gold"] = {
            accent = Color3.fromRGB(238, 190, 40),
            bright = Color3.fromRGB(255, 215, 80)
        },
        ["Sovereign Dark"] = {
            accent = Color3.fromRGB(238, 190, 40),
            bright = Color3.fromRGB(255, 215, 80)
        }
    }
    _G.SpookyThemeAccents = ThemeAccents

    local function loadEarlyThemeConfig()
        pcall(function()
            if isfile and isfile("ProjectSovereign_UIConfig.json") and readfile and HttpService then
                local raw = readfile("ProjectSovereign_UIConfig.json")
                if raw and #raw > 5 then
                    local data = HttpService:JSONDecode(raw)
                    if data and type(data) == "table" and data.theme then
                        CurrentTheme = data.theme
                        _G.CurrentTheme = data.theme
                        local th = ThemeAccents[data.theme]
                        if th then
                            _G.CurrentAccentColor = th.accent
                            _G.CurrentAccentColorBright = th.bright
                        end
                    end
                end
            end
        end)
    end
    loadEarlyThemeConfig()

    launchProjectSpooky = function()
        MAINUIframe.AnchorPoint = Vector2.new(0.5, 0.5)
        MAINUIframe.Position = UDim2.new(0.5, 0, 0.5, 0)
        MAINUIframe.Visible = false
        if MobileToggle then MobileToggle.Visible = false end
        updateMobileScaling()
        UIScale.Scale = currentBaseScale or 1.0

        local function revealSpookyUI()
            if not isCurrentSession() or not MAINUIframe.Parent then return end
            setUIVisibility(true)
            if MobileToggle then MobileToggle.Visible = true end
            if showTab then pcall(function() showTab("Home") end) end
            if showHomeSubView then pcall(function() showHomeSubView("Dashboard") end) end
        end

        if _G.SpookyStartupLoaderFinished then
            revealSpookyUI()
        else
            _G.SpookyOnStartupLoaderFinished = revealSpookyUI
        end
    end

    launchProjectSpooky()
end

