    end)
    btn.MouseLeave:Connect(function()
        TweenService:Create(btn, TweenInfo.new(0.12), { BackgroundColor3 = Color3.fromRGB(20, 20, 26) }):Play()
        TweenService:Create(aStk, TweenInfo.new(0.12), { Color = Color3.fromRGB(45, 45, 58) }):Play()
    end)
    if onClick then
        local lastActionClick = 0
        local function onActionActivated()
            local now = os.clock()
            if now - lastActionClick < 0.12 then return end
            lastActionClick = now
            onClick()
        end
        Spooky.RegisterControl(btn,nil,textEN,textES,onActionActivated)
        btn.Activated:Connect(onActionActivated)
    end
    table.insert(TranslatableUI, {
        txtLbl = txtLbl,
        btn = btn,
        en = textEN,
        es = textES
    })
    table.insert(AllUIButtons, btn)
    return btn
end

local function createSlider(parent, textEN, textES, minV, maxV, defV, isFloat, step, suffix, callback, pos)
    local frame = Instance.new("Frame")
    frame.Size = UDim2.new(1, -12, 0, 38)
    frame.Position = pos or UDim2.new(0, 6, 0, 26)
    frame.BackgroundTransparency = 1
    frame.Parent = parent

    local titleLbl = Instance.new("TextLabel", frame)
    titleLbl.Size = UDim2.new(0.65, 0, 0, 16)
    titleLbl.Position = UDim2.new(0, 4, 0, 0)
    titleLbl.BackgroundTransparency = 1
    titleLbl.Font = Enum.Font.GothamBold
    titleLbl.Text = translateTerm and translateTerm(textEN, textES, CurrentLang) or ((CurrentLang == "EN") and textEN or textES)
    titleLbl.TextSize = 11
    titleLbl.TextColor3 = Color3.fromRGB(210, 210, 225)
    titleLbl.TextXAlignment = Enum.TextXAlignment.Left

    local sfx = suffix or ""
    local valLbl = Instance.new("TextLabel", frame)
    valLbl.Size = UDim2.new(0.35, -4, 0, 16)
    valLbl.Position = UDim2.new(0.65, 0, 0, 0)
    valLbl.BackgroundTransparency = 1
    valLbl.Font = Enum.Font.GothamBold
    valLbl.Text = isFloat and string.format("%.2f%s", defV, sfx) or string.format("%d%s", math.floor(defV), sfx)
    valLbl.TextSize = 11
    valLbl.TextColor3 = Color3.fromRGB(255, 255, 255)
    valLbl.TextXAlignment = Enum.TextXAlignment.Right

    local track = Instance.new("Frame", frame)
    track.Size = UDim2.new(1, -8, 0, 6)
    track.Position = UDim2.new(0, 4, 0, 24)
    track.BackgroundColor3 = Color3.fromRGB(22, 22, 30)
    track.BorderSizePixel = 0
    Instance.new("UICorner", track).CornerRadius = UDim.new(1, 0)
    local trStk = Instance.new("UIStroke", track)
    trStk.Color = Color3.fromRGB(42, 42, 55)
    trStk.Thickness = 1

    local fill = Instance.new("Frame", track)
    local curPct = math.clamp((defV - minV) / (maxV - minV), 0, 1)
    fill.Size = UDim2.new(curPct, 0, 1, 0)
    fill.BackgroundColor3 = Color3.fromRGB(195, 205, 230)
    fill.BorderSizePixel = 0
    Instance.new("UICorner", fill).CornerRadius = UDim.new(1, 0)

    local knob = Instance.new("ImageButton", track)
    knob.Size = UDim2.new(0, 18, 0, 18)
    knob.Position = UDim2.new(curPct, -9, 0.5, -9)
    knob.BackgroundColor3 = Color3.fromRGB(16, 16, 22)
    knob.Image = "rbxassetid://128332470108268"
    knob.BorderSizePixel = 0
    knob.ZIndex = 5
    Instance.new("UICorner", knob).CornerRadius = UDim.new(1, 0)
    local knStk = Instance.new("UIStroke", knob)
    knStk.Color = Color3.fromRGB(240, 240, 255)
    knStk.Thickness = 1.5

    local isDragging = false
    local function updateValue(inputX)
        local absPos = track.AbsolutePosition.X
        local absSize = track.AbsoluteSize.X
        if absSize <= 0 then return end
        local pct = math.clamp((inputX - absPos) / absSize, 0, 1)
        local rawVal = minV + pct * (maxV - minV)
        if step and step > 0 then
            rawVal = math.floor(rawVal / step + 0.5) * step
        end
        rawVal = math.clamp(rawVal, minV, maxV)
        pct = (rawVal - minV) / (maxV - minV)
        fill.Size = UDim2.new(pct, 0, 1, 0)
        knob.Position = UDim2.new(pct, -9, 0.5, -9)
        valLbl.Text = isFloat and string.format("%.2f%s", rawVal, sfx) or string.format("%d%s", math.floor(rawVal), sfx)
        if callback then callback(rawVal) end
    end

    knob.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            isDragging = true
            updateValue(input.Position.X)
        end
    end)
    track.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            isDragging = true
            updateValue(input.Position.X)
        end
    end)
    UserInputService.InputChanged:Connect(function(input)
        if isDragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
            updateValue(input.Position.X)
        end
    end)
    UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            isDragging = false
        end
    end)

    table.insert(TranslatableUI, {
        label = titleLbl,
        en = textEN,
        es = textES
    })
    return frame
end
local function createCycleButton(parent, prefixEN, prefixES, choices, defaultIdx, size, pos, onChange)
    local currentIdx = defaultIdx or 1
    local btn = Instance.new("TextButton")
    btn.Size = size
    btn.Position = pos
    btn.BackgroundColor3 = Color3.fromRGB(16, 16, 22)
    btn.Font = Enum.Font.GothamBold
    local pre = translateTerm and translateTerm(prefixEN, prefixES, CurrentLang) or ((CurrentLang == "EN") and prefixEN or prefixES)
    btn.Text = ""
    btn.AutoButtonColor = true
    btn.Parent = parent
    btn.ClipsDescendants = true
    Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 7)
    local cStk = Instance.new("UIStroke", btn)
    cStk.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    cStk.Color = Color3.fromRGB(42, 42, 54)
    cStk.Thickness = 1

    local txtLbl = Instance.new("TextLabel", btn)
    txtLbl.Name = "CycleText"
    txtLbl.Size = UDim2.new(1, -26, 1, 0)
    txtLbl.Position = UDim2.new(0, 8, 0, 0)
    txtLbl.BackgroundTransparency = 1
    txtLbl.Font = Enum.Font.GothamBold
    txtLbl.Text = string.format("%s: %s", pre, tostring(choices[currentIdx]))
    txtLbl.TextSize = 11
    txtLbl.TextColor3 = Color3.fromRGB(225, 225, 240)
    txtLbl.TextXAlignment = Enum.TextXAlignment.Left
    txtLbl.TextTruncate = Enum.TextTruncate.AtEnd
    txtLbl.ZIndex = 3

    local arrowLbl = Instance.new("TextLabel", btn)
    arrowLbl.Name = "ArrowIndicator"
    arrowLbl.Size = UDim2.new(0, 16, 1, 0)
    arrowLbl.Position = UDim2.new(1, -18, 0, 0)
    arrowLbl.BackgroundTransparency = 1
    arrowLbl.Font = Enum.Font.GothamBold
    arrowLbl.Text = "v"
    arrowLbl.TextSize = 8.5
    arrowLbl.TextColor3 = Color3.fromRGB(255, 65, 75)
    arrowLbl.ZIndex = 3

    btn.MouseEnter:Connect(function()
        local curAccent = _G.CurrentAccentColor or Color3.fromRGB(65, 145, 255)
        TweenService:Create(btn, TweenInfo.new(0.12), { BackgroundColor3 = Color3.fromRGB(24, 26, 36) }):Play()
        TweenService:Create(cStk, TweenInfo.new(0.12), { Color = curAccent }):Play()
        TweenService:Create(arrowLbl, TweenInfo.new(0.12), { TextColor3 = Color3.fromRGB(240, 245, 255) }):Play()
    end)
    btn.MouseLeave:Connect(function()
        TweenService:Create(btn, TweenInfo.new(0.12), { BackgroundColor3 = Color3.fromRGB(16, 16, 22) }):Play()
        TweenService:Create(cStk, TweenInfo.new(0.12), { Color = Color3.fromRGB(42, 42, 54) }):Play()
        TweenService:Create(arrowLbl, TweenInfo.new(0.12), { TextColor3 = Color3.fromRGB(255, 65, 75) }):Play()
    end)

    table.insert(TranslatableUI, {
        btn = btn,
        txtLbl = txtLbl,
        prefixEN = prefixEN,
        prefixES = prefixES,
        getChoice = function() return tostring(choices[currentIdx]) end,
        isCycle = true
    })
    table.insert(AllUIButtons, btn)
    if isSpookyTransparentActive then
        btn.BackgroundColor3 = Color3.fromRGB(15, 15, 22)
        btn.BackgroundTransparency = _G.SpookyGlassAlpha
    end
    local lastCycleClick = 0
    local function onCycleActivated()
        local now = os.clock()
        if now - lastCycleClick < 0.12 then return end
        lastCycleClick = now
        currentIdx = (currentIdx % #choices) + 1
        local choice = choices[currentIdx]
        local p = translateTerm and translateTerm(prefixEN, prefixES, CurrentLang) or ((CurrentLang == "EN") and prefixEN or prefixES)
        txtLbl.Text = string.format("%s: %s", p, tostring(choice))
        if onChange then onChange(choice, currentIdx) end
    end
    btn.Activated:Connect(onCycleActivated)
    btn.MouseButton1Click:Connect(onCycleActivated)
    return btn
end

local function styleSpookyTextBox(box)
    if not box or not box:IsA("TextBox") then return end
    if box.Text == "TextBox" or box.Text == "textbox" then
        box.Text = ""
    end
    box.BackgroundColor3 = Color3.fromRGB(16, 16, 22)
    box.TextColor3 = Color3.fromRGB(240, 240, 250)
    box.PlaceholderColor3 = Color3.fromRGB(125, 130, 150)
    box.Font = Enum.Font.GothamMedium
    if not box:FindFirstChildOfClass("UICorner") then
        Instance.new("UICorner", box).CornerRadius = UDim.new(0, 6)
    end
    local stk = box:FindFirstChildOfClass("UIStroke")
    if not stk then
        stk = Instance.new("UIStroke", box)
    end
    stk.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    stk.Color = Color3.fromRGB(45, 45, 58)
    stk.Thickness = 1

    if not box:FindFirstChild("SovereignBoxEmblem") and not box.MultiLine then
        local emblem = Instance.new("ImageLabel", box)
        emblem.Name = "SovereignBoxEmblem"
        emblem.Size = UDim2.new(0, 16, 0, 16)
        emblem.Position = UDim2.new(1, -22, 0.5, -8)
        emblem.BackgroundTransparency = 1
        emblem.Image = "rbxassetid://128332470108268"
        emblem.ImageColor3 = Color3.fromRGB(255, 65, 75)
        emblem.ZIndex = box.ZIndex + 1
        Instance.new("UICorner", emblem).CornerRadius = UDim.new(1, 0)

        box.Focused:Connect(function()
            TweenService:Create(stk, TweenInfo.new(0.15), { Color = Color3.fromRGB(180, 195, 230) }):Play()
            TweenService:Create(emblem, TweenInfo.new(0.15), { ImageColor3 = Color3.fromRGB(255, 255, 255) }):Play()
        end)
        box.FocusLost:Connect(function()
            TweenService:Create(stk, TweenInfo.new(0.15), { Color = Color3.fromRGB(45, 45, 58) }):Play()
            TweenService:Create(emblem, TweenInfo.new(0.15), { ImageColor3 = Color3.fromRGB(255, 65, 75) }):Play()
        end)
    else
        box.Focused:Connect(function()
            TweenService:Create(stk, TweenInfo.new(0.15), { Color = Color3.fromRGB(180, 195, 230) }):Play()
        end)
        box.FocusLost:Connect(function()
            TweenService:Create(stk, TweenInfo.new(0.15), { Color = Color3.fromRGB(45, 45, 58) }):Play()
        end)
    end
end

