translateTerm = function(enText, esText, targetLang)
    if not targetLang or targetLang == "" then targetLang = CurrentLang or "EN" end
    if targetLang == "ES" and esText and esText ~= "" then return esText end
    if targetLang == "EN" and enText and enText ~= "" then return enText end
    local match = (enText and UI_DICTIONARY[enText]) or (esText and UI_DICTIONARY[esText])
    if match and match[targetLang] then
        return match[targetLang]
    end
    if targetLang == "ES" then return esText or enText or "" end
    return enText or esText or ""
end

applyLanguage = function(lang, silent)
    if lang == "ES" or lang == "EN" or lang == "PT" or lang == "TL" or lang == "FR" then
        CurrentLang = lang
    else
        CurrentLang = "EN"
    end
    _G.Spooky_CurrentLang = CurrentLang
    if _G.SpookyRefreshFloatingWidgets then _G.SpookyRefreshFloatingWidgets() end
    if _G.SpookyRefreshControlPicker then _G.SpookyRefreshControlPicker() end
    pcall(function()
        if writefile then writefile("Sovereign_lang.txt", CurrentLang) end
    end)

    if NavButtons then
        for tabId, btnData in pairs(NavButtons) do
            if btnData and btnData.lbl then
                local trans = TAB_TRANSLATIONS[tabId]
                if trans then
                    btnData.lbl.Text = trans[CurrentLang] or trans.EN or btnData.lbl.Text
                end
            end
        end
    end

    for _, item in ipairs(TranslatableUI) do
        pcall(function()
            if item.isHeader and item.label then
                item.label.Text = translateTerm(item.en, item.es, CurrentLang)
            elseif item.isToggle then
                local tr = translateTerm(item.rawEN, item.rawES, CurrentLang)
                if item.txtLbl then item.txtLbl.Text = tr end
                if item.btn then item.btn.Text = "" end
                if item.toggleName and ToggleButtons[item.toggleName] then
                    ToggleButtons[item.toggleName].text = tr
                end
            elseif item.isCycle and (item.txtLbl or item.btn) then
                local p = translateTerm(item.prefixEN, item.prefixES, CurrentLang)
                local choice = item.getChoice and item.getChoice() or ""
                if item.txtLbl then
                    item.txtLbl.Text = string.format("%s: %s", p, choice)
                else
                    item.btn.Text = string.format("  %s: %s", p, choice)
                end
            elseif item.txtLbl then
                item.txtLbl.Text = translateTerm(item.en, item.es, CurrentLang)
                if item.btn then item.btn.Text = "" end
            elseif item.label then
                item.label.Text = translateTerm(item.en, item.es, CurrentLang)
            elseif item.btn then
                item.btn.Text = translateTerm(item.en, item.es, CurrentLang)
            end
        end)
    end

    if btnDash then
        local tDash = { ES = "Panel", EN = "Dashboard", PT = "Painel", TL = "Panel", FR = "Panneau" }
        btnDash.Text = tDash[CurrentLang] or "Dashboard"
    end
    if btnCustoms then
        local tCust = { ES = "Personalizar", EN = "UI Customs", PT = "Personalizar", TL = "I-customize", FR = "Personnaliser" }
        btnCustoms.Text = tCust[CurrentLang] or "UI Customs"
    end
    if btnConfigs then
        local tConf = { ES = "Ajustes", EN = "Configs", PT = "Configuracoes", TL = "Mga Config", FR = "Configs" }
        btnConfigs.Text = tConf[CurrentLang] or "Configs"
    end
    if _G.btnTogglePicture then
        local isPic = (CurrentLang == "ES" and "Imagen: ") or (CurrentLang == "PT" and "Imagem: ") or (CurrentLang == "FR" and "Image: ") or "Picture: "
        _G.btnTogglePicture.Text = isPic .. (_G.isPictureVisible and "ON" or "OFF")
    end
    if btnToggleTransparent then
        local isTr = (CurrentLang == "ES" and "Transparente: ") or (CurrentLang == "PT" and "Transparente: ") or (CurrentLang == "FR" and "Transparent: ") or "Transparent UI: "
        btnToggleTransparent.Text = isTr .. (isSpookyTransparentActive and "ON" or "OFF")
    end
    if autoBountyMainBtn then
        local abActive = (getgenv().SpookyAutoBountyEnabled == true) or (FeatureStates["AutoBounty"] == true)
        if CurrentLang == "ES" then
            autoBountyMainBtn.Text = abActive and "Detener Auto Bounty" or "Activar Auto Bounty"
        elseif CurrentLang == "PT" then
            autoBountyMainBtn.Text = abActive and "Parar Auto Bounty" or "Ativar Auto Bounty"
        elseif CurrentLang == "FR" then
            autoBountyMainBtn.Text = abActive and "Arreter Auto Bounty" or "Activer Auto Bounty"
        elseif CurrentLang == "TL" then
            autoBountyMainBtn.Text = abActive and "Itigil ang Auto Bounty" or "Paganahin ang Auto Bounty"
        else
            autoBountyMainBtn.Text = abActive and "Stop Auto Bounty" or "Activate Auto Bounty"
        end
    end
    if fruitVBtn then
        local isBlocked = (getgenv().BlockFruitV == true)
        local fvPrefix = (CurrentLang == "ES" and "Bloquear Fruit V: ") or (CurrentLang == "PT" and "Bloquear Fruit V: ") or (CurrentLang == "FR" and "Bloquer Fruit V: ") or "Block Fruit V: "
        fruitVBtn.Text = fvPrefix .. (isBlocked and "ON" or "OFF")
    end
    if not silent then
        local msgs = {
            ES = "Idioma cambiado a Espanol",
            EN = "Language changed to English",
            PT = "Idioma alterado para Portugues",
            TL = "Wika pinalitan sa Tagalog",
            FR = "Langue changee en Francais"
        }
        notifyToggle(msgs[CurrentLang] or "Language switched", true)
    end
end
_G.Spooky_ApplyLanguage = applyLanguage
