local function CheckNearestTeleporter(targetPos)
    local pos = typeof(targetPos) == "CFrame" and targetPos.Position or targetPos
    local minDist = math.huge
    local nearest = nil
    local placeId = game.PlaceId
    local teleporters = {}
    if placeId == 7449423635 or placeId == 100117331123089 then
        teleporters = {
            ["Floating Turtle"] = Vector3.new(-12462, 375, -7552),
            ["Hydra Island"] = Vector3.new(5657.88, 1013.08, -335.50),
            Mansion = Vector3.new(-12462, 375, -7552),
            Castle = Vector3.new(-5036, 315, -3179),
            ["Temple of Time"] = Vector3.new(28286, 14897, 103)
        }
    elseif placeId == 4442272183 or placeId == 79091703265657 then
        teleporters = {
            ["Swan Mansion"] = Vector3.new(-390, 332, 673),
            ["Swan Room"] = Vector3.new(2285, 15, 905),
            ["Cursed Ship"] = Vector3.new(923, 126, 32852),
            ["Zombie Island"] = Vector3.new(-6509, 83, -133)
        }
    else
        teleporters = {
            Sky3 = Vector3.new(-7894, 5547, -380),
            ["Underwater City"] = Vector3.new(61165.19, 0.19, 1897.38),
            ["Pirate Village"] = Vector3.new(-1242.46, 4.79, 3901.28)
        }
    end
    local myHrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
    local myPos = myHrp and myHrp.Position or Vector3.zero
    for _, tpPos in pairs(teleporters) do
        local d = (tpPos - pos).Magnitude
        if d < minDist then
            minDist = d
            nearest = tpPos
        end
    end
    if minDist <= (pos - myPos).Magnitude - 150 then
        return nearest
    end
    return nil
end
local function stopIslandTween()
    _G.stopIslandTween = stopIslandTween
    isTweeningIsland = false
    activeIslandTargetCF = nil
    activeTweenTargetName = nil
    if currentIslandTween then
        pcall(function() currentIslandTween:Cancel() end)
        currentIslandTween = nil
    end
    if islandNoclipConn then
        pcall(function() islandNoclipConn:Disconnect() end)
        islandNoclipConn = nil
    end
    local char = LocalPlayer.Character
    if char then
        local pt = char:FindFirstChild("PartTele")
        if pt then pcall(function() pt:Destroy() end) end
        local hrp = char:FindFirstChild("HumanoidRootPart")
        if hrp then hrp.AssemblyLinearVelocity = Vector3.zero end
    end
    if onIslandTweenStateChanged then onIslandTweenStateChanged(false) end
    notifyToggle("Island Tween: STOPPED (OFF)", false)
end
local activeIslandTargetCF = nil
local function updateRunningIslandTweenSpeed()
    if isTweeningIsland and currentIslandTween and activeIslandTargetCF then
        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        local partTele = char and char:FindFirstChild("PartTele")
        if hrp and partTele then
            pcall(function() currentIslandTween:Cancel() end)
            local dist = (activeIslandTargetCF.Position - hrp.Position).Magnitude
            local speed = getgenv().IslandTweenSpeed or 350
            local t = math.max(dist / speed, 0.1)
            currentIslandTween = TweenService:Create(partTele, TweenInfo.new(t, Enum.EasingStyle.Linear), { CFrame = activeIslandTargetCF })
            currentIslandTween:Play()
            pcall(function()
                currentIslandTween.Completed:Connect(function(playbackState)
                    if playbackState == Enum.PlaybackState.Completed then
                        stopIslandTween()
                        notifyToggle("Arrived at " .. (activeTweenTargetName or "Island") .. "!", true)
                    end
                end)
            end)
        end
    end
end
local function startIslandTween(targetCF, islandName)
    stopIslandTween()
    local char = LocalPlayer.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hrp or not hum or (type(hum.Health) == "number" and hum.Health <= 0) then return end
    isTweeningIsland = true
    activeIslandTargetCF = targetCF
    activeTweenTargetName = islandName or "Island"
    if onIslandTweenStateChanged then onIslandTweenStateChanged(true, activeTweenTargetName) end
    notifyToggle("Tweening to " .. activeTweenTargetName .. " (ON)", true)
    pcall(function()
        local nearest = CheckNearestTeleporter(targetCF)
        if nearest then
            game:GetService("ReplicatedStorage").Remotes.CommF_:InvokeServer("requestEntrance", nearest)
            task.wait(0.4)
        end
    end)
    if not isTweeningIsland then return end
    islandNoclipConn = RunService.Stepped:Connect(function()
        if not isTweeningIsland then
            if islandNoclipConn then islandNoclipConn:Disconnect(); islandNoclipConn = nil end
            return
        end
        local c = LocalPlayer.Character
        if c then
            for _, p in ipairs(c:GetDescendants()) do
                if p:IsA("BasePart") then p.CanCollide = false end
            end
        end
    end)
    local partTele = char:FindFirstChild("PartTele")
    if not partTele then
        partTele = Instance.new("Part", char)
        partTele.Size = Vector3.new(10, 1, 10)
        partTele.Name = "PartTele"
        partTele.Anchored = true
        partTele.Transparency = 1
        partTele.CanCollide = false
        partTele.CFrame = hrp.CFrame
        partTele:GetPropertyChangedSignal("CFrame"):Connect(function()
            if isTweeningIsland and char and char:FindFirstChild("HumanoidRootPart") then
                char.HumanoidRootPart.CFrame = partTele.CFrame
                char.HumanoidRootPart.AssemblyLinearVelocity = Vector3.zero
            end
        end)
    end
    local dist = (targetCF.Position - hrp.Position).Magnitude
    local speed = getgenv().IslandTweenSpeed or 350
    local t = math.max(dist / speed, 0.1)
    currentIslandTween = TweenService:Create(partTele, TweenInfo.new(t, Enum.EasingStyle.Linear), { CFrame = targetCF })
    currentIslandTween:Play()
    pcall(function()
        if currentIslandTween and currentIslandTween.Completed and currentIslandTween.Completed.Connect then
            currentIslandTween.Completed:Connect(function(playbackState)
                if playbackState == Enum.PlaybackState.Completed then
                    stopIslandTween()
                    notifyToggle("Arrived at " .. (islandName or "Island") .. "!", true)
                end
            end)
        end
    end)
end
local ServerBrowserGui = nil
local BestServersGui = nil
local isFetchingServers = false
local function enableAntiTeleportFail()
    pcall(function()
        local CoreGui = game:GetService("CoreGui")
        local promptOverlay = CoreGui:FindFirstChild("RobloxPromptGui")
            and CoreGui.RobloxPromptGui:FindFirstChild("promptOverlay")
        if not promptOverlay then return end
        local function dismiss(v)
            if v and v.Name == "ErrorPrompt" then
                pcall(function()
                    v.Visible = false
                end)
                task.spawn(function()
                    task.wait(1)
                    local fn = _G.quickHopLowestPing or (type(quickHopLowestPing) == "function" and quickHopLowestPing)
                    if fn then fn() end
                end)
            end
        end
        for _, v in ipairs(promptOverlay:GetChildren()) do dismiss(v) end
        promptOverlay.ChildAdded:Connect(dismiss)
    end)
    pcall(function()
        TeleportService.TeleportInitFailed:Connect(function(player, teleportResult, errorMessage)
            notifyToggle("Teleport init failed. Retrying best server...", false)
            task.delay(1.5, function()
                local fn = _G.quickHopLowestPing or (type(quickHopLowestPing) == "function" and quickHopLowestPing)
                if fn then fn() end
            end)
        end)
    end)
end
local function checkInCombat()
    local inCombat = false
    pcall(function()
        local pGui = LocalPlayer:FindFirstChild("PlayerGui")
        local main = pGui and pGui:FindFirstChild("Main")
        local bList = main and main:FindFirstChild("BottomHUDList")
        local ic = bList and bList:FindFirstChild("InCombat")
        if ic and ic.Visible and ic.Text and (string.find(string.lower(ic.Text), "risk") or string.find(string.lower(ic.Text), "combat")) then
            inCombat = true
        end
    end)
    return inCombat
end
local isTeleporting = false
local function teleportToServer(jobId)
    if not jobId or jobId == "" or jobId == game.JobId then return false end
    if isTeleporting then return false end
    if checkInCombat() then
        notifyToggle("Cannot hop: In Combat (Risk)", false)
        return false
    end
    isTeleporting = true
    enableAntiTeleportFail()
    notifyToggle("Connecting to server (" .. string.sub(tostring(jobId), 1, 8) .. "...)", true)
    task.spawn(function()
        if string.find(tostring(jobId), "auto_hop") then
            pcall(function()
                TeleportService:Teleport(game.PlaceId, LocalPlayer)
            end)
            task.wait(6)
            isTeleporting = false
            return
        end
        local sb = ReplicatedStorage:FindFirstChild("__ServerBrowser")
        if sb then
            local ok = pcall(function()
                sb:InvokeServer("teleport", tostring(jobId))
            end)
            if ok then
                task.wait(6)
                isTeleporting = false
                return
            end
        end
        pcall(function()
            TeleportService:TeleportToPlaceInstance(game.PlaceId, tostring(jobId), LocalPlayer)
        end)
        task.wait(6)
        isTeleporting = false
    end)
    return true
end
local function rejoinCurrentServer()
    enableAntiTeleportFail()
    notifyToggle("Rejoining game...", true)
    local ok = false
    pcall(function()
        local sb = ReplicatedStorage:FindFirstChild("__ServerBrowser")
        if sb then
            sb:InvokeServer("teleport", game.JobId)
            ok = true
        end
    end)
    if not ok then
        pcall(function()
            TeleportService:Teleport(game.PlaceId, LocalPlayer)
        end)
    end
end
local selectedServerRegion = "United States"
local maxPlayerServerFilter = 10
local isFetchingServers = false
local cachedServerList = {}
local refreshServerDisplay = function() end
local function setServerRegion(region)
    selectedServerRegion = region or "Auto"
    pcall(function()
        local sbGui = LocalPlayer:FindFirstChild("PlayerGui") and LocalPlayer.PlayerGui:FindFirstChild("ServerBrowser")
        if sbGui and sbGui:FindFirstChild("Frame") and sbGui.Frame:FindFirstChild("Filters") and sbGui.Frame.Filters:FindFirstChild("SearchRegion") then
            sbGui.Frame.Filters.SearchRegion.TextBox.Text = (selectedServerRegion == "Auto") and "" or selectedServerRegion
        end
    end)
    notifyToggle("Region: " .. selectedServerRegion, true)
    if refreshServerDisplay then pcall(refreshServerDisplay) end
end
local function httpGetRaw(url)
    local req = (syn and syn.request) or (http and http.request) or http_request or (fluxus and fluxus.request) or request
    if req then
        local ok, r = pcall(function()
            return req({
                Url = url,
                Method = "GET",
                Headers = {
                    ["User-Agent"] = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"
                }
            })
        end)
        if ok and r and r.Body then return r.Body end
    end
    if game.HttpGet then
        local ok, res = pcall(function() return game:HttpGet(url) end)
        if ok and res and #res > 0 then return res end
    end
    return nil
end
local function fetchBestServers(onComplete)
    if isFetchingServers then
        if onComplete then onComplete(cachedServerList or {}) end
        return
    end
    isFetchingServers = true
    task.spawn(function()
        local serverList = {}
        local seenIds = {}
        local function finalize()
            table.sort(serverList, function(a, b)
                local pingA = (a.ping and a.ping > 0) and a.ping or 999
                local pingB = (b.ping and b.ping > 0) and b.ping or 999
                if pingA ~= pingB then
                    return pingA < pingB
                end
                return a.playing < b.playing
            end)
            cachedServerList = serverList
            isFetchingServers = false
            if onComplete then pcall(onComplete, serverList) end
        end
        pcall(function()
            local sbGui = LocalPlayer:FindFirstChild("PlayerGui") and LocalPlayer.PlayerGui:FindFirstChild("ServerBrowser")
            if sbGui and sbGui:FindFirstChild("Frame") and sbGui.Frame:FindFirstChild("Filters") and sbGui.Frame.Filters:FindFirstChild("SearchRegion") then
                sbGui.Frame.Filters.SearchRegion.TextBox.Text = (selectedServerRegion == "Auto") and "" or selectedServerRegion
            end
        end)
        pcall(function()
            local sb = ReplicatedStorage:FindFirstChild("__ServerBrowser")
            if sb then
                for page = 1, 8 do
                    local ok, data = pcall(function() return sb:InvokeServer(page) end)
                    if ok and type(data) == "table" then
                        for k, v in pairs(data) do
                            if type(v) == "table" and k ~= game.JobId and not seenIds[k] then
                                local cnt = tonumber(v.Count) or 0
                                if cnt > 0 and cnt < 12 then
                                    seenIds[k] = true
                                    table.insert(serverList, {
                                        id = tostring(k),
                                        playing = cnt,
                                        maxPlayers = 12,
                                        ping = 0,
                                        fps = 60,
                                        region = selectedServerRegion
                                    })
                                end
                            end
                        end
                    end
                end
            end
        end)
        pcall(function()
            local url = "https://games.roblox.com/v1/games/" .. tostring(game.PlaceId) .. "/servers/Public?sortOrder=Asc&limit=100&excludeFullGames=true"
            local res = httpGetRaw(url)
            if res then
                local parsed = HttpService:JSONDecode(res)
                if parsed and parsed.data then
                    for _, s in ipairs(parsed.data) do
                        if s.id and s.id ~= game.JobId and not seenIds[s.id] then
                            local playing = tonumber(s.playing) or 0
                            local maxPlayers = tonumber(s.maxPlayers) or 12
                            local ping = tonumber(s.ping) or 0
                            local fps = tonumber(s.fps) or 60
                            if playing < 12 then
                                seenIds[s.id] = true
                                table.insert(serverList, {
                                    id = tostring(s.id),
                                    playing = playing,
                                    maxPlayers = maxPlayers,
                                    ping = ping,
                                    fps = math.floor(fps + 0.5),
                                    region = selectedServerRegion
                                })
                            end
                        end
                    end
                end
            end
        end)
        finalize()
    end)
end
local function quickHopLowestPing(maxCount)
_G.quickHopLowestPing = quickHopLowestPing
    local maxC = maxCount or maxPlayerServerFilter or 9
    if checkInCombat() then
        notifyToggle("Cannot hop: In Combat (Risk)", false)
        return
    end
    notifyToggle("Searching optimal server...", true)
    task.spawn(function()
        local sb = ReplicatedStorage:FindFirstChild("__ServerBrowser")
        if sb then
            for page = 1, 15 do
                local ok, data = pcall(function() return sb:InvokeServer(page) end)
                if ok and type(data) == "table" then
                    for k, v in pairs(data) do
                        if k ~= game.JobId and type(v) == "table" then
                            local cnt = tonumber(v.Count) or 0
                            if cnt > 0 and cnt <= maxC then
                                notifyToggle("Found server (" .. tostring(cnt) .. " players), joining...", true)
                                pcall(function()
                                    sb:InvokeServer("teleport", tostring(k))
                                end)
                                task.wait(4)
                                return
                            end
                        end
                    end
                else
                    break
                end
            end
        end
        fetchBestServers(function(servers)
            for _, s in ipairs(servers) do
                if s.id ~= game.JobId and not string.find(tostring(s.id), "auto_hop") and s.playing <= maxC and s.playing > 0 then
                    teleportToServer(s.id)
                    return
                end
            end
            pcall(function()
                TeleportService:Teleport(game.PlaceId, LocalPlayer)
            end)
        end)
    end)
end
if type(getgenv) == "function" then
    pcall(function() getgenv().HopServer = quickHopLowestPing end)
end
