Spooky.Runtime = {}
function Spooky.Runtime.number(value, fallback, minimum, maximum)
    local n = tonumber(value)
    if not n or n ~= n or n == math.huge or n == -math.huge then n = fallback end
    return math.clamp(n, minimum, maximum)
end
function Spooky.Runtime.copy(value)
    if type(value) ~= "table" then return value end
    local result = {}
    for k, v in pairs(value) do result[k] = Spooky.Runtime.copy(v) end
    return result
end
function Spooky.Runtime.validWebhook(url)
    if type(url) ~= "string" then return false end
    return url:match("^https://discord%.com/api/webhooks/%d+/[%w_-]+$") ~= nil
        or url:match("^https://discordapp%.com/api/webhooks/%d+/[%w_-]+$") ~= nil
end
function Spooky.Runtime.httpStatus(response)
    if type(response) ~= "table" then return false, 0 end
    local status = tonumber(response.StatusCode or response.Status or response.status_code) or 0
    return status >= 200 and status < 300, status
end

do
    local VirtualInputManager = game:GetService("VirtualInputManager")
    local MacroRunning = false
    local MacroRunToken = 0

    local WeaponHelper = {}
    _G.SpookyWeaponHelper = WeaponHelper
    function WeaponHelper.toolToWeaponType(tool)
        if not tool or not tool:IsA("Tool") then return nil end
        if tool:GetAttribute("WeaponType") == "Gun" or tool:FindFirstChild("RemoteFunctionShoot") then return "Gun" end
        local tip = string.lower(tool.ToolTip or ""):gsub("%s+", " "):match("^%s*(.-)%s*$") or ""
        if tip == "melee" then return "Melee"
        elseif tip == "blox fruit" or tip == "fruit" then return "Fruit"
        elseif tip == "sword" then return "Sword"
        elseif tip == "gun" then return "Gun" end
        local name = string.lower(tool.Name)
        if name:find("katana") or name:find("blade") or name:find("saber") or name:find("sword") or name:find("dagger") or name:find("trident") or name:find("cane") or name:find("pole") or name:find("scythe") or name:find("anchor") then
            return "Sword"
        elseif name:find("rifle") or name:find("gun") or name:find("slingshot") or name:find("cannon") or name:find("bazooka") or name:find("kabucha") or name:find("guitar") then
            return "Gun"
        elseif name:find("step") or name:find("karate") or name:find("kung fu") or name:find("claw") or name:find("talon") or name:find("superhuman") or name:find("godhuman") or name:find("sanguine") or name:find("combat") then
            return "Melee"
        elseif name:find("fruit") or name:find("bomb") or name:find("spike") or name:find("chop") or name:find("spring") or name:find("smoke") or name:find("flame") or name:find("ice") or name:find("sand") or name:find("dark") or name:find("light") or name:find("magma") or name:find("quake") or name:find("buddha") or name:find("string") or name:find("phoenix") or name:find("portal") or name:find("rumble") or name:find("blizzard") or name:find("gravity") or name:find("dough") or name:find("shadow") or name:find("venom") or name:find("control") or name:find("spirit") or name:find("dragon") or name:find("leopard") or name:find("kitsune") or name:find("trex") or name:find("mammoth") or name:find("sound") or name:find("gas") or name:find("yeti") then
            return "Fruit"
        end
        return nil
    end

    function WeaponHelper.getEquippedWeaponType()
        local char = LocalPlayer.Character
        if not char then return nil, nil end
        for _, item in ipairs(char:GetChildren()) do
            if item:IsA("Tool") then
                local wType = WeaponHelper.toolToWeaponType(item)
                if wType then return wType, item end
            end
        end
        return nil, nil
    end

    function WeaponHelper.findToolByType(weaponType)
        local char = LocalPlayer.Character
        local backpack = LocalPlayer:FindFirstChildOfClass("Backpack")
        local pools = {char or false, backpack or false}
        for _, container in ipairs(pools) do
            if container then
                for _, item in ipairs(container:GetChildren()) do
                    if item:IsA("Tool") and WeaponHelper.toolToWeaponType(item) == weaponType then
                        return item
                    end
                end
            end
        end
        return nil
    end

    function WeaponHelper.getHotbarKeyForTool(tool)
        if not tool then return nil end
        local pGui = LocalPlayer:FindFirstChildOfClass("PlayerGui")
        local hotbar = pGui and pGui:FindFirstChild("Backpack") and pGui.Backpack:FindFirstChild("Hotbar")
        local container = hotbar and hotbar:FindFirstChild("Container")
        if not container then return nil end
        local slotNum = nil
        for _, elem in ipairs(container:GetDescendants()) do
            if elem:IsA("GuiObject") and elem:GetAttribute("ItemName") == tool.Name then
                slotNum = math.floor(tonumber(elem.LayoutOrder) or 0)
                if slotNum > 0 then break end
            end
        end
        local keyMap = {
            [1] = Enum.KeyCode.One, [2] = Enum.KeyCode.Two, [3] = Enum.KeyCode.Three,
            [4] = Enum.KeyCode.Four, [5] = Enum.KeyCode.Five, [6] = Enum.KeyCode.Six,
            [7] = Enum.KeyCode.Seven, [8] = Enum.KeyCode.Eight, [9] = Enum.KeyCode.Nine,
            [10] = Enum.KeyCode.Zero
        }
        return keyMap[slotNum]
    end

    function WeaponHelper.equipWeaponType(weaponType)
        if not weaponType or weaponType == "None" then return true end
        local curType = WeaponHelper.getEquippedWeaponType()
        if curType == weaponType then return true end

        local char = LocalPlayer.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local tool = WeaponHelper.findToolByType(weaponType)
        if not hum or not tool then return false end

        local hotbarKey = WeaponHelper.getHotbarKeyForTool(tool)
        if hotbarKey and VirtualInputManager then
            pcall(function()
                VirtualInputManager:SendKeyEvent(true, hotbarKey, false, game)
                task.wait(0.02)
                VirtualInputManager:SendKeyEvent(false, hotbarKey, false, game)
            end)
            local deadline = tick() + 0.18
            repeat
                if WeaponHelper.getEquippedWeaponType() == weaponType then return true end
                task.wait(0.015)
            until tick() >= deadline
        end

        pcall(function()
            hum:EquipTool(tool)
        end)
        local deadline2 = tick() + 0.25
        repeat
            if WeaponHelper.getEquippedWeaponType() == weaponType then return true end
            task.wait(0.015)
        until tick() >= deadline2
        return WeaponHelper.getEquippedWeaponType() == weaponType
    end

    function WeaponHelper.isCharacterBusyOrStunned()
        local char = LocalPlayer.Character
        if not char then return true end
        local busy = char:FindFirstChild("Busy")
        local stun = char:FindFirstChild("Stun")
        local isBusy = busy and (busy.Value == true or (tonumber(busy.Value) or 0) > 0)
        local isStun = stun and (stun.Value == true or (tonumber(stun.Value) or 0) > 0)
        return (isBusy or isStun)
    end

    function WeaponHelper.findSkillCooldown(toolName, skillKey)
        local pGui = LocalPlayer:FindFirstChildOfClass("PlayerGui")
        local main = pGui and pGui:FindFirstChild("Main")
        local skills = main and main:FindFirstChild("Skills")
        if not skills then return nil end
        local toolFrame = skills:FindFirstChild(toolName or "")
        if not toolFrame then
            local normalized = string.lower(toolName or ""):gsub("[^%w]", "")
            for _, child in ipairs(skills:GetChildren()) do
                local cn = string.lower(child.Name):gsub("[^%w]", "")
                if cn == normalized or cn == normalized .. normalized then
                    toolFrame = child
                    break
                end
            end
        end
        local skillFrame = toolFrame and toolFrame:FindFirstChild(tostring(skillKey or ""))
        local cdFrame = skillFrame and skillFrame:FindFirstChild("Cooldown")
        if cdFrame and cdFrame:IsA("GuiObject") then return cdFrame end
        return nil
    end

    function WeaponHelper.isSkillOnCooldown(toolName, skillKey)
        local cd = WeaponHelper.findSkillCooldown(toolName, skillKey)
        if not cd or not cd.Parent or not cd.Visible then return false end
        local sx = cd.Size.X
        return (math.abs(sx.Scale) > 0.005 or math.abs(sx.Offset) > 2)
    end

    function WeaponHelper.isTransformed()
        local char = LocalPlayer.Character
        if not char then return false end
        local attrs = {"Transformed", "Transformation", "IsTransformed", "FruitTransformed"}
        for _, attr in ipairs(attrs) do
            if char:GetAttribute(attr) == true then return true end
        end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum and hum.HipHeight > 3.5 then return true end
        return false
    end

    local activeContext
    Spooky.IsMacroRunning=function() return MacroRunning end
    local syntheticKeys = {}
    _G.IsSyntheticKey = function(key)
        local name = typeof(key) == "EnumItem" and key.Name or tostring(key)
        if (syntheticKeys[name] or 0) > os.clock() then return true end
        return false
    end
    Spooky.IsMacroSyntheticKey = _G.IsSyntheticKey

    local function status(text, running)
        for _, label in pairs({_G.MacroStatusLabel or false, _G.MacroFloatingStatus or false}) do
            if label and label.Parent then
                label.Text = text
                label.TextColor3 = running and Color3.fromRGB(255, 170, 70) or Color3.fromRGB(130, 230, 255)
            end
        end
    end
    local function release(ctx)
        if not ctx then return end
        for key in pairs(ctx.keys) do
            syntheticKeys[key.Name] = os.clock() + 0.15
            pcall(function() VirtualInputManager:SendKeyEvent(false, key, false, game) end)
            ctx.keys[key] = nil
        end
        if ctx.tool then pcall(function() ctx.tool:Deactivate() end); ctx.tool = nil end
    end
    local function stopMacro(reason)
        MacroRunning = false
        MacroRunToken += 1
        local ctx = activeContext
        activeContext = nil
        release(ctx)
        status("READY [" .. (Settings.macroTriggerKey or "T") .. "]", false)
    end
    _G.SpookyStopMacro = function()
        stopMacro("Stopped")
        if _G.SpookyStopLegacyMacro then _G.SpookyStopLegacyMacro() end
    end
    registerConnection(LocalPlayer.CharacterRemoving:Connect(function() _G.SpookyStopMacro() end))

    executeMacroCombo = function()
        if MacroRunning then stopMacro("Stopped"); return end
        if UserInputService:GetFocusedTextBox() or not isCurrentSession() then return end
        if _G.SpookyStopLegacyMacro then _G.SpookyStopLegacyMacro() end
        local char = LocalPlayer.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not hum or hum.Health <= 0 then return end
        local index = math.floor(Spooky.Runtime.number(Settings.macroActiveSlot, 1, 1, 5))
        local source = (Settings.macroSlots or {})[index]
        local slot = Spooky.Runtime.copy(source or {steps = Settings.macroCustomSteps or {}})
        local steps = slot.steps or {}
        MacroRunToken += 1
        MacroRunning = true
        local ctx = {token = MacroRunToken, keys = {}, character = char, loop = Settings.macroLoop == true}
        activeContext = ctx
        status("RUNNING SLOT " .. index, true)
        task.spawn(function()
            local function valid()
                return activeContext == ctx and MacroRunning and MacroRunToken == ctx.token
                    and isCurrentSession() and LocalPlayer.Character == char and hum.Parent and hum.Health > 0
            end
            local function waitFor(seconds)
                local deadline = os.clock() + Spooky.Runtime.number(seconds, 0, 0, 10)
                while valid() and os.clock() < deadline do
                    task.wait(math.min(0.02, deadline - os.clock()))
                end
                return valid()
            end
            local function press(name, seconds)
                if not valid() then return false end
                local key = Enum.KeyCode[name]
                if not key then return false end
                ctx.keys[key] = true
                syntheticKeys[name] = os.clock() + seconds + 0.2
                if _G.MarkSyntheticKey then _G.MarkSyntheticKey(name, seconds + 0.2) end
                local ok = pcall(function() VirtualInputManager:SendKeyEvent(true, key, false, game) end)
                if ok then waitFor(seconds) end

                if ctx.keys[key] then
                    pcall(function() VirtualInputManager:SendKeyEvent(false, key, false, game) end)
                    ctx.keys[key] = nil
                end
                return ok and valid()
            end
            local function ready()
                local deadline = os.clock() + 1.5
                while valid() and WeaponHelper.isCharacterBusyOrStunned() and os.clock() < deadline do waitFor(0.02) end
                return valid() and not WeaponHelper.isCharacterBusyOrStunned()
            end
            local function equip(weapon)
                if not valid() then return false end

                local tool = WeaponHelper.findToolByType(weapon)
                if not tool then return false end
                if tool.Parent ~= char then hum:EquipTool(tool) end
                local deadline = os.clock() + 0.4
                while valid() and tool.Parent ~= char and os.clock() < deadline do waitFor(0.02) end
                return valid() and tool.Parent == char, tool
            end
            local function m1(weapon, count)
                if not ready() then return end
                local ok, tool = equip(weapon or "Melee")
                if not ok then return end
                for _ = 1, math.floor(Spooky.Runtime.number(count, 2, 1, 6)) do
                    if not valid() then break end
                    ctx.tool = tool
                    tool:Activate()
                    waitFor(0.035)
                    if ctx.tool == tool then tool:Deactivate(); ctx.tool = nil end
                    if not waitFor(0.08) then break end
                end
            end
            local function extras(position)
                if not valid() then return end
                if slot.soruEnabled and Spooky.Runtime.number(slot.soruAfter, 0, 0, 10) == position and ready() then
                    press("R", 0.04); waitFor(0.12)
                end
                if slot.m1Enabled and Spooky.Runtime.number(slot.m1After, 0, 0, 10) == position then m1(slot.m1Weapon, slot.m1Count) end
                if slot.v3Enabled and Spooky.Runtime.number(slot.v3After, 0, 0, 10) == position and ready() then
                    local remotes = ReplicatedStorage:FindFirstChild("Remotes")
                    local remote = remotes and remotes:FindFirstChild("CommE")
                    if remote then remote:FireServer("ActivateAbility") end
                    waitFor(0.08)
                end
            end
            local function choose(block)
                local weapon, skill = block.weapon, tostring(block.skill or ""):upper()
                local tool = WeaponHelper.findToolByType(weapon)
                if tool and not WeaponHelper.isSkillOnCooldown(tool.Name, skill) then
                    return weapon, skill, block.mode, block.hold
                end
                if block.fallbackEnabled then
                    weapon, skill = block.fallbackWeapon, tostring(block.fallbackSkill or ""):upper()
                    tool = WeaponHelper.findToolByType(weapon)
                    if tool and not WeaponHelper.isSkillOnCooldown(tool.Name, skill) then
                        return weapon, skill, block.fallbackMode, block.fallbackHold
                    end
                elseif tool then
                    local deadline = os.clock() + 1.5
                    while valid() and WeaponHelper.isSkillOnCooldown(tool.Name, skill) and os.clock() < deadline do waitFor(0.02) end
                    if valid() and not WeaponHelper.isSkillOnCooldown(tool.Name, skill) then
                        return weapon, skill, block.mode, block.hold
                    end
                end
            end
            local ok, err = pcall(function()
                local trigger = Enum.KeyCode[Settings.macroTriggerKey or "T"]
                local deadline = os.clock() + 0.5
                while trigger and valid() and UserInputService:IsKeyDown(trigger) and os.clock() < deadline do waitFor(0.02) end
                repeat
                    extras(0)
                    for i = 1, 10 do
                        if not valid() then break end
                        local block = steps[i]
                        if type(block) == "table" and block.enabled and ready() then
                            local weapon, skill, mode, hold = choose(block)
                            if weapon and equip(weapon) and valid() then
                                if skill == "TAP" or skill == "M1" then
                                    m1(weapon, 1)
                                elseif skill:match("^[ZXCVF]$") then
                                    mode = tostring(mode or (hold == true and "Hold" or "Tap")):lower()
                                    local transform = mode == "transform"
                                    local tool = char:FindFirstChildOfClass("Tool")
                                    local name = tool and tool.Name:lower():gsub("[^%w]", "") or ""
                                    local forms = {dragon=true,gas=true,kitsune=true,leopard=true,mammoth=true,phoenix=true,tiger=true,trex=true,venom=true,yeti=true,empyrean=true,fiend=true,werewolf=true,buddha=true}
                                    local transformOK = not transform or (weapon == "Fruit" and skill == "V" and forms[name] and not WeaponHelper.isTransformed())
                                    if transformOK and ready() then
                                        local duration = mode == "hold" and Spooky.Runtime.number(hold, 0.35, 0.03, 5) or 0.05
                                        press(skill, duration)
                                        if valid() then
                                            for _ = 1, math.floor(Spooky.Runtime.number(block.jumpsAfter or block.postJumps, 0, 0, 5)) do
                                                if not press("Space", 0.035) then break end
                                                waitFor(0.08)
                                            end
                                        end
                                    end
                                end
                                waitFor(Spooky.Runtime.number(block.delay, 0.12, 0, 5))
                            end
                        end
                        extras(i)
                    end
                    if ctx.loop then waitFor(0.1) end
                until not ctx.loop or not valid()
            end)
            if activeContext == ctx then
                stopMacro(ok and "Completed" or "Error")
                if not ok then warn("[Zen Macro] " .. tostring(err)); status("STOPPED: playback error", false) end
            end
        end)
    end
    _G.ExecuteMacroCombo = executeMacroCombo
end

local MacroEditorGui = nil
local SelectedSoruTarget = "Nearest"
local function getClientPing()
    local ping = nil
    pcall(function()
        if LocalPlayer and LocalPlayer.GetNetworkPing then
            local p = LocalPlayer:GetNetworkPing()
            if p and p > 0 then
                ping = p * 1000
            end
        end
    end)
    if not ping then
        pcall(function()
            local stats = game:GetService("Stats")
            local net = stats:FindFirstChild("Network")
            local item = net and net:FindFirstChild("ServerStatsItem") and net.ServerStatsItem:FindFirstChild("Data Ping")
            if item then
                local str = item:GetValueString()
                local num = tonumber(str:match("[%d%.]+"))
                if num then ping = num end
            end
        end)
    end
    if not ping then
        pcall(function()
            local ps = game:GetService("Stats"):FindFirstChild("PerformanceStats")
            local p = ps and ps:FindFirstChild("Ping")
            if p then ping = p:GetValue() end
        end)
    end
    return math.clamp(ping or 45, 8, 999)
end
local function getToolCategory(tool)
    if not tool then return "Melee" end
    local tName = string.lower(tool.Name)
    local tt = ""
    pcall(function()
        local tip=tool.ToolTip
        if not tip or tip=="" then tip=tool:GetAttribute("Type") or tool:GetAttribute("WeaponType") end
        tt=string.lower(tostring(tip or ""))
    end)
    if string.find(tt, "sword") or string.find(tt, "espada") then return "Sword" end
    if string.find(tt, "gun") or string.find(tt, "pistola") or string.find(tt, "arma") then return "Gun" end
    if string.find(tt, "fruit") or string.find(tt, "bloxfruit") or string.find(tt, "fruta") then return "Fruit" end
    if string.find(tt, "melee") or string.find(tt, "combat") then return "Melee" end
    local swordKeywords = {
        "sword", "blade", "katana", "yoru", "cursed", "scythe", "saber", "pole", "bisento",
        "trident", "dagger", "anchor", "lamp", "tushita", "yama", "rengoku", "wando", "shisui",
        "saddi", "canvander", "cavander", "koko", "cane", "jitte", "pipe", "mace", "cutlass",
        "hallow", "warden", "dragon trident", "spikey trident", "dark blade", "triple katana", "dual katana"
    }
    for _, sk in ipairs(swordKeywords) do
        if string.find(tName, sk) then return "Sword" end
    end
    local gunKeywords = {
        "guitar", "rifle", "flintlock", "kabucha", "slingshot", "bazooka", "cannon", "gun",
        "serpent bow", "bow", "acidum", "musket", "bizarre", "dragonstorm"
    }
    for _, gk in ipairs(gunKeywords) do
        if string.find(tName, gk) then return "Gun" end
    end
    local meleeKeywords = {
        "godhuman", "electric claw", "superhuman", "dragon talon", "death step", "sharkman karate",
        "combat", "black leg", "electro", "fishman karate", "dragon breath", "sanguine art", "sanguine"
    }
    for _, mk in ipairs(meleeKeywords) do
        if string.find(tName, mk) then return "Melee" end
    end
    local isFruit = string.find(tName, "fruit") or tool:FindFirstChild("Fruit") ~= nil
    if not isFruit and string.find(tName, "-") then
        local firstPart, secondPart = tName:match("^([%w%s]+)%-(%w+)$")
        if firstPart and secondPart and (firstPart:find(secondPart) or secondPart:find(firstPart)) then
            isFruit = true
        end
    end
    local fruitKeywords = {
        "portal", "dough", "dragon", "leopard", "kitsune", "buddha", "t-rex", "trex",
        "mammoth", "sound", "blizzard", "spirit", "venom", "shadow", "control", "gravity",
        "rumble", "paw", "spider", "love", "quake", "magma", "light", "ice", "flame",
        "dark", "sand", "falcon", "diamond", "rubber", "barrier", "ghost", "spin", "chop",
        "spring", "bomb", "smoke", "rocket"
    }
    if not isFruit then
        for _, kw in ipairs(fruitKeywords) do
            if string.find(tName, kw) then
                isFruit = true
                break
            end
        end
    end
    if isFruit then return "Fruit" end
    return "Melee"
end
do
    local SanguineNoLagGui = nil
    local sanguineZConn = nil
    local function doSanguineNoLagBoost()
        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        local camera = workspace.CurrentCamera
        if not hrp or not camera then return end
        local dir = camera.CFrame.LookVector
        local att = Instance.new("Attachment", hrp)
        local lv = Instance.new("LinearVelocity", hrp)
        lv.MaxForce = math.huge
        lv.VelocityConstraintMode = Enum.VelocityConstraintMode.Vector
        lv.VectorVelocity = dir * 400
        lv.Attachment0 = att
        task.delay(0.9, function()
            if lv and lv.Parent then lv:Destroy() end
            if att and att.Parent then att:Destroy() end
        end)
    end
    local function activateZButtonVisual(zBtn)
        if not FeatureStates["ZMeleeNoCd"] and zBtn:GetAttribute("Cooldown") then return end
        zBtn:SetAttribute("Cooldown", true)
        doSanguineNoLagBoost()
        zBtn.Text = "!"
        zBtn.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        zBtn.TextColor3 = Color3.fromRGB(0, 0, 0)
        task.wait(0.35)
        zBtn.Text = "Z"
        zBtn.BackgroundColor3 = Color3.fromRGB(36, 36, 42)
        zBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
        zBtn:SetAttribute("Cooldown", false)
    end
    local function createSanguineNoLagWidget()
        if SanguineNoLagGui and SanguineNoLagGui.Parent then SanguineNoLagGui:Destroy() end
        if sanguineZConn then sanguineZConn:Disconnect(); sanguineZConn = nil end
        local gui = Instance.new("ScreenGui")
        gui.Name = "SanguineNoLagBoostWidget"
        gui.ResetOnSpawn = false
        gui.DisplayOrder = 9998
        safeParent(gui)
        SanguineNoLagGui = gui

        local card = Instance.new("Frame", gui)
        card.Size = UDim2.new(0, 60, 0, 34)
        card.Position = UDim2.new(0.37, 0, 0.26, 0)
        card.BackgroundColor3 = Color3.fromRGB(16, 16, 18)
        card.Active = true
        Instance.new("UICorner", card).CornerRadius = UDim.new(0, 9)
        local cStroke = Instance.new("UIStroke", card)
        cStroke.Thickness = 1.2
        cStroke.Color = Color3.fromRGB(36, 36, 42)

        local titleLbl = Instance.new("TextLabel", card)
        titleLbl.Size = UDim2.new(1, 0, 1, 0)
        titleLbl.BackgroundTransparency = 1
        titleLbl.Font = Enum.Font.GothamBold
        titleLbl.Text = "Z BOOST"
        titleLbl.TextColor3 = Color3.fromRGB(255, 255, 255)
        titleLbl.TextSize = 11
        titleLbl.TextXAlignment = Enum.TextXAlignment.Center

        local zBtn = Instance.new("TextButton", card)
        zBtn.Size = UDim2.new(1, 0, 1, 0)
        zBtn.BackgroundTransparency = 1
        zBtn.Text = ""

        local zIsPressed, zDragging, zDragStart, zStartPos, zHasMoved = false, false, nil, nil, false
        zBtn.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                zIsPressed = true
                zHasMoved = false
                zDragStart = input.Position
                zStartPos = card.Position
                local isLocked = _G.SpookyLockFloatingButtons or (FeatureStates and FeatureStates["LockFloatingButtons"])
                zDragging = not isLocked
            end
        end)
        UserInputService.InputChanged:Connect(function(input)
            local isLocked = _G.SpookyLockFloatingButtons or (FeatureStates and FeatureStates["LockFloatingButtons"])
            if isLocked then zDragging = false return end
            if zDragging and zDragStart and zStartPos and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
                local delta = input.Position - zDragStart
                if delta.Magnitude > 5 then zHasMoved = true end
                card.Position = UDim2.new(zStartPos.X.Scale, zStartPos.X.Offset + delta.X, zStartPos.Y.Scale, zStartPos.Y.Offset + delta.Y)
            end
        end)
        UserInputService.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                if zIsPressed then
                    zIsPressed = false
                    zDragging = false
                    if not zHasMoved then
                        activateZButtonVisual(zBtn)
                    end
                end
            end
        end)
        sanguineZConn = UserInputService.InputBegan:Connect(function(input, gpe)
            if gpe or isSimulatingKeys or (_G.IsSyntheticKey and _G.IsSyntheticKey(input.KeyCode)) then return end
            if input.KeyCode == Enum.KeyCode.Z and FeatureStates["SanguineZBoost"] then
                activateZButtonVisual(zBtn)
            end
        end)
    end
