    local SuperJumpGui = nil
    local isSuperJumping = false
    local superJumpBtn = nil
    local function doSuperJump()
        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not hrp or not hum or hum.Health <= 0 then return end
        hum.PlatformStand = false
        hum.Sit = false
        local jumpHeight = math.clamp(tonumber(Settings.superJumpHeight) or 500, 150, 3000)
        pcall(function()
            hum.JumpPower = 50
            hum.JumpHeight = 7.2
        end)
        local curV = hrp.AssemblyLinearVelocity
        local moveDir = hum.MoveDirection
        local hSpeed = 45
        local targetX = (moveDir.Magnitude > 0.1) and (moveDir.X * hSpeed) or curV.X
        local targetZ = (moveDir.Magnitude > 0.1) and (moveDir.Z * hSpeed) or curV.Z

        hum:ChangeState(Enum.HumanoidStateType.Jumping)
        hrp.AssemblyLinearVelocity = Vector3.new(targetX, jumpHeight, targetZ)

        task.defer(function()
            if hrp and hrp.Parent then
                hrp.AssemblyLinearVelocity = Vector3.new(targetX, jumpHeight, targetZ)
            end
        end)
        task.delay(0.04, function()
            if hrp and hrp.Parent and hrp.AssemblyLinearVelocity.Y < (jumpHeight * 0.7) then
                hrp.AssemblyLinearVelocity = Vector3.new(hrp.AssemblyLinearVelocity.X, jumpHeight, hrp.AssemblyLinearVelocity.Z)
            end
            pcall(function()
                if hum and hum.Parent then
                    hum.JumpPower = 50
                    hum.JumpHeight = 7.2
                end
            end)
        end)

        if not isSuperJumping then
            isSuperJumping = true
            task.spawn(function()
                local t0 = tick()
                local apex = false
                while tick() - t0 < 8 do
                    task.wait(0.06)
                    local c = LocalPlayer.Character
                    local h = c and c:FindFirstChild("HumanoidRootPart")
                    local hm = c and c:FindFirstChildOfClass("Humanoid")
                    if not h or not hm or hm.Health <= 0 then break end
                    local velY = h.AssemblyLinearVelocity.Y
                    if velY < 0 then apex = true end
                    if apex and velY < -60 then
                        local params = RaycastParams.new()
                        params.FilterDescendantsInstances = { c }
                        params.FilterType = Enum.RaycastFilterType.Exclude
                        local ray = workspace:Raycast(h.Position, Vector3.new(0, -35, 0), params)
                        if ray then
                            h.AssemblyLinearVelocity = Vector3.new(h.AssemblyLinearVelocity.X, -20, h.AssemblyLinearVelocity.Z)
                            hm.PlatformStand = false
                            hm.Sit = false
                            hm:ChangeState(Enum.HumanoidStateType.Running)
                            break
                        end
                    end
                    if apex and (hm.FloorMaterial ~= Enum.Material.Air or hm:GetState() == Enum.HumanoidStateType.Landed) then
                        hm.PlatformStand = false
                        hm.Sit = false
                        hm:ChangeState(Enum.HumanoidStateType.Running)
                        break
                    end
                end
                local c = LocalPlayer.Character
                local hm = c and c:FindFirstChildOfClass("Humanoid")
                if hm and hm.Health > 0 then
                    hm.PlatformStand = false
                    hm.Sit = false
                    if hm:GetState() == Enum.HumanoidStateType.Freefall or hm:GetState() == Enum.HumanoidStateType.PlatformStanding or hm:GetState() == Enum.HumanoidStateType.Physics then
                        hm:ChangeState(Enum.HumanoidStateType.Running)
                    end
                    pcall(function()
                        hm.JumpPower = 50
                        hm.JumpHeight = 7.2
                    end)
                end
                isSuperJumping = false
            end)
        end
    end
    local function createSuperJumpWidget()
        if SuperJumpGui and SuperJumpGui.Parent then pcall(function() SuperJumpGui:Destroy() end) end
        local gui = Instance.new("ScreenGui")
        gui.Name = "SuperJumpWidget"
        gui.ResetOnSpawn = false
        gui.DisplayOrder = 9998
        gui.IgnoreGuiInset = true
        safeParent(gui)
        if (not gui.Parent or not gui.Parent:IsDescendantOf(game)) and LocalPlayer then
            gui.Parent = LocalPlayer:FindFirstChildOfClass("PlayerGui") or LocalPlayer:FindFirstChild("PlayerGui")
        end
        SuperJumpGui = gui

        local card = Instance.new("Frame", gui)
        card.Name = "SuperJumpCard"
        card.Size = UDim2.new(0, 84, 0, 36)
        card.Position = UDim2.new(0.68, 0, 0.25, 0)
        card.BackgroundColor3 = Color3.fromRGB(18, 18, 24)
        card.BorderSizePixel = 0
        card.Active = true
        Instance.new("UICorner", card).CornerRadius = UDim.new(0, 10)

        local curAccent = _G.CurrentAccentColor or Color3.fromRGB(65, 145, 255)
        local cStroke = Instance.new("UIStroke", card)
        cStroke.Thickness = 1.4
        cStroke.Color = curAccent

        local titleLbl = Instance.new("TextLabel", card)
        titleLbl.Size = UDim2.new(1, 0, 1, 0)
        titleLbl.Position = UDim2.new(0, 0, 0, 0)
        titleLbl.BackgroundTransparency = 1
        titleLbl.Font = Enum.Font.GothamBold
        titleLbl.Text = "▲ JUMP"
        titleLbl.TextColor3 = Color3.fromRGB(255, 255, 255)
        titleLbl.TextSize = 12.5
        titleLbl.TextXAlignment = Enum.TextXAlignment.Center
        titleLbl.TextYAlignment = Enum.TextYAlignment.Center
        titleLbl.ZIndex = 4

        local btn = Instance.new("TextButton", card)
        btn.Size = UDim2.new(1, 0, 1, 0)
        btn.BackgroundTransparency = 1
        btn.Text = ""
        btn.AutoButtonColor = false
        btn.ZIndex = 10

        local isPressed = false
        local dragging = false
        local dragStart = nil
        local startPos = nil
        local hasMoved = false

        local function updateDrag(input)
            local isLocked = _G.SpookyLockFloatingButtons or (FeatureStates and FeatureStates["LockFloatingButtons"])
            if isLocked then
                dragging = false
                return
            end
            if dragging and dragStart and startPos then
                local delta = input.Position - dragStart
                if delta.Magnitude > 6 then
                    hasMoved = true
                end
                card.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
            end
        end

        local function endDrag()
            if isPressed then
                isPressed = false
                dragging = false
                if not hasMoved then
                    TweenService:Create(card, TweenInfo.new(0.1), { BackgroundColor3 = Color3.fromRGB(35, 35, 50) }):Play()
                    task.delay(0.12, function()
                        if card and card.Parent then
                            TweenService:Create(card, TweenInfo.new(0.15), { BackgroundColor3 = Color3.fromRGB(18, 18, 24) }):Play()
                        end
                    end)
                    doSuperJump()
                end
            end
        end

        btn.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                isPressed = true
                hasMoved = false
                dragStart = input.Position
                startPos = card.Position
                local isLocked = _G.SpookyLockFloatingButtons or (FeatureStates and FeatureStates["LockFloatingButtons"])
                dragging = not isLocked
                input.Changed:Connect(function()
                    if input.UserInputState == Enum.UserInputState.End then
                        endDrag()
                    end
                end)
            end
        end)

        btn.InputChanged:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
                updateDrag(input)
            end
        end)

        UserInputService.InputChanged:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
                updateDrag(input)
            end
        end)

        btn.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                endDrag()
            end
        end)

        UserInputService.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                endDrag()
            end
        end)
    end

