    local waterPlatform = nil
    local function getWaterPlatform()
        if not waterPlatform or not waterPlatform.Parent then
            waterPlatform = Instance.new("Part")
            waterPlatform.Size = Vector3.new(200, 1, 200)
            waterPlatform.Transparency = 1
            waterPlatform.Anchored = true
            waterPlatform.CanCollide = false
            waterPlatform.Name = "SovereignWaterPlatform"
            waterPlatform.Parent = workspace
        end
        return waterPlatform
    end

    FeatureCallbacks["WalkOnWater"] = function(v)
        FeatureStates["WalkOnWater"] = v
        if not v then
            if waterPlatform and waterPlatform.Parent then
                waterPlatform.CanCollide = false
            end
            pcall(function()
                local waterPlane = workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("WaterBase-Plane")
                if waterPlane then
                    waterPlane.CanCollide = false
                    waterPlane.Size = Vector3.new(1000, 80, 1000)
                end
            end)
        end
        notifyToggle((CurrentLang == "ES") and ("Caminar en Agua: " .. (v and "ON" or "OFF")) or ("Walk on Water: " .. (v and "ON" or "OFF")), v)
    end

    local noclipSteppedConnection = nil
    local function applyNoclipToCharacter(char)
        if not char then return end
        local cached = _G.cachedCharacterParts
        if cached and #cached > 0 then
            for i = 1, #cached do
                local p = cached[i]
                if p and p.CanCollide then p.CanCollide = false end
            end
        else
            for _, p in ipairs(char:GetDescendants()) do
                if p:IsA("BasePart") and p.CanCollide then p.CanCollide = false end
            end
        end
    end

    local function restoreCharacterCollisions(char)
        if not char then return end
        for _, p in ipairs(char:GetDescendants()) do
            if p:IsA("BasePart") and p.Name ~= "HumanoidRootPart" then
                p.CanCollide = true
            end
        end
    end

    local function setNoclipState(enable)
        FeatureStates["NoClip"] = enable
        FeatureStates["Noclip"] = enable
        if enable then
            if not noclipSteppedConnection then
                noclipSteppedConnection = RunService.Stepped:Connect(function()
                    if not (FeatureStates["NoClip"] or FeatureStates["Noclip"]) then
                        if noclipSteppedConnection then
                            noclipSteppedConnection:Disconnect()
                            noclipSteppedConnection = nil
                        end
                        return
                    end
                    local char = LocalPlayer.Character
                    if char then
                        applyNoclipToCharacter(char)
                    end
                end)
            end
        else
            if noclipSteppedConnection then
                noclipSteppedConnection:Disconnect()
                noclipSteppedConnection = nil
            end
            local char = LocalPlayer.Character
            if char then
                restoreCharacterCollisions(char)
            end
        end
    end

    FeatureCallbacks["NoClip"] = function(v)
        setNoclipState(v)
        notifyToggle((CurrentLang == "ES") and ("Atravesar Paredes: " .. (v and "ON" or "OFF")) or ("Noclip: " .. (v and "ON" or "OFF")), v)
    end
    FeatureCallbacks["Noclip"] = FeatureCallbacks["NoClip"]

    FeatureCallbacks["AvatarNoCollide"] = function(v)
        FeatureStates["AvatarNoCollide"] = v
        local char = LocalPlayer.Character
        if char and v then
            for _, acc in ipairs(char:GetChildren()) do
                if acc:IsA("Accessory") then
                    local handle = acc:FindFirstChild("Handle")
                    if handle and handle:IsA("BasePart") then
                        handle.CanCollide = false
                    end
                end
            end
        end
        notifyToggle((CurrentLang == "ES") and ("Sin Colision Accesorios: " .. (v and "ON" or "OFF")) or ("No-Collide Accessories: " .. (v and "ON" or "OFF")), v)
    end

    local function rebuildCachedCharacterParts(char)
        local parts = {}
        if char then
            for _, p in ipairs(char:GetDescendants()) do
                if p:IsA("BasePart") then
                    table.insert(parts, p)
                end
            end
        end
        _G.cachedCharacterParts = parts
        return parts
    end

