    local ShipModGui = nil
    local currentShipFound = nil
    local function findCurrentPlayerShip()
        local char = LocalPlayer.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if not root then return nil end
        local rootPos = root.Position
        local closestSeat, minDist = nil, math.huge

        local function checkSeat(obj)
            if obj:IsA("VehicleSeat") or obj:IsA("Seat") then
                local dist = (obj.Position - rootPos).Magnitude
                if dist < minDist and dist <= 120 then
                    minDist = dist
                    closestSeat = obj
                end
            end
        end

        local boats = workspace:FindFirstChild("Boats")
        if boats then
            for _, obj in ipairs(boats:GetDescendants()) do
                checkSeat(obj)
            end
        end

        if not closestSeat then
            for _, model in ipairs(workspace:GetChildren()) do
                if model:IsA("Model") and model ~= char and model.Parent ~= workspace:FindFirstChild("Characters") then
                    local primary = model.PrimaryPart or model:FindFirstChildWhichIsA("BasePart")
                    if primary and (primary.Position - rootPos).Magnitude <= 100 then
                        for _, child in ipairs(model:GetChildren()) do
                            checkSeat(child)
                        end
                    end
                end
            end
        end

        if closestSeat then
            local model = closestSeat:FindFirstAncestorOfClass("Model")
            if model and model ~= char and model.Parent ~= workspace:FindFirstChild("Characters") then
                currentShipFound = model
                return model
            end
        end
        return nil
    end
