    _G.__SyntheticKeys = _G.__SyntheticKeys or {}
    local function markSyntheticKey(key, duration)
        local keyName = typeof(key) == "EnumItem" and key.Name or tostring(key or "")
        if keyName ~= "" then
            _G.__SyntheticKeys[keyName] = tick() + (duration or 2.5)
        end
    end
    local function isSyntheticKey(key)
        local keyName = typeof(key) == "EnumItem" and key.Name or tostring(key or "")
        return tick() < (_G.__SyntheticKeys[keyName] or 0)
    end
    _G.MarkSyntheticKey = markSyntheticKey
    _G.IsSyntheticKey = function(key)
        return (Spooky.IsMacroSyntheticKey and Spooky.IsMacroSyntheticKey(key)) or isSyntheticKey(key)
    end

    local CooldownCache = {}
    local function findSmartCooldown(toolName, skillKey)
        local cacheKey = tostring(toolName or "") .. "__" .. tostring(skillKey or "")
        local cached = CooldownCache[cacheKey]
        if cached then
            local ok, p = pcall(function() return cached.Parent end)
            if ok and p then return cached end
            CooldownCache[cacheKey] = nil
        end
        local ok, result = pcall(function()
            local playerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui") or LocalPlayer:FindFirstChild("PlayerGui")
            local main = playerGui and playerGui:FindFirstChild("Main")
            local skills = main and main:FindFirstChild("Skills")
            if not skills then return nil end
            local toolSkills = skills:FindFirstChild(toolName or "")
            if not toolSkills then
                local cleanTool = tostring(toolName or ""):lower():gsub("[^%w]", "")
                if cleanTool == "" then return nil end
                for _, child in ipairs(skills:GetChildren()) do
                    local cleanChild = child.Name:lower():gsub("[^%w]", "")
                    if cleanChild == cleanTool or string.find(cleanChild, cleanTool) then
                        toolSkills = child
                        break
                    end
                end
            end
            local skillFrame = toolSkills and toolSkills:FindFirstChild(tostring(skillKey or ""))
            local cooldown = skillFrame and skillFrame:FindFirstChild("Cooldown")
            if cooldown and cooldown:IsA("GuiObject") then
                CooldownCache[cacheKey] = cooldown
                return cooldown
            end
            return nil
        end)
        return ok and result or nil
    end

    local function isSkillReady(toolName, skillKey)
        local ok, ready = pcall(function()
            local cd = findSmartCooldown(toolName, skillKey)
            if not cd then return true end
            if not cd.Visible then return true end
            return (cd.Size.X.Scale <= 0.05)
        end)
        return (not ok) or ready
    end

    local function getSkillCooldownScale(toolName, skillKey)
        local ok, scale = pcall(function()
            local cd = findSmartCooldown(toolName, skillKey)
            if not cd or not cd.Visible then return 0 end
            return cd.Size.X.Scale
        end)
        return ok and scale or 0
    end

    local function waitForSmartCooldown(toolName, skillKey, maxTimeout)
        local scale = getSkillCooldownScale(toolName, skillKey)
        if scale <= 0.05 then return true end
        local timeout = (scale <= 0.20) and math.max(maxTimeout or 1.2, 1.8) or (maxTimeout or 0.60)
        local t0 = tick()
        while (tick() - t0 < timeout) and MacroRunning do
            if isSkillReady(toolName, skillKey) then return true end
            task.wait(0.025)
        end
        return isSkillReady(toolName, skillKey)
    end

    local function isFruitTransformed()
        local ok, r = pcall(function()
            local char = LocalPlayer.Character
            if not char then return false end
            return char:GetAttribute("Transformed") == true
                or char:FindFirstChild("Transformation") ~= nil
                or char:FindFirstChild("KitsuneMode") ~= nil
                or char:FindFirstChild("DragonMode") ~= nil
                or char:FindFirstChild("BuddhaForm") ~= nil
        end)
        return ok and r
    end

    local function dispatchFastM1()
        pcall(function()
            local net = ReplicatedStorage:FindFirstChild("Modules") and ReplicatedStorage.Modules:FindFirstChild("Net")
            local regAttack = (net and net:FindFirstChild("RE/RegisterAttack")) or ReplicatedStorage:FindFirstChild("RegisterAttack", true)
            local regHit = (net and net:FindFirstChild("RE/RegisterHit")) or ReplicatedStorage:FindFirstChild("RegisterHit", true)
            if regAttack then regAttack:FireServer(0) end
            local char = LocalPlayer.Character
            local root = char and char:FindFirstChild("HumanoidRootPart")
            if regHit and root then regHit:FireServer(root, {{root, root.Position}}) end
        end)
        pcall(function()
            local char = LocalPlayer.Character
            local tool = char and char:FindFirstChildOfClass("Tool")
            if tool then tool:Activate() end
        end)
    end

    local function runM1Burst(count)
        for _ = 1, math.clamp(tonumber(count) or 2, 1, 5) do
            if not MacroRunning then break end
            dispatchFastM1()
            task.wait(0.035)
        end
    end

