    local function faceMacroTarget()

        return
    end

    local function waitForMacroBusyFree(timeout)
        local t0 = tick()
        local maxT = timeout or 0.60
        while (tick() - t0 < maxT) and MacroRunning do
            local char = LocalPlayer.Character
            if not char then break end
            local isBusy = char:GetAttribute("Busy") or char:FindFirstChild("Busy") or char:GetAttribute("isUsingSkill") or char:GetAttribute("UsingSkill")
            if not isBusy then break end
            task.wait(0.025)
        end
    end

    local function smartEquipWeapon(toolType)
        if not toolType or toolType == "None" then return true end
        local char = LocalPlayer.Character
        if not char then return false end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not hum then return false end
        local targetCategory = (toolType == "Blox Fruit" and "Fruit") or toolType

        local cur = char:FindFirstChildOfClass("Tool")
        if cur and getToolCategory(cur) == targetCategory then return true end

        waitForMacroBusyFree(0.50)

        local bp = LocalPlayer:FindFirstChildOfClass("Backpack") or LocalPlayer:FindFirstChild("Backpack")
        local targetTool = nil
        if bp then
            for _, t in ipairs(bp:GetChildren()) do
                if t:IsA("Tool") and getToolCategory(t) == targetCategory then
                    targetTool = t
                    break
                end
            end
        end
        if not targetTool then
            for _, t in ipairs(char:GetChildren()) do
                if t:IsA("Tool") and getToolCategory(t) == targetCategory then
                    return true
                end
            end
            return false
        end

        if cur and cur ~= targetTool then
            pcall(function() hum:UnequipTools() end)
            task.wait(0.04)
        end

        for attempt = 1, 3 do
            if not MacroRunning then return false end
            pcall(function() hum:EquipTool(targetTool) end)
            local t0 = tick()
            while tick() - t0 < 0.40 do
                if targetTool.Parent == char then
                    task.wait(0.08)
                    return true
                end
                task.wait(0.02)
            end
            task.wait(0.04)
        end
        return (targetTool.Parent == char)
    end

    local lastMacroEndTime = 0

