    local VK_KEY_MAP = {
        Z = 90, X = 88, C = 67, V = 86, F = 70, T = 84, Q = 81, E = 69, R = 82
    }
    local function sendVirtualKey(skillKey, isDown)
        local skill = string.upper(tostring(skillKey or ""))
        local kc = Enum.KeyCode[skill]
        if not kc then return end

        pcall(function()
            local vim = game:GetService("VirtualInputManager")
            if vim then
                vim:SendKeyEvent(isDown, kc, false, game)
            end
        end)

        local vk = VK_KEY_MAP[skill] or string.byte(skill)
        if vk and vk >= 65 and vk <= 90 then
            if isDown and keypress then
                pcall(keypress, vk)
            elseif (not isDown) and keyrelease then
                pcall(keyrelease, vk)
            end
        end
    end

    local function triggerSkillInput(skillKey, isDown)
        local skill = string.upper(tostring(skillKey or ""))
        local kc = Enum.KeyCode[skill]
        if not kc then return end
        isSimulatingKeys = isDown
        if isDown then
            markSyntheticKey(skill, 2.5)
            markSyntheticKey(kc.Name, 2.5)
        end
        sendVirtualKey(skill, isDown)
    end

    local function smartCastSkill(skillName, customHold, weaponType)
        local skill = string.upper(skillName or "Z")
        local kc = Enum.KeyCode[skill]
        if not kc then return false end
        if not MacroRunning then return false end

        local pingSec = getClientPing() / 1000

        if weaponType and weaponType ~= "None" then
            local targetCat = (weaponType == "Blox Fruit" and "Fruit") or weaponType
            local char = LocalPlayer.Character
            local cur = char and char:FindFirstChildOfClass("Tool")
            if not (cur and getToolCategory(cur) == targetCat) then
                smartEquipWeapon(weaponType)
                task.wait(0.18)
            end
        end

        faceMacroTarget()

        if skill == "V" and (weaponType == "Fruit" or weaponType == "Blox Fruit") and isFruitTransformed() then
            task.wait(0.05)
            return true
        end

        local char = LocalPlayer.Character
        local curTool = char and char:FindFirstChildOfClass("Tool")
        local toolName = curTool and curTool.Name or ""

        if not isSkillReady(toolName, skill) then
            waitForSmartCooldown(toolName, skill, 0.80)
        end
        if not MacroRunning then return false end

        if _G.SpookySetSkillKey then _G.SpookySetSkillKey(skill) end
        _G.CurrentSkillKey = skill

        local isHold = (customHold == true) or (type(customHold) == "number" and customHold > 0.15)
        local holdDuration = 0.05
        if isHold then
            if type(customHold) == "number" then
                holdDuration = math.clamp(customHold, 0.05, 5.0)
            else
                holdDuration = 0.38 + math.clamp(pingSec * 0.12, 0.02, 0.12)
            end
        end

        markSyntheticKey(skill, holdDuration + 2.5)
        markSyntheticKey(kc.Name, holdDuration + 2.5)
        isSimulatingKeys = true

        sendVirtualKey(skill, false)
        task.wait(0.02)

        faceMacroTarget()
        sendVirtualKey(skill, true)

        task.wait(holdDuration)

        sendVirtualKey(skill, false)

        local postDelay
        if isHold then
            postDelay = math.clamp(pingSec * 0.12 + 0.44, 0.38, 0.65)
        else
            local baseDelay = 0.50
            local wCat = weaponType or ""
            if wCat == "Melee" then
                if skill == "Z" then
                    baseDelay = 0.68
                elseif skill == "C" or skill == "V" then
                    baseDelay = 0.58
                elseif skill == "X" then
                    baseDelay = 0.55
                else
                    baseDelay = 0.50
                end
            elseif wCat == "Sword" then
                if skill == "Z" then
                    baseDelay = 0.54
                elseif skill == "X" then
                    baseDelay = 0.56
                else
                    baseDelay = 0.50
                end
            elseif wCat == "Fruit" then
                baseDelay = 0.60
            else
                baseDelay = 0.48
            end
            postDelay = math.clamp(pingSec * 0.12 + baseDelay, 0.45, 0.78)
        end
        task.wait(postDelay)

        task.delay(0.08, function() isSimulatingKeys = false end)
        return true
    end

    local function smartTap()
        faceMacroTarget()
        runM1Burst(1)
        safeMouseClick()
        task.wait(0.15)
    end

    local function restoreMacroMobility()

    end

    local function ReleaseAll()
        for _, k in ipairs({"Z", "X", "C", "V", "F"}) do
            triggerSkillInput(k, false)
        end
        safeMouseRelease()
        restoreMacroMobility()
        task.delay(0.08, restoreMacroMobility)
    end

    local function StopSequence()
        if not MacroRunning then return end
        MacroRunning = false
        MacroRunToken = MacroRunToken + 1
        ReleaseAll()
        restoreMacroMobility()
        task.delay(0.08, restoreMacroMobility)
    end

    _G.SpookyStopLegacyMacro = StopSequence

    local function RunSmartSteps()
        if MacroRunning then return end
        MacroRunning = true
        MacroRunToken = MacroRunToken + 1
        local myToken = MacroRunToken

        task.spawn(function()
            local ok, err = pcall(function()

                local tKey = Settings.macroTriggerKey or "T"
                local tCode = Enum.KeyCode[tKey]
                if tCode and UserInputService:IsKeyDown(tCode) then
                    local relWait = tick()
                    while UserInputService:IsKeyDown(tCode) and (tick() - relWait < 0.35) do
                        task.wait(0.03)
                    end
                end
                task.wait(0.06)

                repeat
                    local steps = Settings.macroCustomSteps or {}

                    local firstStep = nil
                    for _, s in ipairs(steps) do
                        if s and s.enabled then firstStep = s; break end
                    end
                    if firstStep then
                        local w = firstStep.weapon or firstStep.tool or "Melee"
                        local sk = tostring(firstStep.skill or firstStep.key or "Z"):upper()
                        if w ~= "None" then
                            smartEquipWeapon(w)
                            task.wait(0.12)
                        end
                        local char = LocalPlayer.Character
                        local cur = char and char:FindFirstChildOfClass("Tool")
                        local tName = cur and cur.Name or ""
                        local scale = getSkillCooldownScale(tName, sk)
                        if scale > 0.20 then

                            if _G.MacroStatusLabel then
                                _G.MacroStatusLabel.Text = "COOLDOWN: " .. w .. " [" .. sk .. "]"
                                _G.MacroStatusLabel.TextColor3 = Color3.fromRGB(255, 170, 70)
                            end
                            if _G.MacroFloatingStatus then
                                _G.MacroFloatingStatus.Text = "COOLDOWN"
                                _G.MacroFloatingStatus.TextColor3 = Color3.fromRGB(255, 170, 70)
                            end
                            notifyToggle("Macro: Habilidades en Cooldown! Espera a que recarguen", false)
                            return
                        elseif scale > 0.05 then

                            if _G.MacroStatusLabel then
                                _G.MacroStatusLabel.Text = "WAITING CD: " .. w .. " [" .. sk .. "]..."
                            end
                            waitForSmartCooldown(tName, sk, 2.0)
                        end
                    end

                    for stepIndex, step in ipairs(steps) do
                        if not MacroRunning or MacroRunToken ~= myToken then return end
                        if step and step.enabled then
                            local weapon = step.weapon or step.tool or "Melee"
                            local skill = tostring(step.skill or step.key or "Z"):upper()

                            waitForMacroBusyFree(0.55)

                            if weapon ~= "None" then
                                smartEquipWeapon(weapon)
                                task.wait(0.06)
                            end
                            if not MacroRunning or MacroRunToken ~= myToken then return end

                            if skill == "M1" or skill == "TAP" then
                                smartTap()
                            elseif ValidSkills[skill] then
                                smartCastSkill(skill, step.hold, weapon)
                            end
                            if not MacroRunning or MacroRunToken ~= myToken then return end

                            local gap = (type(step.delay) == "number" and step.delay > 0) and step.delay or 0.06
                            task.wait(gap)
                        end
                    end
                until not Settings.macroLoop or not MacroRunning or MacroRunToken ~= myToken
            end)
            if not ok then warn("[ZenMacro]:", tostring(err)) end
            ReleaseAll()
            MacroRunning = false
            isSimulatingKeys = false
            lastMacroEndTime = tick()
            if _G.MacroStatusLabel then
                _G.MacroStatusLabel.Text = "STATUS: READY [Key: " .. (Settings.macroTriggerKey or "T") .. " - Auto-Timed]"
                _G.MacroStatusLabel.TextColor3 = Color3.fromRGB(140, 230, 255)
            end
            if _G.MacroFloatingStatus then
                _G.MacroFloatingStatus.Text = "READY [" .. (Settings.macroTriggerKey or "T") .. "]"
                _G.MacroFloatingStatus.TextColor3 = Color3.fromRGB(140, 230, 255)
            end
        end)
    end

    local function RunSequence(sequence)
        if MacroRunning then return end
        MacroRunning = true
        MacroRunToken = MacroRunToken + 1
        local myToken = MacroRunToken

        task.spawn(function()
            local ok, err = pcall(function()
                repeat
                    for _, rawCmd in ipairs(string.split(sequence, "&")) do
                        if not MacroRunning or MacroRunToken ~= myToken then return end
                        local cmd = rawCmd:match("^%s*(.-)%s*$")
                        local waitT = cmd:match("^wait%s*%(?([%d%.]+)%)?$")
                        if waitT then
                            task.wait(tonumber(waitT) or 0.2)
                        elseif ValidWeapons[cmd] then
                            smartEquipWeapon(cmd)
                        elseif cmd == "holdTAP" or cmd == "TAP" or cmd == "M1" then
                            smartTap()
                        elseif cmd:match("^hold(.+)$") then
                            local s = cmd:match("^hold(.+)$")
                            if ValidSkills[s] and s ~= "TAP" and s ~= "M1" then smartCastSkill(s, true) end
                        elseif cmd:match("^unhold(.+)$") then
                            local s = cmd:match("^unhold(.+)$")
                            if ValidSkills[s] and s ~= "TAP" and s ~= "M1" then triggerSkillInput(s, false) end
                        elseif ValidSkills[cmd] and cmd ~= "TAP" and cmd ~= "M1" then
                            smartCastSkill(cmd, false)
                        elseif cmd:find(":") then
                            local parts = string.split(cmd, ":")
                            local wType = parts[1] and parts[1]:match("^%s*(.-)%s*$")
                            local sKey = parts[2] and parts[2]:match("^%s*(.-)%s*$")
                            if wType and ValidWeapons[wType] then smartEquipWeapon(wType) end
                            if sKey == "M1" or sKey == "TAP" then
                                smartTap()
                            elseif sKey and ValidSkills[sKey] then
                                smartCastSkill(sKey, false, wType)
                            end
                        end
                    end
                until not Settings.macroLoop or not MacroRunning or MacroRunToken ~= myToken
            end)
            if not ok then warn("[ZenMacro]:", tostring(err)) end
            ReleaseAll()
            MacroRunning = false
            isSimulatingKeys = false
            lastMacroEndTime = tick()
            if _G.MacroStatusLabel then
                _G.MacroStatusLabel.Text = "STATUS: READY [Key: " .. (Settings.macroTriggerKey or "T") .. " - Auto-Timed]"
                _G.MacroStatusLabel.TextColor3 = Color3.fromRGB(140, 230, 255)
            end
            if _G.MacroFloatingStatus then
                _G.MacroFloatingStatus.Text = "READY [" .. (Settings.macroTriggerKey or "T") .. "]"
                _G.MacroFloatingStatus.TextColor3 = Color3.fromRGB(140, 230, 255)
            end
        end)
    end

    _G.ExecuteMacroCombo = executeMacroCombo
    local floatingTriggerGui = nil
    local floatingStatusLabel = nil
    local function showFloatingComboTrigger(show)
        if floatingTriggerGui and floatingTriggerGui.Parent then
            floatingTriggerGui:Destroy()
            floatingTriggerGui = nil
            floatingStatusLabel = nil
        end
        if not show then return end
        floatingTriggerGui = Instance.new("ScreenGui")
        floatingTriggerGui.Name = "Sovereign_Macro_Floating_Combo"
        floatingTriggerGui.ResetOnSpawn = false
        safeParent(floatingTriggerGui)
        local floatBtn = Instance.new("TextButton", floatingTriggerGui)
        floatBtn.Size = UDim2.new(0, 72, 0, 34)
        floatBtn.Position = UDim2.new(0.85, -36, 0.7, 0)
        floatBtn.BackgroundColor3 = Color3.fromRGB(16, 16, 18)
        floatBtn.Text = "MACRO"
