        floatBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
        floatBtn.Active = true
        Instance.new("UICorner", floatBtn).CornerRadius = UDim.new(0, 9)
        local floatStroke = Instance.new("UIStroke", floatBtn)
        floatStroke.Color = Color3.fromRGB(36, 36, 42)
        floatStroke.Thickness = 1.2
        floatingStatusLabel = Instance.new("TextLabel", floatBtn)
        floatingStatusLabel.Size = UDim2.new(1, 0, 0, 12)
        floatingStatusLabel.Position = UDim2.new(0, 0, 1, -13)
        floatingStatusLabel.BackgroundTransparency = 1
        floatingStatusLabel.Font = Enum.Font.GothamBold
        floatingStatusLabel.Text = "READY"
        floatingStatusLabel.TextSize = 9
        floatingStatusLabel.TextColor3 = Color3.fromRGB(180, 180, 185)

        local mIsPressed, mDragging, mDragStart, mStartPos, mHasMoved = false, false, nil, nil, false
        floatBtn.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                mIsPressed = true
                mHasMoved = false
                mDragStart = input.Position
                mStartPos = floatBtn.Position
                local isLocked = _G.SpookyLockFloatingButtons or (FeatureStates and FeatureStates["LockFloatingButtons"])
                mDragging = not isLocked
            end
        end)
        UserInputService.InputChanged:Connect(function(input)
            local isLocked = _G.SpookyLockFloatingButtons or (FeatureStates and FeatureStates["LockFloatingButtons"])
            if isLocked then mDragging = false return end
            if mDragging and mDragStart and mStartPos and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
                local delta = input.Position - mDragStart
                if delta.Magnitude > 5 then mHasMoved = true end
                floatBtn.Position = UDim2.new(mStartPos.X.Scale, mStartPos.X.Offset + delta.X, mStartPos.Y.Scale, mStartPos.Y.Offset + delta.Y)
            end
        end)
        UserInputService.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                if mIsPressed then
                    mIsPressed = false
                    mDragging = false
                    if not mHasMoved then
                        if executeMacroCombo then executeMacroCombo() end
                    end
                end
            end
        end)
        task.spawn(function()
            while floatingTriggerGui and floatingTriggerGui.Parent do
                if floatingStatusLabel then
                    floatingStatusLabel.Text = MacroRunning and "RUNNING..." or "READY"
                    floatingStatusLabel.TextColor3 = MacroRunning and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(180, 180, 185)
                end
                task.wait(0.2)
            end
        end)
    end
