                dcStk.Color = Color3.fromRGB(70, 40, 50)
                dcStk.Thickness = 1
                loadBtn.MouseButton1Click:Connect(function()
                    SelectedSequenceName = name
                    NameBox.Text = name
                    InputBox.Text = code
                    Settings.macroName = name
                    Settings.macroSequence = code
                    notifyToggle("Loaded: " .. name, true)
                end)
                delComboBtn.MouseButton1Click:Connect(function()
                    Sequences[name] = nil
                    saveSequencesToFile()
                    renderSavedCombos()
                    notifyToggle("Deleted: " .. name, false)
                end)
            end
            savedScroll.CanvasSize = UDim2.new(0, 0, 0, math.max(150, count * 32 + 8))
        end
        saveBtn.MouseButton1Click:Connect(function()
            local n = NameBox.Text
