    local TrackerGui = nil
    local trackerStickEnabled = false
    local trackerLockedChar = nil
    local function createTrackerWidget()
        if TrackerGui and TrackerGui.Parent then pcall(function() TrackerGui:Destroy() end) end
        local gui = Instance.new("ScreenGui")
        gui.Name = "SovereignTrackerWidget"
        gui.ResetOnSpawn = false
        gui.DisplayOrder = 9999
        gui.IgnoreGuiInset = true
        safeParent(gui)
        if (not gui.Parent or not gui.Parent:IsDescendantOf(game)) and LocalPlayer then
            gui.Parent = LocalPlayer:FindFirstChildOfClass("PlayerGui") or LocalPlayer:FindFirstChild("PlayerGui")
        end
        TrackerGui = gui
        local floatBtn = Instance.new("TextButton", gui)
        floatBtn.Name = "TrackerToggle"
        floatBtn.Size = UDim2.new(0, 80, 0, 36)
        floatBtn.Position = UDim2.new(0, 20, 0.42, 0)
        floatBtn.BackgroundColor3 = Color3.fromRGB(18, 18, 24)
        floatBtn.BackgroundTransparency = 0
        floatBtn.Text = "TRACK"
        floatBtn.TextSize = 12.5
        floatBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
        floatBtn.Font = Enum.Font.GothamBold
        floatBtn.Active = true
        floatBtn.Visible = true
        floatBtn.ZIndex = 100
        Instance.new("UICorner", floatBtn).CornerRadius = UDim.new(0, 10)
        local fStroke = Instance.new("UIStroke", floatBtn)
        fStroke.Color = Color3.fromRGB(36, 36, 42)
        fStroke.Thickness = 1.3

        local trackerIsPressed, trackerDragging, trackerDragStart, trackerStartPos, trackerHasMoved = false, false, nil, nil, false
        local function updateTrackerDrag(input)
            local isLocked = _G.SpookyLockFloatingButtons or (FeatureStates and FeatureStates["LockFloatingButtons"])
            if isLocked then trackerDragging = false return end
            if trackerDragging and trackerDragStart and trackerStartPos then
                local delta = input.Position - trackerDragStart
                if delta.Magnitude > 6 then trackerHasMoved = true end
                floatBtn.Position = UDim2.new(trackerStartPos.X.Scale, trackerStartPos.X.Offset + delta.X, trackerStartPos.Y.Scale, trackerStartPos.Y.Offset + delta.Y)
            end
        end

        floatBtn.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                trackerIsPressed = true
                trackerHasMoved = false
                trackerDragStart = input.Position
                trackerStartPos = floatBtn.Position
                local isLocked = _G.SpookyLockFloatingButtons or (FeatureStates and FeatureStates["LockFloatingButtons"])
                trackerDragging = not isLocked
            end
        end)
        floatBtn.InputChanged:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
                updateTrackerDrag(input)
            end
        end)
        UserInputService.InputChanged:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
                updateTrackerDrag(input)
            end
        end)

        local trackerConn = nil
        local function stopTracker()
            trackerStickEnabled = false
            trackerLockedChar = nil
            if trackerConn then
                trackerConn:Disconnect()
                trackerConn = nil
            end
            fStroke.Color = Color3.fromRGB(48, 48, 55)
            floatBtn.TextColor3 = Color3.fromRGB(180, 180, 180)
        end
        local function toggleTrackerAction()
            trackerStickEnabled = not trackerStickEnabled
            fStroke.Color = trackerStickEnabled and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(48, 48, 55)
            floatBtn.TextColor3 = trackerStickEnabled and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(180, 180, 180)
            if not trackerStickEnabled then
                stopTracker()
                return
            end
            if trackerConn then trackerConn:Disconnect() end
            trackerConn = RunService.Stepped:Connect(function(step, dt)
                if not trackerStickEnabled then
                    stopTracker()
                    return
                end
                local char = LocalPlayer.Character
                local myHRP = char and char:FindFirstChild("HumanoidRootPart")
                if not myHRP then return end
                myHRP.CanCollide = false
                local targetChar = nil
                if trackerLockedChar and trackerLockedChar.Parent and trackerLockedChar:FindFirstChild("HumanoidRootPart") then
                    local hum = trackerLockedChar:FindFirstChildOfClass("Humanoid")
                    if hum and hum.Health > 0 then
                        targetChar = trackerLockedChar
                    end
                end
                if not targetChar then
                    local closest, closestDist = nil, 650
                    for _, p in ipairs(Players:GetPlayers()) do
                        if p ~= LocalPlayer and p.Character and p.Character:FindFirstChild("HumanoidRootPart") then
                            if not (_G.PlayerBlacklist and (_G.PlayerBlacklist[p.UserId] or _G.PlayerBlacklist[p.Name])) then
                                local hum = p.Character:FindFirstChildOfClass("Humanoid")
                                if hum and hum.Health > 0 then
                                    local d = (p.Character.HumanoidRootPart.Position - myHRP.Position).Magnitude
                                    if d < closestDist then
                                        closest = p.Character
                                        closestDist = d
                                    end
                                end
                            end
                        end
                    end
                    if not closest then
                        for _, p in ipairs(Players:GetPlayers()) do
                            if p ~= LocalPlayer and p.Character and p.Character:FindFirstChild("HumanoidRootPart") then
                                local hum = p.Character:FindFirstChildOfClass("Humanoid")
                                if hum and hum.Health > 0 then
                                    local d = (p.Character.HumanoidRootPart.Position - myHRP.Position).Magnitude
                                    if d < closestDist then
                                        closest = p.Character
                                        closestDist = d
                                    end
                                end
                            end
                        end
                    end
                    trackerLockedChar = closest
                    targetChar = closest
                end
                if targetChar and targetChar:FindFirstChild("HumanoidRootPart") then
                    local tHrp = targetChar.HumanoidRootPart
                    local tHum = targetChar:FindFirstChildOfClass("Humanoid")
                    if tHum and tHum.Health > 0 and (myHRP.Position - tHrp.Position).Magnitude <= 700 then
                        local dist = Settings.trackerDist or 3.5
                        myHRP.CFrame = tHrp.CFrame * CFrame.new(0, 0, dist)
                        myHRP.AssemblyLinearVelocity = tHrp.AssemblyLinearVelocity
                    else
                        trackerLockedChar = nil
                    end
                end
            end)
            registerConnection(trackerConn)
        end
        local function endTrackerDrag()
            if trackerIsPressed then
                trackerIsPressed = false
                trackerDragging = false
                if not trackerHasMoved then
                    toggleTrackerAction()
                end
            end
        end

        floatBtn.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                endTrackerDrag()
            end
        end)
        UserInputService.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                endTrackerDrag()
            end
        end)
    end
    FeatureCallbacks["Tracker"] = function(v)
        if v then
            createTrackerWidget()
        else
            trackerStickEnabled = false
            trackerLockedChar = nil
            if TrackerGui then pcall(function() TrackerGui:Destroy() end); TrackerGui = nil end
        end
    end
local function _initCamLockSystem()
    local CamLockGui = nil
    local camLockActive = false
    local camLockTargetPlayer = nil
    local camLockStepBound = false
    local updateCamLockVisual = nil
    local stopCamLockTracking

    local function getBestCamLockTarget(excludeCurrent)
        if not Spooky.SelectAimPlayer then return nil end
        return Spooky.SelectAimPlayer(750, excludeCurrent and camLockTargetPlayer or nil)
    end

    local camLockNextScan=0
    local function camLockCameraStep(dt)
        if not isCurrentSession() then stopCamLockTracking(); return end
        if not camLockActive then return end
        if not camLockTargetPlayer then
            if os.clock()<camLockNextScan then return end
            camLockNextScan=os.clock()+0.25
            camLockTargetPlayer=getBestCamLockTarget(false)
            if not camLockTargetPlayer then Spooky.Diagnostics.statuses.CamLock="Waiting for a valid target";return end
            if updateCamLockVisual then updateCamLockVisual(true) end
        end
        Spooky.Diagnostics.statuses.CamLock="Tracking " .. camLockTargetPlayer.Name
        local currentRoot = camLockTargetPlayer.Character and camLockTargetPlayer.Character:FindFirstChild("HumanoidRootPart")
        if not _G.SpookyCombatTargetValid or not _G.SpookyCombatTargetValid(camLockTargetPlayer,750)
            or not currentRoot or (Spooky.AimScore and not Spooky.AimScore(currentRoot,0))
            or (Settings.aimTargetPolicy == "Selected" and tostring(camLockTargetPlayer.UserId) ~= tostring(Settings.aimTargetUserId)) then
            camLockTargetPlayer = getBestCamLockTarget(true)
            if not camLockTargetPlayer then return end
        end
        local cam = workspace.CurrentCamera
        if not cam then return end

        local targetChar = camLockTargetPlayer.Character
        if not (targetChar and targetChar.Parent) then
            local nextPlr = getBestCamLockTarget(true)
            if nextPlr then
                camLockTargetPlayer = nextPlr
                if updateCamLockVisual then updateCamLockVisual(true) end
            else
                camLockTargetPlayer=nil
            end
            return
        end

        local hum = targetChar:FindFirstChildOfClass("Humanoid")
        local targetPartName = Settings.camLockTargetPart or "HumanoidRootPart"
        local hrp = targetChar:FindFirstChild(targetPartName) or targetChar:FindFirstChild("HumanoidRootPart") or targetChar:FindFirstChild("Head") or targetChar.PrimaryPart
        if not hum or hum.Health <= 0 or not hrp then
            local nextPlr = getBestCamLockTarget(true)
            if nextPlr then
                camLockTargetPlayer = nextPlr
                if updateCamLockVisual then updateCamLockVisual(true) end
            else
                camLockTargetPlayer=nil
            end
            return
        end

        local camPos = cam.CFrame.Position
        local targetOffset = Vector3.new(0, (targetPartName == "Head" and 0.2 or 0.5), 0)
        local aimPos = hrp.Position + targetOffset

        local vel = hrp.AssemblyLinearVelocity or hrp.Velocity
        if vel and vel.Magnitude > 2 and vel.Magnitude < 450 then
            aimPos = aimPos + (vel * math.clamp(tonumber(Settings.camLockPrediction) or 0.04, 0, 0.15))
        end

        local diff = aimPos - camPos
        local dist = diff.Magnitude

        if dist > 750 then
            local nextPlr = getBestCamLockTarget(true)
            if nextPlr then
                camLockTargetPlayer = nextPlr
                if updateCamLockVisual then updateCamLockVisual(true) end
            else
                camLockTargetPlayer=nil
            end
            return
        end

        if dist > 1 then
            local smooth = 0.32
            if Settings.camLockSmoothness == "Instant" then
                smooth = 1.0
            elseif Settings.camLockSmoothness == "Very Smooth" then
                smooth = 0.18
            end
            local targetCFrame = CFrame.lookAt(camPos, aimPos)
            local alpha = 1 - (1 - math.clamp(smooth, 0.05, 1)) ^ (math.clamp(tonumber(dt) or 1/60, 0, 0.1) * 60)
            cam.CFrame = cam.CFrame:Lerp(targetCFrame, alpha)
        end
    end

    stopCamLockTracking = function()
        camLockActive = false
        Spooky.Diagnostics.statuses.CamLock="Off"
        camLockTargetPlayer = nil
        if camLockStepBound then
            camLockStepBound = false
            pcall(function() RunService:UnbindFromRenderStep("SovereignCamLockExecution") end)
        end
        if updateCamLockVisual then updateCamLockVisual(false) end
    end

    local function startCamLockTracking()
        local target = getBestCamLockTarget(false)
        camLockTargetPlayer = target
        camLockActive = true
        if updateCamLockVisual then updateCamLockVisual(true) end
        if not camLockStepBound then
            camLockStepBound = true
            RunService:BindToRenderStep("SovereignCamLockExecution", Enum.RenderPriority.Camera.Value + 1, function(dt)
                local ok, err = pcall(camLockCameraStep,dt)
                if not ok then Spooky.ReportIssue("CamLock",err) end
            end)
        end
        local tName = target and (target.DisplayName or target.Name) or "waiting for target"
        notifyToggle("CamLock: LOCKED on " .. tName, true)
    end

    local function toggleCamLockTracking()
        if camLockActive then
            stopCamLockTracking()
            notifyToggle("CamLock: OFF", false)
        else
            startCamLockTracking()
        end
    end

    local camWidgetConnections = {}
    local function disconnectCamWidget()
        for _, connection in ipairs(camWidgetConnections) do connection:Disconnect() end
        table.clear(camWidgetConnections)
        updateCamLockVisual = nil
    end
    local function createCamLockWidget()
        disconnectCamWidget()
        if CamLockGui then CamLockGui:Destroy() end
        local gui = Instance.new("ScreenGui")
        gui.Name = "SovereignCamLockWidget"
        gui.ResetOnSpawn, gui.IgnoreGuiInset, gui.Enabled = false, true, true
        gui.DisplayOrder = 1000000
        gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling

        gui.Parent = (ScreenGui and ScreenGui.Parent) or TargetParent or LocalPlayer:FindFirstChildOfClass("PlayerGui") or PlayerGui
        if not gui.Parent then safeParent(gui) end
        if not gui.Parent then error("Cannot parent the CamLock control") end
        CamLockGui = gui
        local card = Instance.new("TextButton", gui)
        card.Name = "CamLockCard"
        card.Size = UDim2.fromOffset(146, 40)
        card.Position = UDim2.new(0, 24, 0.5, -20)
        card.BackgroundColor3 = Color3.fromRGB(20, 22, 29)
        card.BorderSizePixel, card.TextSize = 0, 12
        card.Font = Enum.Font.GothamMedium
        card.TextColor3 = Color3.new(1, 1, 1)
        card.AutoButtonColor, card.Active, card.Visible, card.ZIndex = false, true, true, 10
        Instance.new("UICorner", card).CornerRadius = UDim.new(0, 10)
        local stroke = Instance.new("UIStroke", card)
        stroke.Thickness = 1.5
        updateCamLockVisual = function(active)
            if not card.Parent then return end
            stroke.Color = active and (_G.CurrentAccentColor or Color3.fromRGB(130, 115, 240)) or Color3.fromRGB(65, 67, 79)
            card.Text = active and (camLockTargetPlayer and "CAMLOCK  •  ON" or "CAMLOCK  •  ...") or "CAMLOCK  •  OFF"
        end
        updateCamLockVisual(camLockActive)
        local dragStart, startPosition, dragInput, moved
        table.insert(camWidgetConnections, card.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragStart, startPosition, dragInput, moved = input.Position, card.Position, input, false
            end
        end))
        table.insert(camWidgetConnections, UserInputService.InputChanged:Connect(function(input)
            if not dragInput or _G.SpookyLockFloatingButtons or FeatureStates["LockFloatingButtons"] then return end
            if input ~= dragInput and input.UserInputType ~= Enum.UserInputType.MouseMovement then return end
            local delta = input.Position - dragStart
            if delta.Magnitude > 6 then moved = true end
            if moved then
                local cam = workspace.CurrentCamera
                local vp = cam and cam.ViewportSize or Vector2.new(800, 600)
                local x = startPosition.X.Scale * vp.X + startPosition.X.Offset + delta.X
                local y = startPosition.Y.Scale * vp.Y + startPosition.Y.Offset + delta.Y
                card.Position = UDim2.fromOffset(math.clamp(x, 0, math.max(0, vp.X - 146)), math.clamp(y, 0, math.max(0, vp.Y - 40)))
            end
        end))
        table.insert(camWidgetConnections, UserInputService.InputEnded:Connect(function(input)
            if input == dragInput then dragInput = nil end
        end))
        table.insert(camWidgetConnections, card.Activated:Connect(function()
            if not moved then toggleCamLockTracking() end
        end))
        registerConnection(gui.Destroying:Connect(disconnectCamWidget))
        Spooky.Diagnostics.statuses["CamLock control"] = "Visible in PlayerGui"
    end

    local function destroyCamLockWidget()
        stopCamLockTracking()
        disconnectCamWidget()
        if CamLockGui then
            CamLockGui:Destroy()
            CamLockGui = nil
        end
    end

    FeatureCallbacks["CamLock"] = function(v)
        if v then
            createCamLockWidget()
            startCamLockTracking()
            notifyToggle("CamLock Widget: Active", true)
        else
            destroyCamLockWidget()
            notifyToggle("CamLock Widget: Hidden", false)
        end
    end

    local function reconcileCamLockWidget()
        if FeatureStates["CamLock"] then
            if not CamLockGui or not CamLockGui.Parent then
                createCamLockWidget()
                if not camLockStepBound then startCamLockTracking() end
            end
            CamLockGui.Enabled = true
            local button = CamLockGui:FindFirstChild("CamLockCard")
            if button then button.Visible = true end
        elseif CamLockGui then
            destroyCamLockWidget()
        end
    end
    local camWidgetClock = 0
    registerConnection(RunService.Heartbeat:Connect(function(dt)
        if not isCurrentSession() then return end
        camWidgetClock += dt
        if camWidgetClock < 0.3 then return end
        camWidgetClock = 0
        local ok, err = pcall(reconcileCamLockWidget)
        if not ok then Spooky.ReportIssue("CamLock control",err) end
    end))
    FeatureCallbacks["SwitchCamLock"] = function()
        if not FeatureStates["CamLock"] then
            setFeatureState("CamLock",true)
            return
        end
        camLockTargetPlayer=getBestCamLockTarget(true) or getBestCamLockTarget(false)
        camLockActive=true
        if not camLockStepBound then
            camLockStepBound=true
            RunService:BindToRenderStep("SovereignCamLockExecution",Enum.RenderPriority.Camera.Value+1,camLockCameraStep)
        end
        if updateCamLockVisual then updateCamLockVisual(camLockTargetPlayer~=nil) end
    end
    end
    _initCamLockSystem()
end
