            if el.rightSideImg then el.rightSideImg.BackgroundTransparency = currentPanelTransparency end
            if el.centerPagesBg then el.centerPagesBg.BackgroundTransparency = currentPanelTransparency end
        end
        for _, card in ipairs(AllCardFrames) do
            if card and card.Parent then
                card.BackgroundTransparency = math.clamp(currentPanelTransparency + 0.1, 0, 0.95)
