    resetAllToFactoryDefaults = function()
        pcall(function()
            for k in pairs(FeatureStates) do
                setFeatureState(k, false)
            end
            local char = LocalPlayer.Character
            if char then
                local hrp = char:FindFirstChild("HumanoidRootPart")
                if hrp then
                    for _, c in ipairs(hrp:GetChildren()) do
                        if c.Name == "Sovereign_FlyVelocity" or c.Name == "Sovereign_FlyGyro" then
                            pcall(function() c:Destroy() end)
                        end
                    end
                end
            end
            Settings.walkSpeed = 16
            Settings.dashDist = 50
            Settings.flySpeed = 100
            Settings.superJumpHeight = 500
            resetUISettingsOnly()
            pcall(function()
                if delfile and isfile then
                    if isfile("ProjectSovereign_QuickToggles.json") then delfile("ProjectSovereign_QuickToggles.json") end
                    if isfile("ProjectSovereign_PCKeybinds.json") then delfile("ProjectSovereign_PCKeybinds.json") end
                    if isfile("ProjectSovereign_ESPConfig.json") then delfile("ProjectSovereign_ESPConfig.json") end
                    if isfile("Sovereign_ui_config.txt") then delfile("Sovereign_ui_config.txt") end
                    if isfile("Sovereign_theme.txt") then delfile("Sovereign_theme.txt") end
                    if isfile("Sovereign_config.txt") then delfile("Sovereign_config.txt") end
                end
            end)
            notifyToggle("ALL SETTINGS & UI RESET TO FACTORY DEFAULTS!", true)
        end)
