    local function loadUIConfig()
        local applied = false
        pcall(function()
            if isfile and isfile("ProjectSovereign_UIConfig.json") and readfile then
                local raw = readfile("ProjectSovereign_UIConfig.json")
                if raw and #raw > 5 then
                    local data = HttpService:JSONDecode(raw)
                    if data and type(data) == "table" then
                        if data.theme then applyTheme(data.theme) end
                        if data.scale and data.scale >= 0.35 and data.scale <= 1.5 and UIScale then
                            UIScale.Scale = data.scale
                            currentBaseScale = data.scale
                            userCustomScale = data.scale
                            _G.InitialUIScaleVal = data.scale
                        end
                        if data.animation and _G.SpookySetUIAnimation then
                            _G.SpookySetUIAnimation(data.animation, data.animationDuration)
                        end
                        if data.font then
                            local fontEnum = Enum.Font[data.font] or Enum.Font.GothamBold
                            applyFontToAll(fontEnum, data.font)
                        end
                        if data.borderThickness then
                            applyBorderThickness(data.borderThickness)
                        end
                        if data.cornerRadius then
                            applyCornerRadius(data.cornerRadius)
                        end
                        if data.wallpaper and data.wallpaper ~= "" then
                            applyWallpaper(data.wallpaper, data.wallpaperOpacity)
                        end
                        if data.panelTransparency then
                            setPanelTransparency(data.panelTransparency)
                        end
                        if data.customAvatarId and data.customAvatarId ~= "" and applyCustomAvatar then
                            applyCustomAvatar(data.customAvatarId)
                        end
                        applied = true
                    end
                end
            end
            if not applied and isfile and isfile("Sovereign_ui_config.txt") and readfile then
                local raw = readfile("Sovereign_ui_config.txt")
                if raw and #raw > 2 then
                    local parts = string.split(raw, "|")
                    local savedTheme = parts[1]
                    local savedScale = parts[2] and tonumber(parts[2])
                    if savedTheme then applyTheme(savedTheme); applied = true end
                    if savedScale and UIScale then
                        UIScale.Scale = savedScale
                        currentBaseScale = savedScale
                    end
                end
            end
        end)
        if not applied then
            applyTheme(CurrentTheme or "White")
            applyWallpaper("rbxassetid://128332470108268", 0.95)
        end
        loadUILayout()
        return applied
    end
    _G.Spooky_LoadUIConfig = loadUIConfig

