local function mathClamp(val, minV, maxV)
    if math.clamp then return math.clamp(val, minV, maxV) end
    if val < minV then return minV end
    if val > maxV then return maxV end
    return val
end

local function showSpookyNotice(title, desc, isSuccess)
    pcall(function()
        if notifyToggle then
            notifyToggle(title .. ": " .. desc, isSuccess)
        else
            print(string.format("[Zen Hub] %s: %s (%s)", title, desc, isSuccess and "SUCCESS" or "WARN"))
        end
    end)
    pcall(function()
        local sg = game:GetService("StarterGui")
        if sg and sg.SetCore then
            sg:SetCore("SendNotification", {
                Title = title,
                Text = desc,
                Duration = 3.5
            })
        end
    end)
end

local Agent2_MacroConfigs = {}
_G.Agent2_MacroConfigs = Agent2_MacroConfigs
local B64_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local B64_LOOKUP = {}
for i = 1, 64 do
    B64_LOOKUP[B64_CHARS:sub(i, i)] = i - 1
end

local function base64Encode(data)
    if not data or #data == 0 then return "" end

    if crypt and crypt.base64encode then
        local ok, res = pcall(crypt.base64encode, data)
        if ok and res then return res end
    elseif syn and syn.crypt and syn.crypt.base64_encode then
        local ok, res = pcall(syn.crypt.base64_encode, data)
        if ok and res then return res end
    elseif base64_encode then
        local ok, res = pcall(base64_encode, data)
        if ok and res then return res end
    end

    local len = #data
    local out = {}
    local k = 1
    for i = 1, len, 3 do
        local b1 = data:byte(i)
        local b2 = data:byte(i + 1) or 0
        local b3 = data:byte(i + 2) or 0

        local n = (b1 * 65536) + (b2 * 256) + b3
        local c1 = math.floor(n / 262144) % 64
        local c2 = math.floor(n / 4096) % 64
        local c3 = math.floor(n / 64) % 64
        local c4 = n % 64

        out[k]     = B64_CHARS:sub(c1 + 1, c1 + 1)
        out[k + 1] = B64_CHARS:sub(c2 + 1, c2 + 1)

        if i + 1 > len then
            out[k + 2] = "="
            out[k + 3] = "="
        elseif i + 2 > len then
            out[k + 2] = B64_CHARS:sub(c3 + 1, c3 + 1)
            out[k + 3] = "="
        else
            out[k + 2] = B64_CHARS:sub(c3 + 1, c3 + 1)
            out[k + 3] = B64_CHARS:sub(c4 + 1, c4 + 1)
        end
        k = k + 4
    end
    return table.concat(out)
end

local function base64Decode(data)
    if not data or #data == 0 then return "" end

    if crypt and crypt.base64decode then
        local ok, res = pcall(crypt.base64decode, data)
        if ok and res then return res end
    elseif syn and syn.crypt and syn.crypt.base64_decode then
        local ok, res = pcall(syn.crypt.base64_decode, data)
        if ok and res then return res end
    elseif base64_decode then
        local ok, res = pcall(base64_decode, data)
        if ok and res then return res end
    end

    data = data:gsub("[^A-Za-z0-9+/=]", "")
    local len = #data
    local out = {}
    local k = 1
    for i = 1, len, 4 do
        local c1 = B64_LOOKUP[data:sub(i, i)] or 0
        local c2 = B64_LOOKUP[data:sub(i + 1, i + 1)] or 0
        local s3 = data:sub(i + 2, i + 2)
        local s4 = data:sub(i + 3, i + 3)
        local c3 = B64_LOOKUP[s3] or 0
        local c4 = B64_LOOKUP[s4] or 0

        local n = (c1 * 262144) + (c2 * 4096) + (c3 * 64) + c4
        local b1 = math.floor(n / 65536) % 256
        local b2 = math.floor(n / 256) % 256
        local b3 = n % 256

        out[k] = string.char(b1)
        k = k + 1

        if s3 ~= "=" and i + 2 <= len then
            out[k] = string.char(b2)
            k = k + 1
        end
        if s4 ~= "=" and i + 3 <= len then
            out[k] = string.char(b3)
            k = k + 1
        end
    end
    return table.concat(out)
end

Agent2_MacroConfigs.base64Encode = base64Encode
Agent2_MacroConfigs.base64Decode = base64Decode

local function exportMacroConfig()
    local payload = {
        type = "MACRO",
        version = 2,
        activeSlot = Settings.macroActiveSlot or 1,
        triggerKey = Settings.macroTriggerKey or "T",
        macroLoop = Settings.macroLoop or false,
        macroSmartDelay = Settings.macroSmartDelay ~= false,
        macroSmartSpeed = Settings.macroSmartSpeed or "Max",
        slots = Settings.macroSlots or {},
        customSteps = Settings.macroCustomSteps or {}
    }
    local json = HttpService:JSONEncode(payload)
    local encoded = "SPK_MACRO:" .. base64Encode(json)
    local ok = universalCopy(encoded)
    if ok then
        showSpookyNotice("Macro Config", "Configuración de Macro copiada al portapapeles!", true)
    else
        showSpookyNotice("Macro Config", "Código generado (Error de portapapeles)", false)
    end
    return encoded
end

local function exportUIConfig()
    local animName, animDur = "Pop", 0.28
    if _G.SpookyGetUIAnimation then
        pcall(function() animName, animDur = _G.SpookyGetUIAnimation() end)
    end
    local payload = {
        type = "UI",
        version = 2,
        theme = CurrentTheme or "White",
        scale = currentBaseScale or (UIScale and UIScale.Scale) or 0.85,
        font = currentUIFontName or "GothamBold",
        borderThickness = currentBorderThickness or 1.5,
        cornerRadius = currentCornerRadius or 8,
        wallpaper = currentCustomWallpaperId or "",
        wallpaperOpacity = currentWallpaperOpacity or 0.85,
        panelTransparency = currentPanelTransparency or 0,
        animation = animName or "Pop",
        animationDuration = animDur or 0.28
    }
    local json = HttpService:JSONEncode(payload)
    local encoded = "SPK_UI:" .. base64Encode(json)
    local ok = universalCopy(encoded)
    if ok then
        showSpookyNotice("UI Config", "Configuración de UI copiada al portapapeles!", true)
    else
        showSpookyNotice("UI Config", "Código generado (Error de portapapeles)", false)
    end
    return encoded
end

local function exportFullConfig()
    local activeFeats = {}
    for featName, state in pairs(FeatureStates) do
        if state == true then
            table.insert(activeFeats, featName)
        end
    end

    local animName, animDur = "Pop", 0.28
    if _G.SpookyGetUIAnimation then
        pcall(function() animName, animDur = _G.SpookyGetUIAnimation() end)
    end

    local payload = {
        type = "GLOBAL",
        version = 2,
        features = activeFeats,
        PlayerBlacklist = Spooky.ExportPlayerBlacklist(),
        CustomControls = _G.SpookyGetCustomControls and _G.SpookyGetCustomControls() or {},
        FloatPos = _G.SpookyGetFloatingPositions and _G.SpookyGetFloatingPositions() or {},
        language = CurrentLang,
        settings = {
            aimMode = Settings.aimMode,
            aimFovRadius = Settings.aimFovRadius,
            aimFovOrigin = Settings.aimFovOrigin,
            aimTargetPolicy = Settings.aimTargetPolicy,
            aimTargetUserId = Settings.aimTargetUserId,
            camLockTargetPart = Settings.camLockTargetPart,
            ignoreLowLevel = Settings.ignoreLowLevel,
            ignoreLowLevelThreshold = Settings.ignoreLowLevelThreshold,
            tracerColorName = Settings.tracerColorName,
            walkSpeed         = Settings.walkSpeed,
            dashDist          = Settings.dashDist,
            flySpeed          = Settings.flySpeed,
            magnetHp          = Settings.magnetHp,
            raceHp            = Settings.raceHp,
            stretchSkew       = Settings.stretchSkew,
            giantScale        = Settings.giantScale,
            fruitScale        = Settings.fruitScale,
            superJumpHeight   = Settings.superJumpHeight,
            centuPrediction   = Settings.centuPrediction,
            centuDistance     = Settings.centuDistance,
            camLockMode       = Settings.camLockMode,
            camLockDistance   = Settings.camLockDistance,
            camLockSmoothness = Settings.camLockSmoothness,
            camLockPrediction = Settings.camLockPrediction,
            showCamLockWidgets= Settings.showCamLockWidgets,
            safeZoneCheck     = Settings.safeZoneCheck,
            teamCheck         = Settings.teamCheck,
            fastAttack        = Settings.fastAttack,
            fastAttackDelay   = Settings.fastAttackDelay,
            m1Extender        = Settings.m1Extender,
            m1Range           = Settings.m1Range,
            autoV4            = Settings.autoV4,
            autoBuso          = Settings.autoBuso,
            autoKen           = Settings.autoKen,
            autoRaceV4        = Settings.autoRaceV4,
            spoofLevel        = Settings.spoofLevel,
            spoofBounty       = Settings.spoofBounty,
            spoofBeli         = Settings.spoofBeli,
            spoofFragments    = Settings.spoofFragments,
            shaderIdx         = Settings.shaderIdx,
            skyIdx            = Settings.skyIdx,
            timeIdx           = Settings.timeIdx,
            filterIdx         = Settings.filterIdx,
            fontIdx           = Settings.fontIdx
        },
        macro = {
            activeSlot      = Settings.macroActiveSlot or 1,
            triggerKey      = Settings.macroTriggerKey or "T",
            macroLoop       = Settings.macroLoop or false,
            macroSmartDelay = Settings.macroSmartDelay ~= false,
            macroSmartSpeed = Settings.macroSmartSpeed or "Max",
            slots           = Settings.macroSlots or {},
            customSteps     = Settings.macroCustomSteps or {}
        },
        ui = {
            theme             = CurrentTheme or "White",
            scale             = currentBaseScale or (UIScale and UIScale.Scale) or 0.85,
            font              = currentUIFontName or "GothamBold",
            borderThickness   = currentBorderThickness or 1.5,
            cornerRadius      = currentCornerRadius or 8,
            wallpaper         = currentCustomWallpaperId or "",
            wallpaperOpacity  = currentWallpaperOpacity or 0.85,
            panelTransparency = currentPanelTransparency or 0,
            animation         = animName or "Pop",
            animationDuration = animDur or 0.28
        },
        keybinds = (function()
            local list = {}
            local kbs = _G.PCKeybinds or PCKeybinds
            if kbs then
                for _, ent in ipairs(kbs) do
                    table.insert(list, { id = ent.id, key = ent.key })
                end
            end
            return list
        end)()
    }
    local json = HttpService:JSONEncode(payload)
    local encoded = "SPK_GLOBAL:" .. base64Encode(json)
    local ok = universalCopy(encoded)
    if ok then
        showSpookyNotice("Global Config", "Configuración Global copiada al portapapeles!", true)
    else
        showSpookyNotice("Global Config", "Código generado (Error de portapapeles)", false)
    end
    return encoded
end

