    local function getCompactUIConfigString()
        local animName, animDur = "Pop", 0.28
        if _G.SpookyGetUIAnimation then animName, animDur = _G.SpookyGetUIAnimation() end
        local pack = {
            t = CurrentTheme or "White",
            s = currentBaseScale or 0.85,
            a = animName or "Pop",
            ad = animDur or 0.28,
            f = currentUIFontName or "GothamBold",
            bt = currentBorderThickness or 1.5,
            cr = currentCornerRadius or 8,
            w = currentCustomWallpaperId or "",
            wo = currentWallpaperOpacity or 0.85,
            pt = currentPanelTransparency or 0
        }
        return "SPK_UI:" .. HttpService:JSONEncode(pack)
    end

    local function applyCompactUIConfig(data)
        if not data or type(data) ~= "table" then return false end
        pcall(function()
            if data.t and _G.ApplyTheme then _G.ApplyTheme(data.t) end
            if data.s and UIScale then
                UIScale.Scale = data.s
                currentBaseScale = data.s
                userCustomScale = data.s
            end
            if data.a and _G.SpookySetUIAnimation then
                _G.SpookySetUIAnimation(data.a, data.ad or 0.28)
            end
            if data.f and _G.SpookyApplyFontToAll then
                local fEnum = Enum.Font[data.f] or Enum.Font.GothamBold
                _G.SpookyApplyFontToAll(fEnum, data.f)
            end
            if data.bt and _G.SpookyApplyBorderThickness then
                _G.SpookyApplyBorderThickness(data.bt)
            end
            if data.cr and _G.SpookyApplyCornerRadius then
                _G.SpookyApplyCornerRadius(data.cr)
            end
            if data.w ~= nil and applyWallpaper then
                applyWallpaper(data.w, data.wo or 0.85)
            end
            if data.pt ~= nil and setPanelTransparency then
                setPanelTransparency(data.pt)
            end
            if _G.saveUIConfig then _G.saveUIConfig() end
        end)
        return true
    end

    local function getCompactConfigString()
        local activeFeats = {}
        local allToggles = {}
        for k, v in pairs(FeatureStates) do
            allToggles[k] = (v == true)
            if v == true then table.insert(activeFeats, k) end
        end
        local kbList = {}
        local kbs = _G.PCKeybinds or PCKeybinds
        if kbs then
            for _, ent in ipairs(kbs) do
                table.insert(kbList, { id = ent.id, key = ent.key })
            end
        end
        local floatPos = nil
        pcall(function()
            if _G.SpookyGetFloatingPositions then floatPos = _G.SpookyGetFloatingPositions() end
        end)
        local isLocked = (_G.SpookyLockFloatingButtons == true) or (FeatureStates and FeatureStates["LockFloatingButtons"] == true)
        local pack = {
            F = activeFeats,
            PlayerBlacklist = Spooky.ExportPlayerBlacklist(),
            Toggles = allToggles,
            Locked = isLocked,
            FloatPos = floatPos,
            CustomControls = _G.SpookyGetCustomControls and _G.SpookyGetCustomControls() or {},
            CustomFunctions = _G.SpookyGetCustomFunctions and _G.SpookyGetCustomFunctions() or {},
            language = CurrentLang,
            S = {
                aimMode = Settings.aimMode,
                aimFovRadius = Settings.aimFovRadius,
                aimFovOrigin = Settings.aimFovOrigin,
                aimTargetPolicy = Settings.aimTargetPolicy,
                aimTargetUserId = Settings.aimTargetUserId,
                w = Settings.walkSpeed,
                d = Settings.dashDist,
                f = Settings.flySpeed,
                m = Settings.macroMode,
                u = currentBaseScale,
                t = CurrentTheme,
                tc = Settings.tracerColorName,
                cp = Settings.camLockTargetPart,
                tk = Settings.macroTriggerKey,
                mcs = Settings.macroCustomSteps,
                minLvl = Settings.ignoreLowLevelThreshold,
                camSmooth = Settings.camLockSmoothness
            },
            KB = kbList,
            V = "SPK2"
        }
        return "SPK_CFG:" .. HttpService:JSONEncode(pack)
    end

    local function applyCompactConfigString(str)
        if not str or #str < 4 then return false end
        if string.sub(str, 1, 7) == "SPK_UI:" then
            local jsonPart = string.sub(str, 8)
            local ok, data = pcall(function() return HttpService:JSONDecode(jsonPart) end)
            if ok and data then
                return applyCompactUIConfig(data)
            end
            return false
        end
        if string.sub(str, 1, 8) == "SPK_CFG:" then
            str = string.sub(str, 9)
        end
        local ok, data = pcall(function() return HttpService:JSONDecode(str) end)
        if ok and data and (data.F or data.Toggles) then
            if data.PlayerBlacklist then Spooky.RestorePlayerBlacklist(data.PlayerBlacklist) end
            if data.S then
                for _, key in ipairs({"aimMode","aimFovRadius","aimFovOrigin","aimTargetPolicy","aimTargetUserId"}) do
                    if data.S[key] ~= nil then Settings[key] = data.S[key] end
                end
                if data.S.w then Settings.walkSpeed = data.S.w end
                if data.S.d then Settings.dashDist = data.S.d end
                if data.S.f then Settings.flySpeed = data.S.f end
                if data.S.u and UIScale then UIScale.Scale = data.S.u; currentBaseScale = data.S.u end
                if data.S.t and _G.ApplyTheme then _G.ApplyTheme(data.S.t) end
                if data.S.tc then Settings.tracerColorName = data.S.tc end
                if data.S.cp then Settings.camLockTargetPart = data.S.cp end
                if data.S.tk then Settings.macroTriggerKey = data.S.tk end
                if data.S.minLvl then Settings.ignoreLowLevelThreshold = data.S.minLvl end
                if data.S.camSmooth then Settings.camLockSmoothness = data.S.camSmooth end
                if data.S.mcs then
                    Settings.macroCustomSteps = data.S.mcs
                    if _G.UpdateMacroBannerFunc then pcall(_G.UpdateMacroBannerFunc) end
                    if _G.RefreshMacroStepsUI then pcall(_G.RefreshMacroStepsUI) end
                end
            end
            if data.Toggles and type(data.Toggles) == "table" then
                for k, v in pairs(data.Toggles) do
                    setFeatureState(k, v)
                end
            elseif data.F then
                for _, k in ipairs(data.F) do
                    setFeatureState(k, true)
                end
            end
            if data.Locked ~= nil then
                setFeatureState("LockFloatingButtons", data.Locked)
                _G.SpookyLockFloatingButtons = data.Locked
            end
    if data.language and applyLanguage then applyLanguage(data.language,true) end
    if type(data.CustomControls) == "table" then
        if _G.SpookySetCustomControls then _G.SpookySetCustomControls(data.CustomControls)
        else Spooky.PendingCustomControls = data.CustomControls end
    end
            if type(data.FloatPos) == "table" then
                if _G.SpookySetFloatingPositions then _G.SpookySetFloatingPositions(data.FloatPos)
                else Spooky.PendingFloatingPositions = data.FloatPos end
            end
            if data.KB and type(data.KB) == "table" and _G.ALL_KEYBIND_DEFS then
                local targetKBs = _G.PCKeybinds or PCKeybinds
                if targetKBs then
                    table.clear(targetKBs)
                    for _, s in ipairs(data.KB) do
                        for _, def in ipairs(_G.ALL_KEYBIND_DEFS) do
                            if Spooky.ResolveFeature(def.id) == Spooky.ResolveFeature(s.id) then
                                table.insert(targetKBs, {
                                    id = def.id,
                                    name = def.name,
                                    mode = def.mode,
                                    key = s.key or def.defaultKey,
                                    run = def.run
                                })
                                break
                            end
                        end
                    end
                    if _G.savePCKeybinds then _G.savePCKeybinds() end
                    if _G.RefreshKeybindsList then pcall(_G.RefreshKeybindsList) end
                end
            end
            return true
        elseif ok and data and (data.t or data.theme or data.scale or data.animation) then
            return applyCompactUIConfig(data)
        end
        return false
    end

