    local function updateOneShotWidgetVisuals(enabled)
        if oneShotStatusLbl then
            oneShotStatusLbl.Text = enabled and "ENABLED" or "DISABLED"
            oneShotStatusLbl.TextColor3 = enabled and Color3.fromRGB(80, 220, 120) or Color3.fromRGB(160, 160, 170)
        end
