    local function toggleOneShotKitsuneWidget()
        if oneShotWidgetGui and oneShotWidgetGui.Parent then
            oneShotWidgetGui.Enabled = not oneShotWidgetGui.Enabled
            return
        end

        local pGui = LocalPlayer:FindFirstChild("PlayerGui")
        if not pGui then return end

        oneShotWidgetGui = Instance.new("ScreenGui")
        oneShotWidgetGui.Name = "Sovereign_OneShotKitsune_Widget"
        oneShotWidgetGui.ResetOnSpawn = false
