do
    local AntiStunActive = false
    local StunConnections = {}
    local CurrentChar = nil
    local CurrentRoot = nil
    local StunObject = nil
    local StunConn = nil
    local LastStunVal = 0
    local MoverEpoch = 0
    local AttrTimes = { Character = {}, HRP = {} }
    local HostileUntil = 0

    local HostileAttrsChar = { LastDamageTick = true, LastDamageTakenAt = true, InCombat = true }
    local HostileAttrsHRP = {
        LastDetectedDuration = true, LastDetectedTimestamp = true, LastDetectedPriority = true,
        LastDetectedVelocity = true, LastDetectedKnockback = true, LastStunAnimation = true, IdleStunCounter = true
    }

    local function cancelHostileMovers()
        if not AntiStunActive or not CurrentRoot then return end
        pcall(function()
            for _, m in ipairs(CurrentRoot:GetChildren()) do
                if (m:IsA("BodyVelocity") or m:IsA("BodyPosition") or m:IsA("BodyGyro")) and m.Name ~= "RootVelocity" and m.Name ~= "Keep" and not m.Name:match("^Sovereign_") then
                    pcall(function() m:Destroy() end)
                end
            end
        end)
    end

    local function onStunChanged()
        if not AntiStunActive or not StunObject then return end
        local val = tonumber(StunObject.Value) or 0
        if val > 0 then
            local now = os.clock()
            local recentDmg = math.max(AttrTimes.Character.LastDamageTick or 0, AttrTimes.Character.LastDamageTakenAt or 0)
            local isHostile = (now - recentDmg <= 0.35) or (now <= HostileUntil)
            if isHostile then
                StunObject.Value = 0
                cancelHostileMovers()
            end
        end
    end

    local function cleanupAntiStunChar()
        for _, c in ipairs(StunConnections) do
            pcall(function() c:Disconnect() end)
        end
        table.clear(StunConnections)
        if StunConn then pcall(function() StunConn:Disconnect() end); StunConn = nil end
        StunObject = nil
        CurrentRoot = nil
        CurrentChar = nil
    end

    local function bindAntiStun(char)
        cleanupAntiStunChar()
        if not char or not char.Parent then return end
        CurrentChar = char
        CurrentRoot = char:FindFirstChild("HumanoidRootPart")
        AttrTimes = { Character = {}, HRP = {} }

        table.insert(StunConnections, char.AttributeChanged:Connect(function(attr)
            if HostileAttrsChar[attr] then
                local now = os.clock()
                AttrTimes.Character[attr] = now
                HostileUntil = now + 0.35
                cancelHostileMovers()
                if StunObject and (tonumber(StunObject.Value) or 0) > 0 then
                    StunObject.Value = 0
                end
            end
        end))

        if CurrentRoot then
            table.insert(StunConnections, CurrentRoot.AttributeChanged:Connect(function(attr)
                if HostileAttrsHRP[attr] then
                    local now = os.clock()
                    AttrTimes.HRP[attr] = now
                    HostileUntil = now + 0.35
                    cancelHostileMovers()
                end
            end))
        end

        local function watchChild(child)
            if child.Name == "Stun" and child:IsA("NumberValue") then
                StunObject = child
                if StunConn then pcall(function() StunConn:Disconnect() end) end
                StunConn = child.Changed:Connect(onStunChanged)
                onStunChanged()
            elseif child.Name == "HumanoidRootPart" then
                CurrentRoot = child
            end
        end

        table.insert(StunConnections, char.ChildAdded:Connect(watchChild))
        table.insert(StunConnections, char.ChildRemoved:Connect(function(child)
            if child == StunObject then
                if StunConn then pcall(function() StunConn:Disconnect() end); StunConn = nil end
                StunObject = nil
            end
        end))

        local existingStun = char:FindFirstChild("Stun")
        if existingStun and existingStun:IsA("NumberValue") then
            watchChild(existingStun)
        end
    end

    function _G.SpookySetAntiStun(enabled)
        AntiStunActive = (enabled == true)
        if AntiStunActive then
            bindAntiStun(LocalPlayer.Character)
        else
            cleanupAntiStunChar()
        end
    end

    LocalPlayer.CharacterAdded:Connect(function(newChar)
        if AntiStunActive then
            task.delay(0.2, function()
                bindAntiStun(newChar)
            end)
        end
    end)

    task.spawn(function()
        local lastAttempt = 0
        while isCurrentSession() do
            task.wait(0.4)
            if not isCurrentSession() then return end
            if FeatureStates["AutoV3"] or Settings.autoV3 then
                local now = os.clock()
                if now - lastAttempt >= 1.5 then
                    lastAttempt = now
                    pcall(function()
                        local rem = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
                        local commE = rem and rem:FindFirstChild("CommE")
                        if commE then
                            commE:FireServer("ActivateAbility")
                        else
                            local commF = rem and rem:FindFirstChild("CommF_")
                            if commF then commF:InvokeServer("ActivateAbility") end
                        end
                    end)
                end
            end
        end
    end)
end

