    getgenv().tomultiply = 250

    task.spawn(function()
        pcall(function()
            local rs = game:GetService("ReplicatedStorage")
            local mod = rs:WaitForChild("Modules", 5)
            local cuInst = mod and mod:WaitForChild("CombatUtil", 5)
            if cuInst then
                local CombatUtil = require(cuInst)
                if CombatUtil and typeof(CombatUtil) == "table" and CombatUtil.GetWeaponData then
                    local oldGetWeaponData = CombatUtil.GetWeaponData
                    CombatUtil.GetWeaponData = function(...)
                        local Data = oldGetWeaponData(...)
                        if not HitboxExpanderActive or not Data then
                            return Data
                        end
                        local Proxy = {}
                        setmetatable(Proxy, {
                            __index = function(self, key)
                                local val = Data[key]
                                if key == "HitboxMagnitude" and typeof(val) == "number" then
                                    local mult = tonumber(getgenv().tomultiply) or 250
                                    return val * mult
                                end
                                return val
                            end,
                            __newindex = function(self, key, val)
                                Data[key] = val
                            end
                        })
                        return Proxy
                    end
                end
            end
        end)
    end)

