    local RegisterHit = nil
    local RegisterAttack = nil
    local function resolveAttackRemotes()
        if RegisterHit and RegisterAttack then return true end
        pcall(function()
            local net = game:GetService("ReplicatedStorage"):WaitForChild("Modules", 2):WaitForChild("Net", 2)
            if net then
                RegisterHit = net:FindFirstChild("RE/RegisterHit") or net["RE/RegisterHit"]
                RegisterAttack = net:FindFirstChild("RE/RegisterAttack") or net["RE/RegisterAttack"]
            end
        end)
        return (RegisterHit ~= nil and RegisterAttack ~= nil)
    end

    local lastFastAttackTime = 0
    local function executeFastAttackBurst()
        local now = tick()
        if now - lastFastAttackTime < math.max(tonumber(Settings.fastAttackDelay) or 0.15,0.12) then return end
        lastFastAttackTime = now
        local myChar = LocalPlayer.Character
        local myHRP = myChar and myChar:FindFirstChild("HumanoidRootPart")
        if not myHRP then return end
        local isCasting = myChar:GetAttribute("isUsingSkill") or myChar:GetAttribute("UsingSkill") or myChar:GetAttribute("Busy")
        if isCasting == true then return end
        local currentTool = myChar:FindFirstChildOfClass("Tool")
        if not currentTool or currentTool.ToolTip == "Gun" then return end
        local myPos = myHRP.Position
        local hitList = {}
        local enemies = workspace:FindFirstChild("Enemies")
        if enemies then
            for _, npc in ipairs(enemies:GetChildren()) do
                local hum = npc:FindFirstChildOfClass("Humanoid")
                local hrp = npc:FindFirstChild("HumanoidRootPart")
                local head = npc:FindFirstChild("Head") or hrp
                if hum and hum.Health > 0 and hrp and head and (hrp.Position - myPos).Magnitude <= 120 then
                    table.insert(hitList, { npc, head })
                end
            end
        end
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LocalPlayer and p.Character then
                local hum = p.Character:FindFirstChildOfClass("Humanoid")
                local hrp = p.Character:FindFirstChild("HumanoidRootPart")
                local head = p.Character:FindFirstChild("Head") or hrp
                if hum and hum.Health > 0 and hrp and head and _G.SpookyCombatTargetValid and _G.SpookyCombatTargetValid(p,120) then
                    table.insert(hitList, { p.Character, head })
                end
            end
        end
        if #hitList > 0 and Spooky.TakeAttackBudget("M1", Settings.fastAttackDelay) then
            local trimmedList = {}
            for i = 1, math.min(#hitList, 3) do
                table.insert(trimmedList, hitList[i])
            end
            local primaryPart = trimmedList[1][2]
            local targetPos = primaryPart.Position
            local diff = targetPos - myPos
            local aimDir = (diff.Magnitude > 0.05 and diff.Unit) or Vector3.new(0, 0, -1)
            pcall(function()
                if currentTool and currentTool:FindFirstChild("LeftClickRemote") then
                    currentTool.LeftClickRemote:FireServer(aimDir, 1)
                elseif resolveAttackRemotes() then
                    RegisterAttack:FireServer(0)
                    RegisterHit:FireServer(primaryPart, trimmedList)
                end
            end)
        end
    end

    local lastFastAttackTick = 0
    registerConnection(RunService.Heartbeat:Connect(function()
        if not (FeatureStates["FastAttack"] or Settings.fastAttack) then return end
        local now = tick()
        if now - lastFastAttackTick < math.max(tonumber(Settings.fastAttackDelay) or 0.15,0.12) then return end
        lastFastAttackTick = now
        executeFastAttackBurst()
    end))

    M1Extender = (function()
        local M = {}
        local active = false
        local maxRange = 100

        local function getExtTarget()
            local myChar = LocalPlayer.Character
            local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
            if not myRoot then return nil end
            local myPos = myRoot.Position
            local target, shortestDist = nil, maxRange

            local enemies = workspace:FindFirstChild("Enemies")
            if enemies then
                for _, v in ipairs(enemies:GetChildren()) do
                    local eRoot = v:FindFirstChild("HumanoidRootPart")
                    local eHum = v:FindFirstChildOfClass("Humanoid")
                    if eRoot and eHum and eHum.Health > 0 then
                        local dist = (eRoot.Position - myPos).Magnitude
                        if dist < shortestDist then
                            shortestDist = dist
                            target = v
                        end
                    end
                end
            end

            local chars = workspace:FindFirstChild("Characters")
            if chars then
                for _, v in ipairs(chars:GetChildren()) do
                    if v ~= myChar then
                        local eRoot = v:FindFirstChild("HumanoidRootPart")
                        local eHum = v:FindFirstChildOfClass("Humanoid")
                        if eRoot and eHum and eHum.Health > 0 then
                            local dist = (eRoot.Position - myPos).Magnitude
                            if dist < shortestDist then
                                shortestDist = dist
                                target = v
                            end
                        end
                    end
                end
            end

            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer and p.Character and p.Character ~= myChar then
                    local eRoot = p.Character:FindFirstChild("HumanoidRootPart")
                    local eHum = p.Character:FindFirstChildOfClass("Humanoid")
                    if eRoot and eHum and eHum.Health > 0 then
                        local dist = (eRoot.Position - myPos).Magnitude
                        if dist < shortestDist then
                            shortestDist = dist
                            target = p.Character
                        end
                    end
                end
            end

            return target
        end

        local lastM1Fire = 0
        local function triggerM1Attack()
            if not (FeatureStates["M1Extender"] or Settings.m1Extender) then return end
            local myChar = LocalPlayer.Character
            local tool = myChar and myChar:FindFirstChildOfClass("Tool")
            if not tool then return end

            local now = tick()
            if now - lastM1Fire < 0.12 then return end
            lastM1Fire = now

            local target = getExtTarget()
            if not target then return end
            local head = target:FindFirstChild("Head") or target:FindFirstChild("HumanoidRootPart")
            if not head then return end

            local owner = Players:GetPlayerFromCharacter(target)
            if owner and (not _G.SpookyCombatTargetValid or not _G.SpookyCombatTargetValid(owner,100)) then return end
            if tool.ToolTip == "Gun" or myChar:GetAttribute("UsingSkill") or myChar:GetAttribute("isUsingSkill") or myChar:GetAttribute("Busy") then return end
            if not Spooky.TakeAttackBudget("M1",0.15) then return end
            local myHRP = myChar:FindFirstChild("HumanoidRootPart")
            if myHRP and tool:FindFirstChild("LeftClickRemote") then
                local dir = (head.Position - myHRP.Position).Unit
                pcall(function()
                    tool.LeftClickRemote:FireServer(dir, 1)
                end)
            elseif resolveAttackRemotes() then
                pcall(function()
                    RegisterAttack:FireServer(0)
                    local hitData = {}
                    table.insert(hitData, {target,head})
                    local sessionId = tostring(LocalPlayer.UserId):sub(2, 4) .. tostring(coroutine.running()):sub(11, 15)
                    RegisterHit:FireServer(head, hitData, {}, sessionId)
                end)
            end
        end

        registerConnection(UserInputService.InputBegan:Connect(function(input, processed)
            if processed then return end
            if input.UserInputType == Enum.UserInputType.MouseButton1 then
                triggerM1Attack()
            end
        end))

        local function bindTool(tool)
            if not tool or not tool:IsA("Tool") then return end
            registerConnection(tool.Activated:Connect(function()
                triggerM1Attack()
            end))
        end

        if LocalPlayer.Character then
            for _, item in ipairs(LocalPlayer.Character:GetChildren()) do
                if item:IsA("Tool") then bindTool(item) end
            end
            LocalPlayer.Character.ChildAdded:Connect(function(child)
                if child:IsA("Tool") then bindTool(child) end
            end)
        end
        LocalPlayer.CharacterAdded:Connect(function(newChar)
            newChar.ChildAdded:Connect(function(child)
                if child:IsA("Tool") then bindTool(child) end
            end)
        end)

        function M:Toggle(v) active = v end
        function M:SetRange(v) maxRange = 100 end
        return M
    end)()

    task.spawn(function()
        while isCurrentSession() do
            if FeatureStates["AutoV4"] or Settings.autoV4 then
                local char = LocalPlayer.Character
                if char then
                    local energy = char:FindFirstChild("RaceEnergy")
                    local transformed = char:FindFirstChild("RaceTransformed")
                    local stun = char:FindFirstChild("Stun")
                    local busy = char:FindFirstChild("Busy")

                    local hasEnergy = energy and tonumber(energy.Value) and tonumber(energy.Value) >= 1
                    local notTransformed = not transformed or (transformed.Value ~= true)
                    local notStunned = not stun or (tonumber(stun.Value) or 0) <= 0
                    local notBusy = not busy or (busy.Value ~= true)

                    if hasEnergy and notTransformed and notStunned and notBusy then
                        pcall(function()
                            local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
                            local commE = remotes and remotes:FindFirstChild("CommE")
                            if commE then commE:FireServer("ActivateAwakening", true) end
                        end)
                        pcall(function()
                            local bp = LocalPlayer:FindFirstChildOfClass("Backpack") or LocalPlayer:FindFirstChild("Backpack")
                            local awk = (bp and bp:FindFirstChild("Awakening")) or (char and char:FindFirstChild("Awakening"))
                            if awk then
                                local hum = char and char:FindFirstChildOfClass("Humanoid")
                                if awk.Parent == bp and hum then
                                    pcall(function() hum:EquipTool(awk) end)
                                end
                                pcall(function() awk:Activate() end)
                                local rf = awk:FindFirstChild("RemoteFunction")
                                if rf and rf:IsA("RemoteFunction") then pcall(function() rf:InvokeServer(true) end) end
                            end
                        end)
                        task.wait(2.0)
                    end
                end
                task.wait(0.5)
            else
                task.wait(0.5)
            end
        end
    end)

    task.spawn(function()
        while isCurrentSession() do
            if FeatureStates["AutoBuso"] or Settings.autoBuso then
                local char = LocalPlayer.Character
                if char and not char:FindFirstChild("HasBuso") then
                    pcall(function()
                        local rem = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
