            if FeatureStates["AutoKen"] or Settings.autoKen then
                pcall(function()
                    local char = LocalPlayer.Character
                    if char and not char:FindFirstChild("KenDisabled") then
                        local pGui = LocalPlayer:FindFirstChild("PlayerGui")
                        if pGui then
                            local ctx = pGui:FindFirstChild("MobileContextButtons")
                            local cFrame = ctx and ctx:FindFirstChild("ContextButtonFrame")
                            local kBtn = cFrame and cFrame:FindFirstChild("BoundActionKen")
                            if kBtn and kBtn:GetAttribute("Selected") ~= true then
                                kBtn:SetAttribute("Selected", true)
                            end
                        end
                        local om = (getrenv and getrenv()._G and getrenv()._G.OM) or (_G and _G.OM)
