    end)

    _G.FruitsM1Enable = false
    _G.FruitsM1DelayValue = 0.15

    local function GetFruitRemote()
        local char = LocalPlayer.Character
        local tool = char and char:FindFirstChildOfClass("Tool")
        if not tool or getToolCategory(tool) ~= "Fruit" then return nil end
        local remote = tool:FindFirstChild("LeftClickRemote") or tool:FindFirstChild("ClickRemote") or tool:FindFirstChild("M1Remote")
        if remote and remote:IsA("RemoteEvent") then return remote end
        for _, child in ipairs(tool:GetChildren()) do
            if child:IsA("RemoteEvent") and child.Name:lower():find("click") then return child end
        end
    end
    task.spawn(function()
        while isCurrentSession() do
            task.wait(math.clamp(tonumber(_G.FruitsM1DelayValue) or 0.15, 0.15, 2))
            if not isCurrentSession() then break end
            if _G.FruitsM1Enable or FeatureStates["OneShotKitsune"] then
                pcall(function()
                    local char = LocalPlayer.Character
                    local root = char and char:FindFirstChild("HumanoidRootPart")
                    local remote = GetFruitRemote()
                    if not root or not remote then return end

                    local folders = {workspace:FindFirstChild("Characters"), workspace:FindFirstChild("Enemies")}
                    for _, folder in pairs(folders) do
                        for _, model in ipairs(folder:GetChildren()) do
                            local hrp = model:FindFirstChild("HumanoidRootPart")
                            local hum = model:FindFirstChildOfClass("Humanoid")
                            local player = Players:GetPlayerFromCharacter(model)
                            local excluded = player and (not _G.SpookyCombatTargetValid or not _G.SpookyCombatTargetValid(player,500))
                            if model ~= char and not excluded and hrp and hum and hum.Health > 0 and (hrp.Position-root.Position).Magnitude < 500 then
                                remote:FireServer(Vector3.new(9e30, 9e30, 9e30), 5, false)
                                return
                            end
                        end
                    end
                end)
            end
        end
    end)

end
