do
    local HideControlActive = false
    local HideV4Active = false
    local ControlConnections = {}
    local V4Connections = {}

    local function hideInstanceFX(inst)
        if not inst then return end
        pcall(function()
            if inst:IsA("ParticleEmitter") or inst:IsA("Trail") or inst:IsA("Beam") then
                inst.Enabled = false
                inst.Transparency = NumberSequence.new(1)
            elseif inst:IsA("Highlight") then
                inst.Enabled = false
                inst.FillTransparency = 1
                inst.OutlineTransparency = 1
            elseif inst:IsA("Light") or inst:IsA("Fire") or inst:IsA("Smoke") or inst:IsA("Sparkles") then
                inst.Enabled = false
            elseif inst:IsA("BasePart") then
                inst.Transparency = 1
                inst.LocalTransparencyModifier = 1
                inst.CastShadow = false
                inst.Size = Vector3.zero
                local sm = inst:FindFirstChildOfClass("SpecialMesh")
                if sm then sm.Scale = Vector3.zero end
                for _, sub in ipairs(inst:GetChildren()) do
                    if sub:IsA("Decal") or sub:IsA("Texture") then
                        sub.Transparency = 1
                    end
                end
            elseif inst:IsA("Decal") or inst:IsA("Texture") then
                inst.Transparency = 1
            end
        end)
    end

    local controlKeywords = {
        "control", "room", "globe", "cube", "dagger", "levitat", "sphere", "teleport_effect", "echoingslash", "dome", "area", "ring", "koko", "domain", "controlroom", "slash"
    }

    local function isControlEffect(inst)
        if not inst or not inst.Parent then return false end
        if inst:IsA("Model") and inst:FindFirstChildOfClass("Humanoid") then return false end
        if inst == workspace.Terrain then return false end
        local map = workspace:FindFirstChild("Map")
        if map and (inst == map or inst:IsDescendantOf(map)) then return false end

        local n = string.lower(inst.Name)
        for _, kw in ipairs(controlKeywords) do
            if string.find(n, kw, 1, true) then
                return true
            end
        end
        local p = inst.Parent
        if p and p ~= workspace and p.Name ~= "Characters" and p.Name ~= "Enemies" then
            local pn = string.lower(p.Name)
            for _, kw in ipairs(controlKeywords) do
                if string.find(pn, kw, 1, true) then
                    return true
                end
            end
        end
        return false
    end

    local function processControlInstance(child)
        if not HideControlActive or not child then return end
        if isControlEffect(child) then
            hideInstanceFX(child)
            for _, d in ipairs(child:GetDescendants()) do
                hideInstanceFX(d)
                if d:IsA("AnimationTrack") then
                    pcall(function() d:AdjustSpeed(0) end)
                end
            end
        end
    end

    local function stopControlWatchers()
        for _, conn in ipairs(ControlConnections) do
            pcall(function() conn:Disconnect() end)
        end
        table.clear(ControlConnections)
    end

    function _G.SpookySetHideControlEffects(enabled)
        HideControlActive = (enabled == true)
        stopControlWatchers()
        if HideControlActive then

            local origin = workspace:FindFirstChild("_WorldOrigin")
            if origin then
                for _, ch in ipairs(origin:GetDescendants()) do
                    processControlInstance(ch)
                end
                table.insert(ControlConnections, origin.DescendantAdded:Connect(function(child)
                    if HideControlActive then task.defer(processControlInstance, child) end
                end))
            end

            local fx = workspace:FindFirstChild("Effects") or workspace:FindFirstChild("FX")
            if fx then
                for _, ch in ipairs(fx:GetDescendants()) do
                    processControlInstance(ch)
                end
                table.insert(ControlConnections, fx.DescendantAdded:Connect(function(child)
                    if HideControlActive then task.defer(processControlInstance, child) end
                end))
            end

            for _, ch in ipairs(workspace:GetChildren()) do
                processControlInstance(ch)
            end
            table.insert(ControlConnections, workspace.ChildAdded:Connect(function(child)
                if HideControlActive then
                    task.defer(processControlInstance, child)
                    if child.Name == "_WorldOrigin" or child.Name == "Effects" or child.Name == "FX" then
                        table.insert(ControlConnections, child.DescendantAdded:Connect(function(desc)
                            if HideControlActive then task.defer(processControlInstance, desc) end
                        end))
                    end
                end
            end))

            for _, p in ipairs(Players:GetPlayers()) do
                if p.Character then
                    for _, ch in ipairs(p.Character:GetDescendants()) do
                        processControlInstance(ch)
                    end
                    table.insert(ControlConnections, p.Character.DescendantAdded:Connect(function(child)
                        if HideControlActive then task.defer(processControlInstance, child) end
                    end))
                end
                table.insert(ControlConnections, p.CharacterAdded:Connect(function(newChar)
                    if HideControlActive then
                        table.insert(ControlConnections, newChar.DescendantAdded:Connect(function(child)
                            if HideControlActive then task.defer(processControlInstance, child) end
                        end))
                    end
                end))
            end

            task.spawn(function()
                while HideControlActive and isCurrentSession() do
                    task.wait(1.5)
                    local wo = workspace:FindFirstChild("_WorldOrigin")
                    if wo then
                        for _, ch in ipairs(wo:GetChildren()) do
                            if isControlEffect(ch) then processControlInstance(ch) end
                        end
                    end
                    for _, ch in ipairs(workspace:GetChildren()) do
                        if isControlEffect(ch) then processControlInstance(ch) end
                    end
                end
            end)
        end
    end

    local function scanV4Container(container)
        if not container then return end
        for _, obj in ipairs(container:GetDescendants()) do
            hideInstanceFX(obj)
        end
    end

    function _G.SpookySetHideV4Effects(enabled)
        HideV4Active = (enabled == true)
        if HideV4Active then
            pcall(function()
                local effect = game:GetService("ReplicatedStorage"):FindFirstChild("Effect")
                local container = effect and effect:FindFirstChild("Container")
                if container then
                    scanV4Container(container:FindFirstChild("RaceAwakenings"))
                    scanV4Container(container:FindFirstChild("RaceTransformation"))
                    scanV4Container(container:FindFirstChild("DracoRace"))
                end
                local fx = game:GetService("ReplicatedStorage"):FindFirstChild("FX")
                if fx then scanV4Container(fx:FindFirstChild("DracoRace")) end
            end)
            for _, p in ipairs(Players:GetPlayers()) do
                local c = p.Character
                if c then
                    for _, d in ipairs(c:GetDescendants()) do
                        local n = string.lower(d.Name)
                        if n:find("v4") or n:find("awakening") or n:find("aura") or n:find("transformation") then
                            hideInstanceFX(d)
                        end
                    end
                end
            end
        end
    end
end

