        tHpBar.BorderSizePixel = 0
        Instance.new("UICorner", tHpBar).CornerRadius = UDim.new(0, 3)

        local dragging = false
        local dragStart, startPos
        hudMain.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging = true
                dragStart = input.Position
                startPos = hudMain.Position
                input.Changed:Connect(function()
                    if input.UserInputState == Enum.UserInputState.End then
                        dragging = false
                    end
                end)
            end
        end)
        UserInputService.InputChanged:Connect(function(input)
            if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
                local delta = input.Position - dragStart
                hudMain.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
            end
        end)

        local lastUpdate = 0
        combatHUDConn = RunService.Heartbeat:Connect(function(dt)
            local now = tick()
            if now - lastUpdate < 0.1 then return end
            lastUpdate = now

            local char = LocalPlayer.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if hum then
                local maxHp = math.max(hum.MaxHealth, 1)
                local curHp = math.clamp(hum.Health, 0, maxHp)
                local pct = curHp / maxHp
                hpBar.Size = UDim2.new(pct, 0, 1, 0)
                hpText.Text = "HP: " .. tostring(math.floor(curHp)) .. " (" .. tostring(math.floor(pct * 100)) .. "%)"
                if pct > 0.5 then
                    hpBar.BackgroundColor3 = Color3.fromRGB(50, 210, 100)
                elseif pct > 0.25 then
                    hpBar.BackgroundColor3 = Color3.fromRGB(240, 180, 40)
                else
                    hpBar.BackgroundColor3 = Color3.fromRGB(230, 60, 60)
                end
            else
                hpText.Text = "HP: Dead"
                hpBar.Size = UDim2.new(0, 0, 1, 0)
            end

            local pMs = (getClientPing and getClientPing()) or 50
            local curFps = math.floor(1 / math.max(dt or 0.016, 0.001))
            curFps = math.clamp(curFps, 1, 144)
            pingLbl.Text = tostring(curFps) .. "FPS | " .. tostring(math.floor(pMs)) .. "ms"
            if pMs < 80 then
                pingLbl.TextColor3 = Color3.fromRGB(80, 240, 140)
            elseif pMs < 160 then
                pingLbl.TextColor3 = Color3.fromRGB(240, 200, 60)
            else
                pingLbl.TextColor3 = Color3.fromRGB(240, 70, 70)
            end

            local tChar = _G.lockedAim1Char or _G.lockedAim2Char or _G.centuTargetChar
            if tChar and tChar.Parent then
                local tHum = tChar:FindFirstChildOfClass("Humanoid")
                local tHrp = tChar:FindFirstChild("HumanoidRootPart") or tChar:FindFirstChild("Head") or tChar.PrimaryPart
                local tName = tChar.Name
                local myRoot = char and char:FindFirstChild("HumanoidRootPart")
                local dist = (myRoot and tHrp) and math.floor((tHrp.Position - myRoot.Position).Magnitude) or 0

                if tHum and tHum.Health > 0 then
                    local tMax = math.max(tHum.MaxHealth, 1)
                    local tCur = math.clamp(tHum.Health, 0, tMax)
                    local tPct = tCur / tMax
                    targetLbl.Text = "TARGET: " .. string.sub(tName, 1, 12) .. " (" .. tostring(math.floor(tCur)) .. " HP)"
                    targetLbl.TextColor3 = Color3.fromRGB(255, 120, 120)
                    targetSubLbl.Text = "Dist: " .. tostring(dist) .. " studs | " .. tostring(math.floor(tPct * 100)) .. "% HP"
                    targetSubLbl.TextColor3 = Color3.fromRGB(180, 220, 255)
                    tHpBar.Size = UDim2.new(tPct, 0, 1, 0)
                    if tPct > 0.5 then
                        tHpBar.BackgroundColor3 = Color3.fromRGB(255, 80, 80)
                    else
                        tHpBar.BackgroundColor3 = Color3.fromRGB(255, 30, 30)
                    end
                else
                    targetLbl.Text = "TARGET: " .. string.sub(tName, 1, 12) .. " (DEAD)"
                    targetLbl.TextColor3 = Color3.fromRGB(160, 160, 175)
                    targetSubLbl.Text = "Dist: " .. tostring(dist) .. " studs | Offline"
                    tHpBar.Size = UDim2.new(0, 0, 1, 0)
                end
            else
                targetLbl.Text = "TARGET: None"
                targetLbl.TextColor3 = Color3.fromRGB(160, 160, 175)
                targetSubLbl.Text = "Scanning active arena..."
                tHpBar.Size = UDim2.new(0, 0, 1, 0)
            end
        end)    end

