        if v then
            createCombatHUDWidget()
            notifyToggle("Combat HUD: ENABLED", true)
        else
            if combatHUDConn then combatHUDConn:Disconnect(); combatHUDConn = nil end
            if CombatHUDWidgetGui then CombatHUDWidgetGui:Destroy(); CombatHUDWidgetGui = nil end
            notifyToggle("Combat HUD: DISABLED", false)
        end
    end

end
