    local function createDefaultBlock()
        return {
            enabled = false, weapon = "Melee", skill = "Z", mode = "Tap", hold = 0.35, delay = 0.22, jumpsAfter = 0,
            fallbackEnabled = false, fallbackWeapon = "Sword", fallbackSkill = "X", fallbackMode = "Tap", fallbackHold = 0.35
        }
