    local function createDefaultSlot(name)
        local sl = {
            name = name or "Slot",
            soruEnabled = false, soruAfter = 0,
            m1Enabled = false, m1Weapon = "Melee", m1Count = 2, m1After = 1,
            v3Enabled = false, v3After = 0,
            abilityTriggerEnabled = false, abilityTriggerWeapon = "Gun", abilityTriggerKey = "Z",
            steps = {}
        }
        for i = 1, 10 do sl.steps[i] = createDefaultBlock() end
        return sl
    end

