    local function selectSlot(idx)
        Settings.macroActiveSlot = idx
        Settings.macroCustomSteps = Settings.macroSlots[idx].steps
        slotNameBox.Text = Settings.macroSlots[idx].name or ("Slot " .. idx)
        for i, b in ipairs(slotBtns) do
            b.Text = Settings.macroSlots[i].name or ("Slot " .. i)
            if i == idx then
                b.BackgroundColor3 = Color3.fromRGB(34, 46, 75)
                b.TextColor3 = Color3.fromRGB(120, 235, 255)
            else
                b.BackgroundColor3 = Color3.fromRGB(18, 18, 26)
                b.TextColor3 = Color3.fromRGB(140, 140, 160)
            end
        end
        if refreshBanner then refreshBanner() end
        if refreshStepRowsVisual then refreshStepRowsVisual() end
        notifyToggle("Macro Slot " .. idx .. ": " .. (Settings.macroSlots[idx].name or ""), true)
    end

