    local liveComboText = Instance.new("TextLabel", bannerFrame)
    liveComboText.Size = UDim2.new(1, -16, 1, 0)
    liveComboText.Position = UDim2.new(0, 8, 0, 0)
    liveComboText.BackgroundTransparency = 1
    liveComboText.Font = Enum.Font.GothamBold
    liveComboText.TextSize = 10.5
    liveComboText.TextColor3 = Color3.fromRGB(120, 235, 255)
    liveComboText.TextXAlignment = Enum.TextXAlignment.Center

    refreshBanner = function()
        local parts = {}
        local steps = Settings.macroCustomSteps or {}
        for _, s in ipairs(steps) do
            if s.enabled and s.weapon and s.skill and s.weapon ~= "None" and s.skill ~= "None" then
                local hStr = (s.hold == true or s.mode == "Hold") and " (Hold)" or ""
                table.insert(parts, tostring(s.weapon) .. " " .. tostring(s.skill) .. hStr)
            end
        end
        if #parts == 0 then
            liveComboText.Text = "No active steps configured (Toggle steps below)"
            liveComboText.TextColor3 = Color3.fromRGB(150, 150, 170)
        else
            liveComboText.Text = table.concat(parts, " -> ") .. " [AUTO-TIMED]"
            liveComboText.TextColor3 = Color3.fromRGB(100, 235, 255)
        end
    end
    _G.UpdateMacroBannerFunc = refreshBanner
    refreshBanner()

    local weaponChoices = { "Melee", "Sword", "Gun", "Fruit", "None" }
    local skillChoices = { "Z", "X", "C", "V", "F", "M1" }
    local WEAPON_SKILLS = {
        Melee = { "Z", "X", "C" },
        Sword = { "Z", "X" },
        Gun   = { "Z", "X" },
        Fruit = { "M1", "Z", "X", "C", "V", "F" },
        None  = { "Z" }
    }

    local WEAPON_PALETTE = {
        Melee = { bg = Color3.fromRGB(34, 16, 26), txt = Color3.fromRGB(255, 145, 170), stroke = Color3.fromRGB(130, 48, 75) },
        Sword = { bg = Color3.fromRGB(16, 28, 44), txt = Color3.fromRGB(130, 215, 255), stroke = Color3.fromRGB(45, 100, 165) },
        Gun   = { bg = Color3.fromRGB(36, 28, 16), txt = Color3.fromRGB(255, 205, 115), stroke = Color3.fromRGB(140, 95, 35) },
        Fruit = { bg = Color3.fromRGB(30, 16, 42), txt = Color3.fromRGB(225, 140, 255), stroke = Color3.fromRGB(120, 50, 160) },
        None  = { bg = Color3.fromRGB(18, 18, 24), txt = Color3.fromRGB(140, 140, 160), stroke = Color3.fromRGB(40, 40, 52) }
    }

    local stepRowUpdaters = {}

    local function createStepRow(i, parent, rowY)
        local stepRow = Instance.new("Frame", parent)
        stepRow.Size = UDim2.new(1, -16, 0, 36)
        stepRow.Position = UDim2.new(0, 8, 0, rowY)
        stepRow.BackgroundColor3 = Color3.fromRGB(14, 14, 20)
        Instance.new("UICorner", stepRow).CornerRadius = UDim.new(0, 7)
        local srStk = Instance.new("UIStroke", stepRow)
        srStk.Color = Color3.fromRGB(38, 36, 52)
        srStk.Thickness = 1.1

        local srGrad = Instance.new("UIGradient", stepRow)
        srGrad.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(18, 18, 26)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(12, 12, 18))
        })
        srGrad.Rotation = 90

        local numPill = Instance.new("Frame", stepRow)
        numPill.Size = UDim2.new(0, 22, 0, 22)
        numPill.Position = UDim2.new(0, 5, 0.5, -11)
        numPill.BackgroundColor3 = Color3.fromRGB(22, 22, 32)
        Instance.new("UICorner", numPill).CornerRadius = UDim.new(0, 6)
        local npStk = Instance.new("UIStroke", numPill)
        npStk.Color = Color3.fromRGB(48, 46, 65)

        local numLbl = Instance.new("TextLabel", numPill)
        numLbl.Size = UDim2.new(1, 0, 1, 0)
        numLbl.BackgroundTransparency = 1
        numLbl.Font = Enum.Font.GothamBold
        numLbl.Text = "#" .. tostring(i)
        numLbl.TextSize = 9.5
        numLbl.TextColor3 = Color3.fromRGB(190, 190, 225)
        numLbl.TextXAlignment = Enum.TextXAlignment.Center

        local toggleStepBtn = Instance.new("TextButton", stepRow)
        toggleStepBtn.Size = UDim2.new(0, 44, 0, 24)
        toggleStepBtn.Position = UDim2.new(0, 31, 0.5, -12)
        toggleStepBtn.Font = Enum.Font.GothamBold
        toggleStepBtn.TextSize = 9
        Instance.new("UICorner", toggleStepBtn).CornerRadius = UDim.new(0, 6)
        local tStk = Instance.new("UIStroke", toggleStepBtn)
        tStk.Thickness = 1.1

        local weaponBtn = Instance.new("TextButton", stepRow)
        weaponBtn.Size = UDim2.new(0, 86, 0, 24)
        weaponBtn.Position = UDim2.new(0, 79, 0.5, -12)
        weaponBtn.Font = Enum.Font.GothamBold
        weaponBtn.TextSize = 10.5
        Instance.new("UICorner", weaponBtn).CornerRadius = UDim.new(0, 6)
        local wStk = Instance.new("UIStroke", weaponBtn)
        wStk.Thickness = 1.1

        local skillBtn = Instance.new("TextButton", stepRow)
        skillBtn.Size = UDim2.new(0, 52, 0, 24)
        skillBtn.Position = UDim2.new(0, 169, 0.5, -12)
        skillBtn.BackgroundColor3 = Color3.fromRGB(22, 22, 32)
        skillBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
        skillBtn.Font = Enum.Font.GothamBold
        skillBtn.TextSize = 11
        Instance.new("UICorner", skillBtn).CornerRadius = UDim.new(0, 6)
        local skStk = Instance.new("UIStroke", skillBtn)
        skStk.Color = Color3.fromRGB(52, 50, 72)
        skStk.Thickness = 1.1

        local holdBtn = Instance.new("TextButton", stepRow)
        holdBtn.Size = UDim2.new(0, 70, 0, 24)
        holdBtn.Position = UDim2.new(0, 225, 0.5, -12)
        holdBtn.Font = Enum.Font.GothamBold
        holdBtn.TextSize = 9
        Instance.new("UICorner", holdBtn).CornerRadius = UDim.new(0, 6)
        local hStk = Instance.new("UIStroke", holdBtn)
        hStk.Thickness = 1.1

        local jumpsBtn = Instance.new("TextButton", stepRow)
        jumpsBtn.Size = UDim2.new(0, 68, 0, 24)
        jumpsBtn.Position = UDim2.new(0, 299, 0.5, -12)
        jumpsBtn.Font = Enum.Font.GothamBold
        jumpsBtn.TextSize = 8.5
        Instance.new("UICorner", jumpsBtn).CornerRadius = UDim.new(0, 6)
        local jStk = Instance.new("UIStroke", jumpsBtn)
        jStk.Thickness = 1.1

        local function getStepData()
            return Settings.macroCustomSteps and Settings.macroCustomSteps[i]
        end

        local function updateVisuals()
            local stepData = getStepData()
            if not stepData then return end

            if stepData.enabled then
                toggleStepBtn.BackgroundColor3 = Color3.fromRGB(18, 40, 58)
                toggleStepBtn.Text = "ON"
                toggleStepBtn.TextColor3 = Color3.fromRGB(90, 225, 255)
                tStk.Color = Color3.fromRGB(45, 125, 195)
            else
                toggleStepBtn.BackgroundColor3 = Color3.fromRGB(18, 18, 24)
                toggleStepBtn.Text = "OFF"
                toggleStepBtn.TextColor3 = Color3.fromRGB(130, 130, 150)
                tStk.Color = Color3.fromRGB(36, 36, 48)
            end

            local pal = WEAPON_PALETTE[stepData.weapon] or WEAPON_PALETTE.None
            weaponBtn.BackgroundColor3 = pal.bg
            weaponBtn.Text = stepData.weapon or "Melee"
            weaponBtn.TextColor3 = pal.txt
            wStk.Color = pal.stroke

            skillBtn.Text = stepData.skill or "Z"

            if stepData.hold == true or stepData.mode == "Hold" then
                holdBtn.BackgroundColor3 = Color3.fromRGB(36, 26, 12)
                holdBtn.Text = "HOLD"
                holdBtn.TextColor3 = Color3.fromRGB(255, 195, 75)
                hStk.Color = Color3.fromRGB(150, 100, 30)
            else
                holdBtn.BackgroundColor3 = Color3.fromRGB(16, 16, 24)
                holdBtn.Text = "TAP"
                holdBtn.TextColor3 = Color3.fromRGB(150, 155, 180)
                hStk.Color = Color3.fromRGB(38, 38, 52)
            end

            local jCount = tonumber(stepData.jumpsAfter or stepData.postJumps) or 0
            if jCount > 0 then
                jumpsBtn.BackgroundColor3 = Color3.fromRGB(16, 32, 28)
                jumpsBtn.Text = jCount .. " Jump" .. (jCount > 1 and "s" or "")
                jumpsBtn.TextColor3 = Color3.fromRGB(110, 240, 180)
                jStk.Color = Color3.fromRGB(35, 110, 75)
            else
                jumpsBtn.BackgroundColor3 = Color3.fromRGB(16, 16, 24)
                jumpsBtn.Text = "0 Jumps"
                jumpsBtn.TextColor3 = Color3.fromRGB(130, 130, 150)
                jStk.Color = Color3.fromRGB(38, 38, 50)
            end
        end

        stepRowUpdaters[i] = updateVisuals
        updateVisuals()

        toggleStepBtn.MouseButton1Click:Connect(function()
            local stepData = getStepData()
            if not stepData then return end
            stepData.enabled = not stepData.enabled
            updateVisuals()
            refreshBanner()
        end)

        local function getValidSkills()
            local stepData = getStepData()
            return WEAPON_SKILLS[stepData and stepData.weapon] or { "Z", "X", "C" }
        end

        weaponBtn.MouseButton1Click:Connect(function()
            local stepData = getStepData()
            if not stepData then return end
            local wIdx = 1
            for idx, wN in ipairs(weaponChoices) do
                if wN == stepData.weapon then wIdx = idx; break end
            end
            wIdx = (wIdx % #weaponChoices) + 1
            stepData.weapon = weaponChoices[wIdx]
            local vs = getValidSkills()
            local found = false
            for _, sk in ipairs(vs) do
                if sk == stepData.skill then found = true; break end
            end
            if not found then stepData.skill = vs[1] end
            updateVisuals()
            refreshBanner()
        end)

        skillBtn.MouseButton1Click:Connect(function()
            local stepData = getStepData()
            if not stepData then return end
            local vs = getValidSkills()
            local curIdx = 1
            for idx, sk in ipairs(vs) do
                if sk == stepData.skill then curIdx = idx; break end
            end
            local nextIdx = (curIdx % #vs) + 1
            stepData.skill = vs[nextIdx]
            updateVisuals()
            refreshBanner()
        end)

        holdBtn.MouseButton1Click:Connect(function()
            local stepData = getStepData()
            if not stepData then return end
            if stepData.mode == "Hold" or stepData.hold == true then
                stepData.mode = "Tap"
                stepData.hold = false
            else
                stepData.mode = "Hold"
                stepData.hold = 0.35
            end
            updateVisuals()
            refreshBanner()
        end)

        jumpsBtn.MouseButton1Click:Connect(function()
            local stepData = getStepData()
            if not stepData then return end
            local curJ = tonumber(stepData.jumpsAfter or stepData.postJumps) or 0
            curJ = (curJ + 1) % 6
            stepData.jumpsAfter = curJ
            stepData.postJumps = curJ
            updateVisuals()
        end)
    end

    refreshStepRowsVisual = function()
        for i = 1, 10 do
            if stepRowUpdaters[i] then stepRowUpdaters[i]() end
        end
    end
    _G.RefreshMacroStepsUI = refreshStepRowsVisual

