            TweenService:Create(fBtn, TweenInfo.new(0.14), { BackgroundTransparency = 0.12 }):Play()
            TweenService:Create(fStk, TweenInfo.new(0.14), { Color = Color3.fromRGB(130, 85, 220), Thickness = 1.3 }):Play()
        end)

        local function onFloatingBtnTrigger()
            pcall(function()
                local pop = TweenService:Create(fStk, TweenInfo.new(0.08), { Color = Color3.fromRGB(255, 255, 255), Thickness = 2.2 })
                pop:Play()
                pop.Completed:Connect(function()
                    TweenService:Create(fStk, TweenInfo.new(0.15), { Color = Color3.fromRGB(130, 85, 220), Thickness = 1.3 }):Play()
                end)
            end)
            if executeMacroCombo then executeMacroCombo() end
        end
        fBtn.Activated:Connect(onFloatingBtnTrigger)
    end
