    local KeybindsPage = createScrollPage("Keybinds_Page", 895)

    local function triggerAwakeningV4(on)
        pcall(function()
            local rem = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
            local commE = rem and rem:FindFirstChild("CommE")
            if commE then commE:FireServer("ActivateAwakening", on ~= false) end
            local bp = LocalPlayer:FindFirstChildOfClass("Backpack") or LocalPlayer:FindFirstChild("Backpack")
            local char = LocalPlayer.Character
            local awk = (bp and bp:FindFirstChild("Awakening")) or (char and char:FindFirstChild("Awakening"))
            if awk then
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                if awk.Parent == bp and hum then
                    pcall(function() hum:EquipTool(awk) end)
                end
                pcall(function() awk:Activate() end)
                local rf = awk:FindFirstChild("RemoteFunction")
                if rf and rf:IsA("RemoteFunction") then pcall(function() rf:InvokeServer(on ~= false) end) end
                local re = awk:FindFirstChild("RemoteEvent")
                if re and re:IsA("RemoteEvent") then pcall(function() re:FireServer(on ~= false) end) end
            end
        end)
    end
    _G.SpookyTriggerAwakeningV4 = triggerAwakeningV4

    local function triggerInstantSoru()
        pcall(function()
            local myChar = LocalPlayer.Character
            local hrp = myChar and (myChar:FindFirstChild("HumanoidRootPart") or myChar.PrimaryPart)
            if not hrp then return end

            pcall(function()
                myChar:SetAttribute("FlashstepCooldown", 0.95)
            end)

            local hum = myChar:FindFirstChildOfClass("Humanoid")
            if hum then
                pcall(function()
                    local anim = Instance.new("Animation")
                    anim.AnimationId = "rbxassetid://17555632156"
                    local tr = hum:LoadAnimation(anim)
                    tr.Priority = Enum.AnimationPriority.Action
                    tr:Play()
                end)
                pcall(function()
                    local snd = Instance.new("Sound")
                    snd.SoundId = "rbxassetid://313762630"
                    snd.Volume = 2
                    snd.Parent = hrp
                    snd:Play()
                    game:GetService("Debris"):AddItem(snd, 2.5)
                end)
            end

            local targetPos = _G.SoruTargetPos or _G.aimbot1TargetPos or _G.centuAimPosition or _G.G_SilentAimTargetPos
            if not targetPos then
                local getter = _G.GetClosestPlayerCombat or _G.GetClosestPlayerAny
                if getter then
                    local char = getter(350)
                    local tHrp = char and (char:FindFirstChild("HumanoidRootPart") or char.PrimaryPart)
                    if tHrp then targetPos = tHrp.Position end
                end
            end
            if not targetPos then
                local cam = workspace.CurrentCamera
                local lookDir = cam and cam.CFrame.LookVector or hrp.CFrame.LookVector
                targetPos = hrp.Position + (lookDir * 110)
            end

            if targetPos then
                _G.SoruTargetPos = targetPos
                pcall(function()
                    local rem = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
                    local commF = rem and rem:FindFirstChild("CommF_")
                    if commF then commF:InvokeServer("Blink", targetPos) end
                end)
                pcall(function()
                    hrp.CFrame = CFrame.new(targetPos + Vector3.new(0, 1.5, 0), targetPos + Vector3.new(0, 1.5, 0) + hrp.CFrame.LookVector)
                    hrp.AssemblyLinearVelocity = Vector3.zero
                end)
            end
        end)
    end
    _G.SpookyTriggerInstantSoru = triggerInstantSoru

