        local function filterAndPopulate(query)
            for _, ch in ipairs(pList:GetChildren()) do
                if ch:IsA("TextButton") then ch:Destroy() end
            end
            local q = string.lower(query or "")
            local matchCount = 0
            for _, def in ipairs(ALL_KEYBIND_DEFS) do
                if q == "" or string.find(string.lower(def.name), q, 1, true) then
                    matchCount = matchCount + 1
                    local itemBtn = Instance.new("TextButton", pList)
                    itemBtn.Size = UDim2.new(1, -4, 0, 32)
                    itemBtn.BackgroundColor3 = Color3.fromRGB(22, 21, 32)
                    itemBtn.Text = ""
                    itemBtn.ZIndex = 12002
                    Instance.new("UICorner", itemBtn).CornerRadius = UDim.new(0, 6)
