    end)

    local kbScroll = Instance.new("ScrollingFrame", cPCKeybinds)
    kbScroll.Size = UDim2.new(1, -12, 0, 545)
    kbScroll.Position = UDim2.new(0, 6, 0, 78)
    kbScroll.BackgroundTransparency = 1
    kbScroll.ScrollBarThickness = 3
    kbScroll.CanvasSize = UDim2.new(0, 0, 0, #PCKeybinds * 34 + 10)

    local kbsLayout = Instance.new("UIListLayout", kbScroll)
    kbsLayout.Padding = UDim.new(0, 4)

    renderPCKeybindsList = function()
        _G.RefreshKeybindsList = renderPCKeybindsList
        for _, ch in ipairs(kbScroll:GetChildren()) do
            if ch:IsA("Frame") or ch:IsA("TextLabel") then ch:Destroy() end
        end
        if #PCKeybinds == 0 then
            kbScroll.CanvasSize = UDim2.new(0, 0, 0, 0)
            local emptyLbl = Instance.new("TextLabel", kbScroll)
            emptyLbl.Size = UDim2.new(1, 0, 0, 60)
            emptyLbl.Position = UDim2.new(0, 0, 0, 20)
            emptyLbl.BackgroundTransparency = 1
            emptyLbl.Font = Enum.Font.Gotham
            emptyLbl.Text = "No keybinds assigned.\nClick '+ ADD KEYBIND' above to add any action or feature!"
            emptyLbl.TextColor3 = Color3.fromRGB(130, 130, 150)
            emptyLbl.TextSize = 10.5
            emptyLbl.TextWrapped = true
            return
        end

        kbScroll.CanvasSize = UDim2.new(0, 0, 0, #PCKeybinds * 34 + 10)

        for _, ent in ipairs(PCKeybinds) do
            local row = Instance.new("Frame", kbScroll)
            row.Size = UDim2.new(1, -6, 0, 30)
            row.BackgroundColor3 = Color3.fromRGB(20, 18, 28)
            Instance.new("UICorner", row).CornerRadius = UDim.new(0, 6)
            local rStk = Instance.new("UIStroke", row)
            rStk.Color = Color3.fromRGB(44, 40, 60)
            rStk.Thickness = 1

            local nameLbl = Instance.new("TextLabel", row)
            nameLbl.Size = UDim2.new(0.44, -8, 1, 0)
            nameLbl.Position = UDim2.new(0, 10, 0, 0)
            nameLbl.BackgroundTransparency = 1
            nameLbl.Font = Enum.Font.GothamBold
            nameLbl.Text = ent.name
            nameLbl.TextColor3 = Color3.fromRGB(235, 235, 245)
            nameLbl.TextSize = 10
            nameLbl.TextXAlignment = Enum.TextXAlignment.Left

            local modeBadge = Instance.new("TextLabel", row)
            modeBadge.Size = UDim2.new(0, 48, 0, 18)
            modeBadge.Position = UDim2.new(0.44, 0, 0.5, -9)
            modeBadge.BackgroundColor3 = (ent.mode == "Toggle") and Color3.fromRGB(30, 50, 40) or Color3.fromRGB(32, 40, 65)
            modeBadge.Font = Enum.Font.GothamBold
            modeBadge.Text = (ent.mode == "Toggle") and "TOGGLE" or "ACTION"
            modeBadge.TextColor3 = (ent.mode == "Toggle") and Color3.fromRGB(140, 225, 170) or Color3.fromRGB(150, 200, 255)
            modeBadge.TextSize = 8
            Instance.new("UICorner", modeBadge).CornerRadius = UDim.new(0, 4)

            local keyBtn = Instance.new("TextButton", row)
            keyBtn.Size = UDim2.new(0, 74, 0, 22)
            keyBtn.Position = UDim2.new(1, -128, 0.5, -11)
            keyBtn.BackgroundColor3 = Color3.fromRGB(28, 26, 38)
            keyBtn.Font = Enum.Font.GothamBold
            keyBtn.Text = "[" .. tostring(ent.key or "None") .. "]"
            keyBtn.TextColor3 = (ent.key and ent.key ~= "None") and Color3.fromRGB(160, 220, 255) or Color3.fromRGB(120, 120, 140)
            keyBtn.TextSize = 9.5
            Instance.new("UICorner", keyBtn).CornerRadius = UDim.new(0, 4)
            local kStk = Instance.new("UIStroke", keyBtn)
            kStk.Color = Color3.fromRGB(55, 50, 75)

            local isListening = false
            keyBtn.MouseButton1Click:Connect(function()
                if isListening then return end
                isListening = true
                keyBtn.Text = "[...]"
                keyBtn.TextColor3 = Color3.fromRGB(255, 215, 50)
                local conn
                conn = UserInputService.InputBegan:Connect(function(input)
                    if input.UserInputType == Enum.UserInputType.Keyboard then
                        conn:Disconnect()
                        isListening = false
                        if input.KeyCode == Enum.KeyCode.Escape then
                            ent.key = "None"
                        else
                            ent.key = input.KeyCode.Name
                        end
                        keyBtn.Text = "[" .. tostring(ent.key) .. "]"
                        keyBtn.TextColor3 = (ent.key ~= "None") and Color3.fromRGB(160, 220, 255) or Color3.fromRGB(120, 120, 140)
                        savePCKeybinds()
                        notifyToggle(ent.name .. " bound to " .. tostring(ent.key), true)
                    end
                end)
            end)

            local clrBtn = Instance.new("TextButton", row)
            clrBtn.Size = UDim2.new(0, 22, 0, 22)
            clrBtn.Position = UDim2.new(1, -50, 0.5, -11)
            clrBtn.BackgroundColor3 = Color3.fromRGB(36, 26, 34)
            clrBtn.Font = Enum.Font.GothamBold
            clrBtn.Text = "X"
            clrBtn.TextColor3 = Color3.fromRGB(255, 140, 140)
            clrBtn.TextSize = 9.5
            Instance.new("UICorner", clrBtn).CornerRadius = UDim.new(0, 4)
            clrBtn.MouseButton1Click:Connect(function()
                ent.key = "None"
                keyBtn.Text = "[None]"
                keyBtn.TextColor3 = Color3.fromRGB(120, 120, 140)
                savePCKeybinds()
                notifyToggle("Cleared keybind for " .. ent.name, true)
            end)

            local delBtn = Instance.new("TextButton", row)
            delBtn.Size = UDim2.new(0, 22, 0, 22)
            delBtn.Position = UDim2.new(1, -26, 0.5, -11)
            delBtn.BackgroundColor3 = Color3.fromRGB(44, 20, 24)
            delBtn.Font = Enum.Font.GothamBold
            delBtn.Text = "-"
            delBtn.TextColor3 = Color3.fromRGB(255, 80, 80)
            delBtn.TextSize = 11
            Instance.new("UICorner", delBtn).CornerRadius = UDim.new(0, 4)
            delBtn.MouseButton1Click:Connect(function()
                for i, k in ipairs(PCKeybinds) do
                    if k == ent then
                        table.remove(PCKeybinds, i)
                        break
                    end
                end
                savePCKeybinds()
                renderPCKeybindsList()
            end)
        end
    end
    _G.RenderPCKeybindsList = renderPCKeybindsList
    renderPCKeybindsList()

    createActionButton(cPCKeybinds, "RESET TO DEFAULTS", "RESETEAR A DEFECTO", UDim2.new(1, -16, 0, 26), UDim2.new(0, 8, 1, -38), function()
        for i = #PCKeybinds, 1, -1 do table.remove(PCKeybinds, i) end
        for _, def in ipairs(ALL_KEYBIND_DEFS) do
            table.insert(PCKeybinds, {
                id = def.id,
                name = def.name,
                mode = def.mode,
                key = def.defaultKey,
                run = def.run
            })
        end
        savePCKeybinds()
        renderPCKeybindsList()
        notifyToggle("PC Keybinds Reset to Default List", true)
    end)

end
do
    local TPIslandsPage = createScrollPage("TPIslands_Page", 860)
    local tc1 = makeCard(TPIslandsPage, "Island Teleport", "Teletransporte", 86, 2)
    local statusBadge = Instance.new("Frame", tc1)
    statusBadge.Size = UDim2.new(1, -20, 0, 24)
