    statusDot.BackgroundColor3 = isTweeningIsland and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(120, 120, 125)
    statusDot.BorderSizePixel = 0
    Instance.new("UICorner", statusDot).CornerRadius = UDim.new(1, 0)
    local statusText = Instance.new("TextLabel", statusBadge)
    statusText.Size = UDim2.new(1, -100, 1, 0)
    statusText.Position = UDim2.new(0, 24, 0, 0)
    statusText.BackgroundTransparency = 1
    statusText.Font = Enum.Font.GothamBold
    statusText.Text = isTweeningIsland and ("TWEENING: " .. (activeTweenTargetName or "Island")) or "STATUS: IDLE"
    statusText.TextSize = 11
    statusText.TextColor3 = isTweeningIsland and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(160, 160, 170)
    statusText.TextXAlignment = Enum.TextXAlignment.Left
    local islandSpeeds = { 200, 250, 300, 350, 400 }
    local currentSpeedIdx = 4
    for idx, spd in ipairs(islandSpeeds) do
        if (getgenv().IslandTweenSpeed or 350) == spd then
            currentSpeedIdx = idx
            break
        end
    end
    local pageSpeedBtn = Instance.new("TextButton", statusBadge)
    pageSpeedBtn.Size = UDim2.new(0, 95, 0, 20)
    pageSpeedBtn.Position = UDim2.new(1, -185, 0, 2)
    pageSpeedBtn.BackgroundColor3 = Color3.fromRGB(36, 36, 42)
    pageSpeedBtn.Font = Enum.Font.GothamBold
    pageSpeedBtn.Text = "SPD: " .. tostring(getgenv().IslandTweenSpeed or 350)
    pageSpeedBtn.TextSize = 10.5
    pageSpeedBtn.TextColor3 = Color3.fromRGB(240, 240, 245)
    Instance.new("UICorner", pageSpeedBtn).CornerRadius = UDim.new(0, 4)
    pageSpeedBtn.MouseButton1Click:Connect(function()
        currentSpeedIdx = (currentSpeedIdx % #islandSpeeds) + 1
        local newSpd = islandSpeeds[currentSpeedIdx]
        getgenv().IslandTweenSpeed = newSpd
        pageSpeedBtn.Text = "SPD: " .. tostring(newSpd)
        if updateRunningIslandTweenSpeed then updateRunningIslandTweenSpeed() end
        notifyToggle("Island Tween Speed: " .. tostring(newSpd), true)
    end)

    local activeSea = "Sea1"
    if game.PlaceId == 4442272183 or game.PlaceId == 79091703265657 then
        activeSea = "Sea2"
    elseif game.PlaceId == 7449423635 or game.PlaceId == 100117331123089 then
        activeSea = "Sea3"
    end
    local seaTabsFrame = Instance.new("Frame", tc1)
    seaTabsFrame.Size = UDim2.new(1, -20, 0, 26)
    seaTabsFrame.Position = UDim2.new(0, 10, 0, 54)
    seaTabsFrame.BackgroundTransparency = 1
    local seaButtons = {}
    local seaDataList = {
        { id = "Sea1", name = "Sea 1 (World 1)" },
        { id = "Sea2", name = "Sea 2 (World 2)" },
        { id = "Sea3", name = "Sea 3 (World 3)" },
    }
    local tc2 = makeCard(TPIslandsPage, "Select Island", "Seleccionar Isla", 740, 92)
    local islandsScroll = Instance.new("ScrollingFrame", tc2)
    islandsScroll.Size = UDim2.new(1, -16, 1, -36)
    islandsScroll.Position = UDim2.new(0, 8, 0, 30)
    islandsScroll.BackgroundTransparency = 1
    islandsScroll.BorderSizePixel = 0
    islandsScroll.ScrollBarThickness = 4
    islandsScroll.ScrollBarImageColor3 = Color3.fromRGB(48, 48, 55)
    local listLayout = Instance.new("UIListLayout", islandsScroll)
    listLayout.Padding = UDim.new(0, 5)
    listLayout.SortOrder = Enum.SortOrder.LayoutOrder
    local function refreshPageIslands()
        for _, c in ipairs(islandsScroll:GetChildren()) do
            if c:IsA("Frame") then c:Destroy() end
        end
        local islands = Islands_NightSlayer[activeSea] or {}
        local char = LocalPlayer.Character
        local myHrp = char and char:FindFirstChild("HumanoidRootPart")
        for idx, isl in ipairs(islands) do
            local row = Instance.new("Frame", islandsScroll)
            row.Name = "Row_" .. isl.name
            row.Size = UDim2.new(1, -6, 0, 36)
            row.BackgroundColor3 = Color3.fromRGB(18, 18, 22)
            row.BorderSizePixel = 0
            Instance.new("UICorner", row).CornerRadius = UDim.new(0, 6)
            local rowStroke = Instance.new("UIStroke", row)
            rowStroke.Color = Color3.fromRGB(34, 34, 42)
            local dist = 0
            pcall(function()
                if myHrp and isl.cf and isl.cf.Position and myHrp.Position then
                    dist = math.floor((isl.cf.Position - myHrp.Position).Magnitude)
                end
            end)
            local nameLbl = Instance.new("TextLabel", row)
            nameLbl.Size = UDim2.new(1, -145, 1, 0)
            nameLbl.Position = UDim2.new(0, 12, 0, 0)
            nameLbl.BackgroundTransparency = 1
            nameLbl.Font = Enum.Font.GothamBold
            nameLbl.Text = string.format("%d. %s   [%dm]", idx, isl.name, dist)
            nameLbl.TextSize = 12
            nameLbl.TextColor3 = Color3.fromRGB(235, 235, 245)
            nameLbl.TextXAlignment = Enum.TextXAlignment.Left
            local isThisIslandActive = isTweeningIsland and (activeTweenTargetName == isl.name)
            local onBtn = Instance.new("TextButton", row)
            onBtn.Size = UDim2.new(0, 58, 0, 26)
            onBtn.Position = UDim2.new(1, -128, 0.5, -13)
            onBtn.BackgroundColor3 = isThisIslandActive and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(14, 14, 18)
            onBtn.Font = Enum.Font.GothamBold
            onBtn.Text = "ON"
            onBtn.TextSize = 11.5
            onBtn.TextColor3 = isThisIslandActive and Color3.fromRGB(12, 12, 15) or Color3.fromRGB(240, 240, 240)
            onBtn.AutoButtonColor = false
            Instance.new("UICorner", onBtn).CornerRadius = UDim.new(0, 5)
            local onStroke = Instance.new("UIStroke", onBtn)
            onStroke.Color = isThisIslandActive and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(45, 45, 55)
            onBtn.MouseButton1Down:Connect(function()
                onBtn.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
                onBtn.TextColor3 = Color3.fromRGB(12, 12, 15)
                onStroke.Color = Color3.fromRGB(255, 255, 255)
            end)
            onBtn.MouseButton1Click:Connect(function()
                startIslandTween(isl.cf, isl.name)
            end)
            local offBtn = Instance.new("TextButton", row)
            offBtn.Size = UDim2.new(0, 58, 0, 26)
            offBtn.Position = UDim2.new(1, -64, 0.5, -13)
            offBtn.BackgroundColor3 = Color3.fromRGB(14, 14, 18)
            offBtn.Font = Enum.Font.GothamBold
            offBtn.Text = "OFF"
            offBtn.TextSize = 11.5
            offBtn.TextColor3 = Color3.fromRGB(240, 240, 240)
            offBtn.AutoButtonColor = false
            Instance.new("UICorner", offBtn).CornerRadius = UDim.new(0, 5)
            local offStroke = Instance.new("UIStroke", offBtn)
            offStroke.Color = Color3.fromRGB(45, 45, 55)
            offBtn.MouseButton1Down:Connect(function()
                offBtn.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
                offBtn.TextColor3 = Color3.fromRGB(12, 12, 15)
                offStroke.Color = Color3.fromRGB(255, 255, 255)
            end)
            local function resetOffVisual()
                TweenService:Create(offBtn, TweenInfo.new(0.18), {
                    BackgroundColor3 = Color3.fromRGB(14, 14, 18),
                    TextColor3 = Color3.fromRGB(240, 240, 240)
                }):Play()
                TweenService:Create(offStroke, TweenInfo.new(0.18), {
                    Color = Color3.fromRGB(45, 45, 55)
                }):Play()
            end
            offBtn.MouseButton1Up:Connect(resetOffVisual)
            offBtn.MouseLeave:Connect(resetOffVisual)
            offBtn.MouseButton1Click:Connect(function()
                stopIslandTween()
            end)
        end
        islandsScroll.CanvasSize = UDim2.new(0, 0, 0, #islands * 41 + 10)
    end
    for i, sData in ipairs(seaDataList) do
        local isSeaActive = (activeSea == sData.id)
        local btn = Instance.new("TextButton", seaTabsFrame)
        btn.Size = UDim2.new(0.32, -4, 1, 0)
        btn.Position = UDim2.new((i - 1) * 0.34, 0, 0, 0)
        btn.BackgroundColor3 = isSeaActive and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(14, 14, 18)
        btn.Font = Enum.Font.GothamBold
        btn.Text = sData.name
        btn.TextSize = 11
        btn.TextColor3 = isSeaActive and Color3.fromRGB(12, 12, 15) or Color3.fromRGB(180, 180, 190)
        btn.AutoButtonColor = false
        Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 6)
        local sStroke = Instance.new("UIStroke", btn)
        sStroke.Color = isSeaActive and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(42, 42, 50)
        seaButtons[sData.id] = { btn = btn, stroke = sStroke }
        btn.MouseButton1Click:Connect(function()
            activeSea = sData.id
            for sId, bData in pairs(seaButtons) do
                local sel = (sId == activeSea)
                TweenService:Create(bData.btn, TweenInfo.new(0.15), {
                    BackgroundColor3 = sel and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(14, 14, 18),
                    TextColor3 = sel and Color3.fromRGB(12, 12, 15) or Color3.fromRGB(180, 180, 190)
                }):Play()
                TweenService:Create(bData.stroke, TweenInfo.new(0.15), {
                    Color = sel and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(42, 42, 50)
                }):Play()
            end
            refreshPageIslands()
        end)
    end
    refreshPageIslands()
    local prevHook = onIslandTweenStateChanged
    onIslandTweenStateChanged = function(active, name)
        if prevHook then pcall(prevHook, active, name) end
        if statusText and statusText.Parent then
            statusText.Text = active and ("TWEENING: " .. (name or "Island")) or "STATUS: IDLE"
            statusText.TextColor3 = active and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(160, 160, 170)
        end
        if statusDot and statusDot.Parent then
            statusDot.BackgroundColor3 = active and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(120, 120, 125)
        end
        refreshPageIslands()
    end
end
