    local function buildCornerBrackets(parentBox)
        local container = Instance.new("Frame", parentBox)
        container.Size = UDim2.new(1, 0, 1, 0)
        container.BackgroundTransparency = 1
        container.ZIndex = 5006

        local lines = {}
        local len, th = 14, 2

        local function addCorner(alignRight, alignBottom)
            local h = Instance.new("Frame", container)
            h.Size = UDim2.new(0, len, 0, th)
            h.Position = UDim2.new(alignRight and 1 or 0, alignRight and -len or 0, alignBottom and 1 or 0, alignBottom and -th or 0)
            h.BackgroundColor3 = _G.G_ESP_Color or _G.CurrentAccentColor or Color3.fromRGB(160, 130, 255)
            h.BorderSizePixel = 0
            h.ZIndex = 5007
            table.insert(lines, h)

            local v = Instance.new("Frame", container)
            v.Size = UDim2.new(0, th, 0, len)
            v.Position = UDim2.new(alignRight and 1 or 0, alignRight and -th or 0, alignBottom and 1 or 0, alignBottom and -len or 0)
            v.BackgroundColor3 = _G.G_ESP_Color or _G.CurrentAccentColor or Color3.fromRGB(160, 130, 255)
            v.BorderSizePixel = 0
            v.ZIndex = 5007
            table.insert(lines, v)
        end

        addCorner(false, false)
        addCorner(true, false)
        addCorner(false, true)
        addCorner(true, true)

        return { container = container, lines = lines }
    end

    openESPCustomizerWindow = function()
        if espCustomizerGui and espCustomizerGui.Parent then
            espCustomizerGui.Enabled = not espCustomizerGui.Enabled
            if espCustomizerGui.Enabled and updatePreview then
                pcall(updatePreview)
            end
            return
        end

        local sg = Instance.new("ScreenGui")
        sg.Name = "Sovereign_ESPCustomizer"
        sg.ResetOnSpawn = false
        sg.DisplayOrder = 999999
        sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        safeParent(sg)
        espCustomizerGui = sg
        sg.Enabled = true

        local mainW = Instance.new("Frame", sg)
        mainW.Size = UDim2.new(0, 490, 0, 360)
        mainW.Position = UDim2.new(0.5, -245, 0.5, -180)
        mainW.BackgroundColor3 = Color3.fromRGB(12, 12, 18)
        mainW.ZIndex = 5000
        Instance.new("UICorner", mainW).CornerRadius = UDim.new(0, 10)
        local mwStk = Instance.new("UIStroke", mainW)
        mwStk.Color = _G.CurrentAccentColor or Color3.fromRGB(255, 45, 55)
        mwStk.Thickness = 1.4
        _G.SpookyESPCustomizerBorder = mwStk

        local topBar = Instance.new("Frame", mainW)
        topBar.Size = UDim2.new(1, 0, 0, 32)
        topBar.BackgroundColor3 = Color3.fromRGB(18, 17, 26)
        topBar.BorderSizePixel = 0
        topBar.ZIndex = 5001
        Instance.new("UICorner", topBar).CornerRadius = UDim.new(0, 10)

        pcall(function()
            local dragging, dragStart, startPos = false, nil, nil
            topBar.InputBegan:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                    dragging = true
                    dragStart = input.Position
                    startPos = mainW.Position
                end
            end)
            UserInputService.InputChanged:Connect(function(input)
                if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
                    local delta = input.Position - dragStart
                    mainW.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
                end
            end)
            UserInputService.InputEnded:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                    dragging = false
                end
            end)
        end)

