        centerTagBtn.MouseButton1Click:Connect(function()
            _G.G_ESP_TagOffsetX = 0
            _G.G_ESP_TagOffsetY = 0
            tagContainer.Position = UDim2.new(0.5, 0, 0.5, -60)
            offsetInfoLbl.Text = "Tag Offset: X: +0.0 | Y: +0.0"
            if _G.RebuildSpookyESPs then pcall(_G.RebuildSpookyESPs) end
        end)

        pcall(function()
            local isDraggingTag = false
            local dragStartMouse = nil
            local startOffX = 0
            local startOffY = 0

            tagContainer.InputBegan:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                    isDraggingTag = true
                    dragStartMouse = input.Position
                    startOffX = _G.G_ESP_TagOffsetX or 0
                    startOffY = _G.G_ESP_TagOffsetY or 0
                end
            end)

            UserInputService.InputChanged:Connect(function(input)
                if isDraggingTag and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
                    local delta = input.Position - dragStartMouse
                    local newX = math.clamp(math.floor((startOffX + delta.X / 10) * 10) / 10, -10, 10)
                    local newY = math.clamp(math.floor((startOffY - delta.Y / 10) * 10) / 10, -5, 15)
                    _G.G_ESP_TagOffsetX = newX
                    _G.G_ESP_TagOffsetY = newY
                    tagContainer.Position = UDim2.new(0.5, math.floor(newX * 10), 0.5, -60 - math.floor(newY * 10))
                    offsetInfoLbl.Text = string.format("Tag Offset: X: %+.1f | Y: %+.1f", newX, newY)
                end
            end)

            UserInputService.InputEnded:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                    isDraggingTag = false
                end
            end)
        end)

        if _G.G_ESP_SimpleMode == nil then _G.G_ESP_SimpleMode = (FeatureStates and FeatureStates["SimpleEsp"] == true) end
