        updatePreview = function()
            local isSimple = (_G.G_ESP_SimpleMode == true or (FeatureStates and FeatureStates["SimpleEsp"] == true))
            local parts = {}
            if isSimple then
                parts[#parts+1] = "[SovereignTarget]\nHP: 12450/12450 (100%)"
                tagContainer.Size = UDim2.new(0, 140, 0, 32)
                previewAvatar.Visible = false
            else
                tagContainer.Size = UDim2.new(0, 190, 0, 75)
                previewAvatar.Visible = (_G.G_ESP_AvatarPhoto ~= false)
                if _G.G_ESP_Name ~= false then
                    parts[#parts+1] = "[Pirates] <font color=\"rgb(255,255,0)\">SovereignTarget</font>"
                end
                if _G.G_ESP_Level ~= false then
                    parts[#parts+1] = " [Lv.2550]"
                end
                if _G.G_ESP_PvP ~= false then
                    parts[#parts+1] = "\n<font color=\"rgb(255,70,70)\">[PVP] PVP: ON</font>"
                end
                if _G.G_ESP_Bounty ~= false then
                    parts[#parts+1] = " | Bounty: 30.0M"
                end
                if _G.G_ESP_Fruit ~= false then
                    parts[#parts+1] = "\nFruit: Kitsune"
                end
                local hpStr = ""
                local fmt = _G.G_ESP_HP_Format or "Numbers"
                if _G.G_ESP_HP ~= false then
                    if fmt == "Numbers" then
                        hpStr = "HP: 12450 / 12450"
                    elseif fmt == "Percentage" then
                        hpStr = "Health: 100%"
                    else
                        hpStr = "HP: 12450/12450 (100%)"
                    end
                end
                local distUnit = _G.G_ESP_DistanceUnit or "Meters"
                local distText = (distUnit == "Studs") and "150 studs" or "42m"
                local distStr = (_G.G_ESP_Distance ~= false) and (distText .. " | ") or ""
                if distStr ~= "" or hpStr ~= "" then
                    parts[#parts+1] = "\n" .. distStr .. hpStr
                end
            end
            previewTag.Text = table.concat(parts)
            previewTag.Font = _G.G_ESP_Font or Enum.Font.GothamBold
            previewTag.TextSize = isSimple and 10 or (_G.G_ESP_TextSize or 11)

            local col = _G.G_ESP_Color or _G.CurrentAccentColor or Color3.fromRGB(160, 130, 255)

            local bStyle = _G.G_ESP_BoxStyle or "Full"
            if _G.G_ESP_Boxes == false or bStyle == "None" then
                previewBox.Visible = false
            elseif bStyle == "Corners" then
                previewBox.Visible = true
                pBoxStk.Enabled = false
                cornerRefs.container.Visible = true
                for _, cl in ipairs(cornerRefs.lines) do
                    cl.BackgroundColor3 = col
                end
            else
                previewBox.Visible = true
                pBoxStk.Enabled = true
                pBoxStk.Color = col
                cornerRefs.container.Visible = false
            end

            previewTracer.Visible = (_G.G_ESP_Tracers == true)
            previewTracer.BackgroundColor3 = col
            previewAvatar.Visible = (_G.G_ESP_AvatarPhoto ~= false)
            previewTag.TextColor3 = col

            mannequin.visor.BackgroundColor3 = col
            mannequin.core.BackgroundColor3 = col
            mannequin.chams.BackgroundColor3 = col
            mannequin.chamsStk.Color = col
            mannequin.chams.Visible = (_G.G_ESP_Chams ~= false)
            mannequin.hpBarTrack.Visible = (_G.G_ESP_HP ~= false)
            mannequin.hpLbl.Visible = (_G.G_ESP_HP ~= false)

            local ox = _G.G_ESP_TagOffsetX or 0
            local oy = _G.G_ESP_TagOffsetY or 0
            tagContainer.Position = UDim2.new(0.5, math.floor(ox * 10), 0.5, -60 - math.floor(oy * 10))
            offsetInfoLbl.Text = string.format("Tag Offset: X: %+.1f | Y: %+.1f", ox, oy)
        end

        local function createCustomizerToggle(name, labelText, getVal, setVal)
            local row = Instance.new("Frame", leftPanel)
            row.Size = UDim2.new(1, 0, 0, 32)
            row.BackgroundColor3 = Color3.fromRGB(24, 22, 34)
            row.ZIndex = 5003
