            rStk.Color = Color3.fromRGB(45, 40, 62)

            local lbl = Instance.new("TextLabel", row)
            lbl.Size = UDim2.new(1, -70, 1, 0)
            lbl.Position = UDim2.new(0, 10, 0, 0)
            lbl.BackgroundTransparency = 1
            lbl.Font = Enum.Font.GothamMedium
            lbl.Text = labelText
            lbl.TextColor3 = Color3.fromRGB(220, 220, 235)
            lbl.TextSize = 11
            lbl.TextXAlignment = Enum.TextXAlignment.Left
            lbl.ZIndex = 5004

            local btn = Instance.new("TextButton", row)
            btn.Size = UDim2.new(0, 52, 0, 22)
            btn.Position = UDim2.new(1, -58, 0.5, -11)
            btn.Font = Enum.Font.GothamBold
            btn.TextSize = 10
            btn.ZIndex = 5004
            Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 4)

            local function refresh()
                local v = getVal()
                btn.Text = v and "ON" or "OFF"
                btn.BackgroundColor3 = v and (_G.CurrentAccentColor or Color3.fromRGB(130, 100, 220)) or Color3.fromRGB(36, 32, 48)
                btn.TextColor3 = v and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(160, 160, 175)
            end
            refresh()

            btn.MouseButton1Click:Connect(function()
                local nv = not getVal()
                setVal(nv)
                refresh()
                updatePreview()
            end)
        end

