    local cAvatar = makeCard(VisualPage, "Avatar & Clothing Cloner", "Clonador de Ropa", 148, 394)
    createToggleButton(cAvatar, "AvatarDeleteAccessories", "Delete Old Accs", "Borrar Accs Viejos", BW, UDim2.new(0, X1, 0, 24))
    createToggleButton(cAvatar, "AvatarNoCollide", "No-Collide Accs", "Sin Colision Accs", BW, UDim2.new(0, X2, 0, 24))

    FeatureStates["AvatarDeleteAccessories"] = true
    FeatureStates["AvatarNoCollide"] = true

    local originalAvatarData = {
        saved = false,
        shirt = nil,
        pants = nil,
        colors = nil,
        face = nil,
        accessories = {}
    }

    local function saveMyOriginalAvatar()
        local char = LocalPlayer.Character
        if not char then return end
        if originalAvatarData.saved then return end

        local shirt = char:FindFirstChildOfClass("Shirt")
        if shirt then originalAvatarData.shirt = shirt.ShirtTemplate end
        local pants = char:FindFirstChildOfClass("Pants")
        if pants then originalAvatarData.pants = pants.PantsTemplate end
        local colors = char:FindFirstChildOfClass("BodyColors")
        if colors then
            originalAvatarData.colors = {
                HeadColor = colors.HeadColor,
                TorsoColor = colors.TorsoColor,
                LeftArmColor = colors.LeftArmColor,
                RightArmColor = colors.RightArmColor,
                LeftLegColor = colors.LeftLegColor,
                RightLegColor = colors.RightLegColor
            }
        end
        local head = char:FindFirstChild("Head")
        local face = head and head:FindFirstChild("face")
        if face then originalAvatarData.face = face.Texture end

        originalAvatarData.accessories = {}
        for _, obj in ipairs(char:GetChildren()) do
            if obj:IsA("Accessory") then
                pcall(function()
                    obj.Archivable = true
                    local cl = obj:Clone()
                    if cl then table.insert(originalAvatarData.accessories, cl) end
                end)
            end
        end

        originalAvatarData.saved = true
    end

    task.spawn(function()
        if LocalPlayer.Character then saveMyOriginalAvatar() end
        LocalPlayer.CharacterAdded:Connect(function()
            task.wait(1.5)
            originalAvatarData.saved = false
            saveMyOriginalAvatar()
        end)
    end)

    local function MakeAccessoryNonCollidable(accessory)
        if not accessory or not accessory:IsA("Accessory") then return end
        for _, obj in ipairs(accessory:GetDescendants()) do
            if obj:IsA("BasePart") then
                obj.CanCollide = false
                obj.CanTouch = false
                obj.CanQuery = false
                obj.Massless = true
            end
        end
    end

    local function attachAccessoryDirect(m, character)
        if not m or not m:IsA("Accessory") then return end
        local handle = m:FindFirstChild("Handle")
        if not handle then return end

        for _, desc in ipairs(m:GetDescendants()) do
            if desc:IsA("JointInstance") or desc:IsA("Weld") or desc:IsA("WeldConstraint") or desc:IsA("Snap") or desc:IsA("Motor") or desc:IsA("Motor6D") then
                pcall(function() desc:Destroy() end)
            end
        end

        if m:FindFirstChild("ThumbnailConfiguration") then
            pcall(function() m.ThumbnailConfiguration:Destroy() end)
        end

        MakeAccessoryNonCollidable(m)
        m.Parent = character

        local welded = false
        for _, f in ipairs(handle:GetChildren()) do
            if f:IsA("Attachment") then
                for _, c in ipairs(character:GetDescendants()) do
                    if c:IsA("Attachment") and c.Name == f.Name and c.Parent and c.Parent:IsA("BasePart") then
                        local w = Instance.new("Weld")
                        w.Name = "AccessoryWeld"
                        w.Part0 = handle
                        w.Part1 = c.Parent
                        w.C0 = f.CFrame
                        w.C1 = c.CFrame
                        w.Parent = handle
                        welded = true
                        break
                    end
                end
                if welded then break end
            end
        end

        if not welded then
            local head = character:FindFirstChild("Head") or character:FindFirstChild("UpperTorso") or character:FindFirstChild("HumanoidRootPart")
            if head then
                local w = Instance.new("Weld")
                w.Name = "AccessoryWeld"
                w.Part0 = handle
                w.Part1 = head
                w.C0 = CFrame.new(0, 0, 0)
                w.C1 = CFrame.new(0, 0, 0)
                w.Parent = handle
            end
        end

        MakeAccessoryNonCollidable(m)
    end

    local function applyAvatarFromSource(srcChar)
        local myChar = LocalPlayer.Character
        if not myChar or not srcChar then return end

        saveMyOriginalAvatar()

        if FeatureStates["AvatarDeleteAccessories"] then
            for _, obj in ipairs(myChar:GetChildren()) do
                if obj:IsA("Accessory") then
                    pcall(function() obj:Destroy() end)
                end
            end
        end

        for _, obj in ipairs(srcChar:GetChildren()) do
            if obj:IsA("Accessory") then
                pcall(function()
                    obj.Archivable = true
                    local clone = obj:Clone()
                    if clone then
                        attachAccessoryDirect(clone, myChar)
                    end
                end)
            end
        end

        local srcShirt = srcChar:FindFirstChildOfClass("Shirt")
        local myShirt = myChar:FindFirstChildOfClass("Shirt")
        if srcShirt then
            if not myShirt then
                myShirt = Instance.new("Shirt", myChar)
            end
            myShirt.ShirtTemplate = srcShirt.ShirtTemplate
        end

        local srcPants = srcChar:FindFirstChildOfClass("Pants")
        local myPants = myChar:FindFirstChildOfClass("Pants")
        if srcPants then
            if not myPants then
                myPants = Instance.new("Pants", myChar)
            end
            myPants.PantsTemplate = srcPants.PantsTemplate
        end

        local srcColors = srcChar:FindFirstChildOfClass("BodyColors")
        local myColors = myChar:FindFirstChildOfClass("BodyColors")
        if srcColors and myColors then
            myColors.HeadColor = srcColors.HeadColor
            myColors.TorsoColor = srcColors.TorsoColor
            myColors.LeftArmColor = srcColors.LeftArmColor
            myColors.RightArmColor = srcColors.RightArmColor
            myColors.LeftLegColor = srcColors.LeftLegColor
            myColors.RightLegColor = srcColors.RightLegColor
        end

        local srcHead = srcChar:FindFirstChild("Head")
        local myHead = myChar:FindFirstChild("Head")
        if srcHead and myHead then
            local srcFace = srcHead:FindFirstChild("face")
            local myFace = myHead:FindFirstChild("face")
            if srcFace then
                if not myFace then
                    myFace = Instance.new("Decal", myHead)
                    myFace.Name = "face"
                end
                myFace.Texture = srcFace.Texture
            end
        end
    end

    local function restoreMyOriginalSkin()
        local myChar = LocalPlayer.Character
        if not myChar then return false end

        local appliedDesc = false
        pcall(function()
            local hum = myChar:FindFirstChildOfClass("Humanoid")
            if hum and Players.GetHumanoidDescriptionFromUserId then
                local desc = Players:GetHumanoidDescriptionFromUserId(LocalPlayer.UserId)
                if desc then
                    hum:ApplyDescription(desc)
                    appliedDesc = true
                end
            end
        end)
        if appliedDesc then return true end

        if not originalAvatarData.saved then return false end

        for _, obj in ipairs(myChar:GetChildren()) do
            if obj:IsA("Accessory") then
                pcall(function() obj:Destroy() end)
            end
        end

        if originalAvatarData.accessories then
            for _, acc in ipairs(originalAvatarData.accessories) do
                pcall(function()
                    acc.Archivable = true
                    local clone = acc:Clone()
                    if clone then
                        attachAccessoryDirect(clone, myChar)
                    end
                end)
            end
        end

        local myShirt = myChar:FindFirstChildOfClass("Shirt")
        if originalAvatarData.shirt then
            if not myShirt then myShirt = Instance.new("Shirt", myChar) end
            myShirt.ShirtTemplate = originalAvatarData.shirt
        elseif myShirt then
            myShirt.ShirtTemplate = ""
        end

        local myPants = myChar:FindFirstChildOfClass("Pants")
        if originalAvatarData.pants then
            if not myPants then myPants = Instance.new("Pants", myChar) end
            myPants.PantsTemplate = originalAvatarData.pants
        elseif myPants then
            myPants.PantsTemplate = ""
        end

        local myColors = myChar:FindFirstChildOfClass("BodyColors")
        if myColors and originalAvatarData.colors then
            for k, v in pairs(originalAvatarData.colors) do
                myColors[k] = v
            end
        end

        local myHead = myChar:FindFirstChild("Head")
        local myFace = myHead and myHead:FindFirstChild("face")
        if myFace and originalAvatarData.face then
            myFace.Texture = originalAvatarData.face
        end

        return true
    end

    local function cloneOutfitByUserIdOrName(query)
        query = string.gsub(tostring(query or ""), "%s+", "")
        if #query == 0 then return false, "Please enter a Name or User ID" end
        local uid = tonumber(query)
        for _, p in ipairs(Players:GetPlayers()) do
            if string.lower(p.Name) == string.lower(query) or string.lower(p.DisplayName) == string.lower(query) or (uid and p.UserId == uid) then
                if p.Character then
                    applyAvatarFromSource(p.Character)
                    return true, "Cloned outfit from " .. p.DisplayName
                end
            end
        end
        local targetId = uid
        if not targetId and Players.GetUserIdFromNameAsync then
            local ok, res = pcall(function() return Players:GetUserIdFromNameAsync(query) end)
            if ok and res then targetId = res end
        end
        if targetId then
            local myChar = LocalPlayer.Character
            local hum = myChar and myChar:FindFirstChildOfClass("Humanoid")
            if hum and Players.GetHumanoidDescriptionFromUserId then
                local ok, desc = pcall(function() return Players:GetHumanoidDescriptionFromUserId(targetId) end)
                if ok and desc then
                    saveMyOriginalAvatar()
                    pcall(function() hum:ApplyDescription(desc) end)
                    return true, "Applied outfit from User ID " .. tostring(targetId)
                end
            end
        end
        return false, "Could not find player or fetch avatar"
    end

