    createActionButton(cAvatar, "Clone Nearest Player", "Clonar Mas Cercano", UDim2.new(0.48, -4, 0, 26), UDim2.new(0, 6, 0, 102), function()
        pcall(function()
            local myChar = LocalPlayer.Character
            local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
            if not myHrp then return end

            local closestP = nil
            local closestDist = math.huge
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer and p.Character then
                    local hrp = p.Character:FindFirstChild("HumanoidRootPart")
                    if hrp then
                        local d = (hrp.Position - myHrp.Position).Magnitude
                        if d < closestDist then
                            closestDist = d
                            closestP = p
                        end
                    end
                end
            end
            if not closestP then
                for _, p in ipairs(Players:GetPlayers()) do
                    if p ~= LocalPlayer then closestP = p; break end
                end
            end

            if closestP and closestP.Character then
                applyAvatarFromSource(closestP.Character)
                notifyToggle("Cloned outfit: " .. closestP.DisplayName .. " (" .. math.floor(closestDist == math.huge and 0 or closestDist) .. " studs)", true)
            else
                notifyToggle("No other players found in server", false)
            end
        end)
    end)

    createActionButton(cAvatar, "Restore Original Outfit", "Restablecer Original", UDim2.new(0.48, -4, 0, 26), UDim2.new(0.5, 4, 0, 102), function()
        pcall(function()
            local ok = restoreMyOriginalSkin()
            if ok then
                notifyToggle("Outfit restored to original", true)
            else
                notifyToggle("No original outfit saved", false)
            end
        end)
    end)

end
do
    -- VFX and Hotbar controls removed at user request. Keep an empty page
    -- object so existing navigation aliases do not error.
    local SacredVFXPage = createScrollPage("SacredVFX_Page", 100)
