    local visitedFruitServers = {}
    local function executeFruitHop()
        currentStatusText = (CurrentLang == "ES") and "Buscando servidor con fruta..." or "Searching fruit server..."
        notifyToggle((CurrentLang == "ES") and "Fruit Hop: Buscando servidor con fruta real..." or "Fruit Hop: Searching real fruit server...", true)
        if statusLbl and statusLbl.Parent then
            statusLbl.Text = (CurrentLang == "ES") and "Estado: Buscando servidor con fruta..." or "Status: Searching fruit server..."
        end
        local function dismissPrompt(v)
            if v.Name == "ErrorPrompt" and v.Visible then
                if v:FindFirstChild("TitleFrame") and v.TitleFrame:FindFirstChild("ErrorTitle") then
                    v.Visible = false
                end
            end
        end
        pcall(function()
            local coreGui = game:GetService("CoreGui")
            local promptOverlay = coreGui:FindFirstChild("RobloxPromptGui") and coreGui.RobloxPromptGui:FindFirstChild("promptOverlay")
            if promptOverlay then
                for _, child in ipairs(promptOverlay:GetChildren()) do
                    dismissPrompt(child)
                end
                promptOverlay.ChildAdded:Connect(dismissPrompt)
            end
        end)
        task.spawn(function()
            local HttpService = game:GetService("HttpService")
            local reqFn = (syn and syn.request) or (http and http.request) or http_request or request or (Fluxus and Fluxus.request)
            if not reqFn then
                notifyToggle("Error: No HTTP function for fruit server hop", false)
                return
            end

            local currentSea = "Sea1"
            if game.PlaceId == 4442272183 or game.PlaceId == 79091703265657 then
                currentSea = "Sea2"
            elseif game.PlaceId == 7449423635 or game.PlaceId == 100117331123089 then
                currentSea = "Sea3"
            end

            local ok, res = pcall(function()
                return reqFn({ Url = "http://163.223.9.144/boss/Fruits", Method = "GET" })
            end)

            if not ok or not res or not res.Body then
                notifyToggle("Error al consultar API de frutas. Esperando...", false)
                return
            end

            local parseOk, parsed = pcall(HttpService.JSONDecode, HttpService, res.Body)
            if not parseOk or not parsed or not parsed.data or type(parsed.data) ~= "table" then
                notifyToggle("Respuesta de API inválida. Esperando...", false)
                return
            end

            local candidates = {}
            for _, s in ipairs(parsed.data) do
                if s.JobId and s.Sea == currentSea and (tonumber(s.Players) or 0) < 12 then
                    table.insert(candidates, s)
                end
            end

            if #candidates == 0 then
                for _, s in ipairs(parsed.data) do
                    if s.JobId and s.PlaceId == game.PlaceId and (tonumber(s.Players) or 0) < 12 then
                        table.insert(candidates, s)
                    end
                end
            end

            if #candidates == 0 then

                local msg = (CurrentLang == "ES") and ("No hay servidores con fruta en " .. currentSea .. ". Esperando fruta...") or ("No fruit servers in " .. currentSea .. ". Waiting for spawn...")
                notifyToggle(msg, false)
                if statusLbl and statusLbl.Parent then
                    statusLbl.Text = (CurrentLang == "ES") and "Estado: Esperando fruta en API..." or "Status: Waiting for fruit in API..."
                end
                return
            end

            table.sort(candidates, function(a, b)
                return (tonumber(a.Age) or 999) < (tonumber(b.Age) or 999)
            end)

            if #visitedFruitServers > 40 then
                visitedFruitServers = {}
            end

            for _, candidate in ipairs(candidates) do
                local okDec, decryptedJobId = NightHubDecoder.decode(candidate.JobId)
                if okDec and decryptedJobId and decryptedJobId ~= game.JobId and not table.find(visitedFruitServers, decryptedJobId) then
                    table.insert(visitedFruitServers, decryptedJobId)
                    local fDisplayName = tostring(candidate.Name or "Fruit"):gsub("\n", ", ")
                    notifyToggle(string.format("Fruit Hop: Conectando a server con %s (%d jug)...", fDisplayName, candidate.Players or 0), true)

                    local sb = ReplicatedStorage:FindFirstChild("__ServerBrowser") or ReplicatedStorage:FindFirstChild("ServerBrowser")
                    if sb then
                        pcall(function()
                            sb:InvokeServer("teleport", decryptedJobId)
                        end)
                        task.wait(1.5)
                    end
                    TeleportService:TeleportToPlaceInstance(game.PlaceId, decryptedJobId, LocalPlayer)
                    task.wait(4)
                    return
                end
            end

            visitedFruitServers = {}
            local msg = (CurrentLang == "ES") and "Servidores de frutas ya visitados. Esperando nuevos spawns..." or "All fruit servers already checked. Waiting for fresh spawns..."
            notifyToggle(msg, false)
            if statusLbl and statusLbl.Parent then
                statusLbl.Text = (CurrentLang == "ES") and "Estado: Esperando nuevos servidores..." or "Status: Waiting for fresh servers..."
            end
        end)
    end
