    task.spawn(function()
        local function GetCommF()
            return ReplicatedStorage:WaitForChild("Remotes", 9):WaitForChild("CommF_", 9)
        end
        local function GetFruitHandle(fruitModel)
            if not fruitModel then return nil end
            if fruitModel:IsA("Tool") then
                return fruitModel:FindFirstChild("Handle") or fruitModel:FindFirstChildWhichIsA("BasePart")
            elseif fruitModel:IsA("Model") then
                return fruitModel:FindFirstChild("Handle") or fruitModel.PrimaryPart or fruitModel:FindFirstChildWhichIsA("BasePart")
            end
            return nil
        end
        local function isStillSpawned(fruitObj)
            if not fruitObj or not fruitObj.Parent then return false end
            local p = fruitObj.Parent
            if p == workspace then return true end
            while p and p ~= game do
                if p == workspace then return true end
                if p:IsA("Model") and Players:GetPlayerFromCharacter(p) then return false end
                p = p.Parent
            end
            return false
        end
        local function GetSpawnedFruits()
            local fruits = {}
            for _, obj in ipairs(workspace:GetChildren()) do
                if (obj:IsA("Tool") or obj:IsA("Model")) and string.find(obj.Name, "Fruit") then
                    local handle = GetFruitHandle(obj)
                    if handle and isStillSpawned(obj) then
                        table.insert(fruits, { Object = obj, Handle = handle })
                    end
                end
            end
            return fruits
        end
        local function FlyToFruit(handle)
            local char = LocalPlayer.Character
            if not char then return end
            local hrp = char:FindFirstChild("HumanoidRootPart")
            local hum = char:FindFirstChildOfClass("Humanoid")
            if not hrp or not handle then return end
            if hum then hum.Sit = false end
            local targetCF = handle.CFrame * CFrame.new(0, 3, 0)
            local distance = (hrp.Position - handle.Position).Magnitude
            local flySpeed = _G.FlySpeed or 280

            local bv = Instance.new("BodyVelocity")
            bv.Name = "SovereignFruitBV"
            bv.MaxForce = Vector3.new(1e9, 1e9, 1e9)
            bv.Velocity = Vector3.zero
            bv.Parent = hrp

            local bg = Instance.new("BodyGyro")
            bg.Name = "SovereignFruitBG"
            bg.MaxTorque = Vector3.new(1e9, 1e9, 1e9)
            bg.CFrame = hrp.CFrame
            bg.Parent = hrp

            local noclipConn = nil
            noclipConn = RunService.Stepped:Connect(function()
                local c = LocalPlayer.Character
                if c then
                    local h = c:FindFirstChildOfClass("Humanoid")
                    if h then h.Sit = false end
                    for _, part in ipairs(c:GetDescendants()) do
                        if part:IsA("BasePart") then
                            part.CanCollide = false
                        end
                    end
                end
            end)
            pcall(function()
                hrp.Velocity = Vector3.zero
                hrp.AssemblyLinearVelocity = Vector3.zero
            end)
            if distance <= 80 then
                pcall(function() char:PivotTo(targetCF) end)
                hrp.CFrame = targetCF
            else
                local flyTime = math.max(distance / flySpeed, 0.2)
                local tweenInfo = TweenInfo.new(flyTime, Enum.EasingStyle.Linear)
                local tween = TweenService:Create(hrp, tweenInfo, { CFrame = targetCF })
                tween:Play()
                local startT = tick()
                while (tick() - startT) < flyTime and handle and handle.Parent and _G.AutoCollectHop do
                    if (hrp.Position - handle.Position).Magnitude <= 12 then
                        tween:Cancel()
                        break
                    end
                    task.wait(0.04)
                end
                pcall(function() tween:Cancel() end)
            end
            if noclipConn then noclipConn:Disconnect() end
            if bv and bv.Parent then bv:Destroy() end
            if bg and bg.Parent then bg:Destroy() end

            if hrp and handle and handle.Parent then
                pcall(function() char:PivotTo(targetCF) end)
                hrp.CFrame = targetCF
                if firetouchinterest then
                    pcall(function()
                        firetouchinterest(hrp, handle, 0)
                        task.wait(0.05)
                        firetouchinterest(hrp, handle, 1)
                    end)
                end
            end
        end
        local fruitESPMap = {}
        local function UpdateFruitESP()
            pcall(function()
                local char = LocalPlayer.Character
                local head = char and char:FindFirstChild("Head")
                local fruits = GetSpawnedFruits()
                local currentHandles = {}
                if _G.FruitESP then
                    for _, fruitData in ipairs(fruits) do
                        local handle = fruitData.Handle
                        local v = fruitData.Object
                        if handle and v and isStillSpawned(v) then
                            currentHandles[handle] = true
                            local espName = "FruitESP_" .. fruitSessionID
                            local bill = handle:FindFirstChild(espName)
                            local dist = head and math.floor((head.Position - handle.Position).Magnitude) or 0
                            if not bill then
                                bill = Instance.new("BillboardGui")
                                bill.Name = espName
                                bill.Size = UDim2.new(0, 200, 0, 45)
                                bill.ExtentsOffset = Vector3.new(0, 2.5, 0)
                                bill.AlwaysOnTop = true
                                bill.Adornee = handle
                                bill.Parent = handle
                                local text = Instance.new("TextLabel", bill)
                                text.Name = "ESPLabel"
                                text.Size = UDim2.new(1, 0, 1, 0)
                                text.BackgroundTransparency = 1
                                text.TextSize = 13
                                text.Font = Enum.Font.GothamBold
                                text.TextColor3 = Color3.fromRGB(240, 240, 255)
                                text.TextStrokeTransparency = 0
                                fruitESPMap[handle] = bill
                            end
                            local lbl = bill:FindFirstChild("ESPLabel")
                            if lbl then
                                lbl.Text = string.format("[Fruit] %s\n[%d studs / %dm]", v.Name, dist, math.floor(dist / 3))
                            end
                        end
                    end
                end
                for handle, bill in pairs(fruitESPMap) do
                    if not currentHandles[handle] or not _G.FruitESP then
                        pcall(function() if bill then bill:Destroy() end end)
                        fruitESPMap[handle] = nil
                    end
                end
            end)
        end
        task.spawn(function()
            while isCurrentSession() do
                task.wait(0.5)
                if _G.FruitESP then
                    UpdateFruitESP()
                elseif next(fruitESPMap) ~= nil then
                    for handle, bill in pairs(fruitESPMap) do
                        pcall(function() if bill then bill:Destroy() end end)
                        fruitESPMap[handle] = nil
                    end
                end
            end
        end)

        workspace.ChildAdded:Connect(function(child)
            if not isCurrentSession() then return end
            if (child:IsA("Tool") or child:IsA("Model")) and string.find(child.Name, "Fruit") then
                task.spawn(function()
                    task.wait(0.4)
                    if child and child.Parent and isStillSpawned(child) then
                        if _G.FruitESP then
                            UpdateFruitESP()
                        end
                    end
                end)
            end
        end)

        local function IsPhysicalFruit(tool)
            if not (tool and tool:IsA("Tool")) then return false end
            return string.find(tool.Name, "Fruit") ~= nil
        end
        local function HasFruitInInventory()
            if LocalPlayer.Character then
                for _, item in ipairs(LocalPlayer.Character:GetChildren()) do
                    if IsPhysicalFruit(item) then return true, item end
                end
            end
            local bp = LocalPlayer:FindFirstChild("Backpack")
            if bp then
                for _, item in ipairs(bp:GetChildren()) do
                    if IsPhysicalFruit(item) then return true, item end
                end
            end
            return false, nil
        end
        local function StoreFruit(fruitTool)
            if not fruitTool then return false end
            local ok, res = pcall(function()
                local commF = GetCommF()
                if not commF then return false end
                local char = LocalPlayer.Character
                local hum = char and char:FindFirstChildOfClass("Humanoid")

                if fruitTool.Parent ~= char and hum then
                    hum:EquipTool(fruitTool)
                    task.wait(0.18)
                end
                local origName = fruitTool:GetAttribute("OriginalName") or fruitTool.Name
                local r = commF:InvokeServer("StoreFruit", origName, fruitTool)
                if not r then
                    commF:InvokeServer("StoreFruit", fruitTool.Name, fruitTool)
                end
                notifyToggle("Auto Store: " .. tostring(fruitTool.Name), true)
                return true
            end)
            return ok and res
        end
        task.spawn(function()
            while isCurrentSession() do
                task.wait(0.5)
                if _G.AutoStoreFruit and HasFruitInInventory() then
                    local has, fruitTool = HasFruitInInventory()
                    if has and fruitTool then
                        StoreFruit(fruitTool)
                    end
                end
            end
        end)
        collectorThread = task.spawn(function()
            local initialWait = 3.0
            while isCurrentSession() do
                task.wait(0.5)
                if _G.AutoCollectHop and not isHopping then
                    if initialWait > 0 then
                        currentStatusText = (CurrentLang == "ES") and "Buscando frutas en el servidor..." or "Checking server for fruits..."
                        task.wait(initialWait)
                        initialWait = 0
                    end
                    local fruits = GetSpawnedFruits()
                    if #fruits > 0 then
                        for _, fData in ipairs(fruits) do
                            if not _G.AutoCollectHop then break end
                            local fObj = fData.Object
                            local fName = resolveRealFruitName(fObj)
                            currentStatusText = (CurrentLang == "ES") and ("Recogiendo: " .. fName) or ("Collecting: " .. fName)
                            FlyToFruit(fData.Handle)
                            task.wait(0.5)
                            local has, fTool = HasFruitInInventory()
                            if has and fTool then
                                StoreFruit(fTool)
                                _G.TotalFruitsCollected = (_G.TotalFruitsCollected or 0) + 1
                            end
                        end
                    else
                        if _G.HopEnabled and not isHopping then
                            currentStatusText = (CurrentLang == "ES") and "Buscando servidor con frutas..." or "Searching server with fruits..."
                            isHopping = true
                            executeFruitHop()
                            task.wait(35)
                            isHopping = false
                        else
                            currentStatusText = (CurrentLang == "ES") and "Sin frutas (Esperando fruta / Job ID en Discord)..." or "No fruits (Waiting for fruit / Discord Job ID)..."
                        end
                    end
                else
                    initialWait = 0
                    currentStatusText = _G.AutoCollectHop and ((CurrentLang == "ES") and "Ejecutando" or "Running") or ((CurrentLang == "ES") and "Inactivo (Haz clic en Iniciar)" or "Idle (Click Start)")
                end
            end
        end)
        task.spawn(function()
            while isCurrentSession() do
                task.wait(0.5)
                if statusLbl and statusLbl.Parent then
                    statusLbl.Text = string.format("%s: %s | %s: %d", (CurrentLang == "ES") and "Estado" or "Status", currentStatusText, (CurrentLang == "ES") and "Frutas" or "Fruits", _G.TotalFruitsCollected or 0)
                end
            end
        end)
    end)
end
