            local zoneState = inSafe and "In SafeZone" or "Free Zone"
            print(string.format("[Zen Monitor] %s: %s | %s | %s | %s",
                tag or "Info", player.Name, pvpState, zoneState, enemy and "Enemy" or "Neutral/Ally"))
        end)
