    -- Shim objects so the existing start/stop/status code (which sets .Text / .BackgroundColor3) keeps working
    function ZENB.zenShim(onSet)
        local store = {}
        return setmetatable({}, {
            __index = function(_, k) return store[k] end,
            __newindex = function(_, k, v) store[k] = v; pcall(onSet, k, v) end,
        })
    end
