            local last = {}
            local function put(key, ctl, text)
                if ctl and last[key] ~= text then last[key] = text; pcall(function() ctl:Set(text) end) end
            end
            while isCurrentSession() and task.wait(0.5) do
                pcall(function()
                    if ZENB.zenRunning() then
                        local t = getgenv().targ
                        if t and t.Character then
                            local hrp = t.Character:FindFirstChild("HumanoidRootPart")
                            local lpHrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                            local dist = (hrp and lpHrp) and math.floor((hrp.Position - lpHrp.Position).Magnitude) or 0
                            put("n", ZENB.zenCtl.tTarget, tostring(t.DisplayName or t.Name))
                            put("d", ZENB.zenCtl.tDist, tostring(dist) .. "m")
                            local bStat = t:FindFirstChild("leaderstats") and (t.leaderstats:FindFirstChild("Bounty/Honor") or t.leaderstats:FindFirstChild("Bounty") or t.leaderstats:FindFirstChild("Honor"))
                            local bVal = bStat and tonumber(bStat.Value) or 0
                            put("b", ZENB.zenCtl.tBounty, string.format("%.1fM", bVal / 1000000))
                        else
                            put("n", ZENB.zenCtl.tTarget, ZENB.zenT("Searching...", "Buscando..."))
                            put("d", ZENB.zenCtl.tDist, "-")
                            put("b", ZENB.zenCtl.tBounty, "-")
                        end
                        put("e", ZENB.zenCtl.tEarned, tostring(Earned or 0))
                    else
                        put("n", ZENB.zenCtl.tTarget, ZENB.zenT("None", "Ninguno"))
                        put("d", ZENB.zenCtl.tDist, "-")
                        put("b", ZENB.zenCtl.tBounty, "-")
                        put("e", ZENB.zenCtl.tEarned, "0")
                    end
                end)
            end
        end)
    end
