    local function answerAnyQuestionLocally(query)
        local q = string.lower(query or "")
        local ans = ""
        local code = ""

        local n1, op, n2 = string.match(q, "(%d+%.?%d*)%s*([%+%-%*%/%^])%s*(%d+%.?%d*)")
        if n1 and op and n2 then
            local num1 = tonumber(n1)
            local num2 = tonumber(n2)
            if num1 and num2 then
                local res = 0
                if op == "+" then res = num1 + num2
                elseif op == "-" then res = num1 - num2
                elseif op == "*" then res = num1 * num2
                elseif op == "/" then res = (num2 ~= 0) and (num1 / num2) or 0
                elseif op == "^" then res = num1 ^ num2
                end
                ans = (CurrentLang == "ES") and string.format("Calculo: %s %s %s = %s", n1, op, n2, tostring(res)) or string.format("Calculation: %s %s %s = %s", n1, op, n2, tostring(res))
                return ans, code
            end
        end

        local sqrtNum = string.match(q, "raiz%s+cuadrada%s+de%s+(%d+%.?%d*)") or string.match(q, "sqrt%s*%(?(%d+%.?%d*)%)?") or string.match(q, "square%s+root%s+of%s+(%d+%.?%d*)")
        if sqrtNum and tonumber(sqrtNum) then
            local val = math.sqrt(tonumber(sqrtNum))
            ans = (CurrentLang == "ES") and string.format("La raiz cuadrada de %s es %s", sqrtNum, tostring(val)) or string.format("The square root of %s is %s", sqrtNum, tostring(val))
            return ans, code
        end

        local pct, total = string.match(q, "(%d+%.?%d*)%%%s+de%s+(%d+%.?%d*)") or string.match(q, "(%d+%.?%d*)%%%s+of%s+(%d+%.?%d*)")
        if pct and total and tonumber(pct) and tonumber(total) then
            local val = (tonumber(pct) / 100) * tonumber(total)
            ans = (CurrentLang == "ES") and string.format("El %s%% de %s es %s", pct, total, tostring(val)) or string.format("%s%% of %s is %s", pct, total, tostring(val))
            return ans, code
