    local function displayAIOutput(query, rawResponse, codeChunk)
        lastGeneratedFullText = rawResponse or ""
        lastGeneratedCode = codeChunk or ""
        if not codeChunk or #codeChunk == 0 then
            local extracted = string.match(rawResponse, "```lua%s*(.-)%s*```") or string.match(rawResponse, "```%s*(.-)%s*```")
            if extracted and #extracted > 0 then
                lastGeneratedCode = extracted
            end
        end
        if speechStatusLbl then
            speechStatusLbl.Text = (CurrentLang == "ES") and "Estado: Listo" or "Status: Ready"
        end
        if terminalLogBox then
            terminalLogBox.Text = string.format(">> [USER]: %s\n\n>> [Zen AI]:\n%s\n\n========================================", query, rawResponse)
        end
    end

    local function sendAIQuery(query)
        if not query or #string.gsub(query, "%s+", "") == 0 then
            notifyToggle((CurrentLang == "ES") and "Por favor escribe una pregunta" or "Please enter a question", false)
            return
        end
        if speechStatusLbl then
            speechStatusLbl.Text = (CurrentLang == "ES") and "Estado: Pensando..." or "Status: Thinking..."
        end
        if terminalLogBox then
            terminalLogBox.Text = (CurrentLang == "ES") and ">> [Zen AI]: Procesando consulta..." or ">> [Zen AI]: Processing query..."
        end
        task.spawn(function()
            local reqFunc = (syn and syn.request) or (http and http.request) or http_request or request
            local onlineResponse = nil

            if reqFunc then
                pcall(function()
                    local apiKey = "AQ.Ab8RN6K0sq8RwAh0lMUhL3GZSzDxAJ6xGQASk5jFr-Z51h1lrw"
                    local geminiUrl = "https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=" .. apiKey
                    local payload = HttpService:JSONEncode({
                        contents = {
                            {
                                role = "user",
                                parts = { { text = query } }
                            }
                        },
                        systemInstruction = {
                            parts = {
                                { text = "You are Zen AI, the official hyper-intelligent AI assistant in Zen Hub, inspired by Marin Kitagawa. You are an expert Roblox Luau developer and Blox Fruits master. Answer smartly, clearly, warmly, and directly in the user language. If the user asks for a script, provide clean, complete, working Roblox Luau code wrapped in ```lua ... ``` blocks without any comments." }
                            }
                        }
                    })
                    local res = reqFunc({
                        Url = geminiUrl,
                        Method = "POST",
                        Headers = {
                            ["Content-Type"] = "application/json"
                        },
                        Body = payload
                    })
                    if res and res.Body then
                        local data = HttpService:JSONDecode(res.Body)
                        if data and data.candidates and data.candidates[1] and data.candidates[1].content and data.candidates[1].content.parts and data.candidates[1].content.parts[1] and data.candidates[1].content.parts[1].text then
                            onlineResponse = data.candidates[1].content.parts[1].text
                        end
                    end
                end)

                if not onlineResponse or #onlineResponse == 0 then
                    pcall(function()
                        local apiKey = "AQ.Ab8RN6K0sq8RwAh0lMUhL3GZSzDxAJ6xGQASk5jFr-Z51h1lrw"
                        local geminiUrl2 = "https://generativelanguage.googleapis.com/v1beta/models/gemini-flash-latest:generateContent?key=" .. apiKey
                        local payload2 = HttpService:JSONEncode({
                            contents = {
                                {
                                    role = "user",
                                    parts = { { text = query } }
                                }
                            }
                        })
                        local res2 = reqFunc({
                            Url = geminiUrl2,
                            Method = "POST",
                            Headers = {
                                ["Content-Type"] = "application/json"
                            },
                            Body = payload2
                        })
                        if res2 and res2.Body then
                            local data2 = HttpService:JSONDecode(res2.Body)
                            if data2 and data2.candidates and data2.candidates[1] and data2.candidates[1].content and data2.candidates[1].content.parts and data2.candidates[1].content.parts[1] and data2.candidates[1].content.parts[1].text then
                                onlineResponse = data2.candidates[1].content.parts[1].text
                            end
                        end
                    end)
                end
            end

            if onlineResponse and #onlineResponse > 0 then
                displayAIOutput(query, onlineResponse, nil)
                notifyToggle("AI Response Received", true)
                return
            end

            local localAns, localCode = answerAnyQuestionLocally(query)
            displayAIOutput(query, localAns, localCode)
            notifyToggle("AI Response Ready", true)
        end)
    end

    local function doSendPrompt()
        local rawText = promptInput.Text
        if not rawText or #string.gsub(rawText, "%s+", "") == 0 then
            notifyToggle((CurrentLang == "ES") and "Por favor escribe una pregunta" or "Please enter a question", false)
            return
        end
        promptInput.Text = ""
        sendAIQuery(rawText)
    end

    local sendBtn = createActionButton(chatCard, "Send", "Enviar", UDim2.new(0, 95, 0, 36), UDim2.new(1, -102, 0, 28), doSendPrompt)
    table.insert(TranslatableUI, { btn = sendBtn, en = "Send", es = "Enviar" })

    promptInput.FocusLost:Connect(function(enterPressed)
        if enterPressed then
            doSendPrompt()
        end
    end)

    local btnRow = Instance.new("Frame", respCard)
    btnRow.Size = UDim2.new(1, -20, 0, 34)
    btnRow.Position = UDim2.new(0, 10, 0, 310)
    btnRow.BackgroundTransparency = 1

    local execBtn = createActionButton(btnRow, "Execute Code", "Ejecutar Codigo", UDim2.new(0.32, 0, 1, 0), UDim2.new(0, 0, 0, 0), function()
        if lastGeneratedCode and #string.gsub(lastGeneratedCode, "%s+", "") > 0 then
            local success, err = pcall(function()
                loadstring(lastGeneratedCode)()
            end)
            if success then
                notifyToggle((CurrentLang == "ES") and "Script ejecutado con exito!" or "Script executed successfully!", true)
            else
