        end
    end)
    table.insert(TranslatableUI, { btn = execBtn, en = "Execute Code", es = "Ejecutar Codigo" })

    local copyBtn = createActionButton(btnRow, "Copy", "Copiar", UDim2.new(0.32, 0, 1, 0), UDim2.new(0.34, 0, 0, 0), function()
        local textToCopy = (#lastGeneratedCode > 0) and lastGeneratedCode or lastGeneratedFullText
        if #textToCopy > 0 then
            universalCopy(textToCopy)
            notifyToggle((CurrentLang == "ES") and "Copiado al portapapeles!" or "Copied to clipboard!", true)
        else
            notifyToggle((CurrentLang == "ES") and "Nada para copiar" or "Nothing to copy", false)
        end
    end)
    table.insert(TranslatableUI, { btn = copyBtn, en = "Copy", es = "Copiar" })

    local clearBtn = createActionButton(btnRow, "Clear", "Limpiar", UDim2.new(0.32, 0, 1, 0), UDim2.new(0.68, 0, 0, 0), function()
        lastGeneratedCode = ""
        lastGeneratedFullText = ""
        if terminalLogBox then
            terminalLogBox.Text = (CurrentLang == "ES") and ">> [Zen AI]: Terminal limpia. Lista para una nueva consulta." or ">> [Zen AI]: Terminal cleared. Ready for a new query."
        end
        notifyToggle((CurrentLang == "ES") and "Terminal limpia" or "Terminal cleared", true)
    end)
    table.insert(TranslatableUI, { btn = clearBtn, en = "Clear", es = "Limpiar" })
end
