            Instance.new("UICorner", ov).CornerRadius = UDim.new(0, 6)
            local ovStroke = Instance.new("UIStroke", ov)
            ovStroke.Color = Color3.fromRGB(160, 175, 215)
            ovStroke.Thickness = 1.2
            table.insert(hudOverlays, ov)

            local dragging = false
            local dragStart = nil
            local startBtnPos = nil
            local startOvPos = nil
            local c1 = ov.InputBegan:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                    dragging = true
                    local mPos = UserInputService:GetMouseLocation()
                    dragStart = Vector3.new(mPos.X, mPos.Y, 0)
                    startBtnPos = btn.Position
                    startOvPos = ov.Position
                end
            end)
            local c2 = UserInputService.InputChanged:Connect(function(input)
                if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
                    local mPos = UserInputService:GetMouseLocation()
                    local curPos = Vector3.new(mPos.X, mPos.Y, 0)
                    local deltaX = curPos.X - dragStart.X
                    local deltaY = curPos.Y - dragStart.Y
                    btn.Position = UDim2.new(
                        startBtnPos.X.Scale,
                        startBtnPos.X.Offset + deltaX,
                        startBtnPos.Y.Scale,
                        startBtnPos.Y.Offset + deltaY
                    )
                    ov.Position = UDim2.new(
                        startOvPos.X.Scale,
                        startOvPos.X.Offset + deltaX,
                        startOvPos.Y.Scale,
                        startOvPos.Y.Offset + deltaY
                    )
                end
            end)
            local c3 = UserInputService.InputEnded:Connect(function(input)
                if dragging and (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) then
                    dragging = false
                    _G.Spooky_ControlsLayout[btn.Name] = _G.Spooky_ControlsLayout[btn.Name] or {}
                    _G.Spooky_ControlsLayout[btn.Name].scaleX = btn.Position.X.Scale
                    _G.Spooky_ControlsLayout[btn.Name].offsetX = btn.Position.X.Offset
                    _G.Spooky_ControlsLayout[btn.Name].scaleY = btn.Position.Y.Scale
                    _G.Spooky_ControlsLayout[btn.Name].offsetY = btn.Position.Y.Offset
                end
            end)
            table.insert(activeDragConns, c1)
            table.insert(activeDragConns, c2)
            table.insert(activeDragConns, c3)
        end
        notifyToggle((CurrentLang == "ES") and "HUD Desbloqueado! Arrastra los controles libremente (Touch / Mouse)." or "HUD Unlocked! Drag buttons freely (Touch / Mouse).", true)
    end

    local editCard = makeCard(HUDPage, "HUD Move", "Mover HUD", 74, 2)
    editControlsBtn = createActionButton(editCard, "Unlock Dragging", "Desbloquear", UDim2.new(0.48, -4, 0, 32), UDim2.new(0, 10, 0, 28), function()
        setEditControlsMode(not isEditingControls)
    end)

    createActionButton(editCard, "Reset Layout", "Restablecer", UDim2.new(0.48, -4, 0, 32), UDim2.new(0.5, 4, 0, 28), function()
        if isfile and isfile("Sovereign_ControlsLayout.json") and delfile then
            pcall(function() delfile("Sovereign_ControlsLayout.json") end)
        end
        _G.Spooky_ControlsLayout = {}
        for name, pos in pairs(originalControlsLayout) do
            for _, b in ipairs(getBloxFruitsControlButtons()) do
                if b.Name == name then b.Position = pos end
            end
        end
        for _, b in ipairs(getBloxFruitsControlButtons()) do
            local s = b:FindFirstChildOfClass("UIScale")
            if s then s.Scale = 1.0 end
        end
        notifyToggle((CurrentLang == "ES") and "Diseño HUD restablecido" or "HUD Layout Reset", true)
    end)

    local scaleCard = makeCard(HUDPage, "HUD Scale", "Escala HUD", 116, 82)
    createSlider(scaleCard, "Button Scale", "Escala de Botones", 0.50, 2.00, (_G.Spooky_ControlsLayout and _G.Spooky_ControlsLayout.globalScale) or 1.0, true, 0.05, "x", function(val)
        _G.Spooky_ControlsLayout.globalScale = val
        for _, btn in ipairs(getBloxFruitsControlButtons()) do
            local s = btn:FindFirstChildOfClass("UIScale") or Instance.new("UIScale", btn)
            s.Scale = val
        end
        saveControlsLayoutToFile()
    end, UDim2.new(0, 8, 0, 28))

    local bsW = UDim2.new(0.23, 0, 0, 26)
    createActionButton(scaleCard, "0.80x", "0.80x", bsW, UDim2.new(0, 8, 0, 74), function()
        _G.Spooky_ControlsLayout.globalScale = 0.80
        for _, btn in ipairs(getBloxFruitsControlButtons()) do
            local s = btn:FindFirstChildOfClass("UIScale") or Instance.new("UIScale", btn)
            s.Scale = 0.80
        end
        saveControlsLayoutToFile()
        notifyToggle("Button Scale: 0.80x", true)
    end)
    createActionButton(scaleCard, "1.00x", "1.00x (Def)", bsW, UDim2.new(0.25, 6, 0, 74), function()
        _G.Spooky_ControlsLayout.globalScale = 1.00
        for _, btn in ipairs(getBloxFruitsControlButtons()) do
            local s = btn:FindFirstChildOfClass("UIScale") or Instance.new("UIScale", btn)
            s.Scale = 1.00
        end
        saveControlsLayoutToFile()
        notifyToggle("Button Scale: 1.00x", true)
    end)
    createActionButton(scaleCard, "1.25x", "1.25x", bsW, UDim2.new(0.50, 4, 0, 74), function()
        _G.Spooky_ControlsLayout.globalScale = 1.25
        for _, btn in ipairs(getBloxFruitsControlButtons()) do
            local s = btn:FindFirstChildOfClass("UIScale") or Instance.new("UIScale", btn)
            s.Scale = 1.25
        end
        saveControlsLayoutToFile()
        notifyToggle("Button Scale: 1.25x", true)
    end)
    createActionButton(scaleCard, "1.50x", "1.50x", bsW, UDim2.new(0.75, 2, 0, 74), function()
        _G.Spooky_ControlsLayout.globalScale = 1.50
        for _, btn in ipairs(getBloxFruitsControlButtons()) do
            local s = btn:FindFirstChildOfClass("UIScale") or Instance.new("UIScale", btn)
            s.Scale = 1.50
        end
        saveControlsLayoutToFile()
        notifyToggle("Button Scale: 1.50x", true)
    end)
    loadControlsLayoutFromFile()
end
do
    local ControlPeoplePage = createScrollPage("ControlPeople_Page", 900)
    _G.PlayerBlacklist = _G.PlayerBlacklist or {}
    Spooky.Blacklist = _G.PlayerBlacklist

    local isSpectatingPlr = nil
    local function stopSpectating()
        isSpectatingPlr = nil
        pcall(function()
            local cam = workspace.CurrentCamera
            local myHum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
            if cam and myHum then cam.CameraSubject = myHum end
        end)
    end

    local p_card1 = makeCard(ControlPeoplePage, "Player Radar", "Radar Jugadores", 94, 2)

    local pCountLbl = Instance.new("TextLabel", p_card1)
    pCountLbl.Size = UDim2.new(0.52, -10, 0, 20)
    pCountLbl.Position = UDim2.new(0, 10, 0, 30)
    pCountLbl.BackgroundTransparency = 1
    pCountLbl.Font = Enum.Font.GothamBold
    pCountLbl.Text = "PLAYERS: " .. tostring(#Players:GetPlayers())
    pCountLbl.TextSize = 11.5
    pCountLbl.TextColor3 = Color3.fromRGB(235, 235, 245)
    pCountLbl.TextXAlignment = Enum.TextXAlignment.Left

    local blCountLbl = Instance.new("TextLabel", p_card1)
    blCountLbl.Size = UDim2.new(0.46, -10, 0, 20)
    blCountLbl.Position = UDim2.new(0.54, 0, 0, 30)
    blCountLbl.BackgroundTransparency = 1
    blCountLbl.Font = Enum.Font.GothamBold
    blCountLbl.Text = "BLACKLISTED: 0"
    blCountLbl.TextSize = 11.5
    blCountLbl.TextColor3 = Color3.fromRGB(255, 110, 110)
    blCountLbl.TextXAlignment = Enum.TextXAlignment.Right

    local function getBlacklistCount()
        local count = 0
        for _, p in ipairs(Players:GetPlayers()) do
            if _G.PlayerBlacklist and (_G.PlayerBlacklist[p.UserId] or _G.PlayerBlacklist[p.Name]) then
                count = count + 1
            end
        end
        return count
    end

    local searchFilter = ""
    local searchBox = Instance.new("TextBox", p_card1)
    searchBox.Size = UDim2.new(0.52, -14, 0, 26)
    searchBox.Position = UDim2.new(0, 10, 0, 56)
    searchBox.BackgroundColor3 = Color3.fromRGB(18, 18, 24)
    searchBox.PlaceholderText = "Search player..."
    searchBox.PlaceholderColor3 = Color3.fromRGB(110, 110, 125)
    searchBox.Text = ""
    searchBox.Font = Enum.Font.GothamMedium
    searchBox.TextSize = 11
    searchBox.TextColor3 = Color3.fromRGB(255, 255, 255)
    searchBox.ClearTextOnFocus = false
    styleSpookyTextBox(searchBox)
    Instance.new("UICorner", searchBox).CornerRadius = UDim.new(0, 6)
    local sStk = Instance.new("UIStroke", searchBox)
    sStk.Color = Color3.fromRGB(44, 44, 56)

    local listContainer = Instance.new("Frame", ControlPeoplePage)
    listContainer.Name = "PlayerListContainer"
    listContainer.Size = UDim2.new(1, 0, 0, 0)
    listContainer.Position = UDim2.new(0, 0, 0, 102)
    listContainer.BackgroundTransparency = 1

    local plLayout = Instance.new("UIListLayout", listContainer)
    plLayout.Padding = UDim.new(0, 6)
    plLayout.SortOrder = Enum.SortOrder.LayoutOrder

    local refreshPlayerList = nil
    _G.SpookyRefreshPlayerList = function()
        if refreshPlayerList then refreshPlayerList() end
    end
    refreshPlayerList = function()
        pcall(function()
            pCountLbl.Text = "PLAYERS: " .. tostring(#Players:GetPlayers())
            blCountLbl.Text = "BLACKLISTED: " .. tostring(getBlacklistCount())

            for _, ch in ipairs(listContainer:GetChildren()) do
                if ch:IsA("GuiObject") and ch.Name ~= "UIListLayout" then
                    ch:Destroy()
                end
            end

            local allPlrs = Players:GetPlayers()
            local q = string.lower(searchFilter or "")
            local renderedCount = 0

            for _, plr in ipairs(allPlrs) do
                local dName = plr.DisplayName or ""
                local uName = plr.Name or ""
                if q == "" or string.find(string.lower(dName), q, 1, true) or string.find(string.lower(uName), q, 1, true) then
                    renderedCount = renderedCount + 1
                    local isMe = (plr == LocalPlayer)
                    local isBlacklisted = (_G.PlayerBlacklist and (_G.PlayerBlacklist[plr.UserId] or _G.PlayerBlacklist[plr.Name])) == true

                    local itemF = Instance.new("Frame", listContainer)
                    itemF.Name = "PlrCard_" .. plr.Name
                    itemF.Size = UDim2.new(1, -10, 0, 74)
                    itemF.Position = UDim2.new(0, 5, 0, 0)
                    itemF.BackgroundColor3 = isMe and Color3.fromRGB(16, 20, 28) or Color3.fromRGB(14, 14, 18)
                    itemF.BorderSizePixel = 0
                    Instance.new("UICorner", itemF).CornerRadius = UDim.new(0, 8)

                    local itStk = Instance.new("UIStroke", itemF)
                    itStk.Color = isBlacklisted and Color3.fromRGB(180, 45, 45) or (isMe and Color3.fromRGB(60, 90, 140) or Color3.fromRGB(36, 36, 46))
                    itStk.Thickness = isBlacklisted and 1.5 or 1

                    local headImg = Instance.new("ImageLabel", itemF)
                    headImg.Size = UDim2.new(0, 48, 0, 48)
                    headImg.Position = UDim2.new(0, 10, 0.5, -24)
                    headImg.BackgroundColor3 = Color3.fromRGB(10, 10, 14)
                    headImg.BackgroundTransparency = 0.3
                    Instance.new("UICorner", headImg).CornerRadius = UDim.new(0, 6)
                    local hStk = Instance.new("UIStroke", headImg)
                    hStk.Color = Color3.fromRGB(36, 36, 48)

                    task.spawn(function()
                        pcall(function()
                            local thumb = Players:GetUserThumbnailAsync(plr.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size100x100)
                            if headImg and headImg.Parent then headImg.Image = thumb end
                        end)
                    end)

                    local infoC = Instance.new("Frame", itemF)
                    infoC.Name = "Info"
                    infoC.Size = UDim2.new(1, -256, 1, -12)
                    infoC.Position = UDim2.new(0, 66, 0, 6)
                    infoC.BackgroundTransparency = 1
                    infoC.ClipsDescendants = true

                    local nameLbl = Instance.new("TextLabel", infoC)
                    nameLbl.Size = UDim2.new(1, 0, 0, 18)
                    nameLbl.Position = UDim2.new(0, 0, 0, 2)
                    nameLbl.BackgroundTransparency = 1
                    nameLbl.Font = Enum.Font.GothamBold
                    nameLbl.Text = plr.DisplayName .. " (@" .. plr.Name .. ")" .. (isMe and " [YOU]" or "")
                    nameLbl.TextSize = 12
                    nameLbl.TextColor3 = isMe and Color3.fromRGB(130, 190, 255) or Color3.fromRGB(240, 240, 250)
                    nameLbl.TextXAlignment = Enum.TextXAlignment.Left
                    nameLbl.TextTruncate = Enum.TextTruncate.AtEnd
                    nameLbl.ClipsDescendants = true

                    local bVal = 0
                    local ls = plr:FindFirstChild("leaderstats")
                    if ls then
                        local bStat = ls:FindFirstChild("Bounty/Honor") or ls:FindFirstChild("Bounty")
                        if bStat then bVal = bStat.Value end
                    end
                    local bountyFmt = tostring(bVal)
                    if bVal >= 1000000 then
                        bountyFmt = string.format("%.2fM", bVal / 1000000)
                    elseif bVal >= 1000 then
                        bountyFmt = string.format("%dK", math.floor(bVal / 1000))
                    end

                    local teamStr = tostring(plr.Team and plr.Team.Name or "Neutral")

                    local statsLbl = Instance.new("TextLabel", infoC)
                    statsLbl.Size = UDim2.new(1, 0, 0, 16)
                    statsLbl.Position = UDim2.new(0, 0, 0, 22)
                    statsLbl.BackgroundTransparency = 1
                    statsLbl.Font = Enum.Font.GothamMedium
                    statsLbl.Text = string.format("Bounty: %s  |  Team: %s", bountyFmt, teamStr)
                    statsLbl.TextSize = 10
                    statsLbl.TextColor3 = Color3.fromRGB(200, 180, 100)
                    statsLbl.TextXAlignment = Enum.TextXAlignment.Left
                    statsLbl.TextTruncate = Enum.TextTruncate.AtEnd
                    statsLbl.ClipsDescendants = true

                    local detectedFruit = "None"
                    local pChar = plr.Character
                    if pChar then
                        for _, ch in ipairs(pChar:GetChildren()) do
                            if ch:IsA("Tool") and (ch:FindFirstChild("Fruit") or string.find(string.lower(ch.Name), "fruit") or string.find(string.lower(ch.Name), "dough") or string.find(string.lower(ch.Name), "dragon") or string.find(string.lower(ch.Name), "kitsune")) then
                                detectedFruit = ch.Name:gsub(" Fruit", ""):gsub("No Mi", "")
                                break
                            end
                        end
                    end
                    local dist = 0
                    local myHrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                    if myHrp and pChar and pChar:FindFirstChild("HumanoidRootPart") then
                        dist = math.floor((myHrp.Position - pChar.HumanoidRootPart.Position).Magnitude)
                    end

                    local distLbl = Instance.new("TextLabel", infoC)
                    distLbl.Size = UDim2.new(1, 0, 0, 16)
                    distLbl.Position = UDim2.new(0, 0, 0, 40)
                    distLbl.BackgroundTransparency = 1
                    distLbl.Font = Enum.Font.GothamMedium
                    distLbl.Text = string.format("Fruit: %s  |  Dist: %d studs", detectedFruit, dist)
                    distLbl.TextSize = 10
                    distLbl.TextColor3 = Color3.fromRGB(180, 195, 225)
                    distLbl.TextXAlignment = Enum.TextXAlignment.Left
                    distLbl.TextTruncate = Enum.TextTruncate.AtEnd
                    distLbl.ClipsDescendants = true

                    local btnContainer = Instance.new("Frame", itemF)
                    btnContainer.Name = "Buttons"
                    btnContainer.Size = UDim2.new(0, 180, 0, 60)
                    btnContainer.Position = UDim2.new(1, -186, 0.5, -30)
                    btnContainer.BackgroundTransparency = 1

                    local btnSpectate = Instance.new("TextButton", btnContainer)
                    btnSpectate.Size = UDim2.new(0, 86, 0, 26)
                    btnSpectate.Position = UDim2.new(0, 0, 0, 2)
                    btnSpectate.BackgroundColor3 = (isSpectatingPlr == plr) and Color3.fromRGB(60, 40, 80) or Color3.fromRGB(24, 24, 32)
                    btnSpectate.Font = Enum.Font.GothamBold
                    btnSpectate.Text = (isSpectatingPlr == plr) and "Viewing" or "Spectate"
                    btnSpectate.TextSize = 10.5
                    btnSpectate.TextColor3 = Color3.fromRGB(240, 240, 255)
                    Instance.new("UICorner", btnSpectate).CornerRadius = UDim.new(0, 5)
                    local spStk = Instance.new("UIStroke", btnSpectate)
                    spStk.Color = Color3.fromRGB(48, 48, 62)

                    btnSpectate.MouseButton1Click:Connect(function()
                        if isSpectatingPlr == plr then
                            stopSpectating()
                            btnSpectate.Text = "Spectate"
                            btnSpectate.BackgroundColor3 = Color3.fromRGB(24, 24, 32)
                        else
                            stopSpectating()
                            isSpectatingPlr = plr
                            btnSpectate.Text = "Viewing"
                            btnSpectate.BackgroundColor3 = Color3.fromRGB(60, 40, 80)
                            local cam = workspace.CurrentCamera
                            if cam and plr.Character and plr.Character:FindFirstChildOfClass("Humanoid") then
                                cam.CameraSubject = plr.Character:FindFirstChildOfClass("Humanoid")
                                notifyToggle("Spectating " .. plr.DisplayName, true)
                            end
                        end
                    end)

                    local btnBlacklist = Instance.new("TextButton", btnContainer)
                    btnBlacklist.Size = UDim2.new(0, 88, 0, 26)
                    btnBlacklist.Position = UDim2.new(0, 92, 0, 2)
                    btnBlacklist.BackgroundColor3 = isBlacklisted and Color3.fromRGB(28, 18, 22) or Color3.fromRGB(20, 20, 26)
                    btnBlacklist.Font = Enum.Font.GothamBold
                    btnBlacklist.Text = isBlacklisted and "Blacklisted" or "Blacklist"
                    btnBlacklist.TextSize = 10.5
                    btnBlacklist.TextColor3 = isBlacklisted and Color3.fromRGB(255, 200, 210) or Color3.fromRGB(220, 220, 235)
                    Instance.new("UICorner", btnBlacklist).CornerRadius = UDim.new(0, 5)
                    local blStk = Instance.new("UIStroke", btnBlacklist)
                    blStk.Color = isBlacklisted and Color3.fromRGB(180, 40, 50) or Color3.fromRGB(45, 45, 58)

                    btnBlacklist.MouseButton1Click:Connect(function()
                        local currentlyBl = (_G.PlayerBlacklist and (_G.PlayerBlacklist[plr.UserId] or _G.PlayerBlacklist[plr.Name])) == true
                        local newBl = not currentlyBl
                        if newBl then
                            _G.PlayerBlacklist[plr.UserId] = true
                            _G.PlayerBlacklist[tostring(plr.UserId)] = true
                            _G.PlayerBlacklist[plr.Name] = true
                            _G.PlayerBlacklist[string.lower(plr.Name)] = true
                            _G.PlayerBlacklist[plr.DisplayName] = true
                            _G.PlayerBlacklist[string.lower(plr.DisplayName)] = true
                            btnBlacklist.Text = "Blacklisted"
                            btnBlacklist.BackgroundColor3 = Color3.fromRGB(28, 18, 22)
                            btnBlacklist.TextColor3 = Color3.fromRGB(255, 200, 210)
                            blStk.Color = Color3.fromRGB(180, 40, 50)
                            itStk.Color = Color3.fromRGB(140, 35, 45)
                            notifyToggle("Blacklist (Aimbot Ignore): " .. plr.DisplayName .. " -> ACTIVADO", true)
                        else
                            _G.PlayerBlacklist[plr.UserId] = nil
                            _G.PlayerBlacklist[tostring(plr.UserId)] = nil
                            _G.PlayerBlacklist[plr.Name] = nil
                            _G.PlayerBlacklist[string.lower(plr.Name)] = nil
                            _G.PlayerBlacklist[plr.DisplayName] = nil
                            _G.PlayerBlacklist[string.lower(plr.DisplayName)] = nil
                            btnBlacklist.Text = "Blacklist"
                            btnBlacklist.BackgroundColor3 = Color3.fromRGB(20, 20, 26)
                            btnBlacklist.TextColor3 = Color3.fromRGB(220, 220, 235)
                            blStk.Color = Color3.fromRGB(45, 45, 58)
                            itStk.Color = isMe and Color3.fromRGB(60, 90, 140) or Color3.fromRGB(36, 36, 46)
                            notifyToggle("Blacklist (Aimbot Ignore): " .. plr.DisplayName .. " -> DESACTIVADO", false)
                        end
                        blCountLbl.Text = "BLACKLISTED: " .. tostring(getBlacklistCount())
                    end)

                    local aimButton = Instance.new("TextButton", btnContainer)
                    aimButton.Size, aimButton.Position = UDim2.fromOffset(88,24), UDim2.fromOffset(92,32)
                    aimButton.BackgroundColor3 = Color3.fromRGB(28,30,42)
                    aimButton.TextColor3, aimButton.Font, aimButton.TextSize = Color3.new(1,1,1), Enum.Font.GothamMedium, 10
                    aimButton.Text = tostring(Settings.aimTargetUserId) == tostring(plr.UserId) and "Selected" or "Aim target"
                    Instance.new("UICorner",aimButton).CornerRadius = UDim.new(0,5)
                    aimButton.Activated:Connect(function()
                        if plr == LocalPlayer then return end
                        Settings.aimTargetUserId = plr.UserId
                        Settings.aimTargetPolicy = "Selected"
                        if _G.StickyCombat then _G.StickyCombat.playerObj = nil end
                        refreshPlayerList()
                    end)

                    local btnCopyId = Instance.new("TextButton", btnContainer)
                    btnCopyId.Size = UDim2.new(0, 86, 0, 24)
                    btnCopyId.Position = UDim2.new(0, 0, 0, 32)
                    btnCopyId.BackgroundColor3 = Color3.fromRGB(20, 20, 26)
                    btnCopyId.Font = Enum.Font.GothamMedium
                    btnCopyId.Text = "Copy ID"
                    btnCopyId.TextSize = 10
                    btnCopyId.TextColor3 = Color3.fromRGB(210, 210, 225)
                    Instance.new("UICorner", btnCopyId).CornerRadius = UDim.new(0, 5)
                    local cpStk = Instance.new("UIStroke", btnCopyId)
                    cpStk.Color = Color3.fromRGB(40, 40, 52)

                    btnCopyId.MouseButton1Click:Connect(function()
                        universalCopy(tostring(plr.UserId))
                        notifyToggle("Copied UserId: " .. tostring(plr.UserId), true)
                    end)
                end
            end

            listContainer.Size = UDim2.new(1, 0, 0, renderedCount * 80 + 10)
            ControlPeoplePage.CanvasSize = UDim2.new(0, 0, 0, 110 + renderedCount * 80 + 20)
        end)
    end

    Spooky.RefreshPlayerList = refreshPlayerList
    searchBox:GetPropertyChangedSignal("Text"):Connect(function()
        searchFilter = searchBox.Text
        refreshPlayerList()
    end)

    createActionButton(p_card1, "Refresh", "Actualizar", UDim2.new(0.23, -4, 0, 26), UDim2.new(0.52, 4, 0, 56), function()
        refreshPlayerList()
        notifyToggle("Player List Refreshed", true)
    end)

    createActionButton(p_card1, "Clear BL", "Limpiar BL", UDim2.new(0.25, -12, 0, 26), UDim2.new(0.75, 2, 0, 56), function()
        _G.PlayerBlacklist = {}
        Spooky.Blacklist = _G.PlayerBlacklist
        refreshPlayerList()
        notifyToggle("All Players Cleared from Blacklist", false)
    end)

    task.spawn(function()
        task.wait(1)
        refreshPlayerList()
    end)
    Players.PlayerAdded:Connect(function() task.defer(refreshPlayerList) end)
    Players.PlayerRemoving:Connect(function(p)
        if isSpectatingPlr == p then stopSpectating() end
        task.defer(refreshPlayerList)
    end)

    pcall(function()
    end)
end

do
    if _G.SpookyStartupStage then _G.SpookyStartupStage("combat") end
    _G.CombatCache = { lastScan = 0, player = nil, npc = nil, heldSkillKeys = {} }
    local CombatCache = _G.CombatCache
    local aimbot1TargetPos = nil
    local lockedAim1Char = nil
    local lockedAim2Char = nil
    local centuTargetChar = nil
    local centuAimPosition = nil
    local currentHeldTool = nil
    local currentHeldCategory = "Melee"
    local currentSkillKey = nil
    local lastSkillTime = 0
    local SKILL_KEYS = { "Z", "X", "C", "V", "F", "TAP" }
    local BlacklistedKeys = {
        Melee = { Z = false, X = false, C = false, all = false },
        Fruit = { M1 = false, TAP = false, Z = false, X = false, C = false, V = false, F = false, all = false },
        Sword = { Z = false, X = false, all = false },
        Gun   = { Z = false, X = false, TAP = false, M1 = false, all = false }
    }
