    local function crewIdentity(value)
        if value == nil or value == false then return nil end
        local text=tostring(value):match("^%s*(.-)%s*$"):lower()
        if text=="" or text=="0" or text=="none" or text=="nil" or text=="n/a" or text=="no crew" or text=="sin crew" then return nil end
        return text
    end
    local function isBloxFruitsAlly(player)
        if not player or player == LocalPlayer then return false end
        local ok, isAlly = pcall(function()

            local pg = LocalPlayer:FindFirstChild("PlayerGui")
            local main = pg and pg:FindFirstChild("Main")
            local allies = main and main:FindFirstChild("Allies")
            local container = allies and allies:FindFirstChild("Container")
            local frame = container and container:FindFirstChild("Allies") and container.Allies:FindFirstChild("ScrollingFrame") and container.Allies.ScrollingFrame:FindFirstChild("Frame")
            if frame and frame:FindFirstChild(player.Name) then return true end
            local list=container and container:FindFirstChild("Allies")
            local scroll=list and list:FindFirstChild("ScrollingFrame")
            if scroll and scroll:FindFirstChild(player.Name,true) then return true end

            local myCrew = LocalPlayer:GetAttribute("Crew") or (LocalPlayer.Character and LocalPlayer.Character:GetAttribute("Crew"))
            local targetCrew = player:GetAttribute("Crew") or (player.Character and player.Character:GetAttribute("Crew"))
            if crewIdentity(myCrew) and crewIdentity(myCrew) == crewIdentity(targetCrew) then return true end

            local myHead = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("Head")
            local targetHead = player.Character and player.Character:FindFirstChild("Head")
            local myCrewGui = myHead and (myHead:FindFirstChild("CrewGui") or myHead:FindFirstChild("Header"))
            local targetCrewGui = targetHead and (targetHead:FindFirstChild("CrewGui") or targetHead:FindFirstChild("Header"))
            if myCrewGui and targetCrewGui then
                local myCrewName = myCrewGui:FindFirstChild("CrewName", true)
                local targetCrewName = targetCrewGui:FindFirstChild("CrewName", true)
                if myCrewName and targetCrewName and crewIdentity(myCrewName.Text) and crewIdentity(myCrewName.Text) == crewIdentity(targetCrewName.Text) then
                    return true
                end
            end
            return false
        end)
        return ok and isAlly == true
    end

    local function isEnemy(player)
        if not player or player == LocalPlayer then return false end
        if isBloxFruitsAlly(player) then return false end
        local myTeam, targetTeam = LocalPlayer.Team, player.Team
        if myTeam and targetTeam and myTeam.Name == "Marines" and targetTeam.Name == "Marines" then
            return false
        end
        return true
    end

    local function AX_ReadPvPState(target)
        if not target then return false end
        local ok, pvpOn = pcall(function()
            local isPlr = typeof(target) == "Instance" and target:IsA("Player")
            local plr = isPlr and target or Players:GetPlayerFromCharacter(target)
            local char = (isPlr and target.Character) or target
            if plr and plr:GetAttribute("PvpDisabled") == true then
                return false
            end
            if char and char:GetAttribute("PvpDisabled") == true then
                return false
            end
            return true
        end)
        return ok and pvpOn == true
    end

    local function AX_InSafeZone(target)
        if not target then return false end
        local ok, inZone = pcall(function()
            local isPlr = typeof(target) == "Instance" and target:IsA("Player")
            local plr = isPlr and target or Players:GetPlayerFromCharacter(target)
            local char = (isPlr and target.Character) or target
            if not char then return false end

            for _,name in ipairs({"SafeZoneShield","SafeZone"}) do
                local flag=char:FindFirstChild(name)
                if flag and (not flag:IsA("BoolValue") or flag.Value==true) then return true end
            end
            if char:FindFirstChildOfClass("ForceField") then return true end
            if char:GetAttribute("SafeZone") == true or char:GetAttribute("InSafeZone") == true then return true end
            if plr and (plr:GetAttribute("SafeZone") == true or plr:GetAttribute("InSafeZone") == true) then return true end

            local hrp = char:FindFirstChild("HumanoidRootPart")
            if not hrp then return false end

            local function checkFolder(folder)
                if not folder then return false end
                for _, zone in ipairs(folder:GetChildren()) do
                    if zone:IsA("BasePart") then
                        local localPos = zone.CFrame:PointToObjectSpace(hrp.Position)
                        local halfSize = zone.Size / 2
                        if math.abs(localPos.X) <= halfSize.X and math.abs(localPos.Y) <= halfSize.Y + 25 and math.abs(localPos.Z) <= halfSize.Z then
                            return true
                        end
                    end
                end
                return false
            end

            local wo = workspace:FindFirstChild("_WorldOrigin")
            if wo and checkFolder(wo:FindFirstChild("SafeZones")) then return true end
            if checkFolder(workspace:FindFirstChild("SafeZones")) then return true end
            local map = workspace:FindFirstChild("Map")
            if map and checkFolder(map:FindFirstChild("SafeZones")) then return true end

            return false
        end)
        return ok and inZone == true
    end

    _G.isPlayerBlacklisted = function(p)
        if not p then return false end
        local bl = _G.PlayerBlacklist or (Spooky and Spooky.Blacklist)
        if not bl then return false end
        if bl[p] == true then return true end
        if p.UserId and (bl[p.UserId] == true or bl[tostring(p.UserId)] == true or bl[tonumber(p.UserId)] == true) then return true end
        if p.Name and (bl[p.Name] == true or bl[string.lower(p.Name)] == true) then return true end
        if p.DisplayName and (bl[p.DisplayName] == true or bl[string.lower(p.DisplayName)] == true) then return true end
        return false
    end

    local PlayerLevelCache = {}
    _G.getPlayerLevel = function(p)
        if not p then return 0 end
        local uId = p.UserId or p.Name
        local cached = PlayerLevelCache[uId]
        local now = tick()
        if cached and (now - cached.time < 12) and cached.lvl > 0 then
            return cached.lvl
        end

        local lvl = 0
        local d = p:FindFirstChild("Data")
        if d and d:FindFirstChild("Level") then
            lvl = tonumber(d.Level.Value) or 0
        end
        if lvl <= 0 then
            local pd = p:FindFirstChild("PlayerData")
            if pd and pd:FindFirstChild("Level") then
                lvl = tonumber(pd.Level.Value) or 0
            end
        end
        if lvl <= 0 then
            local ls = p:FindFirstChild("leaderstats")
            if ls then
                local lStat = ls:FindFirstChild("Level") or ls:FindFirstChild("Lvl")
                if lStat then lvl = tonumber(lStat.Value) or 0 end
            end
        end
        if lvl <= 0 then
            local c = p.Character
            if c then
                local aLvl = c:GetAttribute("Level") or p:GetAttribute("Level")
                if aLvl and tonumber(aLvl) and tonumber(aLvl) > 0 then
                    lvl = tonumber(aLvl)
                else
                    local head = c:FindFirstChild("Head")
                    if head then
                        for _, b in ipairs(head:GetChildren()) do
                            if b:IsA("BillboardGui") then
                                for _, desc in ipairs(b:GetDescendants()) do
                                    if desc:IsA("TextLabel") and desc.Text then
                                        local num = string.match(desc.Text, "Lv%.?%s*(%d+)") or string.match(desc.Text, "Level%s*(%d+)")
                                        if num and tonumber(num) and tonumber(num) > 0 then
                                            lvl = tonumber(num)
                                            break
                                        end
                                    end
                                end
                            end
                            if lvl > 0 then break end
                        end
                    end
                end
            end
        end

        if lvl > 0 then
            PlayerLevelCache[uId] = { lvl = lvl, time = now }
        end
        return lvl
    end

    local function isTargetPlayerCombatValid(p, maxDist)
        if not p or p == LocalPlayer or not p.Character then return false, "invalid target" end
        if _G.isPlayerBlacklisted(p) then return false, "player blacklist" end
        if FeatureStates["IgnoreLowLevel"] == true or Settings.ignoreLowLevel == true then
            local minLvl = tonumber(Settings.ignoreLowLevelThreshold) or 2000
            local lvl = _G.getPlayerLevel(p)
            if lvl > 0 and lvl < minLvl then return false, "below minimum level" end
        end
        local pChar = p.Character
        if not pChar:IsDescendantOf(workspace) then return false, "character unavailable" end
        local hum = pChar:FindFirstChildOfClass("Humanoid")
        local hrp = pChar:FindFirstChild("HumanoidRootPart") or pChar.PrimaryPart
        if not hum or hum.Health <= 0 or not hrp or hrp.Position.Y <= -500 then return false, "dead / unavailable root" end

        if (FeatureStates["SafeZoneCheck"] == true or Settings.safeZoneCheck == true) then
            if AX_InSafeZone(p) or not AX_ReadPvPState(p) then return false, "safe zone / PvP disabled" end
        end

        local needTeamCheck = (FeatureStates["TeamCheck"] == true or Settings.teamCheck == true)
        if needTeamCheck and not isEnemy(p) then return false, "team / ally" end

        local char = LocalPlayer.Character
        local myHrp = char and char:FindFirstChild("HumanoidRootPart")
        if not myHrp then return false, "local character unavailable" end

        local dist = (hrp.Position - myHrp.Position).Magnitude
        if dist > (maxDist or 800) then return false, "out of range" end
        return true, dist, pChar
    end
    _G.SpookyIsEnemy = isEnemy
    _G.SpookyInSafeZone = AX_InSafeZone
    _G.SpookyPvPAllowed = AX_ReadPvPState

    _G.StickyCombat = _G.StickyCombat or { player = nil, playerObj = nil, any = nil, npc = nil }

    function Spooky.AimCenter()
        local cam = workspace.CurrentCamera
        if not cam then return Vector2.zero end
        if Settings.aimFovOrigin == "Mouse" and not UserInputService.TouchEnabled then
            local p = UserInputService:GetMouseLocation()
            if p.X > 0 and p.Y > 0 then return p end
        end
        return cam.ViewportSize / 2
    end
    function Spooky.AimScore(part, distance)
        local cam = workspace.CurrentCamera
        local mode = Settings.aimMode or "360"
        if mode == "360" then return distance end
        if not cam or not part then return nil end
        local delta = part.Position - cam.CFrame.Position
        if mode == "180" then
            if delta:Dot(cam.CFrame.LookVector) < 0 then return nil end
            return distance
        end
        local point, visible = cam:WorldToViewportPoint(part.Position)
        if not visible or point.Z <= 0 then return nil end
        local radius = math.clamp(tonumber(Settings.aimFovRadius) or 150, 20, 800)
        local pixels = (Vector2.new(point.X, point.Y) - Spooky.AimCenter()).Magnitude
        return pixels <= radius and pixels or nil
    end
    function Spooky.SelectAimPlayer(maxDist, exclude)
        local best, bestScore, bestModel = nil, math.huge, nil
        local reasons = {}
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LocalPlayer and p ~= exclude then
                local ok, valid, distance, model = pcall(isTargetPlayerCombatValid, p, maxDist or 1200)
                if not ok then Spooky.ReportIssue("Target filter", valid); valid = false; distance = "filter error" end
                if Settings.aimTargetPolicy == "Selected" and tostring(p.UserId) ~= tostring(Settings.aimTargetUserId) then
                    valid = false; distance = "not selected"
                end
                if valid then
                    local part = model:FindFirstChild(Settings.camLockTargetPart or "HumanoidRootPart") or model:FindFirstChild("HumanoidRootPart")
                    local score = Spooky.AimScore(part, distance)
                    if score and score < bestScore then best, bestScore, bestModel = p, score, model end
                    if not score then distance = "outside aim area"; valid = false end
                end
                if not valid then reasons[distance or "unknown"] = (reasons[distance or "unknown"] or 0) + 1 end
            end
        end
        if best then Spooky.Diagnostics.statuses.Target = best.Name
        else
            local rows = {}
            for reason, count in pairs(reasons) do table.insert(rows, reason .. "=" .. count) end
            table.sort(rows)
            Spooky.Diagnostics.statuses.Target = "No target: " .. table.concat(rows, ", ")
        end
        return best, bestModel
    end
    local function getClosestPlayer(maxDist)
        local player, model = Spooky.SelectAimPlayer(maxDist)
        _G.StickyCombat.playerObj, _G.StickyCombat.player = player, model
        return model
    end
