    local function getClosestNPC(maxDist)
        local char = LocalPlayer.Character
        local myHrp = char and char:FindFirstChild("HumanoidRootPart")
        if not myHrp then return nil end
        local maxD = maxDist or 800

        local closest, closestDist = nil, maxD
        local myPos = myHrp.Position
        local function scanFolder(f)
            if not f then return end
            for _, npc in ipairs(f:GetChildren()) do
                if npc:IsDescendantOf(workspace) and not Players:GetPlayerFromCharacter(npc) then
                    local name = string.lower(npc.Name)
                    local isIgnored = name:find("quest") or name:find("dealer") or name:find("shop") or name:find("citizen") or name:find("trainer") or name:find("agent") or name:find("scientist") or name:find("manager") or name:find("set home") or name:find("pirate starter")
                    if not isIgnored then
                        local hum = npc:FindFirstChildOfClass("Humanoid")
                        local hrp = npc:FindFirstChild("HumanoidRootPart") or npc.PrimaryPart or npc:FindFirstChild("UpperTorso") or npc:FindFirstChild("Torso") or npc:FindFirstChild("Head")
                        if hum and hum.Health > 0 and hrp and hrp.Position.Y > -500 then
                            local dist = (hrp.Position - myPos).Magnitude
                            if dist < closestDist then
                                closest = npc
                                closestDist = dist
                            end
                        end
                    end
                end
            end
        end
        scanFolder(workspace:FindFirstChild("Enemies"))
        scanFolder(workspace:FindFirstChild("Characters"))

        if _G.StickyCombat then
            _G.StickyCombat.npc = closest
        end
        return closest
    end

    local function updateEquippedTool(char)
        if not char then return end
        currentHeldTool = char:FindFirstChildOfClass("Tool")
        currentHeldCategory = getToolCategory(currentHeldTool)
    end
    local function setupCharToolTracking(char)
        if not char then return end
        updateEquippedTool(char)
        char.ChildAdded:Connect(function(child)
            if child:IsA("Tool") then
                currentHeldTool = child
                currentHeldCategory = getToolCategory(child)
                currentSkillKey = nil
            end
        end)
        char.ChildRemoved:Connect(function(child)
            if child:IsA("Tool") then
                task.delay(0.05, function()
                    updateEquippedTool(LocalPlayer.Character)
                end)
            end
        end)
    end
    if LocalPlayer.Character then setupCharToolTracking(LocalPlayer.Character) end
    LocalPlayer.CharacterAdded:Connect(function(char) setupCharToolTracking(char) end)
    local function isOverrideTool(tool)
        if not tool then return false end
        local name = string.lower(tool.Name)
        if name == "godhuman" or string.find(name, "sanguine") then return true end
        if currentHeldCategory == "Sword" then return true end
        if string.find(name, "yama") then return true end
        return false
    end
    local function isKeyCurrentlyBlacklisted(key)
        if FeatureStates["BlacklistAimbot"] == false then return false end
        local char = LocalPlayer.Character
        if char and (not currentHeldTool or not currentHeldTool.Parent or currentHeldTool.Parent ~= char) then
            currentHeldTool = char:FindFirstChildOfClass("Tool")
            currentHeldCategory = getToolCategory(currentHeldTool)
        end
        local cat = currentHeldCategory or "Melee"
        local prefix="BL_" .. cat
        if FeatureStates[prefix] ~= nil then BlacklistedKeys[cat].all=FeatureStates[prefix] end
        for _,k in ipairs({"Z","X","C","V","F","M1","TAP"}) do
            local id=prefix .. ((cat=="Gun" and k=="M1") and "TAP" or (cat=="Fruit" and k=="TAP") and "M1" or k)
            if FeatureStates[id]~=nil then BlacklistedKeys[cat][k]=FeatureStates[id] end
        end
        if BlacklistedKeys[cat] then
            if BlacklistedKeys[cat].all then return true end
            local checkKey = key or currentSkillKey
            if checkKey then
                if BlacklistedKeys[cat][checkKey] == true then return true end
                if (checkKey == "TAP" or checkKey == "M1") and (BlacklistedKeys[cat].M1 or BlacklistedKeys[cat].TAP) then return true end
            end
        end
        return false
    end
    _G.SpookySkillBlocked = isKeyCurrentlyBlacklisted
    local function faceTarget(targetPos)
        if not targetPos then return end
        if FeatureStates["BlacklistAimbot"] ~= false then
            if isKeyCurrentlyBlacklisted(currentSkillKey) then return end
        end
        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if hrp and typeof(targetPos) == "Vector3" then
            local currentPos = hrp.Position
            local lookVector = Vector3.new(targetPos.X - currentPos.X, 0, targetPos.Z - currentPos.Z)
            if lookVector.Magnitude > 0.1 then
                pcall(function()
                    hrp.CFrame = CFrame.lookAt(currentPos, currentPos + lookVector.Unit, Vector3.new(0, 1, 0))
                end)
            end
        end
    end
    CombatCache.heldSkillKeys = CombatCache.heldSkillKeys or {}
    local function setCurrentSkillKey(key)
        if currentSkillKey == key and os.clock() - lastSkillTime < 0.2 then return end
        currentSkillKey = key
        lastSkillTime = os.clock()
        if (FeatureStates["AimbotPlayer1"] or FeatureStates["AimbotNpc1"]) then
            local targetPos = aimbot1TargetPos
            if targetPos and not isKeyCurrentlyBlacklisted(key) then
                task.spawn(function() faceTarget(targetPos) end)
            end
        end
        task.spawn(function()
            local myTime = lastSkillTime
            task.wait(1.5)
            if lastSkillTime == myTime and currentSkillKey == key and not (CombatCache.heldSkillKeys and CombatCache.heldSkillKeys[key]) then
                currentSkillKey = nil
            end
        end)
    end
    _G.SpookySetSkillKey=setCurrentSkillKey
