    local function hookMobileButton(btn)
        if not btn or btn:GetAttribute("SovereignSkillSession") == SCRIPT_SESSION then return end
        btn:SetAttribute("SovereignSkillSession", SCRIPT_SESSION)
        local k = btn.Name
        if table.find(SKILL_KEYS, k) then
            registerConnection(btn.Activated:Connect(function()
                if isCurrentSession() then setCurrentSkillKey(k) end
            end))
        end
    end
    task.spawn(function()
        while isCurrentSession() do
            pcall(function()
                local pg = LocalPlayer:FindFirstChild("PlayerGui")
                local main = pg and pg:FindFirstChild("Main")
                local skills = main and main:FindFirstChild("Skills")
                if skills then
                    for _, wf in ipairs(skills:GetChildren()) do
                        if wf:IsA("Frame") or wf:IsA("GuiObject") then
                            for _, btn in ipairs(wf:GetChildren()) do
                                if btn:IsA("GuiButton") then
                                    hookMobileButton(btn)
                                end
                            end
                        end
                    end
                end
            end)
            task.wait(1.5)
        end
    end)
    registerConnection(UserInputService.InputBegan:Connect(function(input, gp)
        if gp then return end
        local map = { [Enum.KeyCode.Z] = "Z", [Enum.KeyCode.X] = "X", [Enum.KeyCode.C] = "C", [Enum.KeyCode.V] = "V", [Enum.KeyCode.F] = "F" }
        local k = map[input.KeyCode]
        if k then
            if CombatCache.heldSkillKeys then CombatCache.heldSkillKeys[k] = true end
            setCurrentSkillKey(k)
        elseif input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            setCurrentSkillKey("TAP")
        end
    end))
    registerConnection(UserInputService.InputEnded:Connect(function(input, gp)
        local map = { [Enum.KeyCode.Z] = "Z", [Enum.KeyCode.X] = "X", [Enum.KeyCode.C] = "C", [Enum.KeyCode.V] = "V", [Enum.KeyCode.F] = "F" }
        local k = map[input.KeyCode]
        if k then
            if CombatCache.heldSkillKeys then CombatCache.heldSkillKeys[k] = nil end
            task.delay(0.25, function()
                local anyHeld = false
                if CombatCache.heldSkillKeys then
                    for _, held in pairs(CombatCache.heldSkillKeys) do
                        if held then anyHeld = true break end
                    end
                end
                if not anyHeld and currentSkillKey == k then
                    currentSkillKey = nil
                end
            end)
        end
    end))

