    function Spooky.GetMyTracerOrigin(camera)
        local char = LocalPlayer.Character
        if not char or not camera then return nil end
        local torso = char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso") or char:FindFirstChild("HumanoidRootPart")
        if torso then
            local chestWorld = torso.Position + Vector3.new(0, 0.6, 0)
            local pOrigin, onScreen = camera:WorldToViewportPoint(chestWorld)
            if onScreen and pOrigin.Z > 0 then
                return Vector2.new(pOrigin.X, pOrigin.Y)
            end
        end
        local vp = camera.ViewportSize
        return Vector2.new(vp.X * 0.5, vp.Y * 0.5)
    end
    function Spooky.ProjectTracer(camera, position)
        if not camera or not position then return nil end
        local p, visible = camera:WorldToViewportPoint(position)
        local vp = camera.ViewportSize
        if not visible or p.Z <= 0 or vp.X < 1 or vp.Y < 1 then return nil end
        if p.X ~= p.X or p.Y ~= p.Y or p.X < 0 or p.X > vp.X or p.Y < 0 or p.Y > vp.Y then return nil end
        local from = Spooky.GetMyTracerOrigin(camera) or Vector2.new(vp.X * 0.5, vp.Y * 0.5)
        local to = Vector2.new(p.X, p.Y)
        local delta = to - from
        if delta.Magnitude < 1 then return nil end
        return (from + to) / 2, delta.Magnitude, math.deg(math.atan2(delta.Y, delta.X))
    end
    local function hideTracers()
        for _, line in pairs(tracerFrames) do line.Visible = false end
    end
    Spooky.HideTracers = hideTracers
    local function drawTracer(model, camera, color)
        local root = model and (model:FindFirstChild("UpperTorso") or model:FindFirstChild("Torso") or model:FindFirstChild("HumanoidRootPart"))
        local hum = model and model:FindFirstChildOfClass("Humanoid")
        if not root or not hum or hum.Health <= 0 then return end
        local targetPos = root.Position + Vector3.new(0, 0.4, 0)
        local midpoint, length, angle = Spooky.ProjectTracer(camera, targetPos)
        if not midpoint then return end
        local line = tracerFrames[model]
        if not line then
            line = Instance.new("Frame", tracerGui)
            line.Name = "TargetLine"
            line.AnchorPoint, line.BorderSizePixel = Vector2.new(0.5,0.5), 0
            line.Active, line.BackgroundTransparency = false, 0.1
            tracerFrames[model] = line
        end
        line.Position, line.Size = UDim2.fromOffset(midpoint.X,midpoint.Y), UDim2.fromOffset(length,1.5)
        line.Rotation, line.BackgroundColor3, line.Visible = angle, color, true
    end
    registerConnection(RunService.RenderStepped:Connect(function()
        if not isCurrentSession() then return end
        hideTracers()
        for model, line in pairs(tracerFrames) do
            local p = Players:GetPlayerFromCharacter(model)
            if not model.Parent or (p and p.Character ~= model) then line:Destroy(); tracerFrames[model] = nil end
        end
        local cam = workspace.CurrentCamera
        local char = LocalPlayer.Character
        if not cam or not char or not char:FindFirstChild("HumanoidRootPart") then return end
        local aimOn = FeatureStates["Tracers1"] or FeatureStates["Tracers2"] or FeatureStates["Tracers3"]
        local allOn = FeatureStates["TracersAll"] or _G.G_ESP_Tracers == true
        if not aimOn and not allOn then return end
        local aim = aimOn and Spooky.TracerAimModel or nil
        local color = colors[Settings.tracerColorName] or colors.Red
        if aim then
            local p = Players:GetPlayerFromCharacter(aim)
            if not p or isTargetPlayerCombatValid(p,1200) then drawTracer(aim,cam,color) end
        end
        if allOn then
            if os.clock() >= nextTracerScan then
                nextTracerScan = os.clock() + 0.15
                table.clear(tracerCandidates)
                for _, p in ipairs(Players:GetPlayers()) do
                    if isTargetPlayerCombatValid(p,1200) then table.insert(tracerCandidates,p) end
                end
            end
            for _, p in ipairs(tracerCandidates) do
                if p.Character ~= aim and isTargetPlayerCombatValid(p,1200) then
                    drawTracer(p.Character,cam,_G.G_ESP_Color or color)
                end
            end
        end
    end))
    for _, id in ipairs({"Tracers1","Tracers2","Tracers3","TracersAll"}) do
        FeatureCallbacks[id] = function() hideTracers(); nextTracerScan = 0 end
    end
