    local centuHighlight = Instance.new("Highlight")
    centuHighlight.Name = "CentuDox_TargetHighlight"
    centuHighlight.FillColor = Color3.fromRGB(255, 0, 0)
    centuHighlight.OutlineColor = Color3.fromRGB(255, 255, 255)
    centuHighlight.FillTransparency = 0.5
    centuHighlight.OutlineTransparency = 0
    centuHighlight.Enabled = false
