    local function getSkillKeyFromArgs(args)
        for _, arg in ipairs(args) do
            if type(arg) == "string" and table.find(SKILL_KEYS, arg) then
                return arg
            end
        end
        return nil
    end
    local function hookMobileSkillButtons()
        pcall(function()
            local pg = LocalPlayer:FindFirstChild("PlayerGui")
            local main = pg and pg:FindFirstChild("Main")
            local skills = main and main:FindFirstChild("Skills")
            if skills then
                for _, btn in ipairs(skills:GetChildren()) do
                    if btn:IsA("GuiButton") and btn:GetAttribute("SovereignSkillSession") ~= SCRIPT_SESSION then
                        btn:SetAttribute("SovereignSkillSession", SCRIPT_SESSION)
                        local key = btn.Name
                        if table.find(SKILL_KEYS, key) then
                            btn.Activated:Connect(function()
                                setCurrentSkillKey(key)
                            end)
                        end
                    end
                end
            end
        end)
    end
    task.spawn(function()
        while isCurrentSession() do
            hookMobileSkillButtons()
            task.wait(2)
        end
    end)
    local soruUntil = 0
    local function beginSoruAim()
        if isCurrentSession() and FeatureStates["AimbotSoru"] then soruUntil = os.clock()+0.45 end
    end
    local function querySoruPart()
        if not FeatureStates["AimbotSoru"] then return nil end

        local requested = os.clock() < soruUntil or UserInputService:IsKeyDown(Enum.KeyCode.R)
        if not requested and type(getcallingscript) == "function" then
            local ok, caller = pcall(getcallingscript)
            local name = ok and caller and string.lower(caller.Name) or ""
            requested = name:find("soru",1,true) ~= nil or name:find("flashstep",1,true) ~= nil
        end
        if not requested or UserInputService:GetFocusedTextBox() then return nil end
        local model
        if SelectedSoruTarget and SelectedSoruTarget ~= "Nearest" then
            local p = Players:FindFirstChild(SelectedSoruTarget)
            if p and isTargetPlayerCombatValid(p,1000) then model = p.Character end
        else model = getClosestPlayer(1000) end
        local part = model and model:FindFirstChild("HumanoidRootPart")
        if part and Spooky.AimScore(part,0) then return part,part.Position end
    end
    FeatureCallbacks["AimbotSoru"] = function() soruUntil = 0 end
    registerConnection(UserInputService.InputBegan:Connect(function(input,processed)
        if not processed and input.KeyCode == Enum.KeyCode.R then beginSoruAim() end
    end))
    local soruButtons = setmetatable({}, {__mode="k"})
    local function bindSoruButton(button)
        if not button:IsA("GuiButton") or soruButtons[button] then return end
        local name = string.lower(button.Name)
        if not name:find("soru",1,true) and not name:find("flashstep",1,true) then return end
        soruButtons[button] = true
        registerConnection(button.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then beginSoruAim() end
        end))
    end
    for _, button in ipairs(PlayerGui:GetDescendants()) do bindSoruButton(button) end
    registerConnection(PlayerGui.DescendantAdded:Connect(bindSoruButton))

    local function queryAimPart()
        if not isCurrentSession() then return nil end
        local soruPart, soruPosition = querySoruPart()
        if soruPart then return soruPart, soruPosition end
        local char = LocalPlayer.Character
        local tool = char and char:FindFirstChildOfClass("Tool")
        if not tool then return nil end
        currentHeldTool, currentHeldCategory = tool, getToolCategory(tool)
        local key = currentSkillKey or "TAP"
        if isKeyCurrentlyBlacklisted(key) then return nil end

        if currentHeldCategory == "Gun" and (key == "TAP" or key == "M1") then return nil end
        local model, position
        if getgenv().SpookyAutoBountyRunning and getgenv().targ then
            local valid, _, target = isTargetPlayerCombatValid(getgenv().targ, 1200)
            if valid then model = target end
        end
        if not model then
            if FeatureStates["AimbotPlayer2"] or FeatureStates["AimbotNpc2"] then model, position = lockedAim2Char, _G.G_SilentAimTargetPos
            elseif FeatureStates["AimbotPlayer1"] or FeatureStates["AimbotNpc1"] then model, position = lockedAim1Char, aimbot1TargetPos
            elseif FeatureStates["AimbotPlayer3"] or FeatureStates["AimbotNpc3"] then model, position = centuTargetChar, centuAimPosition
            end
        end
        if not model or not model.Parent then return nil end
        local hum = model:FindFirstChildOfClass("Humanoid")
        local part = model:FindFirstChild(Settings.camLockTargetPart or "HumanoidRootPart") or model:FindFirstChild("HumanoidRootPart")
        if not part or not hum or hum.Health <= 0 then return nil end
        local player = Players:GetPlayerFromCharacter(model)
        if player and not isTargetPlayerCombatValid(player, 1200) then return nil end
        if not getgenv().SpookyAutoBountyRunning and not Spooky.AimScore(part, 0) then return nil end
        return part, position or part.Position
    end
    local function readAimProperty(key)
        if key ~= "Hit" and key ~= "Target" and key ~= "UnitRay" then return false end
        local ok, part, position = pcall(queryAimPart)
        if not ok then Spooky.ReportIssue("Aim query", part); return false end
        if not part then return false end
        if key == "Hit" then return true, CFrame.new(position) end
        if key == "Target" then return true, part end
        local cam = workspace.CurrentCamera
        if not cam then return false end
        local direction = position - cam.CFrame.Position
        if direction.Magnitude < 0.001 then return false end
        return true, Ray.new(cam.CFrame.Position, direction.Unit)
    end

    getgenv()._SpookyActiveNamecallHandler = nil
    task.spawn(function()
        local ok, err = pcall(function()
            local env = getgenv()
            local wrap = type(newcclosure) == "function" and newcclosure or function(fn) return fn end
            env._SpookyActiveIndexHandler = nil
            if not env._SpookyOldIndex then
                local function dispatcher(object, key)
                    local handler = env._SpookyActiveIndexHandler
                    if handler then return handler(object, key) end
                    local native = env._SpookyOldIndex
                    if type(native) == "function" then return native(object, key) end
                    if type(native) == "table" then return native[key] end
                end
                if type(hookmetamethod) == "function" then
                    env._SpookyOldIndex = hookmetamethod(rawMouse, "__index", wrap(dispatcher))
                elseif type(getrawmetatable) == "function" and type(setreadonly) == "function" then
                    local mt = getrawmetatable(rawMouse)
                    env._SpookyOldIndex = mt.__index
                    setreadonly(mt, false); mt.__index = wrap(dispatcher); setreadonly(mt, true)
                else error("Mouse hook API unavailable; module adapter only") end
            end
            local native = env._SpookyOldIndex
            if type(native) ~= "function" and type(native) ~= "table" then error("Native mouse index unavailable") end
            env._SpookyActiveIndexHandler = function(object, key)
                if object == rawMouse and isCurrentSession() and not (checkcaller and checkcaller()) then
                    local changed, value = readAimProperty(key)
                    if changed then return value end
                end
                if type(native) == "function" then return native(object, key) end
                return native[key]
            end
            Spooky.Diagnostics.statuses["Mouse hook"] = "Installed; Hit/Target/UnitRay only"
        end)
        if not ok then Spooky.ReportIssue("Mouse hook", err) end
    end)
    task.spawn(function()
        local ok, err = pcall(function()
            if _G.SpookyRestoreMouseAim then _G.SpookyRestoreMouseAim() end
            local instance = ReplicatedStorage:WaitForChild("Mouse", 10)
            if not instance or not isCurrentSession() then error("Mouse module unavailable") end
            local object = require(instance)
            if type(object) ~= "table" then error("Mouse module has an unsupported interface") end
            local mt = type(getrawmetatable) == "function" and getrawmetatable(object) or getmetatable(object)
            if mt ~= nil and type(mt) ~= "table" then error("Mouse module metatable is protected") end
            if not mt then mt = {}; setmetatable(object, mt) end
            local oldIndex, oldNewIndex = mt.__index, mt.__newindex
            local values = {Hit = rawget(object, "Hit"), Target = rawget(object, "Target")}
            local stored = {Hit = values.Hit ~= nil, Target = values.Target ~= nil}
            local wasReadOnly = type(isreadonly) == "function" and isreadonly(mt) or false
            if type(setreadonly) == "function" then setreadonly(mt, false) end
            local function originalIndex(self, key)
                if stored[key] then return values[key] end
                if type(oldIndex) == "function" then return oldIndex(self, key) end
                if type(oldIndex) == "table" then return oldIndex[key] end
                return nil
            end
            local ownIndex = function(self, key)
                if isCurrentSession() and (key == "Hit" or key == "Target") then
                    local changed, value = readAimProperty(key)
                    if changed then return value end
                end
                return originalIndex(self, key)
            end
            local ownNewIndex = function(self, key, value)
                if key == "Hit" or key == "Target" then
                    values[key], stored[key] = value, true
                elseif type(oldNewIndex) == "function" then oldNewIndex(self, key, value)
                elseif type(oldNewIndex) == "table" then oldNewIndex[key] = value
                else rawset(self, key, value) end
            end
            mt.__index, mt.__newindex = ownIndex, ownNewIndex
            rawset(object, "Hit", nil); rawset(object, "Target", nil)
            _G.SpookyRestoreMouseAim = function()
                if mt.__index ~= ownIndex then return end
                if type(setreadonly) == "function" then setreadonly(mt, false) end
                mt.__index = oldIndex
                if mt.__newindex == ownNewIndex then mt.__newindex = oldNewIndex end
                rawset(object, "Hit", values.Hit); rawset(object, "Target", values.Target)
                if type(setreadonly) == "function" then setreadonly(mt, wasReadOnly) end
            end
            if type(setreadonly) == "function" then setreadonly(mt, wasReadOnly) end
            Spooky.Diagnostics.statuses["Mouse module"] = "Installed; original properties preserved"
        end)
        if not ok then Spooky.ReportIssue("Mouse module", err) end
    end)

    local LastTargetVelocities = setmetatable({}, { __mode = "k" })
    local TurnUntilTimers = setmetatable({}, { __mode = "k" })

    local function getDynamicPredictedPosition(targetPart, targetHum, myPart, customSkillKey)
        if not targetPart or not targetPart.Parent then return nil end
        local basePos = targetPart.Position
        local char = targetPart.Parent
        local hrp = (char and (char:FindFirstChild("HumanoidRootPart") or char.PrimaryPart)) or targetPart
        local vel = (hrp and hrp.AssemblyLinearVelocity) or Vector3.zero
        local horizontalSpeed = Vector3.new(vel.X, 0, vel.Z).Magnitude

        if horizontalSpeed <= 85 then
            return basePos
        end

        local myChar = LocalPlayer.Character
        local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
        local dist = (myHrp and (targetPart.Position - myHrp.Position).Magnitude) or 80
        local leadTime = math.clamp(0.06 + (dist / 1200), 0.08, 0.18)
        local clampedVel = (vel.Magnitude > 150) and (vel.Unit * 150) or vel

        local pred = targetPart.Position + (clampedVel * leadTime)
        if pred.X ~= pred.X or pred.Y ~= pred.Y or pred.Z ~= pred.Z then
            return basePos
        end
        return pred
    end
    _G.SpookyGetDynamicPredictedPosition = getDynamicPredictedPosition

    CombatCache.lastScan = 0
    local combatCleanedUp = false
    local function combatStep()
        if not isCurrentSession() then return end
        local anyCombatActive = FeatureStates["AimbotPlayer1"] or FeatureStates["AimbotNpc1"]
            or FeatureStates["AimbotPlayer2"] or FeatureStates["AimbotNpc2"]
            or FeatureStates["AimbotPlayer3"] or FeatureStates["AimbotNpc3"]
            or FeatureStates["Tracers1"] or FeatureStates["Tracers2"] or FeatureStates["Tracers3"]
            or FeatureStates["CamLock"] or _G.AimlockPlayerEnabled or _G.AimlockNpcEnabled
            or FeatureStates["AimbotSoru"]
        if not anyCombatActive then
            if combatCleanedUp then return end
            combatCleanedUp = true
            Spooky.TracerAimModel = nil
            if Spooky.HideTracers then Spooky.HideTracers() end
            if centuHighlight and centuHighlight.Enabled then centuHighlight.Enabled = false end
            aimbot1TargetPos = nil
            _G.aimbot1TargetPos = nil
            lockedAim1Char = nil
            _G.lockedAim1Char = nil
            lockedAim2Char = nil
            _G.lockedAim2Char = nil
            _G.G_SilentAimTargetPos = nil
            centuTargetChar = nil
            _G.centuTargetChar = nil
            centuAimPosition = nil
            _G.centuAimPosition = nil
            if _G.StickyCombat then
                _G.StickyCombat.player = nil
                _G.StickyCombat.playerObj = nil
                _G.StickyCombat.any = nil
                _G.StickyCombat.npc = nil
            end
            CombatCache.player = nil
            CombatCache.npc = nil
            return
        end
        local char = LocalPlayer.Character
        local myHrp = char and char:FindFirstChild("HumanoidRootPart")
        if not myHrp then
            if centuHighlight and centuHighlight.Enabled then centuHighlight.Enabled = false end
            aimbot1TargetPos = nil
            _G.aimbot1TargetPos = nil
            lockedAim1Char = nil
            _G.lockedAim1Char = nil
            lockedAim2Char = nil
            _G.lockedAim2Char = nil
            _G.G_SilentAimTargetPos = nil
            centuTargetChar = nil
            _G.centuTargetChar = nil
            centuAimPosition = nil
            _G.centuAimPosition = nil
            CombatCache.player = nil
            CombatCache.npc = nil
            return
        end
        local myPos = myHrp.Position
        if char then
            currentHeldTool = char:FindFirstChildOfClass("Tool")
            currentHeldCategory = getToolCategory(currentHeldTool)
        end
        local now = tick()
        local wantNpcScan = (FeatureStates["AimbotNpc1"] == true) or (FeatureStates["AimbotNpc2"] == true) or (FeatureStates["AimbotNpc3"] == true)
        if (now - CombatCache.lastScan > 0.10) then
            CombatCache.lastScan = now
            CombatCache.player = getClosestPlayer(1000) or false
            if wantNpcScan then
                CombatCache.npc = getClosestNPC(1000) or false
            else
                CombatCache.npc = false
            end
        else
            if CombatCache.player and (not CombatCache.player.Parent or not CombatCache.player:FindFirstChildOfClass("Humanoid") or CombatCache.player:FindFirstChildOfClass("Humanoid").Health <= 0) then
                CombatCache.player = getClosestPlayer(1000) or false
            end
            if wantNpcScan and CombatCache.npc and (not CombatCache.npc.Parent or not CombatCache.npc:FindFirstChildOfClass("Humanoid") or CombatCache.npc:FindFirstChildOfClass("Humanoid").Health <= 0) then
                CombatCache.npc = getClosestNPC(1000) or false
            end
        end
        local function getSharedPlayer()
            local model = CombatCache.player
            local player = model and Players:GetPlayerFromCharacter(model)
            return player and isTargetPlayerCombatValid(player, 1000) and model or nil
        end
        local function getSharedNPC()
            return CombatCache.npc or nil
        end

        local function resolveCombatTarget(wantPlayer, wantNpc)
            if wantPlayer and wantNpc then
                local p = getSharedPlayer()
                local n = getSharedNPC()
                if p and n then
                    local pHrp = p:FindFirstChild("HumanoidRootPart") or p.PrimaryPart
                    local nHrp = n:FindFirstChild("HumanoidRootPart") or n.PrimaryPart
                    if pHrp and nHrp then
                        local pDist = (pHrp.Position - myPos).Magnitude
                        local nDist = (nHrp.Position - myPos).Magnitude
                        return (pDist <= nDist) and p or n
                    end
                end
                return p or n
            elseif wantPlayer then
                return getSharedPlayer()
            elseif wantNpc then
                return getSharedNPC()
            end
            return nil
        end

        local target1 = resolveCombatTarget(FeatureStates["AimbotPlayer1"], FeatureStates["AimbotNpc1"])

        lockedAim1Char = target1
        _G.lockedAim1Char = target1
        if target1 then
            local r1 = target1:FindFirstChild(Settings.camLockTargetPart or "HumanoidRootPart") or target1:FindFirstChild("HumanoidRootPart") or target1.PrimaryPart
            local hum1 = target1:FindFirstChildOfClass("Humanoid")
            aimbot1TargetPos = r1 and getDynamicPredictedPosition(r1, hum1, myHrp, currentSkillKey) or (r1 and r1.Position) or nil
        else
            aimbot1TargetPos = nil
        end
        _G.aimbot1TargetPos = aimbot1TargetPos

        local target2 = resolveCombatTarget(FeatureStates["AimbotPlayer2"], FeatureStates["AimbotNpc2"])
        lockedAim2Char = target2
        _G.lockedAim2Char = target2
        if target2 then
            local r2 = (Settings.camLockTargetPart == "Head" and target2:FindFirstChild("Head")) or target2:FindFirstChild("HumanoidRootPart") or target2.PrimaryPart
            local hum2 = target2:FindFirstChildOfClass("Humanoid")
            _G.G_SilentAimTargetPos = r2 and getDynamicPredictedPosition(r2, hum2, myHrp, currentSkillKey) or (r2 and r2.Position) or nil
        else
            _G.G_SilentAimTargetPos = nil
        end

        local soruTargetPos = nil
        local soruTargetChar = nil
        if FeatureStates["AimbotSoru"] then
            local sTarget = nil
            if SelectedSoruTarget and SelectedSoruTarget ~= "Nearest" then
                local p = Players:FindFirstChild(SelectedSoruTarget)
                if p and p.Character and isTargetPlayerCombatValid(p,1000) then sTarget = p.Character end
            else
                sTarget = lockedAim1Char or lockedAim2Char or centuTargetChar
                if sTarget and not Players:GetPlayerFromCharacter(sTarget) then
                    if not FeatureStates["AimbotNpc1"] and not FeatureStates["AimbotNpc2"] and not FeatureStates["AimbotNpc3"] then
                        sTarget = nil
                    end
                end
                if not sTarget then
                    sTarget = getSharedPlayer() or getClosestPlayer(1000) or (getClosestPlayerAny and getClosestPlayerAny(1000))
                    if not sTarget and (FeatureStates["AimbotNpc1"] or FeatureStates["AimbotNpc2"] or FeatureStates["AimbotNpc3"]) then
                        sTarget = getSharedNPC()
                    end
                end
            end
            if sTarget then
                local sHrp = sTarget:FindFirstChild("HumanoidRootPart") or sTarget.PrimaryPart
                if sHrp then
                    soruTargetChar = sTarget
                    soruTargetPos = sHrp.Position
                    _G.SoruTargetPos = soruTargetPos
                end
            else
                _G.SoruTargetPos = nil
            end
        end

        local target3 = resolveCombatTarget(FeatureStates["AimbotPlayer3"], FeatureStates["AimbotNpc3"])
        centuTargetChar = target3
        _G.centuTargetChar = target3
        if target3 then
            local r3 = target3:FindFirstChild("HumanoidRootPart") or target3.PrimaryPart
            local hum3 = target3:FindFirstChildOfClass("Humanoid")
            if r3 and hum3 and hum3.Health > 0 then
                centuAimPosition = getDynamicPredictedPosition(r3, hum3, myHrp, currentSkillKey)
                _G.centuAimPosition = centuAimPosition
                centuHighlight.Adornee = target3
                if not centuHighlight.Enabled then centuHighlight.Enabled = true end
            else
                centuAimPosition = nil
                _G.centuAimPosition = nil
                if centuHighlight.Enabled then centuHighlight.Enabled = false end
            end
        else
            centuAimPosition = nil
            _G.centuAimPosition = nil
            if centuHighlight.Enabled then centuHighlight.Enabled = false end
        end

        local aimbot1Active = (FeatureStates["AimbotPlayer1"] == true) or (FeatureStates["AimbotNpc1"] == true)
        local aimbot2Active = (FeatureStates["SilentAim"] == true) or (FeatureStates["AimbotPlayer2"] == true) or (FeatureStates["AimbotNpc2"] == true)
        local aimbot3Active = (FeatureStates["AimbotPlayer3"] == true) or (FeatureStates["AimbotNpc3"] == true)
        local anyAimbotActive = aimbot1Active or aimbot2Active or aimbot3Active or FeatureStates["Tracers1"] or FeatureStates["Tracers2"] or FeatureStates["Tracers3"]

        local preview = getSharedPlayer()
        Spooky.TracerAimModel = (FeatureStates["Tracers2"] and lockedAim2Char)
            or (FeatureStates["Tracers1"] and lockedAim1Char)
            or (FeatureStates["Tracers3"] and centuTargetChar) or preview
    end
    local nextCombatRetry=0
    registerConnection(RunService.RenderStepped:Connect(function()
        if os.clock()<nextCombatRetry then return end
        local ok,err=pcall(combatStep)
        if not ok then nextCombatRetry=os.clock()+1;Spooky.ReportIssue("Combat update",err) end
    end))
end

do
    local ShootGunEvent = nil
    local Validator2 = nil
    local ShootFunction = nil
    local V_Idx = { v26 = 12, v22 = 13, v25 = 14, v21 = 15, v23 = 16, v24 = 17, v27 = 18 }
    local getupval  = debug.getupvalue or getupvalue
    local setupval  = debug.setupvalue or setupvalue
    local getupvals = debug.getupvalues or getupvalues
    local function resolveDragonRemotes()
        if ShootGunEvent and Validator2 then return true end
        pcall(function()
            local modules = ReplicatedStorage:FindFirstChild("Modules")
            local net = modules and modules:FindFirstChild("Net")
            if net then ShootGunEvent = net:FindFirstChild("RE/ShootGunEvent") end
            local remotes = ReplicatedStorage:FindFirstChild("Remotes")
            if remotes then Validator2 = remotes:FindFirstChild("Validator2") end
        end)
        return (ShootGunEvent ~= nil and Validator2 ~= nil)
    end
    local function InitDragonGun()
        pcall(function()
            local controllers = ReplicatedStorage:FindFirstChild("Controllers")
            local combat = controllers and controllers:FindFirstChild("CombatController")
            if combat then
                local res = require(combat)
                if type(res) == "table" and res.Attack and getupval then
                    ShootFunction = getupval(res.Attack, 9)
                end
            end
        end)
    end
    local function GetNextValidator()
        if not ShootFunction then InitDragonGun() end
        if not ShootFunction or not getupvals or not setupval or not getupval then return 0, 0 end
        local upvals = getupvals(ShootFunction)
        if not upvals then return 0, 0 end
        if upvals[V_Idx.v21] ~= 727595 then
            for i, v in pairs(upvals) do
                if v == 727595 then
                    local offset = i - 15
                    V_Idx.v21 = i; V_Idx.v22 = 13 + offset; V_Idx.v23 = 16 + offset
                    V_Idx.v24 = 17 + offset; V_Idx.v26 = 12 + offset; V_Idx.v25 = 14 + offset
                    V_Idx.v27 = 18 + offset
                    break
                end
            end
        end
        local v1 = getupval(ShootFunction, V_Idx.v21)
        local v2 = getupval(ShootFunction, V_Idx.v22)
        local v3 = getupval(ShootFunction, V_Idx.v23)
        local v4 = getupval(ShootFunction, V_Idx.v24)
        local v5 = getupval(ShootFunction, V_Idx.v25)
        local v6 = getupval(ShootFunction, V_Idx.v26)
        local v7 = getupval(ShootFunction, V_Idx.v27)
        for _,value in pairs({v1,v2,v3,v4,v5,v6,v7}) do
            if type(value)~="number" or value~=value or math.abs(value)==math.huge then return 0,0 end
        end
        if not (v1 and v2 and v3 and v4 and v5 and v6 and v7) or v3<=0 or v4<=0 then return 0,0 end
        local v8 = v6 * v2
        local v9 = (v5 * v2 + v6 * v1) % v3
        v9 = (v9 * v3 + v8) % v4
        v5 = math.floor(v9 / v3)
        v6 = v9 - v5 * v3
        v7 = v7 + 1
        setupval(ShootFunction, V_Idx.v25, v5)
        setupval(ShootFunction, V_Idx.v26, v6)
        setupval(ShootFunction, V_Idx.v27, v7)
        return math.floor(v9 / v4 * 16777215), v7
    end
    local function GetEntityPart(entity)
        return entity:FindFirstChild("HumanoidRootPart")
            or entity:FindFirstChild("Engine")
            or entity:FindFirstChild("Head")
            or entity:FindFirstChild("Base")
            or entity.PrimaryPart
    end
    _G.G_DragonGunM1 = false
    _G.G_AttackMobs = true
    _G.G_AttackPlayers = true
    _G.G_AttackSeaEvents = true
    _G.G_MaxDistance = 400

    local function GetClosestTarget_Dragon()
        local char = LocalPlayer.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if not root then return nil end
        local closest, dist = nil, _G.G_MaxDistance or 400
        local myPos = root.Position

        if _G.G_AttackMobs then
            local enemies = workspace:FindFirstChild("Enemies")
            if enemies then
                for _, enemy in ipairs(enemies:GetChildren()) do
                    local hum = enemy:FindFirstChildOfClass("Humanoid")
                    local r = GetEntityPart(enemy)
                    if hum and hum.Health > 0 and r then
                        local d = (r.Position - myPos).Magnitude
                        if d < dist then dist = d; closest = r end
                    end
                end
            end
        end

        if _G.G_AttackSeaEvents then
            local seaFolders = { workspace:FindFirstChild("SeaBeasts"), workspace:FindFirstChild("SeaEvents") }
            for _, folder in ipairs(seaFolders) do
                if folder then
                    for _, seaMob in ipairs(folder:GetChildren()) do
                        local hum = seaMob:FindFirstChildOfClass("Humanoid")
                        local r = GetEntityPart(seaMob)
                        if r and (not hum or hum.Health > 0) then
                            local d = (r.Position - myPos).Magnitude
                            if d < dist then dist = d; closest = r end
                        end
                    end
                end
            end
            local boatFolder = workspace:FindFirstChild("Boats")
            if boatFolder then
                for _, obj in ipairs(boatFolder:GetChildren()) do
                    local hum = obj:FindFirstChildOfClass("Humanoid")
                    local r = GetEntityPart(obj)
                    if r and (not hum or hum.Health > 0) then
                        local d = (r.Position - myPos).Magnitude
                        if d < dist then dist = d; closest = r end
                    end
                end
            end
            for _, obj in ipairs(Workspace:GetChildren()) do
                if obj:IsA("Model") and obj ~= char then
                    local name = string.lower(obj.Name)
                    if string.find(name, "ship") or string.find(name, "boat") or string.find(name, "beast") or string.find(name, "terror") or string.find(name, "piranha") or string.find(name, "leviathan") then
                        local hum = obj:FindFirstChildOfClass("Humanoid")
                        local r = GetEntityPart(obj)
                        if r and (not hum or hum.Health > 0) then
                            local d = (r.Position - myPos).Magnitude
                            if d < dist then dist = d; closest = r end
                        end
                    end
                end
            end
        end

        if _G.G_AttackPlayers then
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer and p.Character and _G.SpookyCombatTargetValid and _G.SpookyCombatTargetValid(p,1000) then
                    local hum = p.Character:FindFirstChildOfClass("Humanoid")
                    local r = p.Character:FindFirstChild("HumanoidRootPart")
                    if hum and hum.Health > 0 and r then
                        local d = (r.Position - myPos).Magnitude
                        if d < dist then dist = d; closest = r end
                    end
                end
            end
        end
        return closest
    end

    local lastGunAuraShot = 0

    registerConnection(RunService.Heartbeat:Connect(function()
        if not _G.G_DragonGunM1 and not FeatureStates["GunAura"] then return end
        local now = tick()
        if now - lastGunAuraShot < 0.15 then return end
        lastGunAuraShot = now
        pcall(function()
            if not resolveDragonRemotes() then return end
            local char = LocalPlayer.Character
            local tool = char and char:FindFirstChildOfClass("Tool")
            if tool and (tool.ToolTip == "Gun" or tool:GetAttribute("Type") == "Gun" or tool:FindFirstChild("ShootGunEvent") or string.find(string.lower(tool.Name), "gun") or string.find(string.lower(tool.Name), "rifle") or string.find(string.lower(tool.Name), "guitar") or string.find(string.lower(tool.Name), "cannon") or string.find(string.lower(tool.Name), "bazooka") or string.find(string.lower(tool.Name), "slingshot") or string.find(string.lower(tool.Name), "flintlock") or string.find(string.lower(tool.Name), "kabucha")) then
                local target = GetClosestTarget_Dragon()
                if target and target.Parent then
                    local targetModel = target:FindFirstAncestorOfClass("Model") or target.Parent
                    local hum = targetModel:FindFirstChildOfClass("Humanoid")
                    if not hum or hum.Health > 0 then
                        for burst = 1, 1 do
                            local code, count = GetNextValidator()
