    local fruitAuraGeneration = 0
    FeatureCallbacks["MagnetM1"] = function(enabled)
        fruitAuraGeneration += 1
        local generation = fruitAuraGeneration
        if not enabled then return end
        task.spawn(function()
            while isCurrentSession() and FeatureStates["MagnetM1"] and generation == fruitAuraGeneration do
                task.wait(0.15)
                if not isCurrentSession() or not FeatureStates["MagnetM1"] or generation ~= fruitAuraGeneration then return end
                local ok, err = pcall(function()
                    local char = LocalPlayer.Character
                    local root = char and char:FindFirstChild("HumanoidRootPart")
                    local tool = char and char:FindFirstChildOfClass("Tool")
                    if not root or not tool or getToolCategory(tool) ~= "Fruit" then return end
                    if char:GetAttribute("UsingSkill") or char:GetAttribute("isUsingSkill") or char:GetAttribute("Busy") then return end
                    local remote = tool:FindFirstChild("LeftClickRemote")
                    if not remote then return end
                    local closest, distance = nil, 1000
                    local function candidate(model)
                        local hum = model and model:FindFirstChildOfClass("Humanoid")
                        local part = model and model:FindFirstChild("HumanoidRootPart")
                        if not hum or hum.Health <= 0 or not part then return end
