    local dashRunning = false
    local dashInputConn = nil
    local dashChildConn = nil
    local lastDashTime = 0

    local function triggerBoostedDash()
        if not FeatureStates["DashDistance"] then return end
        if tick() - lastDashTime < 0.22 then return end
        local c = LocalPlayer.Character
        if not c then return end

        if c:GetAttribute("isUsingSkill") or c:GetAttribute("UsingSkill") or c:GetAttribute("Busy") or currentSkillKey ~= nil then
            return
        end
        lastDashTime = tick()

        local hrp = c:FindFirstChild("HumanoidRootPart")
        local hum = c:FindFirstChildOfClass("Humanoid")
        if not hrp or not hum or hum.Health <= 0 then return end

        local moveDir = hum.MoveDirection
        local dir = (moveDir.Magnitude > 0.1) and moveDir.Unit or hrp.CFrame.LookVector
        local targetDist = math.clamp(tonumber(Settings.dashDist) or 500, 100, 2500)
        local dashVelocityMagnitude = math.clamp(targetDist * 0.9, 120, 2000)

        local currentY = hrp.AssemblyLinearVelocity.Y
        hrp.AssemblyLinearVelocity = Vector3.new(dir.X * dashVelocityMagnitude, math.clamp(currentY, -5, 30), dir.Z * dashVelocityMagnitude)

        task.delay(0.18, function()
            local curChar = LocalPlayer.Character
            local curHrp = curChar and curChar:FindFirstChild("HumanoidRootPart")
            if curHrp and curHrp.Parent then
                local v = curHrp.AssemblyLinearVelocity
                curHrp.AssemblyLinearVelocity = Vector3.new(v.X * 0.15, v.Y, v.Z * 0.15)
            end
        end)
    end

    local function hookCharacterDash(c)
        if not c then return end
        if dashChildConn then dashChildConn:Disconnect(); dashChildConn = nil end
        dashChildConn = c.ChildAdded:Connect(function(child)
            if FeatureStates["DashDistance"] and (child.Name == "Dash" or child.Name == "Dashing") then
                triggerBoostedDash()
            end
        end)
    end

    local function hookMobileDashButtons()
        pcall(function()
            local pg = LocalPlayer:FindFirstChildOfClass("PlayerGui")
            if not pg then return end
            for _, gui in ipairs(pg:GetChildren()) do
                for _, desc in ipairs(gui:GetDescendants()) do
                    if (desc:IsA("ImageButton") or desc:IsA("TextButton")) and string.lower(desc.Name):find("dash") then
                        desc.MouseButton1Down:Connect(function()
                            if FeatureStates["DashDistance"] then
                                triggerBoostedDash()
                            end
                        end)
                    end
                end
            end
        end)
    end

    FeatureCallbacks["DashDistance"] = function(v)
        local char = LocalPlayer.Character
        if v then
            dashRunning = true
            hookCharacterDash(char)
            hookMobileDashButtons()
            if not dashInputConn then
                dashInputConn = UserInputService.InputBegan:Connect(function(input, gpe)
                    if gpe or not FeatureStates["DashDistance"] then return end
                    if input.KeyCode == Enum.KeyCode.Q and not UserInputService:GetFocusedTextBox() then
                        triggerBoostedDash()
                    end
                end)
            end
            task.spawn(function()
                while dashRunning and FeatureStates["DashDistance"] do
                    task.wait(0.2)
                    local c = LocalPlayer.Character
                    if c then
                        pcall(function()
                            local safeDist = math.clamp(tonumber(Settings.dashDist) or 500, 50, 2500)
                            if c:GetAttribute("DashLength") ~= safeDist then c:SetAttribute("DashLength", safeDist) end
                            if c:GetAttribute("DashLengthAir") ~= safeDist then c:SetAttribute("DashLengthAir", safeDist) end
                        end)
                    end
                end
            end)
        else
            dashRunning = false
            if dashInputConn then dashInputConn:Disconnect(); dashInputConn = nil end
            if dashChildConn then dashChildConn:Disconnect(); dashChildConn = nil end
            local freshChar = LocalPlayer.Character
            if freshChar then
                pcall(function()
                    freshChar:SetAttribute("DashLength", nil)
                    freshChar:SetAttribute("DashLengthAir", nil)
                end)
                local hrp = freshChar:FindFirstChild("HumanoidRootPart")
                if hrp then
                    hrp.AssemblyLinearVelocity = Vector3.zero
                end
            end
        end
    end
    registerConnection(LocalPlayer.CharacterAdded:Connect(function(newChar)
        if not FeatureStates["DashDistance"] then
            task.wait(0.2)
            pcall(function()
                newChar:SetAttribute("DashLength", nil)
                newChar:SetAttribute("DashLengthAir", nil)
            end)
        end
    end))
    local flyOn = false
    local flight = {parts = {}, connection = nil, humanoid = nil, takeoffUntil=0, riseUntil=0}
    local flyEpoch = 0
    local function destroyFlyEngine()
        if flight.connection then flight.connection:Disconnect(); flight.connection = nil end
        if flight.partAdded then flight.partAdded:Disconnect(); flight.partAdded = nil end
        if flight.velocity then flight.velocity:Destroy(); flight.velocity = nil end
        if flight.gyro then flight.gyro:Destroy(); flight.gyro = nil end
        for part, collision in pairs(flight.parts) do
            if part.Parent then part.CanCollide = collision end
        end
        table.clear(flight.parts)
        if flight.humanoid and flight.humanoid.Parent then
            flight.humanoid.PlatformStand = flight.platform
            flight.humanoid.AutoRotate = flight.rotate
        end
        if flight.root and flight.root.Parent then flight.root.AssemblyLinearVelocity = Vector3.zero end
        if flight.humanoid and flight.humanoid.Parent and flight.humanoid.Health > 0 then
            pcall(function() flight.humanoid:ChangeState(Enum.HumanoidStateType.GettingUp) end)
        end
        flight.root, flight.humanoid = nil, nil
        flight.takeoffUntil, flight.riseUntil = 0, 0
    end
    local function startFlyEngine()
        destroyFlyEngine()
        if not flyOn or not isCurrentSession() then return end
        local char = LocalPlayer.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not root or not hum or hum.Health <= 0 then return end
        flight.root, flight.humanoid = root, hum
        flight.platform, flight.rotate = hum.PlatformStand, hum.AutoRotate
        hum.Sit = false
        hum.PlatformStand, hum.AutoRotate = true, false
        hum:ChangeState(Enum.HumanoidStateType.Physics)
        flight.takeoffUntil = os.clock()+0.2
        root.AssemblyLinearVelocity = Vector3.new(0,12,0)
        local function trackPart(part)
            if part:IsA("BasePart") then
                if flight.parts[part] == nil then flight.parts[part] = part.CanCollide end
                part.CanCollide = false
            end
        end
        for _, part in ipairs(char:GetDescendants()) do trackPart(part) end
        flight.partAdded = char.DescendantAdded:Connect(trackPart)
        local velocity = Instance.new("BodyVelocity")
        velocity.Name = "Sovereign_FlyVelocity"
        velocity.MaxForce = Vector3.new(1e9, 1e9, 1e9)
        velocity.P = 50000
        velocity.Velocity = Vector3.new(0,12,0)
        velocity.Parent = root
        local gyro = Instance.new("BodyGyro")
        gyro.Name = "Sovereign_FlyGyro"
        gyro.MaxTorque = Vector3.new(1e9, 1e9, 1e9)
        gyro.P = 1e5
        gyro.CFrame = root.CFrame
        gyro.Parent = root
        flight.velocity, flight.gyro = velocity, gyro
        if UserInputService.TouchEnabled and not flight.controls then
            task.spawn(function()
                pcall(function()
                    local scripts = LocalPlayer:FindFirstChild("PlayerScripts")
                    local module = scripts and scripts:FindFirstChild("PlayerModule")
                    if module then flight.controls = require(module):GetControls() end
                end)
            end)
        end
        flight.connection = RunService.RenderStepped:Connect(function()
            if not flyOn or not isCurrentSession() or LocalPlayer.Character ~= char or not root.Parent or hum.Health <= 0 then
                destroyFlyEngine(); return
            end
            if not flight.velocity or not flight.velocity.Parent or not flight.gyro or not flight.gyro.Parent then
                startFlyEngine();return
            end
            hum.PlatformStand, hum.AutoRotate = true, false
            if hum:GetState() ~= Enum.HumanoidStateType.Physics then hum:ChangeState(Enum.HumanoidStateType.Physics) end
            for part in pairs(flight.parts) do if part.Parent then part.CanCollide = false else flight.parts[part] = nil end end
            local camera = workspace.CurrentCamera
            if not camera then return end
            gyro.CFrame = camera.CFrame
            local direction = Vector3.zero
            if not UserInputService:GetFocusedTextBox() then
                local cf = camera.CFrame
                if UserInputService:IsKeyDown(Enum.KeyCode.W) then direction += cf.LookVector end
                if UserInputService:IsKeyDown(Enum.KeyCode.S) then direction -= cf.LookVector end
                if UserInputService:IsKeyDown(Enum.KeyCode.D) then direction += cf.RightVector end
                if UserInputService:IsKeyDown(Enum.KeyCode.A) then direction -= cf.RightVector end
                if UserInputService.TouchEnabled and direction.Magnitude < 0.01 then
                    if flight.controls then
                        local ok, move = pcall(function() return flight.controls:GetMoveVector() end)
                        if ok and move then direction = cf:VectorToWorldSpace(move) else direction = hum.MoveDirection end
                    else direction = hum.MoveDirection end
                end
                if UserInputService:IsKeyDown(Enum.KeyCode.Space) or hum.Jump or os.clock() < flight.riseUntil then direction += Vector3.yAxis end
                if UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) or UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) then direction -= Vector3.yAxis end
            end
            local speed = Spooky.Runtime.number(Settings.flySpeed, 350, 10, 1000)
            if (flight.dashUntil or 0) > os.clock() then direction = flight.dashDirection; speed *= 1.8 end
            local desired = direction.Magnitude > 0.01 and direction.Unit * speed or Vector3.zero
            if os.clock() < flight.takeoffUntil then desired = Vector3.new(desired.X,math.max(desired.Y,12),desired.Z) end
            velocity.Velocity = desired
        end)
    end
    registerConnection(UserInputService.InputBegan:Connect(function(input, processed)
        if processed or not flyOn or UserInputService:GetFocusedTextBox() then return end
        if input.KeyCode == Enum.KeyCode.Q and workspace.CurrentCamera then
            local velocity = flight.velocity and flight.velocity.Velocity
            flight.dashDirection = velocity and velocity.Magnitude > 0.01 and velocity.Unit or workspace.CurrentCamera.CFrame.LookVector
            flight.dashUntil = os.clock() + 0.3
        end
    end))
    registerConnection(UserInputService.JumpRequest:Connect(function()
        if flyOn then flight.riseUntil = os.clock()+0.25 end
    end))
    registerConnection(LocalPlayer.CharacterRemoving:Connect(destroyFlyEngine))
    registerConnection(LocalPlayer.CharacterAdded:Connect(function(char)
        local root = char:WaitForChild("HumanoidRootPart", 10)
        if root and flyOn and char == LocalPlayer.Character and isCurrentSession() then startFlyEngine() end
    end))
