    local FLASH_NAMES = { "FlashStepRegular", "FlashStepDraco", "FlashStep", "Flashstep", "Soru" }
    local FLASH_IDS   = {
        ["17555632156"] = true,
        ["18461649274"] = true,
        ["616006778"]   = true,
        ["616010882"]   = true,
        ["5403485593"]  = true,
        ["5403491911"]  = true,
        ["313762630"]   = true,
        ["313762631"]   = true,
        ["1846164274"]  = true,
        ["1846163351"]  = true,
    }

    local function isFlashstep(track)
        if not track then return false end
        local trackName = string.lower(track.Name or "")
        for _, n in ipairs(FLASH_NAMES) do
            if string.find(trackName, string.lower(n)) then return true end
        end
        local id = track.Animation and track.Animation.AnimationId:match("%d+") or ""
        if FLASH_IDS[id] then return true end
        return false
    end

    local vim = nil
    pcall(function() vim = game:GetService("VirtualInputManager") end)

    local function pressKey(kc)
        local v = vim or game:GetService("VirtualInputManager")
        if not v or not kc then return end
        pcall(function()
            v:SendKeyEvent(true, kc, false, game)
            task.wait(0.06)
            v:SendKeyEvent(false, kc, false, game)
        end)
    end

    local lastSoruSkillTick = 0
    local function executeSkillSoru()
        if not FeatureStates["SkillSoru"] then return end
        local now = tick()
        if now - lastSoruSkillTick < 0.35 then return end
        lastSoruSkillTick = now

        task.spawn(function()
            local delayVal = tonumber(Settings.soruDelay) or 0.30
            if delayVal > 0 then task.wait(delayVal) end
            if not FeatureStates["SkillSoru"] then return end

            local slotMap = { Melee = 1, Fruit = 2, Sword = 3, Gun = 4 }
            local slotNum = slotMap[Settings.soruWeapon or "Fruit"] or 2
            local SLOT_KEYS = { [1] = Enum.KeyCode.One, [2] = Enum.KeyCode.Two, [3] = Enum.KeyCode.Three, [4] = Enum.KeyCode.Four }

            local slotKey = SLOT_KEYS[slotNum]
            if slotKey then
                pressKey(slotKey)
            end
            task.wait(0.12)
            local keyName = Settings.soruSkill or "Z"
            if Enum.KeyCode[keyName] then
                pressKey(Enum.KeyCode[keyName])
            end
        end)
    end
    _G.SpookyExecuteSkillSoru = executeSkillSoru

    local function setupAnimListener(char)
        if not char then return end
        local hum = char:WaitForChild("Humanoid", 5)
        if not hum then return end
        local animConn = hum.AnimationPlayed:Connect(function(track)
            local anim = track.Animation
            local id = anim and tostring(anim.AnimationId):match("%d+")
            local animName = string.lower(anim and anim.Name or "")
            if FeatureStates["BunnyHop"] and (string.find(animName, "dash") or string.find(animName, "flashstep") or id == "17555632156" or id == "1846164274" or id == "1846163351") then
                task.spawn(function()
                    task.wait(0.05)
                    if hum and hum.FloorMaterial ~= Enum.Material.Air then
                        hum:ChangeState(Enum.HumanoidStateType.Jumping)
                    end
                end)
            end
            if isFlashstep(track) then
                if FeatureStates["SkillSoru"] then
                    executeSkillSoru()
                end
                if FeatureStates["MacroBeta"] and Settings.macroMode == "Soru" and _G.ExecuteMacroCombo then
                    task.spawn(_G.ExecuteMacroCombo)
                end
            end
        end)
        registerConnection(animConn)
    end

    if LocalPlayer.Character then
        task.spawn(setupAnimListener, LocalPlayer.Character)
    end
    registerConnection(LocalPlayer.CharacterAdded:Connect(function(newChar)
        task.spawn(setupAnimListener, newChar)
    end))
    do
        local function isCombatAnimationTrack(t)
            if not t then return false end

            local p = t.Priority
            if p then
                if p == Enum.AnimationPriority.Action then
                    return true
                end
                local ok2, isAct2 = pcall(function() return p == Enum.AnimationPriority.Action2 end)
                if ok2 and isAct2 then return true end
                local ok3, isAct3 = pcall(function() return p == Enum.AnimationPriority.Action3 end)
                if ok3 and isAct3 then return true end
                local ok4, isAct4 = pcall(function() return p == Enum.AnimationPriority.Action4 end)
                if ok4 and isAct4 then return true end
                local pStr = tostring(p)
                if string.find(pStr, "Action") then
                    return true
                end
            end

            local tName = string.lower(t.Name or "")
            local anim = t.Animation
            local aName = string.lower(anim and anim.Name or "")
            local aId = anim and tostring(anim.AnimationId or ""):match("%d+") or ""

            if FLASH_IDS and FLASH_IDS[aId] then
                return true
            end
            if FLASH_NAMES then
                for _, fn in ipairs(FLASH_NAMES) do
                    if string.find(tName, string.lower(fn)) or string.find(aName, string.lower(fn)) then
                        return true
                    end
                end
            end

            local combatKeywords = {
                "attack", "skill", "slash", "shoot", "hit", "gun", "m1", "punch",
                "fire", "swing", "combo", "fruit", "ability", "soru", "dash",
                "cast", "release", "charge", "special", "bullet", "blade"
            }
            for _, kw in ipairs(combatKeywords) do
                if string.find(tName, kw) or string.find(aName, kw) then
                    return true
                end
            end

            return false
        end

        local function shouldStopAnimation(t)
            if not t then return false end
            if isCombatAnimationTrack(t) then
                return false
            end
            local p = t.Priority
            if p then
                if p == Enum.AnimationPriority.Core or p == Enum.AnimationPriority.Idle or p == Enum.AnimationPriority.Movement then
                    return true
                end
                local pStr = tostring(p)
                if string.find(pStr, "Core") or string.find(pStr, "Idle") or string.find(pStr, "Movement") then
                    return true
                end
            end
            local tName = string.lower(t.Name or "")
            local anim = t.Animation
            local aName = string.lower(anim and anim.Name or "")
            local moveKeywords = { "idle", "walk", "run", "jump", "fall", "climb", "swim", "sit", "toolnone" }
            for _, mk in ipairs(moveKeywords) do
                if string.find(tName, mk) or string.find(aName, mk) then
                    return true
                end
            end
            local pStr = tostring(p or "")
            if not string.find(pStr, "Action") then
                return true
            end
            return false
        end

        local noAnimTrackConn = nil
        local function stopAllActiveTracks()
            local char = LocalPlayer.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            local animator = hum and (hum:FindFirstChildOfClass("Animator") or hum)
            if animator and animator.GetPlayingAnimationTracks then
                local tracks = animator:GetPlayingAnimationTracks()
                if tracks then
                    for i = 1, #tracks do
                        pcall(function() tracks[i]:Stop(0) end)
                    end
                end
            end
        end

        FeatureCallbacks["NoAnimation"] = function(v)
            FeatureStates["NoAnimation"] = v
            if v then
                stopAllActiveTracks()
                local char = LocalPlayer.Character
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                local animator = hum and (hum:FindFirstChildOfClass("Animator") or hum)
                if animator then
                    if noAnimTrackConn then noAnimTrackConn:Disconnect() end
                    noAnimTrackConn = animator.AnimationPlayed:Connect(function(track)
                        if FeatureStates["NoAnimation"] then
                            pcall(function() track:Stop(0) end)
                        end
                    end)
                end
            else
                if noAnimTrackConn then noAnimTrackConn:Disconnect(); noAnimTrackConn = nil end
            end
        end

        local lastNoAnimTick = 0
        registerConnection(RunService.RenderStepped:Connect(function()
            if FeatureStates["NoAnimation"] then
                local now = tick()
                if now - lastNoAnimTick < 0.15 then return end
                lastNoAnimTick = now
                stopAllActiveTracks()
            end
        end))
    end
    local bigSkinBugEnabled = false
    local bigSkinBugOriginal = {}
    local bigSkinBugConnections = { CharAdded = nil }
    local function applyBigSkin(char)
        local data = bigSkinBugOriginal[char]
        if not data then return end
        for _, acc in ipairs(data.accessories or {}) do
            pcall(function()
                if acc.Handle and acc.Handle.Parent then
                    acc.Handle.Transparency = 1
                end
            end)
        end
        for _, item in ipairs(data.clothing or {}) do
            pcall(function()
                if item and item.Parent then
                    item.Parent = nil
                end
            end)
        end
        for part, saved in pairs(data.parts or {}) do
            pcall(function()
                if part and part.Parent then
                    part.Color = Color3.fromRGB(128, 128, 128)
                    part.Material = Enum.Material.SmoothPlastic
                    part.CanCollide = false
                    local nameLower = part.Name:lower()
                    if nameLower:match("torso") then
                        part.Size = Vector3.new(5.6, 4.4, 3.4)
                    elseif nameLower:match("leg") or nameLower:match("arm") then
                        part.Size = Vector3.new(2.6, 4.8, 2.6)
                    elseif nameLower == "head" then
                        part.Size = Vector3.new(2.2, 2.2, 2.2)
                        if saved.Mesh and saved.Mesh.Parent == part then
                            saved.Mesh.Parent = nil
                        end
                    end
                end
            end)
        end
        for joint, saved in pairs(data.joints or {}) do
            pcall(function()
                if joint and joint.Parent then
                    local jName = joint.Name:lower()
                    local c0 = saved.C0
                    if jName:match("rightshoulder") or jName:match("right shoulder") then
                        joint.C0 = c0 * CFrame.new(2.4, 0.6, 0)
                    elseif jName:match("leftshoulder") or jName:match("left shoulder") then
                        joint.C0 = c0 * CFrame.new(-2.4, 0.6, 0)
                    elseif jName:match("righthip") or jName:match("right hip") then
                        joint.C0 = c0 * CFrame.new(0.9, -0.6, 0)
                    elseif jName:match("lefthip") or jName:match("left hip") then
                        joint.C0 = c0 * CFrame.new(-0.9, -0.6, 0)
                    elseif jName:match("neck") then
                        joint.C0 = c0 * CFrame.new(0, 0.8, 0)
                    end
                end
            end)
        end
    end
    local function saveBigSkinOriginal(char)
        if not char then return end
        local data = { parts = {}, accessories = {}, clothing = {}, joints = {} }
        for _, item in pairs(char:GetDescendants()) do
            if item:IsA("Accessory") then
                local h = item:FindFirstChild("Handle")
                if h then
                    table.insert(data.accessories, { Handle = h, Transparency = h.Transparency })
                end
            elseif item:IsA("Clothing") or item:IsA("ShirtGraphic") or item:IsA("Decal") then
                table.insert(data.clothing, item)
            elseif item:IsA("BasePart") and item.Name ~= "HumanoidRootPart" then
                local saved = {
                    Size = item.Size,
                    Color = item.Color,
                    Material = item.Material,
                    CanCollide = item.CanCollide,
                }
                if item.Name == "Head" then
                    local mesh = item:FindFirstChildOfClass("SpecialMesh")
                    if mesh then saved.Mesh = mesh end
                end
                data.parts[item] = saved
            elseif item:IsA("Motor6D") and item.Part0 and item.Part1 then
                data.joints[item] = { C0 = item.C0, C1 = item.C1 }
            end
        end
        bigSkinBugOriginal[char] = data
    end
    local function restoreBigSkin(char)
        local data = bigSkinBugOriginal[char]
        if not data then return end
        for _, acc in ipairs(data.accessories or {}) do
            pcall(function()
                if acc.Handle and acc.Handle.Parent then
                    acc.Handle.Transparency = acc.Transparency or 0
                end
            end)
        end
        for _, item in ipairs(data.clothing or {}) do
            pcall(function()
                item.Parent = char
            end)
        end
        for part, saved in pairs(data.parts or {}) do
            pcall(function()
                if part and part.Parent then
                    part.Size = saved.Size
                    part.Color = saved.Color
                    part.Material = saved.Material
                    part.CanCollide = (saved.CanCollide ~= nil) and saved.CanCollide or true
                    if saved.Mesh and saved.Mesh.Parent ~= part then
                        saved.Mesh.Parent = part
                    end
                end
            end)
        end
        for joint, saved in pairs(data.joints or {}) do
            pcall(function()
                if joint and joint.Parent then
                    joint.C0 = saved.C0
                    joint.C1 = saved.C1
                end
            end)
        end
        bigSkinBugOriginal[char] = nil
    end
    local function onCharAddedBigSkin(char)
        if not bigSkinBugEnabled then return end
        task.wait(0.4)
        saveBigSkinOriginal(char)
        applyBigSkin(char)
    end

    FeatureCallbacks["LowTextures"] = function(v)
        pcall(function()
            workspace.Terrain.Decoration = not v
            Lighting.GlobalShadows = not v
        end)
        notifyToggle("Low Textures: " .. (v and "ENABLED" or "DISABLED"), v)
    end
    FeatureCallbacks["NoShadows"] = function(v)
        pcall(function()
            Lighting.GlobalShadows = not v
        end)
        notifyToggle("No Shadows: " .. (v and "ENABLED" or "DISABLED"), v)
    end
    FeatureCallbacks["Fullbright"] = function(v)
        pcall(function()
            Lighting.Brightness = v and 2 or 1
            Lighting.Ambient = v and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(128, 128, 128)
        end)
        notifyToggle("Fullbright: " .. (v and "ENABLED" or "DISABLED"), v)
    end
    FeatureCallbacks["NoFog"] = function(v)
        pcall(function()
            Lighting.FogEnd = v and 9e9 or 1000
        end)
        notifyToggle("No Fog: " .. (v and "ENABLED" or "DISABLED"), v)
    end

    FeatureCallbacks["BigSkinBug"] = function(v)
        bigSkinBugEnabled = v
        if v then
            if LocalPlayer.Character then
                saveBigSkinOriginal(LocalPlayer.Character)
                applyBigSkin(LocalPlayer.Character)
            end
            if bigSkinBugConnections.CharAdded then bigSkinBugConnections.CharAdded:Disconnect() end
            bigSkinBugConnections.CharAdded = LocalPlayer.CharacterAdded:Connect(onCharAddedBigSkin)
        else
            if bigSkinBugConnections.CharAdded then
                bigSkinBugConnections.CharAdded:Disconnect()
                bigSkinBugConnections.CharAdded = nil
            end
            if LocalPlayer.Character then
                restoreBigSkin(LocalPlayer.Character)
            end
        end
    end
    local fflag1OriginalShadows = Lighting.GlobalShadows
    local fflag1OriginalFog = Lighting.FogEnd
    local SPOOKY_FFLAGS = {
        { "DFIntTaskSchedulerTargetFps", "240" },
        { "FFlagDisablePostFx", "True" },
        { "FIntFRMMaxGrassDistance", "0" },
        { "FIntFRMMinGrassDistance", "0" },
        { "DebugFRMQualityLevelOverride", "1" },
        { "TextureQualityOverride", "0" },
    }

    local function applyFastFlagsList(flagList, onProgress, shouldContinue)
        local setter = setfflag or set_fflag
        if type(flagList) ~= "table" then return 0, 0 end
        if type(setter) ~= "function" then return 0, #flagList end
        local accepted, failed = 0, 0
        for i, pair in ipairs(flagList) do
            if shouldContinue and not shouldContinue() then break end
            local ok, result = pcall(setter, pair[1], tostring(pair[2]))
            if ok and result ~= false then accepted += 1 else failed += 1 end
            if onProgress then pcall(onProgress, i, #flagList) end
            if i % 4 == 0 then task.wait() end
        end
        return accepted, failed
    end
    _G.SpookyApplyFastFlagsList = applyFastFlagsList
    _G.SpookyFFlags = SPOOKY_FFLAGS
    _G.SpookyFullFlags = SPOOKY_FFLAGS

    local flagPreset = {generation=0, originals={}}
    FeatureCallbacks["FFlag1"] = function(enabled)
        flagPreset.generation += 1
        local generation = flagPreset.generation
        if enabled then
            if flagPreset.active then return end
            flagPreset.active = true
            fflag1OriginalShadows, fflag1OriginalFog = Lighting.GlobalShadows, Lighting.FogEnd
            pcall(function() flagPreset.quality = settings().Rendering.QualityLevel end)
            if type(getfpscap) == "function" then
                local ok, fps = pcall(getfpscap)
                if ok then flagPreset.fps = fps end
            end
            local getter = getfflag or get_fflag
            flagPreset.unrestorable = type(getter) ~= "function"
            flagPreset.originals = {}
            for _, pair in ipairs(SPOOKY_FFLAGS) do
                if type(getter) == "function" then
                    local ok, value = pcall(getter, pair[1])
                    if ok and value ~= nil then flagPreset.originals[pair[1]] = value
                    else flagPreset.unrestorable = true end
                end
            end
            Lighting.GlobalShadows, Lighting.FogEnd = false, 9e9
            pcall(function() settings().Rendering.QualityLevel = Enum.QualityLevel.Level01 end)
            if type(setfpscap) == "function" then pcall(setfpscap, 240) end
            task.spawn(function()
                local accepted, failed = applyFastFlagsList(SPOOKY_FFLAGS, nil, function()
                    return isCurrentSession() and flagPreset.active and flagPreset.generation == generation
                end)
                if flagPreset.generation == generation and flagPreset.active then
                    notifyToggle("FFlags accepted: " .. accepted .. " | Failed: " .. failed, accepted > 0)
                end
            end)
        elseif flagPreset.active then
            flagPreset.active = false
            Lighting.GlobalShadows, Lighting.FogEnd = fflag1OriginalShadows, fflag1OriginalFog
            pcall(function() if flagPreset.quality ~= nil then settings().Rendering.QualityLevel = flagPreset.quality end end)
            if flagPreset.fps ~= nil and type(setfpscap) == "function" then pcall(setfpscap, flagPreset.fps) end
            local setter = setfflag or set_fflag
            if type(setter) == "function" then
                for name, value in pairs(flagPreset.originals) do
                    local ok, result = pcall(setter, name, tostring(value))
                    if not ok or result == false then flagPreset.unrestorable = true end
                end
            end
            notifyToggle(flagPreset.unrestorable and "Visuals restored; restart Roblox to reset unreadable FFlags" or "FPS preset restored", false)
        end
    end

    local noGfxActive = false
    local noGfxQuality = nil
    local noGfxConnections = {}
    local noGfxModifiedObjects = {}
    local originalTerrainProps = nil
    local originalLightingProps = nil

    local function restoreNoGfx()
        noGfxActive = false
        if noGfxQuality ~= nil then
            pcall(function() settings().Rendering.QualityLevel = noGfxQuality end)
            noGfxQuality = nil
        end
        for obj, data in pairs(noGfxModifiedObjects) do
            pcall(function()
                if not obj or not obj.Parent then return end
                if data.Enabled ~= nil then obj.Enabled = data.Enabled end
                if data.Texture ~= nil then obj.Texture = data.Texture end
                if data.Rate ~= nil then obj.Rate = data.Rate end
                if data.Material ~= nil then obj.Material = data.Material end
                if data.Transparency ~= nil then obj.Transparency = data.Transparency end
            end)
        end
        noGfxModifiedObjects = {}

        if originalTerrainProps then
            pcall(function()
                local t = workspace.Terrain
                t.WaterWaveSize = originalTerrainProps.WaterWaveSize
                t.WaterWaveSpeed = originalTerrainProps.WaterWaveSpeed
                t.WaterReflectance = originalTerrainProps.WaterReflectance
                t.WaterTransparency = originalTerrainProps.WaterTransparency
                t.Decoration = originalTerrainProps.Decoration
            end)
            originalTerrainProps = nil
        end

        if originalLightingProps then
            pcall(function()
                Lighting.GlobalShadows = originalLightingProps.GlobalShadows
                Lighting.FogEnd = originalLightingProps.FogEnd
            end)
            originalLightingProps = nil
        end

        for k, conn in pairs(noGfxConnections) do
            pcall(function() conn:Disconnect() end)
        end
        noGfxConnections = {}
    end

    local function processNoGfxObject(inst)
        if not noGfxActive or not isCurrentSession() or not inst then return end
        local cName = inst.ClassName
        if cName == "ParticleEmitter" then
            if not noGfxModifiedObjects[inst] then
                noGfxModifiedObjects[inst] = { Enabled = inst.Enabled, Rate = inst.Rate }
            end
            inst.Enabled = false
            inst.Rate = 0
        elseif cName == "Beam" or cName == "Trail" or cName == "Fire" or cName == "Smoke" or cName == "Sparkles" then
            if not noGfxModifiedObjects[inst] then
                noGfxModifiedObjects[inst] = { Enabled = inst.Enabled }
            end
            inst.Enabled = false
        elseif cName == "PointLight" or cName == "SpotLight" or cName == "SurfaceLight" then
            if not noGfxModifiedObjects[inst] then
                noGfxModifiedObjects[inst] = { Enabled = inst.Enabled }
            end
            inst.Enabled = false
        elseif cName == "Highlight" and inst.Name ~= "CentuDox_TargetHighlight" and not string.find(inst.Name, "ESP") and not string.find(inst.Name, "Sovereign") then
            if not noGfxModifiedObjects[inst] then
                noGfxModifiedObjects[inst] = { Enabled = inst.Enabled }
            end
            inst.Enabled = false
        elseif (cName == "Decal" or cName == "Texture") and inst.Parent and not inst.Parent:IsDescendantOf(LocalPlayer.Character) then
            if not noGfxModifiedObjects[inst] then
                noGfxModifiedObjects[inst] = { Texture = inst.Texture }
            end
            inst.Texture = ""
        elseif cName == "WrapLayer" then
            if not noGfxModifiedObjects[inst] then noGfxModifiedObjects[inst] = {Enabled=inst.Enabled} end
            inst.Enabled = false
        end

    end

    local function processWorldOriginChild(child)
        if not child then return end
        pcall(function()
            for _, desc in ipairs(child:GetDescendants()) do
                processNoGfxObject(desc)
            end
            table.insert(noGfxConnections, child.DescendantAdded:Connect(processNoGfxObject))
        end)
    end

    local function stripV4Auras(char)
        if not noGfxActive or not isCurrentSession() or not char then return end
        for _, item in ipairs(char:GetDescendants()) do
            pcall(processNoGfxObject, item)
            local name = string.lower(item.Name)
            if item:IsA("BasePart") and (name == "aura" or name == "raceaura" or name == "auravisuals" or name == "terroraura") then
                if not noGfxModifiedObjects[item] then noGfxModifiedObjects[item] = {Transparency=item.Transparency} end
                item.Transparency = 1
            end
        end
    end

    local function startNoGfxV2()
        restoreNoGfx()
        noGfxActive = true

        pcall(function()
            local t = workspace.Terrain
            originalTerrainProps = {
                WaterWaveSize = t.WaterWaveSize,
                WaterWaveSpeed = t.WaterWaveSpeed,
                WaterReflectance = t.WaterReflectance,
                WaterTransparency = t.WaterTransparency,
                Decoration = t.Decoration
            }
            t.WaterWaveSize = 0
            t.WaterWaveSpeed = 0
            t.WaterReflectance = 0
            t.WaterTransparency = 0
            t.Decoration = false
        end)

        pcall(function()
            originalLightingProps = {
                GlobalShadows = Lighting.GlobalShadows,
                FogEnd = Lighting.FogEnd
            }
            Lighting.GlobalShadows = false
            Lighting.FogEnd = 9e9
            for _, v in ipairs(Lighting:GetChildren()) do
                if v:IsA("PostProcessEffect") or v:IsA("Atmosphere") or v:IsA("Clouds") or v:IsA("BloomEffect") or v:IsA("SunRaysEffect") or v:IsA("DepthOfFieldEffect") then
                    pcall(function()
                        if not noGfxModifiedObjects[v] then noGfxModifiedObjects[v] = {Enabled=v.Enabled} end
                        v.Enabled = false
                    end)
                end
            end
        end)

        pcall(function()
            noGfxQuality = settings().Rendering.QualityLevel
            settings().Rendering.QualityLevel = Enum.QualityLevel.Level01
        end)

        pcall(function()
            local wo = workspace:FindFirstChild("_WorldOrigin")
            if wo then
                for _, ch in ipairs(wo:GetChildren()) do
                    processWorldOriginChild(ch)
                end
                noGfxConnections.WorldOriginChildAdded = wo.ChildAdded:Connect(processWorldOriginChild)
            end
        end)

        pcall(function()
            for _, plr in ipairs(Players:GetPlayers()) do
                if plr.Character then stripV4Auras(plr.Character) end
                table.insert(noGfxConnections, plr.CharacterAdded:Connect(stripV4Auras))
            end
            noGfxConnections.PlayerCharAdded = Players.PlayerAdded:Connect(function(plr)
                table.insert(noGfxConnections, plr.CharacterAdded:Connect(function(ch)
                    task.wait(0.5)
                    stripV4Auras(ch)
                end))
            end)
        end)

    end

    FeatureCallbacks["FFlag2"] = function(v)
        if v then startNoGfxV2() else restoreNoGfx() end
        notifyToggle("Ultra Potato: " .. (v and "ENABLED" or "DISABLED"), v)
    end
end
do
    local MATCHA_COLOR = Color3.fromRGB(155, 225, 80)
    local FRUIT_COLOR  = Color3.fromRGB(210, 45, 45)
    local GOLD_COLOR   = Color3.fromRGB(255, 200, 40)
    local bespokeESPStore = {}
    local matchaESPStore  = {}
    local npcESPStore     = {}
    local fruitESPStore   = {}
    local activeESPTags   = {}
    local playerCache     = {}
    local function getMyRoot()
        local c = LocalPlayer.Character
        return c and (c:FindFirstChild("HumanoidRootPart") or c:FindFirstChild("Head") or c.PrimaryPart)
    end
    local function removeDrawingObj(obj)
        if not obj then return end
        pcall(function() obj.Visible = false end)
        pcall(function()
            if obj.Remove then
                obj:Remove()
            elseif obj.Destroy then
                obj:Destroy()
            end
        end)
    end
    local function createDrawingLine()
        if not Drawing or not Drawing.new then return nil end
        local ok, line = pcall(function()
            local l = Drawing.new("Line")
            l.Visible = false
            l.Color = MATCHA_COLOR
            l.Thickness = 3.5
            l.Transparency = 1
            return l
        end)
        return ok and line or nil
    end
    local function createDrawingSquare()
        if not Drawing or not Drawing.new then return nil end
        local ok, sq = pcall(function()
            local s = Drawing.new("Square")
            s.Visible = false
            s.Color = MATCHA_COLOR
            s.Thickness = 2.8
            s.Filled = false
            s.Transparency = 1
            return s
        end)
        return ok and sq or nil
    end
    local function getTeamInfo(targetP)
        if not targetP or not targetP.Team then
            return "Neutral", Color3.fromRGB(220, 220, 220)
        end
        if targetP.Team.Name == "Marines" then
            return "Marines", Color3.fromRGB(0, 170, 255)
        else
            return "Pirates", Color3.fromRGB(255, 70, 70)
        end
    end
    local function getPlayerData(targetP)
        if not playerCache[targetP] then
            playerCache[targetP] = {
                level = "?",
                fruit = "None",
                bounty = 0,
                team = "Neutral",
                color = Color3.fromRGB(220, 220, 220),
                lastUpdate = 0
            }
        end
        local data = playerCache[targetP]
        local now = os.clock()
        if now - data.lastUpdate > 3 or data.level == "?" or data.fruit == "None" then
            pcall(function()
                local tName, tCol = getTeamInfo(targetP)
                data.team = tName
                data.color = tCol
                local d = targetP:FindFirstChild("Data")
                if d then
                    local lvl = d:FindFirstChild("Level")
                    if lvl and lvl.Value then data.level = tostring(lvl.Value) end
                    local fr = d:FindFirstChild("DevilFruit")
                    if fr and fr.Value then data.fruit = tostring(fr.Value) end
                end
                local ls = targetP:FindFirstChild("leaderstats")
                if ls then
                    local b = ls:FindFirstChild("Bounty/Honor") or ls:FindFirstChild("Bounty") or ls:FindFirstChild("Honor")
                    if b and b.Value then data.bounty = b.Value end
                    if data.level == "?" then
                        local l = ls:FindFirstChild("Level") or ls:FindFirstChild("Lvl")
                        if l and l.Value then data.level = tostring(l.Value) end
                    end
                end
                data.lastUpdate = now
            end)
        end
        return data
    end
    local function cleanPlayerBespokeESP(p)
        if p and bespokeESPStore[p] then
            local data = bespokeESPStore[p]
            if data.bb then pcall(function() data.bb:Destroy() end) end
            if data.hl then pcall(function() data.hl:Destroy() end) end
            bespokeESPStore[p] = nil
        end
    end
    local function cleanMatchaESP(p)
        if p and matchaESPStore[p] then
            local data = matchaESPStore[p]
            if data.square then removeDrawingObj(data.square) end
            if data.lines then
                for _, l in ipairs(data.lines) do
                    removeDrawingObj(l)
                end
            end
            if data.sBox then pcall(function() data.sBox:Destroy() end) end
            if data.hl then pcall(function() data.hl:Destroy() end) end
            matchaESPStore[p] = nil
        end
    end
    local function cleanNPCESP(npc)
        if npc and npcESPStore[npc] then
            local data = npcESPStore[npc]
            if data.bb then
                activeESPTags[data.bb] = nil
                pcall(function() data.bb:Destroy() end)
            end
            if data.hl then
                activeESPTags[data.hl] = nil
                pcall(function() data.hl:Destroy() end)
            end
            npcESPStore[npc] = nil
        end
    end
    local function cleanFruitESP(fruit)
        if fruit and fruitESPStore[fruit] then
            local data = fruitESPStore[fruit]
            if data.bb then
                activeESPTags[data.bb] = nil
                pcall(function() data.bb:Destroy() end)
            end
            if data.hl then
                activeESPTags[data.hl] = nil
                pcall(function() data.hl:Destroy() end)
            end
            fruitESPStore[fruit] = nil
        end
    end
    local function cleanAllESPs()
    _G.cleanAllESPs = cleanAllESPs
        _G.Spooky_CleanAllESPs = cleanAllESPs
        for p, _ in pairs(bespokeESPStore) do cleanPlayerBespokeESP(p) end
        bespokeESPStore = {}
        for p, _ in pairs(matchaESPStore) do cleanMatchaESP(p) end
        matchaESPStore = {}
        for npc, _ in pairs(npcESPStore) do cleanNPCESP(npc) end
        npcESPStore = {}
        for fr, _ in pairs(fruitESPStore) do cleanFruitESP(fr) end
        fruitESPStore = {}
        pcall(function()
            for _, p in ipairs(Players:GetPlayers()) do
                if p.Character then
                    local o1 = p.Character:FindFirstChild("SacredESP_Billboard", true)
                    if o1 then o1:Destroy() end
                    local o2 = p.Character:FindFirstChild("SacredESP_Highlight", true)
                    if o2 then o2:Destroy() end
                    local o3 = p.Character:FindFirstChild("PlayerESP", true)
                    if o3 then o3:Destroy() end
                    local o4 = p.Character:FindFirstChild("PlayerESP_Highlight", true)
                    if o4 then o4:Destroy() end
                    local o5 = p.Character:FindFirstChild("Matcha_3DBox", true)
                    if o5 then o5:Destroy() end
                    local o6 = p.Character:FindFirstChild("Matcha_3DSelectionBox", true)
                    if o6 then o6:Destroy() end
                end
            end
            for tag, _ in pairs(activeESPTags) do
                pcall(function()
                    if tag and tag.Parent then
                        tag:Destroy()
                    end
                end)
                activeESPTags[tag] = nil
            end
        end)
    end
    local function applyAvatarThumb(bb, player)
        if not bb or not player then return end
        local thumb = bb:FindFirstChild("AvatarThumb")
        local isSimple = (_G.G_ESP_SimpleMode == true or (FeatureStates and FeatureStates["SimpleEsp"] == true))
        if isSimple then
            if thumb then thumb.Visible = false end
            return
        end
        if _G.G_ESP_AvatarPhoto ~= false then
            if not thumb then
                thumb = Instance.new("ImageLabel", bb)
                thumb.Name = "AvatarThumb"
                thumb.Size = UDim2.new(0, 32, 0, 32)
                thumb.Position = UDim2.new(0, -36, 0, 2)
                thumb.BackgroundColor3 = Color3.fromRGB(15, 15, 25)
                thumb.BackgroundTransparency = 0.2
                Instance.new("UICorner", thumb).CornerRadius = UDim.new(1, 0)
                local tStk = Instance.new("UIStroke", thumb)
                tStk.Color = Color3.fromRGB(240, 240, 255)
                tStk.Thickness = 1.2
                task.spawn(function()
                    pcall(function()
                        local content = Players:GetUserThumbnailAsync(player.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size48x48)
                        if content and thumb and thumb.Parent then
                            thumb.Image = content
                        end
                    end)
                end)
            end
            thumb.Visible = true
        elseif thumb then
            thumb.Visible = false
        end
    end

    local function buildESPText(player, hum, hrp, pData, myPos)
        local isSimple = (_G.G_ESP_SimpleMode == true or (FeatureStates and FeatureStates["SimpleEsp"] == true))
        if isSimple then
            local maxH = math.max(hum.MaxHealth, 1)
            local curH = math.clamp(hum.Health, 0, maxH)
            local hpPct = math.floor((curH / maxH) * 100)
            local nameStr = player.DisplayName or player.Name
            local hpStr = "HP: " .. tostring(math.floor(curH)) .. "/" .. tostring(math.floor(maxH)) .. " (" .. tostring(hpPct) .. "%)"
            return "[" .. nameStr .. "]\n" .. hpStr
        end
        local dist = math.floor((myPos - hrp.Position).Magnitude)
        local hpPct = math.floor((hum.Health / math.max(hum.MaxHealth, 1)) * 100)
        local bM = type(pData.bounty) == "number" and math.floor(pData.bounty / 1000000) or 0
        local isPvpDisabled = (player:GetAttribute("PvpDisabled") == true)
        local parts = {}
        if _G.G_ESP_Name ~= false then
            local warnTag = (type(pData.bounty) == "number" and pData.bounty > 10000000) and "[!] " or ""
            parts[#parts+1] = warnTag .. "[" .. pData.team .. "] <font color=\"rgb(255,255,0)\">" .. (player.DisplayName or player.Name) .. "</font>"
        end
        if _G.G_ESP_Level ~= false then
            parts[#parts+1] = " [Lv." .. tostring(pData.level) .. "]"
        end
        if _G.G_ESP_PvP ~= false or _G.G_ESP_Bounty ~= false then
            parts[#parts+1] = "\n"
            if _G.G_ESP_PvP ~= false then
                if isPvpDisabled then
                    parts[#parts+1] = "<font color=\"rgb(0,255,0)\">[SAFE] PvP Off</font>"
                else
                    parts[#parts+1] = "[PVP] PvP On"
                end
            end
            if _G.G_ESP_Bounty ~= false then
                if _G.G_ESP_PvP ~= false then parts[#parts+1] = " | " end
                parts[#parts+1] = "Bounty: " .. tostring(bM) .. "M"
            end
        end
        if _G.G_ESP_Fruit ~= false then
            parts[#parts+1] = "\nFruit: " .. tostring(pData.fruit)
        end
        local hpStr = ""
        local fmt = _G.G_ESP_HP_Format or "Numbers"
        if _G.G_ESP_HP ~= false then
            if fmt == "Numbers" then
                hpStr = "HP: " .. math.floor(hum.Health) .. " / " .. math.floor(hum.MaxHealth)
            elseif fmt == "Percentage" then
                hpStr = "HP: " .. tostring(hpPct) .. "%"
            else
                hpStr = "HP: " .. math.floor(hum.Health) .. "/" .. math.floor(hum.MaxHealth) .. " (" .. tostring(hpPct) .. "%)"
            end
        end
        local distStr = ""
        if _G.G_ESP_Distance ~= false then
            if _G.G_ESP_DistanceUnit == "Studs" then
                distStr = tostring(dist) .. " studs"
            else
                distStr = tostring(dist) .. "m"
            end
        end
        if distStr ~= "" or hpStr ~= "" then
            parts[#parts+1] = "\n" .. distStr .. ((distStr ~= "" and hpStr ~= "") and " | " or "") .. hpStr
        end
        return table.concat(parts)
    end

    local function setupGeneralESP(player)
        if player == LocalPlayer or not FeatureStates["GeneralEsp"] then return end
        local char = player.Character
        if not char then return end
        local hrp = char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Head") or char.PrimaryPart
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not hrp or not hum then return end
        if bespokeESPStore[player] and bespokeESPStore[player].style == "General" and bespokeESPStore[player].bb and bespokeESPStore[player].bb.Parent then
            return
        end
        cleanPlayerBespokeESP(player)
        local pData = getPlayerData(player)
        local teamCol = _G.G_ESP_Color or pData.color
        local bb = Instance.new("BillboardGui")
        bb.Name = "SacredESP_Billboard"
        bb.Adornee = hrp
        local isSimple = (_G.G_ESP_SimpleMode or (FeatureStates and FeatureStates["SimpleEsp"])) == true
        bb.Size = isSimple and UDim2.new(0, 140, 0, 32) or UDim2.new(0, 220, 0, 75)
        local offX = _G.G_ESP_TagOffsetX or 0
        local offY = _G.G_ESP_TagOffsetY or 0
        bb.StudsOffset = Vector3.new(offX, 3.2 + offY, 0)
        bb.AlwaysOnTop = true
        bb.MaxDistance = 100000
        bb.Parent = hrp
        local lbl = Instance.new("TextLabel", bb)
        lbl.Name = "TextLabel"
        lbl.Size = UDim2.new(1, 0, 1, 0)
        lbl.BackgroundTransparency = 1
        lbl.Font = _G.G_ESP_Font or Enum.Font.GothamBold
        lbl.TextSize = _G.G_ESP_TextSize or 11.5
        lbl.RichText = true
        lbl.TextStrokeTransparency = 0
        lbl.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
        lbl.TextColor3 = teamCol
        lbl.TextYAlignment = Enum.TextYAlignment.Top
        local myRoot = getMyRoot()
        local myPos = myRoot and myRoot.Position or Vector3.zero
        lbl.Text = buildESPText(player, hum, hrp, pData, myPos)
        applyAvatarThumb(bb, player)
        local hl = nil
        if _G.G_ESP_Chams ~= false then
            pcall(function()
                hl = Instance.new("Highlight")
                hl.Name = "SacredESP_Highlight"
                hl.Adornee = char
                hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
                hl.FillColor = teamCol
                hl.FillTransparency = 0.5
                hl.OutlineColor = teamCol
                hl.OutlineTransparency = 0
                local dist = math.floor((myPos - hrp.Position).Magnitude)
                hl.Enabled = (dist <= 150)
                hl.Parent = char
            end)
        end
        bespokeESPStore[player] = {
            bb = bb,
            lbl = lbl,
            hl = hl,
            player = player,
            char = char,
            style = "General"
        }
    end
    local function setupPlayerESP(player)
        if player == LocalPlayer or not (FeatureStates["PlayerEsp"] or FeatureStates["RainbowEsp"] or FeatureStates["SimpleEsp"] or _G.G_ESP_SimpleMode) then return end
        local char = player.Character
