        cleanPlayerBespokeESP(player)
        local pData = getPlayerData(player)
        local teamCol = (player.Team == LocalPlayer.Team) and Color3.fromRGB(0, 255, 0) or (_G.G_ESP_Color or pData.color)
        local bb = Instance.new("BillboardGui")
        bb.Name = "PlayerESP"
        bb.Adornee = hrp
        local isSimple = (_G.G_ESP_SimpleMode == true or (FeatureStates and FeatureStates["SimpleEsp"] == true))
        bb.Size = isSimple and UDim2.new(0, 140, 0, 32) or UDim2.new(0, 180, 0, 36)
        local offX = _G.G_ESP_TagOffsetX or 0
        local offY = _G.G_ESP_TagOffsetY or 0
        bb.StudsOffset = Vector3.new(offX, 2.8 + offY, 0)
        bb.AlwaysOnTop = true
        bb.MaxDistance = 100000
        bb.Parent = hrp
        local lbl = Instance.new("TextLabel", bb)
        lbl.Name = "TextLabel"
        lbl.Size = UDim2.new(1, 0, 1, 0)
        lbl.BackgroundTransparency = 1
        lbl.Font = _G.G_ESP_Font or Enum.Font.GothamBold
        lbl.TextSize = _G.G_ESP_TextSize or 11.5
        lbl.RichText = true
        lbl.TextStrokeTransparency = 0
        lbl.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
        lbl.TextColor3 = teamCol
        local myRoot = getMyRoot()
        local myPos = myRoot and myRoot.Position or Vector3.zero
        lbl.Text = buildESPText(player, hum, hrp, pData, myPos)
        applyAvatarThumb(bb, player)
        local hl = nil
        if _G.G_ESP_Chams ~= false then
            pcall(function()
                hl = Instance.new("Highlight")
                hl.Name = "PlayerESP_Highlight"
                hl.Adornee = char
                hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
                hl.FillColor = teamCol
                hl.FillTransparency = 0.65
                hl.OutlineColor = teamCol
                hl.OutlineTransparency = 0.2
                local dist = math.floor((myPos - hrp.Position).Magnitude)
                hl.Enabled = (dist <= 150)
                hl.Parent = char
            end)
        end
        bespokeESPStore[player] = {
            bb = bb,
            lbl = lbl,
            hl = hl,
            player = player,
            char = char,
            style = "Player"
        }
    end
    local function setupNpcESP(npcModel)
        if not FeatureStates["NpcEsp"] then return end
        if not npcModel or not npcModel.Parent then return end
        local hrp = npcModel:FindFirstChild("HumanoidRootPart") or npcModel:FindFirstChild("Head") or npcModel.PrimaryPart
        local hum = npcModel:FindFirstChildOfClass("Humanoid")
        if not hrp or not hum or hum.Health <= 0 then return end
        if npcESPStore[npcModel] and npcESPStore[npcModel].bb and npcESPStore[npcModel].bb.Parent then
            return
        end
        cleanNPCESP(npcModel)
        local bb = Instance.new("BillboardGui")
        bb.Name = "NPCESP_Tag"
        bb.Adornee = hrp
        bb.Size = UDim2.new(0, 160, 0, 28)
        bb.StudsOffset = Vector3.new(0, 3, 0)
        bb.AlwaysOnTop = true
        bb.MaxDistance = 100000
        bb.Parent = hrp
        activeESPTags[bb] = true
        local lbl = Instance.new("TextLabel", bb)
        lbl.Name = "TextLabel"
        lbl.Size = UDim2.new(1, 0, 1, 0)
        lbl.BackgroundTransparency = 1
        lbl.Font = Enum.Font.GothamBold
        lbl.TextSize = 11.5
        lbl.TextColor3 = GOLD_COLOR
        lbl.TextStrokeTransparency = 0.2
        lbl.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
        local myRoot = getMyRoot()
        local myPos = myRoot and myRoot.Position or Vector3.zero
        local dist = math.floor((myPos - hrp.Position).Magnitude)
        local hpPct = math.floor((hum.Health / math.max(hum.MaxHealth, 1)) * 100)
        lbl.Text = string.format("NPC: %s [%dm] %d%%", npcModel.Name, dist, hpPct)
        local hl = nil
        pcall(function()
            hl = Instance.new("Highlight")
            hl.Name = "NPCESP_Highlight"
            hl.Adornee = npcModel
            hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
            hl.FillColor = GOLD_COLOR
            hl.FillTransparency = 0.75
            hl.OutlineColor = GOLD_COLOR
            hl.OutlineTransparency = 0.2
            hl.Enabled = (dist <= 150)
            hl.Parent = npcModel
            activeESPTags[hl] = true
        end)
        npcESPStore[npcModel] = {
            bb = bb,
            lbl = lbl,
            hl = hl,
            char = npcModel
        }
    end
    local function scanAndSetupAllNPCs()
        if not FeatureStates["NpcEsp"] then return end
        pcall(function()
            local enemies = workspace:FindFirstChild("Enemies")
            if enemies then
                for _, npc in ipairs(enemies:GetChildren()) do
                    if npc:FindFirstChild("HumanoidRootPart") or npc:FindFirstChild("Head") or npc.PrimaryPart then
                        setupNpcESP(npc)
                    end
                end
            end
            local npcs = workspace:FindFirstChild("NPCs")
            if npcs then
                for _, npc in ipairs(npcs:GetChildren()) do
                    if npc:FindFirstChild("HumanoidRootPart") or npc:FindFirstChild("Head") or npc.PrimaryPart then
                        setupNpcESP(npc)
                    end
                end
            end
            local chars = workspace:FindFirstChild("Characters")
            if chars then
                for _, npc in ipairs(chars:GetChildren()) do
                    if npc ~= LocalPlayer.Character and not Players:GetPlayerFromCharacter(npc) then
                        setupNpcESP(npc)
                    end
                end
            end
            for _, obj in ipairs(workspace:GetChildren()) do
                if obj:IsA("Model") and obj ~= LocalPlayer.Character and not Players:GetPlayerFromCharacter(obj) then
                    local hum = obj:FindFirstChildOfClass("Humanoid")
                    if hum and hum.Health > 0 and (obj:FindFirstChild("HumanoidRootPart") or obj:FindFirstChild("Head") or obj.PrimaryPart) then
                        setupNpcESP(obj)
                    end
                end
            end
        end)
    end
    local function updateFruitESP()
        if not FeatureStates["FruitEsp"] then
            for fr, _ in pairs(fruitESPStore) do cleanFruitESP(fr) end
            fruitESPStore = {}
            return
        end
        local myPos = getMyRoot() and getMyRoot().Position or Vector3.zero
        for _, obj in ipairs(workspace:GetChildren()) do
            pcall(function()
                if (obj:IsA("Tool") or obj:IsA("Model")) and string.find(obj.Name, "Fruit") and (not LocalPlayer.Character or obj.Parent ~= LocalPlayer.Character) then
                    local basePart = obj:FindFirstChild("Handle") or obj.PrimaryPart or obj:FindFirstChildWhichIsA("BasePart")
                    if basePart and not fruitESPStore[obj] then
                        local old = obj:FindFirstChild("FruitESP", true)
                        if old then
                            activeESPTags[old] = nil
                            old:Destroy()
                        end
                        local bb = Instance.new("BillboardGui")
                        bb.Name = "FruitESP"
                        bb.Adornee = basePart
                        bb.Size = UDim2.new(0, 220, 0, 32)
                        bb.StudsOffset = Vector3.new(0, 1.5, 0)
                        bb.AlwaysOnTop = true
                        bb.MaxDistance = 100000
                        bb.Parent = basePart
                        activeESPTags[bb] = true
                        local lbl = Instance.new("TextLabel", bb)
                        lbl.Name = "Label"
                        lbl.Size = UDim2.new(1, 0, 1, 0)
                        lbl.BackgroundTransparency = 1
                        lbl.Font = Enum.Font.GothamBold
                        lbl.TextSize = 12
                        lbl.TextColor3 = FRUIT_COLOR
                        lbl.TextStrokeTransparency = 0.2
                        lbl.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
                        local dist = math.floor((myPos - basePart.Position).Magnitude)
                        lbl.Text = string.format("Fruit | %s | < %d >", obj.Name, dist)
                        local hl = nil
                        pcall(function()
                            hl = Instance.new("Highlight")
                            hl.Name = "FruitESP_Highlight"
                            hl.Adornee = obj
                            hl.FillColor = FRUIT_COLOR
                            hl.FillTransparency = 0.6
                            hl.OutlineColor = Color3.fromRGB(255, 255, 255)
                            hl.OutlineTransparency = 0.2
                            hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
                            hl.Parent = obj
                            activeESPTags[hl] = true
                        end)
                        fruitESPStore[obj] = { bb = bb, lbl = lbl, hl = hl, part = basePart, model = obj }
                    end
                end
            end)
        end
    end
    local function setupMatchaESP(player)
        if player == LocalPlayer or not FeatureStates["EspMatcha"] then return end
        local char = player.Character
        if not char then return end
        local hrp = char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Head") or char.PrimaryPart
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not hrp or not hum then return end
        if matchaESPStore[player] then return end
        local sq = createDrawingSquare()
        local lines = {}
        if Drawing and Drawing.new then
            for _ = 1, 14 do
                local l = createDrawingLine()
                if l then table.insert(lines, l) end
            end
        end
        local sBox = nil
        pcall(function()
            sBox = Instance.new("SelectionBox")
            sBox.Name = "Matcha_3DSelectionBox"
            sBox.Adornee = char
            sBox.Color3 = MATCHA_COLOR
            sBox.LineThickness = 0.05
            sBox.SurfaceColor3 = MATCHA_COLOR
            sBox.SurfaceTransparency = 0.88
            sBox.Parent = char
        end)
        local hl = nil
        pcall(function()
            hl = Instance.new("Highlight")
            hl.Name = "Matcha_3DBox"
            hl.Adornee = char
            hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
            hl.FillColor = MATCHA_COLOR
            hl.FillTransparency = 0.85
            hl.OutlineColor = MATCHA_COLOR
            hl.OutlineTransparency = 0
            hl.Parent = char
        end)
        matchaESPStore[player] = {
            square = sq,
            lines = lines,
            sBox = sBox,
            hl = hl,
            player = player,
            char = char,
            hum = hum,
            hrp = hrp
        }
    end
    local function drawBone(line, partA, partB, cam, col)
        if not line then return end
        if not partA or not partB or not partA.Parent or not partB.Parent then
            if line.Visible then line.Visible = false end
            return
        end
        local pA, onA = cam:WorldToViewportPoint(partA.Position)
        local pB, onB = cam:WorldToViewportPoint(partB.Position)
        if (onA or onB) and pA.Z > 0 and pB.Z > 0 then
            line.From = Vector2.new(pA.X, pA.Y)
            line.To = Vector2.new(pB.X, pB.Y)
            line.Color = col
            line.Thickness = 3.5
            if not line.Visible then line.Visible = true end
        else
            if line.Visible then line.Visible = false end
        end
    end
    local function drawBox(square, char, cam, col)
        if not square or not char or not char.Parent then
            if square and square.Visible then square.Visible = false end
            return
        end
        local hrp = char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Head") or char.PrimaryPart
        if not hrp then
            if square.Visible then square.Visible = false end
            return
        end
        local cf = hrp.CFrame
        local sz = Vector3.new(4, 5.5, 2.5)
        local camPos = cam.CFrame.Position
        local dir = (cf.Position - camPos)
        if cam.CFrame.LookVector:Dot(dir) <= 0 then
            if square.Visible then square.Visible = false end
            return
        end
        local topWorld = cf.Position + Vector3.new(0, sz.Y * 0.58, 0)
        local btmWorld = cf.Position - Vector3.new(0, sz.Y * 0.58, 0)
        local pTop, onTop = cam:WorldToViewportPoint(topWorld)
        local pBtm, onBtm = cam:WorldToViewportPoint(btmWorld)
        if (onTop or onBtm) and pTop.Z > 0 and pBtm.Z > 0 then
            local boxH = math.abs(pBtm.Y - pTop.Y)
            local boxW = boxH * 0.68
            if boxH > 4 and boxW > 3 then
                local midX = (pTop.X + pBtm.X) * 0.5
                local minY = math.min(pTop.Y, pBtm.Y)
                square.Size = Vector2.new(boxW, boxH)
                square.Position = Vector2.new(midX - boxW * 0.5, minY)
                square.Color = col
                square.Thickness = 2.8
                if not square.Visible then square.Visible = true end
                return
            end
        end
        if square.Visible then square.Visible = false end
    end
    local function rebuildESPs()
        local isGen     = FeatureStates["GeneralEsp"]
        local isPlayer  = FeatureStates["PlayerEsp"]
        local isMatcha  = FeatureStates["EspMatcha"]
        local isNpc     = FeatureStates["NpcEsp"]
        local isFruit   = FeatureStates["FruitEsp"]
        local isRainbow = FeatureStates["RainbowEsp"]
        local isSimple  = (_G.G_ESP_SimpleMode == true or (FeatureStates and FeatureStates["SimpleEsp"] == true))
        for p, _ in pairs(bespokeESPStore) do
            cleanPlayerBespokeESP(p)
        end
        bespokeESPStore = {}
        if isGen or isPlayer or isRainbow or isSimple then
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer and p.Character then
                    if isGen then
                        setupGeneralESP(p)
                    else
                        setupPlayerESP(p)
                    end
                end
            end
        end
        if isMatcha then
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer and p.Character then
                    setupMatchaESP(p)
                end
            end
        else
            for p, _ in pairs(matchaESPStore) do
                cleanMatchaESP(p)
            end
            matchaESPStore = {}
        end
        if isNpc then
            scanAndSetupAllNPCs()
        else
            for npc, _ in pairs(npcESPStore) do
                cleanNPCESP(npc)
            end
            npcESPStore = {}
        end
        if isFruit then
            updateFruitESP()
        else
            for fr, _ in pairs(fruitESPStore) do
                cleanFruitESP(fr)
            end
            fruitESPStore = {}
        end
    end
    _G.RebuildSpookyESPs = rebuildESPs
    local lastEspTextUpdate = 0
    local rainbowHue = 0
    RunService.RenderStepped:Connect(function(dt)
        local anyActive = FeatureStates["GeneralEsp"] or FeatureStates["PlayerEsp"] or FeatureStates["NpcEsp"]
            or FeatureStates["FruitEsp"] or FeatureStates["RainbowEsp"] or FeatureStates["EspMatcha"]
            or FeatureStates["SimpleEsp"] or _G.G_ESP_SimpleMode
        if not anyActive then return end
        rainbowHue = (rainbowHue + dt * 0.4) % 1
        local curRainbow = Color3.fromHSV(rainbowHue, 1, 1)
        local cam = workspace.CurrentCamera
        local myRoot = getMyRoot()
        local myPos = myRoot and myRoot.Position or Vector3.zero
        local now = tick()
        local doTextUpdate = false
        if now - lastEspTextUpdate >= 0.1 then
            doTextUpdate = true
            lastEspTextUpdate = now
        end
        if doTextUpdate then
            for p, data in pairs(bespokeESPStore) do
                pcall(function()
                    if p.Parent and data.char and data.char.Parent and data.lbl and data.bb and data.bb.Parent then
                        local hrp = data.char:FindFirstChild("HumanoidRootPart") or data.char:FindFirstChild("Head")
                        local hum = data.char:FindFirstChildOfClass("Humanoid")
                        if hrp and hum and hum.Health > 0 then
                            local pData = getPlayerData(p)
                            local col = FeatureStates["RainbowEsp"] and curRainbow or pData.color
                            local finalCol = _G.G_ESP_Color or col
                            local isSimple = (_G.G_ESP_SimpleMode == true or (FeatureStates and FeatureStates["SimpleEsp"] == true))
                            data.lbl.Text = buildESPText(p, hum, hrp, pData, myPos)
                            data.lbl.TextColor3 = finalCol
                            data.lbl.Font = _G.G_ESP_Font or data.lbl.Font
                            data.lbl.TextSize = isSimple and 10.5 or (_G.G_ESP_TextSize or data.lbl.TextSize)
                            local targetSize = isSimple and UDim2.new(0, 140, 0, 32) or (data.style == "Player" and UDim2.new(0, 180, 0, 36) or UDim2.new(0, 220, 0, 75))
                            if data.bb.Size ~= targetSize then
                                data.bb.Size = targetSize
                            end
                            local offX = _G.G_ESP_TagOffsetX or 0
                            local offY = _G.G_ESP_TagOffsetY or 0
                            data.bb.StudsOffset = Vector3.new(offX, (data.style == "Player" and 2.8 or 3.2) + offY, 0)
                            applyAvatarThumb(data.bb, p)
                            if data.hl then
                                data.hl.FillColor = finalCol
                                data.hl.OutlineColor = finalCol
                                local dist = math.floor((myPos - hrp.Position).Magnitude)
                                data.hl.Enabled = (_G.G_ESP_Chams ~= false) and (dist <= 150)
                            end
                        else
                            cleanPlayerBespokeESP(p)
                        end
                    else
                        cleanPlayerBespokeESP(p)
                    end
                end)
            end
        end
        if FeatureStates["EspMatcha"] and cam then
            local vp = cam.ViewportSize
            local vpMargin = 80
            for p, data in pairs(matchaESPStore) do
                pcall(function()
                    if p.Parent and data.char and data.char.Parent and data.hum and data.hum.Parent and data.hum.Health > 0 then
                        local char = data.char
                        local hum = data.hum
                        local hrp = data.hrp
                        if not hrp or not hrp.Parent then
                            hrp = char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Head") or char.PrimaryPart
                            data.hrp = hrp
                        end

                        if not hrp then
                            if data.square and data.square.Visible then data.square.Visible = false end
                            if data.lines then
                                for _, l in ipairs(data.lines) do
                                    if l and l.Visible then l.Visible = false end
                                end
                            end
                            return
                        end

                        local rootPos = hrp.Position
                        local dist = (myPos - rootPos).Magnitude

                        if dist > 350 then
                            if data.square and data.square.Visible then data.square.Visible = false end
                            if data.lines then
                                for _, l in ipairs(data.lines) do
                                    if l and l.Visible then l.Visible = false end
                                end
                            end
                            return
                        end

                        local rootScreen, onScreen = cam:WorldToViewportPoint(rootPos)
                        local isVisible = onScreen or (rootScreen.Z > 0
                            and rootScreen.X >= -vpMargin and rootScreen.X <= vp.X + vpMargin
                            and rootScreen.Y >= -vpMargin and rootScreen.Y <= vp.Y + vpMargin)

                        if not isVisible then
                            if data.square and data.square.Visible then data.square.Visible = false end
                            if data.lines then
                                for _, l in ipairs(data.lines) do
                                    if l and l.Visible then l.Visible = false end
                                end
                            end
                            return
                        end

                        if data.square then
                            drawBox(data.square, char, cam, MATCHA_COLOR)
                        end
                        if data.lines and #data.lines > 0 then
                            local lines = data.lines
                            local parts = data.bodyParts
                            if not parts or parts.char ~= char or not parts.head or not parts.head.Parent then
                                parts = { char = char, isR15 = (hum.RigType == Enum.HumanoidRigType.R15) }
                                if parts.isR15 then
                                    parts.head = char:FindFirstChild("Head")
                                    parts.uTorso = char:FindFirstChild("UpperTorso")
                                    parts.lTorso = char:FindFirstChild("LowerTorso")
                                    parts.lArm = char:FindFirstChild("LeftUpperArm")
                                    parts.lElbow = char:FindFirstChild("LeftLowerArm")
                                    parts.lHand = char:FindFirstChild("LeftHand")
                                    parts.rArm = char:FindFirstChild("RightUpperArm")
                                    parts.rElbow = char:FindFirstChild("RightLowerArm")
                                    parts.rHand = char:FindFirstChild("RightHand")
                                    parts.lLeg = char:FindFirstChild("LeftUpperLeg")
                                    parts.lKnee = char:FindFirstChild("LeftLowerLeg")
                                    parts.lFoot = char:FindFirstChild("LeftFoot")
                                    parts.rLeg = char:FindFirstChild("RightUpperLeg")
                                    parts.rKnee = char:FindFirstChild("RightLowerLeg")
                                    parts.rFoot = char:FindFirstChild("RightFoot")
                                else
                                    parts.head = char:FindFirstChild("Head")
                                    parts.torso = char:FindFirstChild("Torso")
                                    parts.lArm = char:FindFirstChild("Left Arm")
                                    parts.rArm = char:FindFirstChild("Right Arm")
                                    parts.lLeg = char:FindFirstChild("Left Leg")
                                    parts.rLeg = char:FindFirstChild("Right Leg")
                                end
                                data.bodyParts = parts
                            end

                            if parts.head then
                                if parts.isR15 then
                                    drawBone(lines[1], parts.head, parts.uTorso, cam, MATCHA_COLOR)
                                    drawBone(lines[2], parts.uTorso, parts.lTorso, cam, MATCHA_COLOR)
                                    drawBone(lines[3], parts.uTorso, parts.lArm, cam, MATCHA_COLOR)
                                    drawBone(lines[4], parts.lArm, parts.lElbow, cam, MATCHA_COLOR)
                                    drawBone(lines[5], parts.lElbow, parts.lHand, cam, MATCHA_COLOR)
                                    drawBone(lines[6], parts.uTorso, parts.rArm, cam, MATCHA_COLOR)
                                    drawBone(lines[7], parts.rArm, parts.rElbow, cam, MATCHA_COLOR)
                                    drawBone(lines[8], parts.rElbow, parts.rHand, cam, MATCHA_COLOR)
                                    drawBone(lines[9], parts.lTorso, parts.lLeg, cam, MATCHA_COLOR)
                                    drawBone(lines[10], parts.lLeg, parts.lKnee, cam, MATCHA_COLOR)
                                    drawBone(lines[11], parts.lKnee, parts.lFoot, cam, MATCHA_COLOR)
                                    drawBone(lines[12], parts.lTorso, parts.rLeg, cam, MATCHA_COLOR)
                                    drawBone(lines[13], parts.rLeg, parts.rKnee, cam, MATCHA_COLOR)
                                    drawBone(lines[14], parts.rKnee, parts.rFoot, cam, MATCHA_COLOR)
                                else
                                    drawBone(lines[1], parts.head, parts.torso, cam, MATCHA_COLOR)
                                    drawBone(lines[2], parts.torso, parts.lArm, cam, MATCHA_COLOR)
                                    drawBone(lines[3], parts.torso, parts.rArm, cam, MATCHA_COLOR)
                                    drawBone(lines[4], parts.torso, parts.lLeg, cam, MATCHA_COLOR)
                                    drawBone(lines[5], parts.torso, parts.rLeg, cam, MATCHA_COLOR)
                                    for i = 6, 14 do
                                        if lines[i] and lines[i].Visible then lines[i].Visible = false end
                                    end
                                end
                            else
                                for _, l in ipairs(lines) do
                                    if l and l.Visible then l.Visible = false end
                                end
                            end
                        end
                    else
                        cleanMatchaESP(p)
                    end
                end)
            end
        end
        if FeatureStates["NpcEsp"] and doTextUpdate then
            for npc, data in pairs(npcESPStore) do
                pcall(function()
                    if npc.Parent and data.char and data.char.Parent and data.lbl and data.bb and data.bb.Parent then
                        local hrp = data.char:FindFirstChild("HumanoidRootPart") or data.char:FindFirstChild("Head") or data.char.PrimaryPart
                        local hum = data.char:FindFirstChildOfClass("Humanoid")
                        if hrp and hum and hum.Health > 0 then
                            local dist = math.floor((myPos - hrp.Position).Magnitude)
                            local hpPct = math.floor((hum.Health / math.max(hum.MaxHealth, 1)) * 100)
                            data.lbl.Text = string.format("NPC: %s [%dm] %d%%", data.char.Name, dist, hpPct)
                            if data.hl then
                                data.hl.Enabled = (dist <= 150)
                            end
                        else
                            cleanNPCESP(npc)
                        end
                    else
                        cleanNPCESP(npc)
                    end
                end)
            end
        end
        if FeatureStates["FruitEsp"] and doTextUpdate then
            for fr, data in pairs(fruitESPStore) do
                pcall(function()
                    if fr.Parent and data.lbl and data.part and data.part.Parent then
                        local dist = math.floor((myPos - data.part.Position).Magnitude)
                        data.lbl.Text = string.format("Fruit | %s | < %d >", fr.Name, dist)
                    else
                        cleanFruitESP(fr)
                    end
                end)
            end
        end
    end)
    local function setupPlayerListeners(p)
        if p == LocalPlayer then return end
        pcall(function()
            if p.CharacterAdded and p.CharacterAdded.Connect then
                p.CharacterAdded:Connect(function(char)
                    task.wait(0.3)
                    if not char.Parent then return end
                    local isGen     = FeatureStates["GeneralEsp"]
                    local isPlayer  = FeatureStates["PlayerEsp"]
                    local isRainbow = FeatureStates["RainbowEsp"]
                    local isMatcha  = FeatureStates["EspMatcha"]
                    local isSimple  = (_G.G_ESP_SimpleMode == true or (FeatureStates and FeatureStates["SimpleEsp"] == true))
                    if isGen then
                        setupGeneralESP(p)
                    elseif isPlayer or isRainbow or isSimple then
                        setupPlayerESP(p)
                    end
                    if isMatcha then
                        setupMatchaESP(p)
                    end
                end)
            end
        end)
    end
    for _, p in ipairs(Players:GetPlayers()) do
        setupPlayerListeners(p)
    end
    pcall(function()
        if Players.PlayerAdded and Players.PlayerAdded.Connect then
            Players.PlayerAdded:Connect(setupPlayerListeners)
        end
        if Players.PlayerRemoving and Players.PlayerRemoving.Connect then
            Players.PlayerRemoving:Connect(function(p)
                cleanPlayerBespokeESP(p)
                cleanMatchaESP(p)
            end)
        end
    end)
    local function hookNpcFolder(folder)
        if not folder then return end
        pcall(function()
            folder.ChildAdded:Connect(function(child)
                if FeatureStates["NpcEsp"] then
                    task.wait(0.05)
                    if child:IsA("Model") and (child:FindFirstChild("HumanoidRootPart") or child:FindFirstChild("Head") or child.PrimaryPart) then
                        setupNpcESP(child)
                    end
                end
            end)
        end)
    end
    local enemiesFolder = workspace:FindFirstChild("Enemies")
    if enemiesFolder then hookNpcFolder(enemiesFolder) end
    local npcsFolder = workspace:FindFirstChild("NPCs")
    if npcsFolder then hookNpcFolder(npcsFolder) end
    workspace.ChildAdded:Connect(function(item)
        if item.Name == "Enemies" or item.Name == "NPCs" then
            hookNpcFolder(item)
            return
        end
        if FeatureStates["FruitEsp"] and (item:IsA("Tool") or item:IsA("Model")) and string.find(item.Name, "Fruit") then
            task.spawn(function()
                task.wait(0.1)
                if FeatureStates["FruitEsp"] then updateFruitESP() end
            end)
        end
        if FeatureStates["NpcEsp"] and item:IsA("Model") and not Players:GetPlayerFromCharacter(item) then
            task.spawn(function()
                task.wait(0.05)
                if FeatureStates["NpcEsp"] and item:FindFirstChildOfClass("Humanoid") then
                    setupNpcESP(item)
                end
            end)
        end
    end)
    task.spawn(function()
        while isCurrentSession() do
            task.wait(2.5)
            local anyActive = FeatureStates["GeneralEsp"] or FeatureStates["PlayerEsp"] or FeatureStates["NpcEsp"]
                or FeatureStates["FruitEsp"] or FeatureStates["RainbowEsp"] or FeatureStates["EspMatcha"]
                or FeatureStates["SimpleEsp"] or _G.G_ESP_SimpleMode
            if anyActive then
                rebuildESPs()
            end
        end
    end)
    for _, espN in ipairs({"GeneralEsp", "PlayerEsp", "NpcEsp", "FruitEsp", "RainbowEsp", "EspMatcha", "SimpleEsp"}) do
        FeatureCallbacks[espN] = rebuildESPs
    end
    FeatureCallbacks["SimpleEsp"] = function(v)
        FeatureStates["SimpleEsp"] = v
        _G.G_ESP_SimpleMode = v
        rebuildESPs()
        notifyToggle((CurrentLang == "ES") and ("ESP Simple: " .. (v and "ON" or "OFF")) or ("Simple ESP: " .. (v and "ON" or "OFF")), v)
    end
end
do
    FeatureCallbacks["Headless"] = function(v)
        local char = LocalPlayer.Character
        if not char then return end
        local head = char:FindFirstChild("Head")
        if head then
            head.Transparency = v and 1 or 0
            local face = head:FindFirstChild("face")
            if face then face.Transparency = v and 1 or 0 end
        end
        for _, item in ipairs(char:GetChildren()) do
            if item:IsA("Accessory") then
                local handle = item:FindFirstChild("Handle")
                if handle then
                    local att = handle:FindFirstChildOfClass("Attachment")
                    local attName = att and att.Name or ""
                    local isHeadItem = attName:find("Hat") or attName:find("Hair") or attName:find("Face") or attName:find("Head") or item.AccessoryType == Enum.AccessoryType.Hair or item.AccessoryType == Enum.AccessoryType.Hat or item.AccessoryType == Enum.AccessoryType.Face
                    if isHeadItem then
                        handle.Transparency = v and 1 or 0
                        for _, d in ipairs(handle:GetDescendants()) do
                            if d:IsA("BasePart") or d:IsA("Decal") then d.Transparency = v and 1 or 0 end
                        end
                    end
                end
            end
        end
    end
    local korbloxMeshes = {}
    FeatureCallbacks["Korblox"] = function(v)
        local char = LocalPlayer.Character
        if not char then return end
        local rl  = char:FindFirstChild("RightUpperLeg")
        local rl2 = char:FindFirstChild("RightLowerLeg")
        local rf  = char:FindFirstChild("RightFoot")
        if v then
            if rl then
