    local activeSky = nil
    local rainbowSkyThread = nil
    local origLightingProps = nil
    local origAtmosphereProps = nil
    local activeRainbowSky = nil
    local activeRainbowAtmosphere = nil

    local function enforceSkybox()
        if not FeatureStates["Skybox"] then return end
        if FeatureStates["RainbowSkybox"] then return end
        local sb = SKYBOXES[Settings.skyIdx]
        if sb and sb.bk then
            if not activeSky or activeSky.Parent ~= Lighting then
                if activeSky then activeSky:Destroy() end
                activeSky = Instance.new("Sky", Lighting)
                activeSky.Name = "Sovereign_Skybox"
                activeSky.SkyboxBk = sb.bk
                activeSky.SkyboxDn = sb.dn
                activeSky.SkyboxFt = sb.ft
                activeSky.SkyboxLf = sb.lf
                activeSky.SkyboxRt = sb.rt
                activeSky.SkyboxUp = sb.up
            end
        end
    end

    local function stopRainbowSky()
        if rainbowSkyThread then
            pcall(function() task.cancel(rainbowSkyThread) end)
            rainbowSkyThread = nil
        end
        if activeRainbowSky then
            pcall(function() activeRainbowSky:Destroy() end)
            activeRainbowSky = nil
        end
        if activeRainbowAtmosphere then
            pcall(function() activeRainbowAtmosphere:Destroy() end)
            activeRainbowAtmosphere = nil
        end
        if origLightingProps then
            pcall(function()
                Lighting.Ambient = origLightingProps.Ambient
                Lighting.OutdoorAmbient = origLightingProps.OutdoorAmbient
                Lighting.ColorShift_Top = origLightingProps.ColorShift_Top
                Lighting.ColorShift_Bottom = origLightingProps.ColorShift_Bottom
            end)
            origLightingProps = nil
        end
        local atmo = Lighting:FindFirstChildOfClass("Atmosphere")
        if atmo and origAtmosphereProps then
            pcall(function()
                atmo.Color = origAtmosphereProps.Color
                atmo.Decay = origAtmosphereProps.Decay
            end)
            origAtmosphereProps = nil
        end
        if FeatureStates["Skybox"] then
            enforceSkybox()
        end
    end

    local function startRainbowSky()
        stopRainbowSky()
        origLightingProps = {
            Ambient = Lighting.Ambient,
            OutdoorAmbient = Lighting.OutdoorAmbient,
            ColorShift_Top = Lighting.ColorShift_Top,
            ColorShift_Bottom = Lighting.ColorShift_Bottom
        }
        local existingAtmo = Lighting:FindFirstChildOfClass("Atmosphere")
        if existingAtmo then
            origAtmosphereProps = {
                Color = existingAtmo.Color,
                Decay = existingAtmo.Decay
            }
        end

        if activeSky then
            pcall(function() activeSky:Destroy() end)
            activeSky = nil
        end

        activeRainbowSky = Instance.new("Sky")
        activeRainbowSky.Name = "Sovereign_RainbowSky"
        activeRainbowSky.CelestialBodiesShown = true
        activeRainbowSky.SkyboxBk = "rbxassetid://16876541778"
        activeRainbowSky.SkyboxDn = "rbxassetid://16876543880"
        activeRainbowSky.SkyboxFt = "rbxassetid://16876546384"
        activeRainbowSky.SkyboxLf = "rbxassetid://16876548320"
        activeRainbowSky.SkyboxRt = "rbxassetid://16876550345"
        activeRainbowSky.SkyboxUp = "rbxassetid://16876552681"
        activeRainbowSky.Parent = Lighting

        local atmo = existingAtmo
        if not atmo then
            atmo = Instance.new("Atmosphere", Lighting)
            atmo.Name = "Sovereign_RainbowAtmosphere"
            activeRainbowAtmosphere = atmo
        end

        rainbowSkyThread = task.spawn(function()
            local hue = 0
            while FeatureStates["RainbowSkybox"] and isCurrentSession() do
                hue = (hue + 0.006) % 1
                local rainbowColor = Color3.fromHSV(hue, 0.75, 1)
                local ambientColor = Color3.fromHSV(hue, 0.45, 0.9)
                local decayColor = Color3.fromHSV(hue, 0.85, 0.5)

                pcall(function()
                    Lighting.Ambient = ambientColor
                    Lighting.OutdoorAmbient = rainbowColor
                    Lighting.ColorShift_Top = rainbowColor
                    if atmo and atmo.Parent then
                        atmo.Color = rainbowColor
                        atmo.Decay = decayColor
                    end
                end)
                task.wait(0.06)
            end
        end)
    end

