    local noObjectsOn = false
    local noObjLoopConn = nil
    local function hideEquippedWeapons()
        local char = LocalPlayer.Character
        if not char then return end
        for _, child in ipairs(char:GetChildren()) do
            if child:IsA("Tool") or child:IsA("Model") or child:IsA("Accessory") then
                local name = string.lower(child.Name)
                if child:IsA("Tool") or name:find("sword") or name:find("blade") or name:find("guitar") or name:find("gun") or name:find("weapon") or name:find("melee") then
                    for _, part in ipairs(child:GetDescendants()) do
                        if part:IsA("BasePart") then
                            part.LocalTransparencyModifier = 1
                            part.Transparency = 1
                        elseif part:IsA("Decal") or part:IsA("Texture") then
                            part.Transparency = 1
                        elseif part:IsA("ParticleEmitter") or part:IsA("Beam") or part:IsA("Trail") then
                            part.Enabled = false
                        end
                    end
                end
            end
        end
    end
    local function restoreEquippedWeapons()
        local char = LocalPlayer.Character
        if not char then return end
        for _, child in ipairs(char:GetChildren()) do
            if child:IsA("Tool") or child:IsA("Model") or child:IsA("Accessory") then
                for _, part in ipairs(child:GetDescendants()) do
                    if part:IsA("BasePart") then
                        part.LocalTransparencyModifier = 0
                        part.Transparency = 0
                    elseif part:IsA("Decal") or part:IsA("Texture") then
                        part.Transparency = 0
                    elseif part:IsA("ParticleEmitter") or part:IsA("Beam") or part:IsA("Trail") then
                        part.Enabled = true
                    end
                end
            end
        end
    end
    FeatureCallbacks["NoObject"] = function(v)
        noObjectsOn = v
        if noObjLoopConn then noObjLoopConn:Disconnect(); noObjLoopConn = nil end
        if v then
            noObjLoopConn = RunService.RenderStepped:Connect(function()
                if not noObjectsOn then return end
                hideEquippedWeapons()
            end)
        else
            restoreEquippedWeapons()
        end
    end
    local function isFruitObject(obj)
        if not obj or not obj.Parent then return false end
        local name = string.lower(obj.Name)
        if name:find("fruit") or name:find("fruta") then return true end
        if obj:FindFirstChild("Fruit") or obj:FindFirstChild("FruitName") or obj:FindFirstChild("EatRemote") or obj:GetAttribute("Fruit") then return true end
        if (obj:IsA("Tool") or obj:IsA("Model")) and name:find("-") then
            if obj:FindFirstChild("Handle") or obj:FindFirstChildOfClass("MeshPart") or obj:FindFirstChildOfClass("SpecialMesh", true) then
                return true
            end
        end
        return false
    end
    local function applyScaleToFruit(fruit, targetScale)
        if not fruit or not fruit.Parent then return end
        pcall(function()
            if fruit:IsA("Model") then
                if not fruit:GetAttribute("SovereignOrigScale") then
                    fruit:SetAttribute("SovereignOrigScale", fruit:GetScale() or 1)
                end
                local orig = fruit:GetAttribute("SovereignOrigScale") or 1
                fruit:ScaleTo(orig * targetScale)
            end
            for _, part in ipairs(fruit:GetDescendants()) do
                if part:IsA("BasePart") then
                    part.CanCollide = false
                    part.Massless = true
                    if not fruit:IsA("Model") and part.Name == "Handle" then
                        if not part:GetAttribute("OrigPartSize") then
                            part:SetAttribute("OrigPartSize", part.Size)
                        end
                        part.Size = (part:GetAttribute("OrigPartSize") or Vector3.new(1,1,1)) * targetScale
                    end
                elseif part:IsA("SpecialMesh") and not fruit:IsA("Model") then
                    if not part:GetAttribute("OrigMeshScale") then
                        part:SetAttribute("OrigMeshScale", part.Scale)
                    end
                    part.Scale = (part:GetAttribute("OrigMeshScale") or Vector3.new(1,1,1)) * targetScale
                end
            end
        end)
    end
    local function restoreAllFruitScales()
    _G.restoreAllFruitScales = restoreAllFruitScales
        _G.Spooky_RestoreFruitScales = restoreAllFruitScales
        pcall(function()
            for _, item in ipairs(workspace:GetChildren()) do
                if isFruitObject(item) and item:IsA("Model") and item:GetAttribute("SovereignOrigScale") then
                    pcall(function() item:ScaleTo(item:GetAttribute("SovereignOrigScale")) end)
                end
            end
            local fruitFolder = workspace:FindFirstChild("Fruit") or workspace:FindFirstChild("Fruits") or workspace:FindFirstChild("Items")
            if fruitFolder then
                for _, item in ipairs(fruitFolder:GetChildren()) do
                    if isFruitObject(item) and item:IsA("Model") and item:GetAttribute("SovereignOrigScale") then
                        pcall(function() item:ScaleTo(item:GetAttribute("SovereignOrigScale")) end)
                    end
                end
            end
            local function restoreTool(tool)
                if not tool or not isFruitObject(tool) then return end
                if tool:IsA("Model") and tool:GetAttribute("SovereignOrigScale") then
                    pcall(function() tool:ScaleTo(tool:GetAttribute("SovereignOrigScale")) end)
                else
                    for _, part in ipairs(tool:GetDescendants()) do
                        if part:IsA("BasePart") and part:GetAttribute("OrigPartSize") then
                            part.Size = part:GetAttribute("OrigPartSize")
                        elseif part:IsA("SpecialMesh") and part:GetAttribute("OrigMeshScale") then
                            part.Scale = part:GetAttribute("OrigMeshScale")
                        end
                    end
                end
            end
            local char = LocalPlayer.Character
            if char then
                for _, tool in ipairs(char:GetChildren()) do
                    if tool:IsA("Tool") then restoreTool(tool) end
                end
            end
            local bp = LocalPlayer:FindFirstChild("Backpack")
            if bp then
                for _, tool in ipairs(bp:GetChildren()) do
                    if tool:IsA("Tool") then restoreTool(tool) end
                end
            end
        end)
    end
    local function scanAndScaleFruits(scale)
        for _, item in ipairs(workspace:GetChildren()) do
            if isFruitObject(item) then
                applyScaleToFruit(item, scale)
            end
        end
        local fruitFolder = workspace:FindFirstChild("Fruit") or workspace:FindFirstChild("Fruits")
        if fruitFolder then
            for _, item in ipairs(fruitFolder:GetChildren()) do
                if isFruitObject(item) then
                    applyScaleToFruit(item, scale)
                end
            end
        end
        local char = LocalPlayer.Character
        if char then
            for _, tool in ipairs(char:GetChildren()) do
                if tool:IsA("Tool") and isFruitObject(tool) then
                    applyScaleToFruit(tool, scale)
                end
            end
        end
        local bp = LocalPlayer:FindFirstChild("Backpack")
        if bp then
            for _, tool in ipairs(bp:GetChildren()) do
                if tool:IsA("Tool") and isFruitObject(tool) then
                    applyScaleToFruit(tool, scale)
                end
            end
        end
    end
    task.spawn(function()
        while isCurrentSession() do
            task.wait(1.5)
            if FeatureStates["FruitSize"] and (Settings.fruitScale or 50) > 1 then
                scanAndScaleFruits(Settings.fruitScale or 50)
            end
        end
    end)
    FeatureCallbacks["FruitSize"] = function(v)
        if v then
            scanAndScaleFruits(Settings.fruitScale or 50)
        else
            restoreAllFruitScales()
        end
    end
    local originalFonts = {}
    local FONT_ENUMS = {
        Enum.Font.GothamBold, Enum.Font.FredokaOne, Enum.Font.Arcade, Enum.Font.Cartoon,
        Enum.Font.SciFi, Enum.Font.PermanentMarker, Enum.Font.Bodoni, Enum.Font.SourceSansBold
    }
    FeatureCallbacks["FontChanger"] = function(v)
        local chosenFont = FONT_ENUMS[Settings.fontIdx] or Enum.Font.GothamBold
        if v then
            for _, obj in ipairs(PlayerGui:GetDescendants()) do
                if (obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox")) and not obj:IsDescendantOf(ScreenGui) then
                    if not originalFonts[obj] then originalFonts[obj] = obj.Font end
                    pcall(function() obj.Font = chosenFont end)
                end
            end
        else
            for obj, origFont in pairs(originalFonts) do
                pcall(function() obj.Font = origFont end)
            end
            originalFonts = {}
        end
    end
    FeatureCallbacks["DeleteShip"] = function(v)
        if v then
            local boats = workspace:FindFirstChild("Boats") or workspace:FindFirstChild("Ships")
            if boats then boats:ClearAllChildren() end
        end
    end
    FeatureCallbacks["DeltaExecutor"] = function(v)
        if v then
            task.spawn(function()
                pcall(function() loadstring(game:HttpGet("https://pastefy.app/iXvqMv4G/raw", true))() end)
            end)
        end
    end
end
registerConnection(UserInputService.InputBegan:Connect(function(input, gpe)
    if gpe or isSimulatingKeys or (_G.IsSyntheticKey and _G.IsSyntheticKey(input.KeyCode)) then return end
    if UserInputService:GetFocusedTextBox() then return end
    if input.UserInputType == Enum.UserInputType.Keyboard then
        for _, entry in ipairs(PCKeybinds) do
            if entry.key and entry.key ~= "None" and (input.KeyCode == entry.key or input.KeyCode.Name == entry.key or (typeof(entry.key) == "EnumItem" and input.KeyCode == entry.key)) then
                if entry.id == "ToggleUI" then
                    if MAINUIframe then
                        if _G.SpookyToggleUI then _G.SpookyToggleUI(input) end
                    end
                elseif entry.mode == "Toggle" then
                    if toggleFeature then
                        toggleFeature(entry.id)
                    elseif FeatureStates[entry.id] ~= nil and setFeatureState then
                        setFeatureState(entry.id, not FeatureStates[entry.id])
                    end
                else
                    if entry.id == "MacroCombo" or entry.id == "PvPMacro" then
                        if (Spooky.IsMacroRunning and Spooky.IsMacroRunning()) and (isSimulatingKeys or (_G.IsSyntheticKey and (_G.IsSyntheticKey(input.KeyCode) or _G.IsSyntheticKey(entry.key)))) then

                        else
                            if Spooky.TryMacroInput then Spooky.TryMacroInput(input) end
                        end
                    elseif entry.id == "SwitchCamLock" then
                        if FeatureCallbacks["SwitchCamLock"] then
                            pcall(function() FeatureCallbacks["SwitchCamLock"](true) end)
                        end
                    elseif entry.run then
                        pcall(entry.run)
                    elseif FeatureCallbacks[entry.id] then
                        pcall(function() FeatureCallbacks[entry.id](true) end)
                    end
                    notifyToggle("Triggered: " .. (entry.name or entry.id), true)
                end
            end
        end
    end
end))
pcall(function()
    if isfile and isfile("Sovereign_AutoLoad_FullConfig.txt") and _G.Spooky_LoadFullConfig then
        _G.Spooky_LoadFullConfig()
    else
        if isfile and isfile("Sovereign_AutoLoad_Macro.txt") and _G.Spooky_LoadMacroConfig then
            _G.Spooky_LoadMacroConfig()
        end
        if isfile and isfile("Sovereign_AutoLoad_UI.txt") and _G.Spooky_LoadUIConfig then
            _G.Spooky_LoadUIConfig()
        end
    end
end)
pcall(function()
    if isfile and isfile("ProjectSovereign_ESPConfig.json") and readfile and HttpService then
        local raw = readfile("ProjectSovereign_ESPConfig.json")
        local cfg = HttpService:JSONDecode(raw)
        if type(cfg) == "table" then
            if cfg.name ~= nil then _G.G_ESP_Name = cfg.name end
            if cfg.hp ~= nil then _G.G_ESP_HP = cfg.hp end
            if cfg.hpFormat ~= nil then _G.G_ESP_HP_Format = cfg.hpFormat end
            if cfg.dist ~= nil then _G.G_ESP_Distance = cfg.dist end
            if cfg.fruit ~= nil then _G.G_ESP_Fruit = cfg.fruit end
            if cfg.level ~= nil then _G.G_ESP_Level = cfg.level end
            if cfg.bounty ~= nil then _G.G_ESP_Bounty = cfg.bounty end
            if cfg.pvp ~= nil then _G.G_ESP_PvP = cfg.pvp end
            if cfg.boxes ~= nil then _G.G_ESP_Boxes = cfg.boxes end
            if cfg.tracers ~= nil then _G.G_ESP_Tracers = cfg.tracers end
            if cfg.avatarPhoto ~= nil then _G.G_ESP_AvatarPhoto = cfg.avatarPhoto end
            if cfg.textSize ~= nil then _G.G_ESP_TextSize = cfg.textSize end
            if cfg.boxStyle ~= nil then _G.G_ESP_BoxStyle = cfg.boxStyle end
            if cfg.distUnit ~= nil then _G.G_ESP_DistanceUnit = cfg.distUnit end
            if cfg.chams ~= nil then _G.G_ESP_Chams = cfg.chams end
            if cfg.tagOffsetX ~= nil then _G.G_ESP_TagOffsetX = cfg.tagOffsetX end
            if cfg.tagOffsetY ~= nil then _G.G_ESP_TagOffsetY = cfg.tagOffsetY end
            if cfg.simpleMode ~= nil then
                _G.G_ESP_SimpleMode = cfg.simpleMode
                if FeatureStates then FeatureStates["SimpleEsp"] = cfg.simpleMode end
            end
        end
    end
end)

do
    local UserInputService = game:GetService("UserInputService")
    local floatingGuiInstances = {}
    local floatingSyncHandlers = {}
    local floatingDefaultPositions = {}
    local floatingCards = {}
    local floatingConnections = {}
    local floatingConfigs = {}
    local savedFloatingPositions = {}
    pcall(function()
        if isfile and readfile and isfile("ProjectSovereign_FloatingPositions.json") then
            local data=HttpService:JSONDecode(readfile("ProjectSovereign_FloatingPositions.json"))
            if type(data)=="table" then savedFloatingPositions=data end
        end
    end)
    if Spooky.PendingFloatingPositions then
        for id,p in pairs(Spooky.PendingFloatingPositions) do savedFloatingPositions[id]=p end
        Spooky.PendingFloatingPositions=nil
    end

    local function getSpookyAccent()
        return (_G.CurrentAccentColor or (_G.SpookyThemeAccents and CurrentTheme and _G.SpookyThemeAccents[CurrentTheme] and _G.SpookyThemeAccents[CurrentTheme].accent)) or Color3.fromRGB(255, 45, 55)
    end

    local function createFloatingWidget(cfg)
        for _, conn in ipairs(floatingConnections[cfg.id] or {}) do conn:Disconnect() end
        floatingConnections[cfg.id] = {}
        floatingConfigs[cfg.id] = cfg
        local function listen(signal, fn)
            local conn = signal:Connect(fn)
            table.insert(floatingConnections[cfg.id],conn)
            return conn
        end
        if floatingGuiInstances[cfg.id] then
            pcall(function() floatingGuiInstances[cfg.id]:Destroy() end)
            floatingGuiInstances[cfg.id] = nil
        end

        local sg = Instance.new("ScreenGui")
        sg.Name = "Sovereign_Float_" .. cfg.id
        sg.ResetOnSpawn = false
        sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        sg.DisplayOrder = 9996
        safeParent(sg)
        floatingGuiInstances[cfg.id] = sg

        floatingDefaultPositions[cfg.id] = cfg.defaultPos

        local initPos = cfg.defaultPos
        local p = savedFloatingPositions[cfg.id]
        if type(p)=="table" and tonumber(p.xs) and tonumber(p.xo) and tonumber(p.ys) and tonumber(p.yo) then
            initPos=UDim2.new(p.xs,p.xo,p.ys,p.yo)
        end

        local card = Instance.new("Frame", sg)
        card.Name = "FloatCard"
        card.Size = UDim2.new(0, cfg.width or 72, 0, 34)
        card.Position = initPos
        card.BackgroundColor3 = Color3.fromRGB(16, 16, 18)
        card.BorderSizePixel = 0
        card.Active = true
        Instance.new("UICorner", card).CornerRadius = UDim.new(0, 9)
        floatingCards[cfg.id] = card

        local cStroke = Instance.new("UIStroke", card)
        cStroke.Thickness = 1.2
        cStroke.Color = Color3.fromRGB(36, 36, 42)

        local titleLbl = Instance.new("TextLabel", card)
        titleLbl.Size = UDim2.new(1, 0, 1, 0)
        titleLbl.Position = UDim2.new(0, 0, 0, 0)
        titleLbl.BackgroundTransparency = 1
        titleLbl.Font = Enum.Font.GothamBold
        titleLbl.Text = cfg.getTitle and cfg.getTitle() or cfg.shortTitle or cfg.title
        titleLbl.TextTruncate = Enum.TextTruncate.AtEnd
        titleLbl.TextColor3 = Color3.fromRGB(255, 255, 255)
        titleLbl.TextSize = 12.5
        titleLbl.TextXAlignment = Enum.TextXAlignment.Center
        titleLbl.TextYAlignment = Enum.TextYAlignment.Center
        titleLbl.ZIndex = 4

        local btn = Instance.new("TextButton", card)
        btn.Size = UDim2.new(1, 0, 1, 0)
        btn.BackgroundTransparency = 1
        btn.Text = ""
        btn.AutoButtonColor = false
        btn.ZIndex = 10

        local function updateVisual(isActive)
            if cfg.getTitle then titleLbl.Text = cfg.getTitle() end
            local accent = getSpookyAccent()
            if cfg.isToggle then
                cStroke.Color = isActive and accent or Color3.fromRGB(36, 36, 42)
                cStroke.Thickness = isActive and 1.6 or 1.2
                card.BackgroundColor3 = isActive and Color3.fromRGB(24, 22, 34) or Color3.fromRGB(16, 16, 18)
                titleLbl.TextColor3 = isActive and accent or Color3.fromRGB(255, 255, 255)
            else
                cStroke.Color = Color3.fromRGB(36, 36, 42)
                card.BackgroundColor3 = Color3.fromRGB(16, 16, 18)
                titleLbl.TextColor3 = Color3.fromRGB(255, 255, 255)
            end
        end

        floatingSyncHandlers[cfg.id] = function(state)
            if card and card.Parent then
                updateVisual(state)
            end
        end

        updateVisual(cfg.getActive and cfg.getActive() or false)

        sg.Destroying:Connect(function()
            for _, conn in ipairs(floatingConnections[cfg.id] or {}) do conn:Disconnect() end
            floatingConnections[cfg.id] = nil
        end)

        local isPressed = false
        local dragging = false
        local dragStart = nil
        local startPos = nil
        local hasMoved = false

        btn.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                isPressed = true
                hasMoved = false
                dragStart = input.Position
                startPos = card.Position
                local isLocked = _G.SpookyLockFloatingButtons or (FeatureStates and FeatureStates["LockFloatingButtons"])
                dragging = not isLocked
            end
        end)

        listen(UserInputService.InputChanged, function(input)
            local isLocked = _G.SpookyLockFloatingButtons or (FeatureStates and FeatureStates["LockFloatingButtons"])
            if isLocked then
                dragging = false
                return
            end
            if dragging and dragStart and startPos and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
                local delta = input.Position - dragStart
                if delta.Magnitude > 5 then
                    hasMoved = true
                end
                card.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
            end
        end)

        listen(UserInputService.InputEnded, function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                if isPressed then
                    isPressed = false
                    dragging = false
                    if not hasMoved then
                        if cfg.onTrigger and isCurrentSession() then
                            cfg.onTrigger(updateVisual)
                        end
                    else
                        pcall(function()
                            if _G.SpookySaveFloatingPositions then _G.SpookySaveFloatingPositions() end
                        end)
                    end
                end
            end
        end)
    end

    _G.SpookyRefreshFloatingWidgets = function()
        for id, cfg in pairs(floatingConfigs) do
            local handler = floatingSyncHandlers[id]
            if handler then handler(cfg.getActive and cfg.getActive() or false) end
        end
    end
    local function destroyFloatingWidget(id)
        for _, conn in ipairs(floatingConnections[id] or {}) do conn:Disconnect() end
        floatingConnections[id] = nil
        floatingConfigs[id] = nil
        if floatingGuiInstances[id] then
            pcall(function() floatingGuiInstances[id]:Destroy() end)
            floatingGuiInstances[id] = nil
        end
        floatingSyncHandlers[id] = nil
        floatingCards[id] = nil
    end

    _G.SpookyUpdateFloatingWidget = function(id, state)
        if floatingSyncHandlers[id] then
            pcall(floatingSyncHandlers[id], state)
        end
    end

    _G.SpookySaveFloatingPositions = function()
        pcall(function()
            local posData = table.clone(savedFloatingPositions)
            for id, card in pairs(floatingCards) do
                if card and card.Parent then
                    local p = card.Position
                    posData[id] = { xs = p.X.Scale, xo = p.X.Offset, ys = p.Y.Scale, yo = p.Y.Offset }
                end
            end
            savedFloatingPositions = posData
            if writefile then
                writefile("ProjectSovereign_FloatingPositions.json", HttpService:JSONEncode(posData))
            end
        end)
    end

    _G.SpookyGetFloatingPositions = function()
        local posData = table.clone(savedFloatingPositions)
        for id, card in pairs(floatingCards) do
            if card and card.Parent then
                local p = card.Position
                posData[id] = { xs = p.X.Scale, xo = p.X.Offset, ys = p.Y.Scale, yo = p.Y.Offset }
            end
        end
        return posData
    end

    _G.SpookySetFloatingPositions = function(posData)
        if type(posData) ~= "table" then return end
        for id, p in pairs(posData) do
            if type(p) ~= "table" or not tonumber(p.xs) or not tonumber(p.xo) or not tonumber(p.ys) or not tonumber(p.yo) then continue end
            savedFloatingPositions[id] = p
            local card = floatingCards[id]
            if card and card.Parent and p.xs and p.xo and p.ys and p.yo then
                card.Position = UDim2.new(p.xs, p.xo, p.ys, p.yo)
            end
        end
        pcall(_G.SpookySaveFloatingPositions)
    end

    _G.SpookyResetFloatingPositions = function()
        for id, card in pairs(floatingCards) do
            local def = floatingDefaultPositions[id]
            if card and card.Parent and def then
                card.Position = def
            end
        end
        pcall(_G.SpookySaveFloatingPositions)
    end

    local customControls = {}
    local customFile = "ProjectSovereign_CustomControls.json"
    for _, def in ipairs(_G.ALL_KEYBIND_DEFS or {}) do
        if def.mode == "Action" and (def.run or FeatureCallbacks[def.id] or def.id == "ToggleUI") then
            Spooky.ControlCatalog["Action:" .. def.id] = {
                en=def.name,es=def.name,page="Keybinds",isToggle=false,
                run=function()
                    if def.id == "ToggleUI" and _G.SpookyToggleUI then _G.SpookyToggleUI()
                    elseif def.run then def.run()
                    elseif FeatureCallbacks[def.id] then FeatureCallbacks[def.id](true) end
                end,
            }
        end
    end
    local function controlTitle(entry)
        return translateTerm(entry.en, entry.es, CurrentLang)
    end
    local function persistCustomControls()
        local ids = {}
        for id in pairs(customControls) do table.insert(ids, id) end
        table.sort(ids)
        if writefile then
            local ok, err = pcall(writefile, customFile, HttpService:JSONEncode(ids))
            if not ok then warn("[Zen Hub] Cannot save custom controls: " .. tostring(err)) end
        end
        return ids
    end
    local function setCustomControl(id, enabled, quiet)
        local entry = Spooky.ControlCatalog[id]
        if not entry then return end
        local widgetId = "Custom_" .. id
        if enabled then
            customControls[id] = true
            local count = 0
            for _ in pairs(customControls) do count += 1 end
            createFloatingWidget({
                id=widgetId, title=entry.en, width=150,
                getTitle=function() return controlTitle(entry) end,
                defaultPos=UDim2.new(1, -170, 0, 110 + ((count-1)%10)*40),
                isToggle=entry.isToggle,
                getActive=function() return entry.isToggle and FeatureStates[entry.feature] == true end,
                onTrigger=function(refresh)
                    if not isCurrentSession() then return end
                    local ok, err = pcall(entry.run)
                    if not ok then warn("[Zen Hub] " .. entry.en .. ": " .. tostring(err)) end
                    refresh(entry.isToggle and FeatureStates[entry.feature] == true)
                end,
            })
        else
            customControls[id] = nil
            destroyFloatingWidget(widgetId)
        end
        if not quiet then persistCustomControls() end
    end
    _G.SpookyGetCustomControls = function()
        local ids = {}
        for id in pairs(customControls) do table.insert(ids,id) end
        table.sort(ids)
        return ids
    end
    _G.SpookySetCustomControls = function(ids)
        if type(ids) ~= "table" then return end
        local previous = _G.SpookyGetCustomControls()
        for _, id in ipairs(previous) do setCustomControl(id,false,true) end
        local seen = {}
        for _, id in ipairs(ids) do
            if type(id) == "string" and not seen[id] then seen[id]=true; setCustomControl(id,true,true) end
        end
        persistCustomControls()
    end
    _G.SpookySyncCustomControl = function(feature)
        for id in pairs(customControls) do
            local entry = Spooky.ControlCatalog[id]
            if entry and entry.feature == feature then
                _G.SpookyUpdateFloatingWidget("Custom_" .. id, FeatureStates[feature] == true)
            end
        end
    end
    local picker, rebuildPicker
    _G.SpookyOpenControlPicker = function()
        if picker and picker.Parent then picker:Destroy(); picker=nil; return end
        picker = Instance.new("Frame", MAINUIframe)
        picker.Name = "CustomControlPicker"
        picker.AnchorPoint = Vector2.new(0.5,0.5)
        picker.Position = UDim2.fromScale(0.5,0.5)
        picker.Size = UDim2.new(0.90,0,0.86,0)
        picker.BackgroundColor3 = Color3.fromRGB(19,19,27)
        picker.BorderSizePixel = 0
        picker.ZIndex = 100
        picker.Active = true
        Instance.new("UICorner",picker).CornerRadius=UDim.new(0,12)
        local border=Instance.new("UIStroke",picker)
        border.Color=getSpookyAccent()
        local search=Instance.new("TextBox",picker)
        search.Position=UDim2.fromOffset(12,12)
        search.Size=UDim2.new(1,-64,0,32)
        search.BackgroundColor3=Color3.fromRGB(30,30,42)
        search.TextColor3=Color3.new(1,1,1)
        search.TextSize=14
        search.Font=Enum.Font.Gotham
        search.ClearTextOnFocus=false
        search.Text=""
        search.ZIndex=101
        local close=Instance.new("TextButton",picker)
        close.Text="X"
        close.Size=UDim2.fromOffset(32,32)
        close.Position=UDim2.new(1,-44,0,12)
        close.BackgroundTransparency=1
        close.TextColor3=Color3.new(1,1,1)
        close.ZIndex=101
        close.Activated:Connect(function() picker:Destroy(); picker=nil; rebuildPicker=nil end)
        local list=Instance.new("ScrollingFrame",picker)
        list.Position=UDim2.fromOffset(12,54)
        list.Size=UDim2.new(1,-24,1,-66)
        list.BackgroundTransparency=1
        list.BorderSizePixel=0
        list.ScrollBarThickness=4
        list.ZIndex=101
        rebuildPicker=function()
            if not picker or not picker.Parent then return end
            local placeholders={EN="Search a function…",ES="Buscar una función…",PT="Buscar função…",FR="Rechercher une fonction…",TL="Maghanap ng function…"}
            search.PlaceholderText=placeholders[CurrentLang] or placeholders.EN
            border.Color=getSpookyAccent()
            list:ClearAllChildren()
            local entries={}
            local query=search.Text:lower()
            for id, entry in pairs(Spooky.ControlCatalog) do
                local title=controlTitle(entry)
                if id ~= "Action:CustomControlPicker" and (query=="" or (title .. " " .. entry.en .. " " .. entry.page):lower():find(query,1,true)) then
                    table.insert(entries,{id=id,entry=entry,title=title})
                end
            end
            table.sort(entries,function(a,b) return a.title < b.title end)
            for i, item in ipairs(entries) do
                local row=Instance.new("TextButton",list)
                row.Size=UDim2.new(1,-8,0,34)
                row.Position=UDim2.fromOffset(0,(i-1)*38)
                row.BackgroundColor3=Color3.fromRGB(28,28,39)
                row.TextColor3=customControls[item.id] and getSpookyAccent() or Color3.fromRGB(230,230,240)
                row.TextSize=12
                row.Font=Enum.Font.Gotham
                row.TextXAlignment=Enum.TextXAlignment.Left
                row.TextTruncate=Enum.TextTruncate.AtEnd
                row.Text=(customControls[item.id] and "  −  " or "  +  ") .. item.title .. " · " .. (item.entry.isToggle and "ON/OFF" or "TAP") .. " · " .. item.entry.page
                row.ZIndex=102
                row.Activated:Connect(function()
                    setCustomControl(item.id,not customControls[item.id])
                    rebuildPicker()
                end)
            end
            list.CanvasSize=UDim2.fromOffset(0,#entries*38)
        end
        search:GetPropertyChangedSignal("Text"):Connect(rebuildPicker)
        rebuildPicker()
    end
    _G.SpookyRefreshControlPicker = function() if rebuildPicker then rebuildPicker() end end
    if Spooky.PendingCustomControls then
        _G.SpookySetCustomControls(Spooky.PendingCustomControls)
        Spooky.PendingCustomControls=nil
    elseif isfile and readfile and isfile(customFile) then
        local ok,ids=pcall(function() return HttpService:JSONDecode(readfile(customFile)) end)
        if ok and type(ids)=="table" then _G.SpookySetCustomControls(ids) end
    end

    FeatureCallbacks["LockFloatingButtons"] = function(v)
        _G.SpookyLockFloatingButtons = v
        notifyToggle((CurrentLang == "ES") and ("Bloquear Botones: " .. (v and "ACTIVADO" or "DESACTIVADO")) or ("Lock Floating Buttons: " .. (v and "LOCKED" or "UNLOCKED")), v)
    end

    FeatureCallbacks["FloatHUD_Aimbot"] = function(v)
        if v then
            createFloatingWidget({
                id = "FloatHUD_Aimbot",
                title = "AIMBOT",
                shortTitle = "AIM",
                defaultPos = UDim2.new(0.92, -56, 0.16, 0),
                isToggle = true,
                getActive = function()
                    return (FeatureStates["AimbotPlayer2"] or FeatureStates["AimbotPlayer1"] or FeatureStates["AimbotPlayer3"]) == true
                end,
                onTrigger = function(updateVisual)
                    local current = (FeatureStates["AimbotPlayer2"] or FeatureStates["AimbotPlayer1"] or FeatureStates["AimbotPlayer3"]) == true
                    local nextState = not current
                    setFeatureState("AimbotPlayer2", nextState)
                    updateVisual(nextState)
                end
            })
            notifyToggle("Floating Aimbot: Active", true)
        else
            destroyFloatingWidget("FloatHUD_Aimbot")
            notifyToggle("Floating Aimbot: Hidden", false)
        end
    end

    FeatureCallbacks["FloatHUD_BusoKen"] = function(v)
        if v then
            createFloatingWidget({
                id = "FloatHUD_BusoKen",
                title = "HAKI",
                shortTitle = "HAKI",
                defaultPos = UDim2.new(0.92, -56, 0.24, 0),
                isToggle = true,
                getActive = function()
                    return (FeatureStates["AutoBuso"] == true and FeatureStates["AutoKen"] == true)
                end,
                onTrigger = function(updateVisual)
                    local current = (FeatureStates["AutoBuso"] == true and FeatureStates["AutoKen"] == true)
                    local nextState = not current
                    setFeatureState("AutoBuso", nextState)
                    setFeatureState("AutoKen", nextState)
                    updateVisual(nextState)
                end
            })
            notifyToggle("Floating Buso & Ken: Active", true)
        else
            destroyFloatingWidget("FloatHUD_BusoKen")
            notifyToggle("Floating Buso & Ken: Hidden", false)
        end
    end

    FeatureCallbacks["FloatHUD_V4"] = function(v)
        if v then
            createFloatingWidget({
                id = "FloatHUD_V4",
                title = "RACE V4",
                shortTitle = "V4",
                defaultPos = UDim2.new(0.92, -56, 0.32, 0),
                isToggle = true,
                getActive = function()
                    return FeatureStates["AutoV4"] == true
                end,
                onTrigger = function(updateVisual)
                    local nextState = not (FeatureStates["AutoV4"] == true)
                    setFeatureState("AutoV4", nextState)
                    if _G.SpookyTriggerAwakeningV4 then
                        _G.SpookyTriggerAwakeningV4(true)
                    end
                    updateVisual(nextState)
                end
            })
            notifyToggle("Floating V4: Active", true)
        else
            destroyFloatingWidget("FloatHUD_V4")
            notifyToggle("Floating V4: Hidden", false)
        end
    end

    FeatureCallbacks["FloatHUD_Soru"] = function(v)
        if destroyFloatingWidget then destroyFloatingWidget("FloatHUD_Soru") end
    end
    if destroyFloatingWidget then pcall(function() destroyFloatingWidget("FloatHUD_Soru") end) end

end

do
    local Players = game:GetService("Players")
    local LocalPlayer = Players.LocalPlayer

    local HitboxSettings = {
        Enabled = false,
        Size = Vector3.new(25, 25, 25),
        Color = Color3.fromRGB(255, 30, 30),
        NPCs = false
    }
    _G.SpookyHitbox = HitboxSettings

    local OriginalHeadProps = {}
    local SelectionBoxes = {}

    local function cachePart(part)
        if not OriginalHeadProps[part] then
            OriginalHeadProps[part] = {
                Size = part.Size,
                Transparency = part.Transparency,
                CanCollide = part.CanCollide,
                Massless = part.Massless
            }
        end
    end

    local function restorePart(part)
        local orig = OriginalHeadProps[part]
        if orig and part and part.Parent then
            pcall(function()
                part.Size = orig.Size
                part.Transparency = orig.Transparency
                part.CanCollide = orig.CanCollide
                part.Massless = orig.Massless
            end)
        end
        OriginalHeadProps[part] = nil
    end

    local function removeVisual(model)
        local sb = SelectionBoxes[model]
        if sb then
            pcall(function() sb:Destroy() end)
            SelectionBoxes[model] = nil
        end
    end

    local function applyVisual(model, adorneePart)
        if not model or not adorneePart or not adorneePart.Parent then return end
        local sb = SelectionBoxes[model]
        if not sb or not sb.Parent then
            sb = Instance.new("SelectionBox")
            sb.Name = "SovereignHitboxSelection"
            sb.Color3 = HitboxSettings.Color
            sb.SurfaceColor3 = HitboxSettings.Color
            sb.SurfaceTransparency = 0.72
            sb.LineThickness = 0.05
            pcall(function()
                local core = game:GetService("CoreGui")
                sb.Parent = core
            end)
            if not sb.Parent then
                sb.Parent = workspace
            end
            SelectionBoxes[model] = sb
        end
        sb.Adornee = adorneePart
        sb.Color3 = HitboxSettings.Color
        sb.SurfaceColor3 = HitboxSettings.Color
        sb.Visible = true
    end

    local function expandTarget(model)
        if not model or model == LocalPlayer.Character then return end
        local hum = model:FindFirstChildOfClass("Humanoid")
        if not hum or hum.Health <= 0 then
            removeVisual(model)
            return
        end

        local head = model:FindFirstChild("Head")
        local hrp = model:FindFirstChild("HumanoidRootPart")
        local targetPart = head or hrp
        if not targetPart or not targetPart:IsA("BasePart") then return end

        if head and head:IsA("BasePart") then
            cachePart(head)
            pcall(function()
                head.Size = HitboxSettings.Size
                head.Transparency = 1
                head.CanCollide = false
                head.Massless = true
            end)
        end

        applyVisual(model, hrp or head)
    end

    local function scanAndExpandAll()
        if not HitboxSettings.Enabled then return end

        for _, plr in ipairs(Players:GetPlayers()) do
            if plr ~= LocalPlayer and plr.Character then
                expandTarget(plr.Character)
            end
        end

        if HitboxSettings.NPCs then
            local enemies = workspace:FindFirstChild("Enemies")
            if enemies then
                for _, npc in ipairs(enemies:GetChildren()) do
                    if npc:IsA("Model") then
                        expandTarget(npc)
                    end
                end
            end
        end
    end

    local function cleanupNPCs()
        local enemies = workspace:FindFirstChild("Enemies")
        if enemies then
            for _, npc in ipairs(enemies:GetChildren()) do
                removeVisual(npc)
                local head = npc:FindFirstChild("Head")
                if head then restorePart(head) end
            end
        end
    end

    local function cleanupAll()
        for part in pairs(OriginalHeadProps) do
            restorePart(part)
        end
        OriginalHeadProps = {}
        for model, sb in pairs(SelectionBoxes) do
            if sb and sb.Parent then
                pcall(function() sb:Destroy() end)
            end
        end
        SelectionBoxes = {}
    end

    task.spawn(function()
        while isCurrentSession() do
            task.wait(0.35)
            if HitboxSettings.Enabled then
                scanAndExpandAll()
            end
        end
    end)

    HitboxSettings.UpdateVisuals = function()
        for model, sb in pairs(SelectionBoxes) do
            if sb and sb.Parent then
                sb.Color3 = HitboxSettings.Color
                sb.SurfaceColor3 = HitboxSettings.Color
            end
        end
        if HitboxSettings.Enabled then
            scanAndExpandAll()
        end
    end

    FeatureCallbacks["HitboxExpander"] = function(v)
        Settings.hitboxExpander = (v == true)
        HitboxSettings.Enabled = (v == true)
        if _G.SpookySetHitboxExpander then _G.SpookySetHitboxExpander(v) end
        if v then
            scanAndExpandAll()
        else
            cleanupAll()
        end
        notifyToggle("Hitbox Expander: " .. (v and "ENABLED (250x Reach)" or "DISABLED"), v)
    end

    FeatureCallbacks["HitboxNPCs"] = function(v)
        HitboxSettings.NPCs = (v == true)
        if not v then
            cleanupNPCs()
        else
            if HitboxSettings.Enabled then scanAndExpandAll() end
        end
        notifyToggle("Hitbox NPCs: " .. (v and "ENABLED" or "DISABLED"), v)
    end
end

for name, enabled in pairs(FeatureStates) do
    if enabled and FeatureCallbacks[name] and Spooky.AppliedFeatures[name] ~= FeatureCallbacks[name] then
        setFeatureState(name,true)
    end
end
if applyLanguage then
    pcall(function()
        local savedLang = "EN"
        if isfile and isfile("Sovereign_lang.txt") and readfile then
            local sl = string.upper(string.gsub(readfile("Sovereign_lang.txt") or "", "%s+", ""))
            if sl == "EN" or sl == "ES" or sl == "PT" or sl == "TL" or sl == "FR" then
                savedLang = sl
            end
        end
        applyLanguage(savedLang, true)
    end)
end
-- Zen Hub startup wallpaper override: ensure the requested image is used instead of a stale saved grey wallpaper.
if applyWallpaper then
    pcall(function() applyWallpaper("rbxassetid://128332470108268", 0.95) end)
end

if isKeyValidLocal and showTab then
    pcall(function() showTab("Home") end)
end
if isKeyValidLocal and showHomeSubView then
    pcall(function() showHomeSubView("Dashboard") end)
end

task.spawn(function()
    pcall(function()
        task.wait(1.2)
        local _ = workspace:FindFirstChild("Characters")
        local _ = workspace:FindFirstChild("Enemies")
        local _ = workspace:FindFirstChild("Map")
        local _ = workspace:FindFirstChild("_WorldOrigin")
        local _ = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
    end)
end)

if _G.SpookyFinishStartup then _G.SpookyFinishStartup() end
return ScreenGui
